import { useState, useEffect, useRef } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { DatabaseRowType } from '@/types';

interface Props {
  items: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function dpCurrencyFromMOP(mop?: string): string {
  const m = (mop || '').toUpperCase();
  if (m.includes('AED')) return 'AED';
  if (m.includes('PHP')) return 'PHP';
  if (m.includes('USD')) return 'USD';
  // GCash and Bank Transfer PHP are always PHP payments
  if (m.includes('GCASH') || m.includes('BANK TRANSFER')) return 'PHP';
  return 'AED';
}

function getPrimaryDP(items: DatabaseRowType[]): { item: DatabaseRowType | null; amount: string } {
  for (const r of items) {
    const v = String(r.downpayment || '').trim();
    if (v && v !== 'acknowledged' && !isNaN(parseFloat(v))) {
      return { item: r, amount: v };
    }
  }
  return { item: null, amount: '' };
}

/** Whether the group has a real saved downpayment (not just '' or 'acknowledged') */
function hasSavedDP(items: DatabaseRowType[]): boolean {
  return getPrimaryDP(items).amount !== '';
}

export default function GroupDownpaymentSection({ items, onUpdate }: Props) {
  const { amount: initialAmount } = getPrimaryDP(items);

  // checked is ONLY driven by user interaction — not by useEffect.
  // We keep it true once user ticks the box, even before an amount is entered.
  const [checked, setChecked] = useState(() => hasSavedDP(items));
  const [amount, setAmount] = useState(initialAmount);
  const [saving, setSaving] = useState(false);

  // userActed prevents useEffect from overriding a fresh checkbox click
  const userActed = useRef(false);

  // Sync amount from external record updates (e.g. another tab saves)
  // But only reset checked to false if there's genuinely no DP saved externally.
  useEffect(() => {
    const { amount: ext } = getPrimaryDP(items);
    if (ext) {
      setAmount(ext);
      setChecked(true);
    } else if (!userActed.current) {
      // Only uncheck if the user hasn't recently interacted
      setChecked(false);
      setAmount('');
    }
    userActed.current = false;
  }, [items]);

  const dpCurrency = dpCurrencyFromMOP(items[0]?.modeOfPayment);

  const saveGroupDP = useDebouncedCallback(async (val: string) => {
    if (!val || isNaN(parseFloat(val))) return;
    setSaving(true);
    for (let i = 0; i < items.length; i++) {
      const dpVal = i === 0 ? val : 'acknowledged';
      await onUpdate(items[i].id, { downpayment: dpVal });
      await new Promise(res => setTimeout(res, 80));
    }
    setSaving(false);
  }, 600);

  const handleCheck = async (on: boolean) => {
    userActed.current = true;
    setChecked(on);
    if (!on) {
      // Uncheck: clear all downpayments
      setAmount('');
      setSaving(true);
      for (const r of items) {
        await onUpdate(r.id, { downpayment: '' });
        await new Promise(res => setTimeout(res, 80));
      }
      setSaving(false);
    }
    // When checking ON: just show the input, don't save until user types an amount
  };

  const handleAmount = (val: string) => {
    userActed.current = true;
    setAmount(val);
    saveGroupDP(val);
  };

  const invoiceNo = items.find(r => r.pureWeight)?.pureWeight;

  return (
    <div className="mx-1 mb-2 rounded-lg border border-primary/20 bg-primary/5 px-3 py-2">
      <div className="flex items-center gap-2 flex-wrap">
        <Checkbox
          id={`group-dp-${items[0]?.id}`}
          checked={checked}
          disabled={saving}
          onCheckedChange={(v) => handleCheck(!!v)}
        />
        <Label htmlFor={`group-dp-${items[0]?.id}`} className="text-xs cursor-pointer font-semibold">
          Downpayment
          <span className="text-muted-foreground font-normal ml-1">
            (applies to all {items.length} item{items.length !== 1 ? 's' : ''}{invoiceNo ? ` · Invoice ${invoiceNo}` : ''})
          </span>
        </Label>
        {checked && amount && (
          <span className="text-xs text-primary font-bold ml-auto">
            {dpCurrency} {parseFloat(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </span>
        )}
      </div>
      {checked && (
        <Input
          type="number"
          value={amount}
          onChange={e => handleAmount(e.target.value)}
          className="h-8 text-xs bg-background border-border mt-2"
          placeholder={`Enter ${dpCurrency} downpayment for this group...`}
          disabled={saving}
          autoFocus
        />
      )}
    </div>
  );
}

