import { DatabaseRowType } from '@/types';

export function isPcItem(record: DatabaseRowType): boolean {
  if (!record.grams || isNaN(record.grams) || record.grams === 0) return true;
  if (record.category?.toLowerCase() === 'silver') return true;
  return false;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 15.5;
  return value;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = record.clientRate || 0;
  if (isPcItem(record)) return clientRate;
  return (record.grams || 0) * clientRate;
}

export function calcItemCost(record: DatabaseRowType): number {
  const supplierRate = parseFloat(record.supplierRate || '0') || 0;
  const mc = parseFloat(record.mc || '0') || 0;
  if (isPcItem(record)) return supplierRate + mc;
  return ((record.goldRate || 0) * (record.grams || 0)) + mc;
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCost(record);
}

export function calcProfitAED(record: DatabaseRowType): number {
  return toAED(calcProfit(record), record.currency);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (record.freeSf === 'TRUE' || record.freeSf === 'true') return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  const p = (v?: string) => parseFloat(v || '0') || 0;
  return p(record.downpayment) + p(record.la1MonthPayment) + p(record.la2MonthPayment) +
    p(record.la3MonthPayment) + p(record.la4MonthPayment) + p(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPrice = calcItemPrice(record);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = parseFloat(record.additionalCharges || '0') || 0;
  const totalPaid = calcTotalPaid(record);
  return (itemPrice + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return toAED(calcRemainingBalance(record), record.currency);
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending') return false;
  if (!record.dateOfLive) return false;
  const liveDate = new Date(record.dateOfLive);
  const diffMs = Date.now() - liveDate.getTime();
  return diffMs > 24 * 60 * 60 * 1000;
}

export function calcDueDate(dateOfLive?: string): Date | null {
  if (!dateOfLive) return null;
  const d = new Date(dateOfLive);
  if (isNaN(d.getTime())) return null;
  d.setDate(d.getDate() + 3);
  return d;
}

import { format, parseISO, isValid } from 'date-fns';
import { DatabaseRowType } from '@/types';

export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  try {
    const d = parseISO(dateStr);
    if (!isValid(d)) return dateStr;
    return format(d, 'MMM dd, yyyy');
  } catch {
    return dateStr;
  }
}

export function formatDateObj(date: Date | null): string {
  if (!date || !isValid(date)) return '—';
  return format(date, 'MMM dd, yyyy');
}

export function formatCurrency(value: number, currency?: string): string {
  const curr = currency || 'AED';
  return `${curr} ${value.toFixed(2)}`;
}

export function groupByMinerName(records: DatabaseRowType[]): Map<string, DatabaseRowType[]> {
  const map = new Map<string, DatabaseRowType[]>();
  for (const record of records) {
    const key = record.minerName || 'Unknown';
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(record);
  }
  return map;
}

export function groupByLocationSourceMiner(
  records: DatabaseRowType[]
): Map<string, Map<string, Map<string, DatabaseRowType[]>>> {
  const grouped = new Map<string, Map<string, Map<string, DatabaseRowType[]>>>();
  for (const record of records) {
    const location = record.locationOfMiner || 'Unknown';
    const source = record.source || 'Unknown';
    const miner = record.minerName || 'Unknown';
    if (!grouped.has(location)) grouped.set(location, new Map());
    const byLocation = grouped.get(location)!;
    if (!byLocation.has(source)) byLocation.set(source, new Map());
    const bySource = byLocation.get(source)!;
    if (!bySource.has(miner)) bySource.set(miner, []);
    bySource.get(miner)!.push(record);
  }
  return grouped;
}

export function applySearch(records: DatabaseRowType[], query: string): DatabaseRowType[] {
  if (!query.trim()) return records;
  const q = query.toLowerCase();
  return records.filter(r =>
    r.minerName?.toLowerCase().includes(q) ||
    r.itemDescription?.toLowerCase().includes(q) ||
    r.orderId?.toLowerCase().includes(q)
  );
}

export const MOP_OPTIONS = [
  'Tabby', 'Tamara', 'COD', 'Bank Transfer', 'Credit Card',
  'Meet Up', 'Pick Up Shop', 'Layaway',
];

export const REGION_OPTIONS = [
  'Dubai', 'Abu Dhabi', 'Sharjah', 'Ajman', 'Western Region', 'UAQ', 'RAK', 'Fujairah',
];

export const STATUS_COLORS: Record<string, string> = {
  'Pending': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
  'Waiting for Details': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  'For Pullout': 'bg-purple-500/20 text-purple-400 border-purple-500/30',
  'Dispatched': 'bg-orange-500/20 text-orange-400 border-orange-500/30',
  'Delivered': 'bg-green-500/20 text-green-400 border-green-500/30',
  'Cancelled': 'bg-red-500/20 text-red-400 border-red-500/30',
};

