import { Skeleton } from '@/components/ui/skeleton';

export default function LoadingSkeleton() {
  return (
    <div className="min-h-screen bg-background p-4">
      <div className="max-w-2xl mx-auto">
        <div className="mb-6">
          <Skeleton className="h-8 w-48 mb-2" />
          <Skeleton className="h-4 w-32" />
        </div>
        <Skeleton className="h-10 w-full mb-4" />
        {[1, 2, 3, 4].map(i => (
          <div key={i} className="mb-3 rounded-lg border border-border p-4">
            <div className="flex items-center justify-between mb-3">
              <Skeleton className="h-5 w-36" />
              <Skeleton className="h-5 w-16" />
            </div>
            <Skeleton className="h-4 w-24 mb-2" />
            <Skeleton className="h-4 w-full" />
          </div>
        ))}
      </div>
    </div>
  );
}

import { STATUS_COLORS } from '@/lib/formatters';

interface StatusBadgeProps {
  status?: string;
  className?: string;
}

export default function StatusBadge({ status, className = '' }: StatusBadgeProps) {
  if (!status) return null;
  const colorClass = STATUS_COLORS[status] || 'bg-muted text-muted-foreground border-border';
  return (
    <span className={`inline-flex items-center px-2 py-0.5 rounded border text-xs font-medium ${colorClass} ${className}`}>
      {status}
    </span>
  );
}

import { ShieldX } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useAuth } from 'zite-auth-sdk';

interface Props { email: string; }

export default function AccessDenied({ email }: Props) {
  const { logout } = useAuth();
  return (
    <div className="min-h-screen bg-background flex flex-col items-center justify-center p-8 text-center">
      <ShieldX className="h-16 w-16 text-destructive mb-4" />
      <h1 className="font-cinzel text-2xl text-primary mb-2">Access Denied</h1>
      <p className="text-muted-foreground mb-1 text-sm">
        Your account ({email}) is not assigned to any role.
      </p>
      <p className="text-muted-foreground mb-6 text-xs">
        Contact your administrator to be added to the system.
      </p>
      <Button variant="outline" onClick={() => logout()} className="border-border">
        Sign Out
      </Button>
    </div>
  );
}

import { Search, LogOut } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { useAuth } from 'zite-auth-sdk';

interface TabHeaderProps {
  title: string;
  subtitle?: string;
  searchQuery: string;
  onSearchChange: (q: string) => void;
  rightContent?: React.ReactNode;
}

export default function TabHeader({ title, subtitle, searchQuery, onSearchChange, rightContent }: TabHeaderProps) {
  const { logout, user } = useAuth();
  return (
    <div className="sticky top-0 z-20 bg-background border-b border-border">
      <div className="px-4 pt-4 pb-3">
        <div className="flex items-center justify-between mb-3">
          <div>
            <h1 className="font-cinzel text-lg text-primary leading-tight">{title}</h1>
            {subtitle && <p className="text-xs text-muted-foreground">{subtitle}</p>}
          </div>
          <div className="flex items-center gap-2">
            {rightContent}
            <Button
              variant="ghost"
              size="icon"
              onClick={() => logout()}
              title={user?.email}
              className="h-8 w-8 text-muted-foreground"
            >
              <LogOut className="h-4 w-4" />
            </Button>
          </div>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            value={searchQuery}
            onChange={e => onSearchChange(e.target.value)}
            placeholder="Search client, item, or order ID..."
            className="pl-9 bg-secondary border-border h-9 text-sm"
          />
        </div>
      </div>
    </div>
  );
}

