import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate, formatDateObj } from '@/lib/formatters';
import { calcItemPrice, calcShippingFee, calcCCFee, calcDueDate, toAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const first = records[0];
  const currency = first?.currency || 'AED';
  const subtotal = records.reduce((sum, r) => sum + calcItemPrice(r), 0);
  const subtotalAED = records.reduce((sum, r) => sum + toAED(calcItemPrice(r), r.currency), 0);
  const shippingFee = first ? calcShippingFee(first) : 0;
  const ccFee = first ? calcCCFee(first) : 0;
  const additionalCharges = parseFloat(first?.additionalCharges || '0') || 0;
  const grandTotal = subtotalAED + shippingFee + ccFee + additionalCharges;
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Invoice</title><style>
      body { font-family: 'Lato', sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; }
      h1, h2, .cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
      table { width: 100%; border-collapse: collapse; margin-top: 12px; }
      th { background: #f5f0e8; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 13px; }
      .total-row td { font-weight: bold; border-top: 2px solid #C9A84C; }
      .gold { color: #C9A84C; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Client Invoice</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <div className="mb-4 pb-4 border-b border-border">
            <h2 className="font-cinzel text-lg text-primary mb-1">INVOICE</h2>
            <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
              <span>Client: <span className="text-foreground font-medium">{first?.minerName}</span></span>
              <span>Date: <span className="text-foreground">{formatDate(first?.dateOfLive)}</span></span>
              <span>Region: <span className="text-foreground">{first?.regions || '—'}</span></span>
              <span>Due: <span className="text-foreground">{dueDate}</span></span>
              <span className="col-span-2">Payment: <span className="text-foreground">{first?.modeOfPayment || '—'}</span></span>
            </div>
          </div>
          <table className="w-full text-xs mb-4">
            <thead>
              <tr className="border-b border-border">
                <th className="text-left py-1 text-muted-foreground font-medium">Item</th>
                <th className="text-left py-1 text-muted-foreground font-medium">Cat</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Grams</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Rate</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Price</th>
              </tr>
            </thead>
            <tbody>
              {records.map(r => (
                <tr key={r.id} className="border-b border-border/50">
                  <td className="py-1.5 pr-2">{r.itemDescription}</td>
                  <td className="py-1.5">{r.category}</td>
                  <td className="py-1.5 text-right">{r.grams || 'PC'}</td>
                  <td className="py-1.5 text-right">{currency} {r.clientRate?.toFixed(2)}</td>
                  <td className="py-1.5 text-right">{currency} {calcItemPrice(r).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="space-y-1 text-xs border-t border-border pt-3">
            <div className="flex justify-between"><span className="text-muted-foreground">Subtotal ({currency})</span><span>{currency} {subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>AED {shippingFee.toFixed(2)}</span></div>
            {additionalCharges > 0 && <div className="flex justify-between"><span className="text-muted-foreground">Additional Charges</span><span>AED {additionalCharges.toFixed(2)}</span></div>}
            {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Surcharge</span><span>AED {ccFee.toFixed(2)}</span></div>}
            <div className="flex justify-between font-bold text-sm pt-2 border-t border-primary/30">
              <span className="font-cinzel text-primary">GRAND TOTAL</span>
              <span className="text-primary">AED {grandTotal.toFixed(2)}</span>
            </div>
          </div>
        </div>
        <Button onClick={handlePrint} className="w-full mt-2 bg-primary text-primary-foreground">
          <Printer className="h-4 w-4 mr-2" /> Print / Save as PDF
        </Button>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useRef } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { uploadFile } from 'zite-file-upload-sdk';
import { createUpload } from 'zite-endpoints-sdk';

export default function UploadMasterlistFAB() {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleUpload = async () => {
    if (!selectedFile) { toast.error('Please select a file'); return; }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: selectedFile, filename: selectedFile.name });
      await createUpload({ masterlistFile: fileUrl, status: 'Uploaded' });
      toast.success('Masterlist uploaded successfully');
      setOpen(false);
      setSelectedFile(null);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-4 z-50 flex items-center gap-2 bg-primary text-primary-foreground px-4 py-3 rounded-full shadow-lg font-medium text-sm no-print"
      >
        <Upload className="h-4 w-4" />
        Upload Masterlist
      </button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent side="bottom" className="bg-card border-border pb-8">
          <SheetHeader className="mb-4">
            <SheetTitle className="font-cinzel text-primary">Upload Masterlist</SheetTitle>
          </SheetHeader>
          <div className="space-y-4">
            <div>
              <Label className="text-sm text-muted-foreground mb-2 block">Select Excel / CSV File</Label>
              <div
                className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer"
                onClick={() => fileRef.current?.click()}
              >
                {selectedFile ? (
                  <div className="flex items-center justify-center gap-2">
                    <span className="text-sm text-foreground">{selectedFile.name}</span>
                    <button onClick={e => { e.stopPropagation(); setSelectedFile(null); }}>
                      <X className="h-4 w-4 text-muted-foreground" />
                    </button>
                  </div>
                ) : (
                  <div>
                    <Upload className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Tap to select file</p>
                  </div>
                )}
              </div>
              <input ref={fileRef} type="file" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
            </div>
            <Button onClick={handleUpload} disabled={uploading || !selectedFile} className="w-full bg-primary text-primary-foreground">
              {uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Uploading...</> : 'Upload File'}
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  );
}

