import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch all Database rows in batches',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const allRecords: unknown[] = [];
    let offset = 0;
    const limit = 500;
    while (true) {
      const batch = await Database.findAll({ offset, limit });
      if (!batch || batch.length === 0) break;
      allRecords.push(...batch);
      if (batch.length < limit) break;
      offset += limit;
    }
    return allRecords;
  },
});

import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Update a Database row by rowId',
  authenticated: true,
  inputSchema: z.object({
    rowId: z.number(),
    fields: z.record(z.unknown()),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    await Database.update({
      rowId: input.rowId,
      row: input.fields as Parameters<typeof Database.update>[0]['row'],
    });
    return { success: true };
  },
});

