import { useMemo } from 'react';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const grouped = useMemo(() => {
    const filtered = records.filter(r =>
      r.status === 'Pending' || r.status === 'Waiting for Details'
    );
    const searched = applySearch(filtered, searchQuery);
    return groupByMinerName(searched);
  }, [records, searchQuery]);

  const totalCount = useMemo(() => {
    let count = 0;
    grouped.forEach(items => { count += items.length; });
    return count;
  }, [grouped]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle={`${grouped.size} clients · ${totalCount} items`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />
      <div className="px-4 pt-4">
        {grouped.size === 0 ? (
          <div className="text-center py-16 text-muted-foreground">
            <p className="text-sm">No pending records found.</p>
            {searchQuery && <p className="text-xs mt-1">Try clearing your search.</p>}
          </div>
        ) : (
          Array.from(grouped.entries()).map(([minerName, items]) => (
            <AdminClientCard
              key={minerName}
              minerName={minerName}
              records={items}
              onUpdate={onUpdate}
            />
          ))
        )}
      </div>
    </div>
  );
}

import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate } from '@/lib/formatters';
import { calcProfit } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

export default function PulloutReport({ records, onClose }: Props) {
  const forPullout = records.filter(r => r.status === 'For Pullout');
  const bySource = new Map<string, DatabaseRowType[]>();
  for (const r of forPullout) {
    const src = r.source || 'Unknown';
    if (!bySource.has(src)) bySource.set(src, []);
    bySource.get(src)!.push(r);
  }

  const handlePrint = () => {
    window.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Pullout Report — Internal Use Only</DialogTitle>
        </DialogHeader>
        <div className="text-sm">
          <p className="text-xs text-muted-foreground mb-4">Generated: {new Date().toLocaleString()} · Status: For Pullout only</p>
          {bySource.size === 0 ? (
            <p className="text-center text-muted-foreground py-8">No items with "For Pullout" status.</p>
          ) : (
            Array.from(bySource.entries()).map(([source, items]) => {
              const totalProfit = items.reduce((sum, r) => sum + calcProfit(r), 0);
              return (
                <div key={source} className="mb-6">
                  <div className="flex items-center justify-between mb-2 pb-1 border-b border-primary/30">
                    <h3 className="font-cinzel text-sm text-primary">{source}</h3>
                    <span className="text-xs text-muted-foreground">{items.length} items · Profit: {totalProfit.toFixed(2)}</span>
                  </div>
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="text-muted-foreground">
                        <th className="text-left py-1">Client</th>
                        <th className="text-left py-1">Item</th>
                        <th className="text-left py-1">Cat</th>
                        <th className="text-right py-1">Grams</th>
                        <th className="text-right py-1">Date</th>
                        <th className="text-right py-1">Gold Rate</th>
                        <th className="text-right py-1">Profit</th>
                      </tr>
                    </thead>
                    <tbody>
                      {items.map(r => (
                        <tr key={r.id} className="border-b border-border/40">
                          <td className="py-1.5 pr-1">{r.minerName}</td>
                          <td className="py-1.5 pr-1">{r.itemDescription}</td>
                          <td className="py-1.5 pr-1">{r.category}</td>
                          <td className="py-1.5 text-right">{r.grams || 'PC'}</td>
                          <td className="py-1.5 text-right">{formatDate(r.dateOfLive)}</td>
                          <td className="py-1.5 text-right">{r.goldRate?.toFixed(2) || '—'}</td>
                          <td className="py-1.5 text-right">{calcProfit(r).toFixed(2)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              );
            })
          )}
        </div>
        <Button onClick={handlePrint} className="w-full bg-primary text-primary-foreground">
          <Printer className="h-4 w-4 mr-2" /> Print Report
        </Button>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { ChevronDown, FileText, Truck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, calcDueDate } from '@/lib/calculations';
import { formatDate, formatDateObj } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

export default function DispatchClientCard({ minerName, records, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered') fields.deliveredDate = new Date().toISOString();
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-2 rounded-xl border border-border bg-card overflow-hidden">
      <button className="w-full text-left px-4 py-3 flex items-center justify-between" onClick={() => setExpanded(e => !e)}>
        <div className="flex-1 min-w-0">
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Live: {formatDate(first?.dateOfLive)}</span>
            <span>Due: {dueDate}</span>
          </div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3 space-y-2">
          {records.map(record => (
            <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
              <div className="flex items-start justify-between mb-2">
                <div>
                  <p className="text-sm font-medium">{record.itemDescription}</p>
                  <p className="text-xs text-muted-foreground">{record.category} · {record.grams ? `${record.grams}g` : 'PC'}</p>
                </div>
                <StatusBadge status={record.status} />
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-1 text-xs text-muted-foreground">
                  <Truck className="h-3 w-3" />
                  <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                  {(record.freeSf === 'TRUE' || record.freeSf === 'true') && <span className="text-primary">(FREE)</span>}
                </div>
                <Select onValueChange={v => handleStatusChange(record, v)}>
                  <SelectTrigger className="h-7 text-xs w-32 bg-background border-border">
                    <SelectValue placeholder="Set status..." />
                  </SelectTrigger>
                  <SelectContent className="bg-popover border-border">
                    <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                    <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
          ))}
          <Button variant="outline" size="sm" className="w-full border-primary/40 text-primary text-xs" onClick={() => setShowInvoice(true)}>
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => { if (cancelRecord) { await onUpdate(cancelRecord.id, { status: 'Cancelled' }); toast.success('Cancelled'); setCancelRecord(null); } }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ClipboardList } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps } from '@/types';
import { applySearch, groupByLocationSourceMiner } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

const LOCATION_ORDER = ['Local', 'Pinas', 'International'];

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const [showReport, setShowReport] = useState(false);

  const grouped = useMemo(() => {
    const filtered = records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatched');
    const searched = applySearch(filtered, searchQuery);
    return groupByLocationSourceMiner(searched);
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout').length, [records]);

  const sortedLocations = useMemo(() => {
    const keys = Array.from(grouped.keys());
    return [...LOCATION_ORDER.filter(l => keys.includes(l)), ...keys.filter(k => !LOCATION_ORDER.includes(k))];
  }, [grouped]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">
        {sortedLocations.length === 0 ? (
          <div className="text-center py-16 text-muted-foreground text-sm">No dispatch records found.</div>
        ) : (
          sortedLocations.map(location => {
            const bySource = grouped.get(location)!;
            return (
              <div key={location} className="mb-6">
                <div className="flex items-center gap-2 mb-3">
                  <div className="h-px flex-1 bg-border" />
                  <span className="font-cinzel text-xs text-primary px-2">{location.toUpperCase()}</span>
                  <div className="h-px flex-1 bg-border" />
                </div>
                {Array.from(bySource.entries()).map(([source, byMiner]) => (
                  <div key={source} className="mb-4">
                    <p className="text-xs text-muted-foreground mb-2 px-1">Source: <span className="text-foreground">{source}</span></p>
                    {Array.from(byMiner.entries()).map(([miner, items]) => (
                      <DispatchClientCard key={miner} minerName={miner} records={items} onUpdate={onUpdate} />
                    ))}
                  </div>
                ))}
              </div>
            );
          })
        )}
      </div>
      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useState } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcItemPrice, calcItemCost, calcShippingFee, calcCCFee, calcTotalPaid, calcRemainingBalance } from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash'];

export default function FinancialsForm({ record, onUpdate }: Props) {
  const [saving, setSaving] = useState(false);
  const isLayaway = record.modeOfPayment === 'Layaway';
  const [form, setForm] = useState({
    goldRate: record.goldRate?.toString() || '',
    supplierRate: record.supplierRate || '',
    mc: record.mc || '',
    additionalCharges: record.additionalCharges || '',
    amountReceived: record.amountReceived || '',
    la1MonthPayment: record.la1MonthPayment || '',
    la2MonthPayment: record.la2MonthPayment || '',
    la3MonthPayment: record.la3MonthPayment || '',
    la4MonthPayment: record.la4MonthPayment || '',
    remittanceStatus: record.remittanceStatus || '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  const handleSave = async () => {
    setSaving(true);
    try {
      await onUpdate(record.id, {
        goldRate: parseFloat(form.goldRate) || record.goldRate,
        supplierRate: form.supplierRate,
        mc: form.mc,
        additionalCharges: form.additionalCharges,
        amountReceived: form.amountReceived,
        la1MonthPayment: form.la1MonthPayment,
        la2MonthPayment: form.la2MonthPayment,
        la3MonthPayment: form.la3MonthPayment,
        la4MonthPayment: form.la4MonthPayment,
        remittanceStatus: form.remittanceStatus,
      });
      toast.success('Financials saved');
    } finally {
      setSaving(false);
    }
  };

  // Use current form values for live calculation preview
  const previewRecord: DatabaseRowType = {
    ...record,
    goldRate: parseFloat(form.goldRate) || record.goldRate,
    supplierRate: form.supplierRate,
    mc: form.mc,
    additionalCharges: form.additionalCharges,
    amountReceived: form.amountReceived,
    la1MonthPayment: form.la1MonthPayment,
    la2MonthPayment: form.la2MonthPayment,
    la3MonthPayment: form.la3MonthPayment,
    la4MonthPayment: form.la4MonthPayment,
  };

  const itemPrice = calcItemPrice(previewRecord);
  const itemCost = calcItemCost(previewRecord);
  const shippingFee = calcShippingFee(previewRecord);
  const ccFee = calcCCFee(previewRecord);
  const totalPaid = calcTotalPaid(previewRecord);
  const remaining = calcRemainingBalance(previewRecord);

  const numField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input
        type="number"
        value={form[key as keyof typeof form]}
        onChange={e => set(key, e.target.value)}
        disabled={disabled}
        className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-40"
        placeholder="0.00"
      />
    </div>
  );

  return (
    <div className="border-t border-border pt-3 mt-2">
      <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wide">Financials</p>
      <div className="grid grid-cols-2 gap-2 mb-3">
        {numField('Gold Rate', 'goldRate')}
        {numField('Supplier Rate', 'supplierRate')}
        {numField('MC (Making Charge)', 'mc')}
        {numField('Additional Charges', 'additionalCharges')}
        {numField('Amount Received', 'amountReceived')}
      </div>

      {isLayaway && (
        <div className="grid grid-cols-2 gap-2 mb-3">
          <p className="col-span-2 text-xs text-muted-foreground">Layaway Payments</p>
          {numField('Month 1', 'la1MonthPayment')}
          {numField('Month 2', 'la2MonthPayment')}
          {numField('Month 3', 'la3MonthPayment')}
          {numField('Month 4', 'la4MonthPayment')}
        </div>
      )}
      {!isLayaway && (
        <div className="grid grid-cols-2 gap-2 mb-3 opacity-40">
          <p className="col-span-2 text-xs text-muted-foreground">Layaway Payments (locked — not Layaway MOP)</p>
          {numField('Month 1', 'la1MonthPayment', true)}
          {numField('Month 2', 'la2MonthPayment', true)}
          {numField('Month 3', 'la3MonthPayment', true)}
          {numField('Month 4', 'la4MonthPayment', true)}
        </div>
      )}

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Remittance Status</Label>
        <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select remittance..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {REMITTANCE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="bg-secondary/50 rounded-lg p-3 mb-3 space-y-1 text-xs">
        <div className="flex justify-between"><span className="text-muted-foreground">Item Price</span><span>{record.currency || 'AED'} {itemPrice.toFixed(2)}</span></div>
        <div className="flex justify-between"><span className="text-muted-foreground">Item Cost</span><span>{record.currency || 'AED'} {itemCost.toFixed(2)}</span></div>
        <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>AED {shippingFee.toFixed(2)}</span></div>
        {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Fee</span><span>AED {ccFee.toFixed(2)}</span></div>}
        <div className="flex justify-between"><span className="text-muted-foreground">Total Paid</span><span>AED {totalPaid.toFixed(2)}</span></div>
        <div className={`flex justify-between font-bold pt-1 border-t border-border ${remaining > 0 ? 'text-destructive' : 'text-green-400'}`}>
          <span>Remaining Balance</span><span>AED {remaining.toFixed(2)}</span>
        </div>
      </div>

      <Button onClick={handleSave} disabled={saving} className="w-full bg-primary text-primary-foreground text-xs h-8">
        {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Save Financials'}
      </Button>
    </div>
  );
}

import { useState } from 'react';
import { ChevronDown, FileText } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { calcRemainingBalance, calcShippingFee, calcCCFee, calcItemPrice } from '@/lib/calculations';
import { formatDateObj } from '@/lib/formatters';
import { calcDueDate } from '@/lib/calculations';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import FinancialsForm from './FinancialsForm';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

export default function AccountsClientCard({ minerName, records, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [expandedItem, setExpandedItem] = useState<number | null>(null);
  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));
  const totalRemaining = records.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button className="w-full text-left px-4 py-3 flex items-center justify-between" onClick={() => setExpanded(e => !e)}>
        <div className="flex-1 min-w-0">
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Due: {dueDate}</span>
          </div>
          {totalRemaining > 0 && (
            <span className="text-xs font-medium text-destructive">Balance: AED {totalRemaining.toFixed(2)}</span>
          )}
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {records.map(record => (
            <div key={record.id} className="mb-3 rounded-lg border border-border/50 bg-secondary/20 overflow-hidden">
              <button
                className="w-full text-left p-3 flex items-start justify-between"
                onClick={() => setExpandedItem(expandedItem === record.id ? null : record.id)}
              >
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <p className="text-sm font-medium truncate">{record.itemDescription}</p>
                    <StatusBadge status={record.status} />
                  </div>
                  <div className="text-xs text-muted-foreground">
                    {record.category} · {record.grams ? `${record.grams}g` : 'PC'} · {record.modeOfPayment}
                  </div>
                  <div className="flex gap-3 text-xs mt-1">
                    <span className="text-muted-foreground">Price: <span className="text-foreground">{record.currency || 'AED'} {calcItemPrice(record).toFixed(2)}</span></span>
                    <span className="text-muted-foreground">SF: <span className="text-foreground">AED {calcShippingFee(record).toFixed(2)}</span></span>
                    {calcCCFee(record) > 0 && <span className="text-muted-foreground">CC: <span className="text-foreground">AED {calcCCFee(record).toFixed(2)}</span></span>}
                  </div>
                  <div className="text-xs mt-0.5">
                    <span className={`font-medium ${calcRemainingBalance(record) > 0 ? 'text-destructive' : 'text-green-400'}`}>
                      Balance: AED {calcRemainingBalance(record).toFixed(2)}
                    </span>
                  </div>
                </div>
                <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground shrink-0 ml-2 mt-1 transition-transform ${expandedItem === record.id ? 'rotate-180' : ''}`} />
              </button>
              {expandedItem === record.id && (
                <div className="px-3 pb-3">
                  <FinancialsForm record={record} onUpdate={onUpdate} />
                </div>
              )}
            </div>
          ))}
          <Button variant="outline" size="sm" className="w-full mt-1 border-primary/40 text-primary text-xs" onClick={() => setShowInvoice(true)}>
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
    </div>
  );
}

import { useMemo } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { calcRemainingBalance } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const { activeGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(records, searchQuery);

    const active = searched.filter(r => {
      const isDeliveredOrLayaway = r.status === 'Delivered' || r.modeOfPayment === 'Layaway';
      if (!isDeliveredOrLayaway) return false;
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received');
      if (isCleared) return false;
      const isPendingOrEmpty = !remStatus || remStatus === 'pending payment';
      const hasBalance = calcRemainingBalance(r) > 0;
      return isPendingOrEmpty || hasBalance;
    });

    const cleared = searched.filter(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      return remStatus.includes('secured') || remStatus.includes('received');
    });

    return {
      activeGroups: groupByMinerName(active),
      clearedGroups: groupByMinerName(cleared),
    };
  }, [records, searchQuery]);

  const renderGroups = (groups: Map<string, typeof records>) => (
    groups.size === 0 ? (
      <div className="text-center py-16 text-muted-foreground text-sm">No records found.</div>
    ) : (
      Array.from(groups.entries()).map(([minerName, items]) => (
        <AccountsClientCard key={minerName} minerName={minerName} records={items} onUpdate={onUpdate} />
      ))
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />
      <div className="px-4 pt-4">
        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({activeGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>
          <TabsContent value="active">{renderGroups(activeGroups)}</TabsContent>
          <TabsContent value="cleared">{renderGroups(clearedGroups)}</TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

interface Props {
  title: string;
  value: string;
  subtitle?: string;
  highlight?: boolean;
}

export default function KpiCard({ title, value, subtitle, highlight }: Props) {
  return (
    <div className={`rounded-xl border p-4 ${highlight ? 'border-primary/40 bg-accent/20' : 'border-border bg-card'}`}>
      <p className="text-xs text-muted-foreground uppercase tracking-wide mb-1">{title}</p>
      <p className={`font-cinzel text-2xl ${highlight ? 'text-primary' : 'text-foreground'}`}>{value}</p>
      {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Calendar } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps } from '@/types';
import { calcProfitAED, calcRemainingBalanceAED } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import { startOfWeek, startOfMonth, subMonths, isValid, parseISO, isAfter, isBefore } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);

  const filtered = useMemo(() => {
    const base = records.filter(r => r.status !== 'Cancelled');
    if (range === 'all') return base;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseISO(r.dateOfLive);
      if (!isValid(d)) return false;
      if (isAfter(from, d)) return false;
      if (to && isBefore(to, d)) return false;
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const kpis = useMemo(() => {
    const totalProfit = filtered.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered').length;
    const outstanding = filtered
      .filter(r => r.status === 'Delivered' || r.modeOfPayment === 'Layaway')
      .reduce((sum, r) => sum + Math.max(0, calcRemainingBalanceAED(r)), 0);
    return { totalProfit, totalSold, outstanding };
  }, [filtered]);

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Read-only executive view" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3 mb-6">
          <KpiCard
            title="Total Expected Profit"
            value={`AED ${kpis.totalProfit.toFixed(2)}`}
            subtitle={`${filtered.length} active records`}
            highlight
          />
          <KpiCard
            title="Total Items Sold"
            value={kpis.totalSold.toString()}
            subtitle="Delivered items"
          />
          <KpiCard
            title="Outstanding Receivables"
            value={`AED ${kpis.outstanding.toFixed(2)}`}
            subtitle="Sum of remaining balances"
          />
        </div>

        <div className="rounded-xl border border-border bg-card overflow-hidden">
          <div className="px-4 py-3 border-b border-border">
            <p className="font-cinzel text-xs text-primary">RECENT RECORDS ({filtered.length})</p>
          </div>
          <div className="divide-y divide-border max-h-96 overflow-y-auto">
            {filtered.slice(0, 100).map(r => (
              <div key={r.id} className="px-4 py-2.5 flex items-center justify-between">
                <div className="min-w-0 flex-1">
                  <p className="text-xs font-medium truncate">{r.minerName}</p>
                  <p className="text-xs text-muted-foreground truncate">{r.itemDescription}</p>
                </div>
                <div className="text-right ml-2 shrink-0">
                  <p className="text-xs text-muted-foreground">{formatDate(r.dateOfLive)}</p>
                  <p className="text-xs text-primary">AED {calcProfitAED(r).toFixed(2)}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';

export default function App() {
  const { user, isLoading, loginWithRedirect } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (!isLoading && !user) loginWithRedirect();
  }, [isLoading, user, loginWithRedirect]);

  useEffect(() => {
    if (!user) return;
    setDataLoading(true);
    getRecords({})
      .then(data => setRecords((data as DatabaseRowType[]) || []))
      .catch(() => toast.error('Failed to load records'))
      .finally(() => setDataLoading(false));
  }, [user]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      // Re-fetch to restore correct state
      getRecords({}).then(data => setRecords((data as DatabaseRowType[]) || []));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <p className="font-cinzel text-2xl text-primary mb-2">Jewelry CRM</p>
          <p className="text-muted-foreground text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) return null;

  const role = getUserRole(user.email);
  if (!role) return <AccessDenied email={user.email} />;

  const tabProps = { records, searchQuery, onSearchChange: setSearchQuery, onUpdate: handleUpdate };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />
      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <>
          {role === 'admin' && <AdminPipeline {...tabProps} />}
          {role === 'dispatch' && <DispatchBoard {...tabProps} />}
          {role === 'accounts' && <AccountsTracking {...tabProps} />}
          {role === 'bossing' && <BossingDashboard {...tabProps} />}
          <UploadMasterlistFAB />
        </>
      )}
    </div>
  );
}

