// ============================================================
// ROLE CONFIGURATION
// Add email addresses to the arrays below to grant access.
// Each user sees ONLY their assigned tab.
// ============================================================
export const roleConfig = {
  adminEmails: ["reynanteevillegas@gmail.com"] as string[],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: ["reynanteevillegas@gmail.com"] as string[],
};

export type UserRole = 'admin' | 'dispatch' | 'accounts' | 'bossing' | null;

export function getUserRole(email: string): UserRole {
  const e = email.toLowerCase();
