import { useEffect, useState } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (!user) return;
    setDataLoading(true);
    getRecords({})
      .then(data => setRecords((data as DatabaseRowType[]) || []))
      .catch(() => toast.error('Failed to load records'))
      .finally(() => setDataLoading(false));
  }, [user]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      // Re-fetch to restore correct state
      getRecords({}).then(data => setRecords((data as DatabaseRowType[]) || []));
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <p className="font-cinzel text-2xl text-primary mb-2">Jewelry CRM</p>
          <p className="text-muted-foreground text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) return null;

  const role = getUserRole(user.email);
  if (!role) return <AccessDenied email={user.email} />;

  const tabProps = { records, searchQuery, onSearchChange: setSearchQuery, onUpdate: handleUpdate };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />
      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <>
          {role === 'admin' && <AdminPipeline {...tabProps} />}
          {role === 'dispatch' && <DispatchBoard {...tabProps} />}
          {role === 'accounts' && <AccountsTracking {...tabProps} />}
          {role === 'bossing' && <BossingDashboard {...tabProps} />}
          <UploadMasterlistFAB />
        </>
      )}
    </div>
  );
}

import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate, formatDateObj } from '@/lib/formatters';
import { calcItemPrice, calcShippingFee, calcCCFee, calcDueDate, toAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const first = records[0];
  const currency = first?.currency || 'AED';
  const subtotal = records.reduce((sum, r) => sum + calcItemPrice(r), 0);
  const subtotalAED = records.reduce((sum, r) => sum + toAED(calcItemPrice(r), r.currency), 0);
  const shippingFee = first ? calcShippingFee(first) : 0;
  const ccFee = first ? calcCCFee(first) : 0;
  const additionalCharges = parseFloat(first?.additionalCharges || '0') || 0;
  const grandTotal = subtotalAED + shippingFee + ccFee + additionalCharges;
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Invoice</title><style>
      body { font-family: 'Lato', sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; }
      h1, h2, .cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
      table { width: 100%; border-collapse: collapse; margin-top: 12px; }
      th { background: #f5f0e8; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 13px; }
      .total-row td { font-weight: bold; border-top: 2px solid #C9A84C; }
      .gold { color: #C9A84C; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Client Invoice</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <div className="mb-4 pb-4 border-b border-border">
            <h2 className="font-cinzel text-lg text-primary mb-1">INVOICE</h2>
            <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
              <span>Client: <span className="text-foreground font-medium">{first?.minerName}</span></span>
              <span>Date: <span className="text-foreground">{formatDate(first?.dateOfLive)}</span></span>
              <span>Region: <span className="text-foreground">{first?.regions || '—'}</span></span>
              <span>Due: <span className="text-foreground">{dueDate}</span></span>
              <span className="col-span-2">Payment: <span className="text-foreground">{first?.modeOfPayment || '—'}</span></span>
