import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate, formatDateObj } from '@/lib/formatters';
import { calcItemPrice, calcShippingFee, calcCCFee, calcDueDate, fromAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const first = records[0];
  const currency = first?.currency || 'AED';

  // All amounts in client currency
  const subtotal = records.reduce((sum, r) => sum + calcItemPrice(r), 0);
  const shippingFeeAED = first ? calcShippingFee(first) : 0;
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const additionalChargesAED = parseFloat(first?.additionalCharges || '0') || 0;
  const shippingFee = fromAED(shippingFeeAED, currency);
  const ccFee = fromAED(ccFeeAED, currency);
  const additionalCharges = fromAED(additionalChargesAED, currency);
  const grandTotal = subtotal + shippingFee + ccFee + additionalCharges;
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Invoice</title><style>
      body { font-family: 'Lato', sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; }
      h1, h2, .cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
      table { width: 100%; border-collapse: collapse; margin-top: 12px; }
      th { background: #f5f0e8; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 13px; }
      .total-row td { font-weight: bold; border-top: 2px solid #C9A84C; }
      .gold { color: #C9A84C; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Client Invoice</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <div className="mb-4 pb-4 border-b border-border">
            <h2 className="font-cinzel text-lg text-primary mb-1">INVOICE</h2>
            <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
              <span>Client: <span className="text-foreground font-medium">{first?.minerName}</span></span>
              <span>Date: <span className="text-foreground">{formatDate(first?.dateOfLive)}</span></span>
              <span>Region: <span className="text-foreground">{first?.regions || '—'}</span></span>
              <span>Due: <span className="text-foreground">{dueDate}</span></span>
              <span className="col-span-2">Payment: <span className="text-foreground">{first?.modeOfPayment || '—'}</span></span>
            </div>
          </div>
          <table className="w-full text-xs mb-4">
            <thead>
              <tr className="border-b border-border">
                <th className="text-left py-1 text-muted-foreground font-medium">Item</th>
                <th className="text-left py-1 text-muted-foreground font-medium">Cat</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Grams</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Rate</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Price</th>
              </tr>
            </thead>
            <tbody>
