import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate } from '@/lib/formatters';
import { calcProfitAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

function groupByDateThenMiner(records: DatabaseRowType[]) {
  const byDate = new Map<string, Map<string, DatabaseRowType[]>>();
  for (const r of records) {
    const dateKey = r.dateOfLive || 'Unknown Date';
    const miner = r.minerName || 'Unknown';
    if (!byDate.has(dateKey)) byDate.set(dateKey, new Map());
    const byMiner = byDate.get(dateKey)!;
    if (!byMiner.has(miner)) byMiner.set(miner, []);
    byMiner.get(miner)!.push(r);
  }
  // Sort dates ascending
  return new Map([...byDate.entries()].sort((a, b) => a[0].localeCompare(b[0])));
}

export default function PulloutReport({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const forPullout = records.filter(r => r.status === 'For Pullout');
  const grouped = groupByDateThenMiner(forPullout);

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Pullout Report</title><style>
      body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
      h2 { font-size: 16px; margin-bottom: 4px; }
      h3 { font-size: 13px; margin: 12px 0 4px; }
      h4 { font-size: 11px; margin: 8px 0 2px; color: #555; }
      table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
      th { background: #f0f0f0; padding: 5px 6px; text-align: left; font-size: 11px; }
      th.r, td.r { text-align: right; }
      td { padding: 5px 6px; border-bottom: 1px solid #ddd; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Pullout Report — Internal Use Only</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <p className="text-xs text-muted-foreground mb-4">
            Generated: {new Date().toLocaleString()} · {forPullout.length} items for pullout
          </p>
          {grouped.size === 0 ? (
            <p className="text-center text-muted-foreground py-8">No items with "For Pullout" status.</p>
          ) : (
            Array.from(grouped.entries()).map(([dateKey, byMiner]) => (
              <div key={dateKey} className="mb-6">
                <div className="flex items-center gap-2 mb-3">
                  <div className="h-px flex-1 bg-border" />
                  <span className="font-cinzel text-xs text-primary px-2">{formatDate(dateKey)}</span>
                  <div className="h-px flex-1 bg-border" />
                </div>
                {Array.from(byMiner.entries()).map(([miner, items]) => {
                  const totalProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
                  return (
                    <div key={miner} className="mb-4">
                      <div className="flex justify-between items-center mb-1.5 pb-1 border-b border-primary/30">
                        <span className="text-xs font-medium text-foreground">{miner}</span>
                        <span className="text-xs text-muted-foreground">{items.length} item{items.length !== 1 ? 's' : ''} · Profit: AED {totalProfit.toFixed(2)}</span>
                      </div>
                      <table className="w-full text-xs">
                        <thead>
                          <tr className="text-muted-foreground">
                            <th className="text-left py-1 font-medium">Item</th>
                            <th className="text-left py-1 font-medium">Cat</th>
                            <th className="text-right py-1 font-medium">Grams</th>
                            <th className="text-right py-1 font-medium">Rate</th>
                            <th className="text-right py-1 font-medium">Profit (AED)</th>
                          </tr>
                        </thead>
                        <tbody>
                          {items.map(r => (
                            <tr key={r.id} className="border-b border-border/40">
                              <td className="py-1.5 pr-2">{r.itemDescription}</td>
                              <td className="py-1.5">{r.category}</td>
                              <td className="py-1.5 text-right">{r.grams || 'PC'}</td>
                              <td className="py-1.5 text-right">{r.goldRate ? Number(r.goldRate).toFixed(2) : '—'}</td>
                              <td className="py-1.5 text-right">{calcProfitAED(r).toFixed(2)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  );
                })}
              </div>
            ))
          )}
        </div>
        <Button onClick={handlePrint} className="w-full bg-primary text-primary-foreground">
          <Printer className="h-4 w-4 mr-2" /> Print Report
        </Button>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useRef } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { uploadFile } from 'zite-file-upload-sdk';
import { createUpload } from 'zite-endpoints-sdk';

export default function UploadMasterlistFAB() {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleUpload = async () => {
    if (!selectedFile) { toast.error('Please select a file'); return; }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: selectedFile, filename: selectedFile.name });
      await createUpload({ masterlistFile: fileUrl, status: 'Uploaded' });
      toast.success('Masterlist uploaded successfully');
      setOpen(false);
      setSelectedFile(null);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-4 z-50 flex items-center gap-2 bg-primary text-primary-foreground px-4 py-3 rounded-full shadow-lg font-medium text-sm no-print"
      >
        <Upload className="h-4 w-4" />
        Upload Masterlist
      </button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent side="bottom" className="bg-card border-border pb-8">
          <SheetHeader className="mb-4">
            <SheetTitle className="font-cinzel text-primary">Upload Masterlist</SheetTitle>
          </SheetHeader>
          <div className="space-y-4">
            <div>
              <Label className="text-sm text-muted-foreground mb-2 block">Select Excel / CSV File</Label>
              <div
                className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer"
                onClick={() => fileRef.current?.click()}
              >
                {selectedFile ? (
                  <div className="flex items-center justify-center gap-2">
                    <span className="text-sm text-foreground">{selectedFile.name}</span>
                    <button onClick={e => { e.stopPropagation(); setSelectedFile(null); }}>
                      <X className="h-4 w-4 text-muted-foreground" />
                    </button>
                  </div>
                ) : (
                  <div>
                    <Upload className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Tap to select file</p>
                  </div>
                )}
              </div>
              <input ref={fileRef} type="file" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
            </div>
            <Button onClick={handleUpload} disabled={uploading || !selectedFile} className="w-full bg-primary text-primary-foreground">
              {uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Uploading...</> : 'Upload File'}
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  );
}

