export type DatabaseRowType = {
  orderId?: string;
  dateOfLive?: string;
  page?: string;
  liverName?: string;
  locationOfMiner?: string;
  minerName?: string;
  itemDescription?: string;
  grams?: number;
  source?: string;
  category?: string;
  mc?: string;
  goldRate?: number;
  supplierRate?: string;
  clientRate?: number;
  profit?: string;
  modeOfSale?: string;
  status?: string;
  modeOfPayment?: string;
  downpayment?: string;
  la1MonthPayment?: string;
  la2MonthPayment?: string;
  la3MonthPayment?: string;
  la4MonthPayment?: string;
  liverAdminRemarks?: string;
  dispatchDate?: string;
  deliveredDate?: string;
  reviewChasing?: string;
  fbProfileName?: string;
  regions?: string;
  remittanceStatus?: string;
  currency?: string;
  additionalCharges?: string;
  amountReceived?: string;
  freeSf?: string; // 'TRUE' | '' — stored as string in Google Sheets
  id: number;
};

export type ClientGroup = {
  minerName: string;
  records: DatabaseRowType[];
};

export type TabProps = {
  records: DatabaseRowType[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
};

import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

/** Robustly parse a date string from Google Sheets (handles ISO, MM/DD/YYYY, "March 04,2026", etc.) */
export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  if (!grams || isNaN(grams)) return true;
  if (record.category?.toLowerCase() === 'silver') return true;
  return false;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

/** Convert client rate to AED. PHP / 16.6, AED as-is. */
export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  if (record.currency === 'PHP') return rate / 16.6;
  return rate;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6;
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6;
  return value;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

export function calcItemCost(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  if (isPcItem(record)) return supplierRate + mc;
  return (n(record.goldRate) * n(record.grams)) + mc;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const isSilver = record.category?.toLowerCase() === 'silver';
  if (isSilver) return 0;
  const rateAED = clientRateAED(record);
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const mc = n(record.mc);
  if (!grams) return rateAED - (n(record.supplierRate) + mc);
  return (rateAED * grams) - ((goldRate + mc) * grams);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCost(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

/** Due Date = Date of Live + 24 hours. */
export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

/** Overdue if status is Pending AND current time > due date. */
export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType } from 'zite-integrations-backend-sdk';

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
]);

export default createEndpoint({
  description: 'Update a Database row by rowId',
  inputSchema: z.object({
    rowId: z.number(),
    fields: z.record(z.unknown()),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const sanitized: Partial<DatabaseRowType> = {};
    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        // Always store as string 'TRUE' or ''
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? 'TRUE' : '';
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
      }
    }
    await Database.update({ rowId: input.rowId, row: sanitized });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, Uploads } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Create a new Upload record with uploader email',
  inputSchema: z.object({
    masterlistFile: z.string(),
    status: z.string().optional(),
  }),
  outputSchema: z.object({ success: z.boolean(), id: z.number() }),
  execute: async ({ input, context }) => {
    const row = await Uploads.create({
      row: {
        uploadId: context.user.email, // Staff/Uploader field
        masterlistFile: input.masterlistFile,
        status: input.status || 'Uploaded',
      },
    });
    return { success: true, id: row.id };
  },
});

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';

const ADMIN_TABS = [
  { key: 'admin', label: 'Admin' },
  { key: 'dispatch', label: 'Dispatch' },
  { key: 'accounts', label: 'Accounts' },
  { key: 'bossing', label: 'Bossing' },
] as const;

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  const fetchRecords = useCallback(() => {
    if (!user) return;
    setDataLoading(true);
    getRecords({})
      .then(data => setRecords((data as DatabaseRowType[]) || []))
      .catch(() => toast.error('Failed to load records'))
      .finally(() => setDataLoading(false));
  }, [user]);

  useEffect(() => { fetchRecords(); }, [fetchRecords]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      fetchRecords();
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <p className="font-cinzel text-2xl text-primary mb-2">Jewelry CRM</p>
          <p className="text-muted-foreground text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) return null;

  const role = getUserRole(user.email);
  if (!role) return <AccessDenied email={user.email} />;

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />
      {role === 'admin' && (
        <div className="flex border-b border-border sticky top-0 z-30 bg-background">
          {ADMIN_TABS.map(tab => (
            <button
              key={tab.key}
              onClick={() => setActiveTab(tab.key)}
              className={`flex-1 py-2.5 text-xs font-cinzel tracking-wide transition-colors ${
                activeTab === tab.key
                  ? 'text-primary border-b-2 border-primary'
                  : 'text-muted-foreground'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      )}
      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <>
          {role === 'admin' && activeTab === 'admin' && <AdminPipeline {...tabProps} />}
          {role === 'admin' && activeTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {role === 'admin' && activeTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {role === 'admin' && activeTab === 'bossing' && <BossingDashboard {...tabProps} />}
          {role === 'dispatch' && <DispatchBoard {...tabProps} />}
          {role === 'accounts' && <AccountsTracking {...tabProps} />}
          {role === 'bossing' && <BossingDashboard {...tabProps} />}
          <UploadMasterlistFAB onRefresh={fetchRecords} />
        </>
      )}
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { Upload, X, Loader2, CheckCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { uploadFile } from 'zite-file-upload-sdk';
import { createUpload, getUploads } from 'zite-endpoints-sdk';

interface Props {
  onRefresh: () => void;
}

export default function UploadMasterlistFAB({ onRefresh }: Props) {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const uploadIdRef = useRef<number | null>(null);

  useEffect(() => {
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, []);

  const startPolling = (rowId: number) => {
    uploadIdRef.current = rowId;
    setProcessing(true);
    pollRef.current = setInterval(async () => {
      try {
        const uploads = await getUploads({});
        const row = (uploads as Array<{ id: number; status?: string }>).find(u => u.id === rowId);
        if (row?.status === 'Processed') {
          clearInterval(pollRef.current!);
          setProcessing(false);
          toast.success('Masterlist processed! Records refreshed.');
          onRefresh();
          setOpen(false);
          setSelectedFile(null);
        }
      } catch { /* ignore poll errors */ }
    }, 4000);
  };

  const handleUpload = async () => {
    if (!selectedFile) { toast.error('Please select a file'); return; }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: selectedFile, filename: selectedFile.name });
      const result = await createUpload({ masterlistFile: fileUrl, status: 'Uploaded' });
      toast.success('File uploaded! Waiting for processing...');
      startPolling(result.id);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-4 z-50 flex items-center gap-2 bg-primary text-primary-foreground px-4 py-3 rounded-full shadow-lg font-medium text-sm no-print"
      >
        {processing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Upload className="h-4 w-4" />}
        {processing ? 'Processing...' : 'Upload Masterlist'}
      </button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent side="bottom" className="bg-card border-border pb-8">
          <SheetHeader className="mb-4">
            <SheetTitle className="font-cinzel text-primary">Upload Masterlist</SheetTitle>
          </SheetHeader>
          {processing ? (
            <div className="flex flex-col items-center py-8 gap-3">
              <Loader2 className="h-8 w-8 animate-spin text-primary" />
              <p className="text-sm text-muted-foreground">Processing masterlist... App will auto-refresh when done.</p>
            </div>
          ) : (
            <div className="space-y-4">
              <div>
                <Label className="text-sm text-muted-foreground mb-2 block">Select Excel / CSV File</Label>
                <div
                  className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer"
                  onClick={() => fileRef.current?.click()}
                >
                  {selectedFile ? (
                    <div className="flex items-center justify-center gap-2">
                      <CheckCircle className="h-4 w-4 text-primary" />
                      <span className="text-sm text-foreground">{selectedFile.name}</span>
                      <button onClick={e => { e.stopPropagation(); setSelectedFile(null); }}>
                        <X className="h-4 w-4 text-muted-foreground" />
                      </button>
                    </div>
                  ) : (
                    <div>
                      <Upload className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
                      <p className="text-sm text-muted-foreground">Tap to select file</p>
                    </div>
                  )}
                </div>
                <input ref={fileRef} type="file" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
              </div>
              <Button onClick={handleUpload} disabled={uploading || !selectedFile} className="w-full bg-primary text-primary-foreground">
                {uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Uploading...</> : 'Upload File'}
              </Button>
            </div>
          )}
        </SheetContent>
      </Sheet>
    </>
  );
}

import { useState } from 'react';
import { ChevronDown, FileText, MapPin, User, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue, calcDueDate } from '@/lib/calculations';
import { formatDate, formatDateObj } from '@/lib/formatters';
import AdminItemRow from './AdminItemRow';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

export default function AdminClientCard({ minerName, records, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const first = records[0];
  const hasOverdue = records.some(isOverdue);
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  // Propagate a field update to ALL records in this client group
  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    await Promise.all(records.map(r => onUpdate(r.id, fields)));
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {hasOverdue && (
              <span className="shrink-0 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">OVERDUE</span>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{first?.locationOfMiner || '—'}</span>
            {first?.fbProfileName && <span className="flex items-center gap-1"><User className="h-3 w-3" />{first.fbProfileName}</span>}
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
          </div>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>Live: {formatDate(first?.dateOfLive)}</span>
            <span>Due: {dueDate}</span>
          </div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {records.map(record => (
            <AdminItemRow
              key={record.id}
              record={record}
              onUpdate={onUpdate}
              onGroupUpdate={handleGroupUpdate}
            />
          ))}
          <Button
            variant="outline"
            size="sm"
            className="w-full mt-2 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
    </div>
  );
}

import { useState } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = remarks.toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('cod')) return { modeOfPayment: 'COD' };
  return null;
}

export default function AdminItemRow({ record, onUpdate, onGroupUpdate }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const overdue = isOverdue(record);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const updates: Partial<DatabaseRowType> = { liverAdminRemarks: val };
    const autoFill = detectAutoFill(val);
    if (autoFill) {
      Object.assign(updates, autoFill);
      await onGroupUpdate(updates);
      toast.success('Auto-filled from remarks');
    } else {
      await onUpdate(record.id, updates);
    }
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    await onGroupUpdate({ regions: region });
  };

  const handleStatusChange = async (newStatus: string) => {
    if (newStatus === 'Cancelled') { setShowCancel(true); return; }
    if (newStatus === 'For Pullout') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required for pullout'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }
    await onUpdate(record.id, { status: newStatus });
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> OVERDUE
              </span>
            )}
          </div>
        </div>
        <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">{record.grams ? `${record.grams}g` : 'PC'}</p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {record.locationOfMiner === 'Local' && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div>
          <Label className="text-xs text-muted-foreground">Liver/Admin Remarks</Label>
          <Textarea
            value={remarks}
            onChange={e => { setRemarks(e.target.value); debouncedRemarks(e.target.value); }}
            className="h-14 text-xs bg-background border-border mt-0.5 resize-none"
            placeholder="e.g. TABBY APPROVED, COD..."
          />
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Switch
              checked={record.freeSf === 'TRUE' || record.freeSf === 'true'}
              onCheckedChange={v => onGroupUpdate({ freeSf: v ? 'TRUE' : '' })}
              className="scale-90"
            />
            <Label className="text-xs">FREE SF</Label>
          </div>
          <Select onValueChange={handleStatusChange}>
            <SelectTrigger className="h-7 text-xs w-36 bg-background border-border">
              <SelectValue placeholder="Change status..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="For Pullout" className="text-xs">For Pullout</SelectItem>
              <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <AlertDialog open={showCancel} onOpenChange={setShowCancel}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground"
              onClick={async () => { await onUpdate(record.id, { status: 'Cancelled' }); toast.success('Item cancelled'); }}
            >
              Cancel Item
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);

  const { forPullout, dispatched } = useMemo(() => {
    const filtered = records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatched');
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByMinerName(searched.filter(r => r.status === 'For Pullout')),
      dispatched: groupByMinerName(searched.filter(r => r.status === 'Dispatched')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout').length, [records]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">
        {/* FOR PULLOUT section */}
        <div className="flex items-center gap-2 mb-3">
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT ({forPullout.size})</span>
          <div className="h-px flex-1 bg-purple-400/30" />
        </div>
        {forPullout.size === 0 ? (
          <p className="text-xs text-muted-foreground mb-6 px-1">No items for pullout.</p>
        ) : (
          <div className="mb-6">
            {Array.from(forPullout.entries()).map(([miner, items]) => (
              <DispatchClientCard key={miner} minerName={miner} records={items} onUpdate={onUpdate} userEmail={userEmail} />
            ))}
          </div>
        )}

        {/* DISPATCHED section */}
        <div className="flex items-center gap-2 mb-3">
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED ({dispatched.size})</span>
          <div className="h-px flex-1 bg-orange-400/30" />
        </div>
        {dispatched.size === 0 ? (
          <p className="text-xs text-muted-foreground px-1">No dispatched items.</p>
        ) : (
          Array.from(dispatched.entries()).map(([miner, items]) => (
            <DispatchClientCard key={miner} minerName={miner} records={items} onUpdate={onUpdate} userEmail={userEmail} />
          ))
        )}
      </div>
      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useState } from 'react';
import { FileText, Truck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

export default function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const first = records[0];

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered') fields.deliveredDate = new Date().toISOString();

    // Append audit trail to remarks
    if (userEmail) {
      const date = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      const audit = `[${newStatus} by ${userEmail} on ${date}]`;
      fields.liverAdminRemarks = record.liverAdminRemarks
        ? `${record.liverAdminRemarks} ${audit}`
        : audit;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      {/* Header */}
      <div className="px-4 py-2.5 border-b border-border/50 flex items-center justify-between">
        <div>
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Live: {formatDate(first?.dateOfLive)}</span>
          </div>
        </div>
        <Button variant="outline" size="sm" className="border-primary/40 text-primary text-xs h-7" onClick={() => setShowInvoice(true)}>
          <FileText className="h-3 w-3 mr-1" /> Invoice
        </Button>
      </div>

      {/* Items — always visible */}
      <div className="px-3 py-2 space-y-2">
        {records.map(record => (
          <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
            <div className="flex items-start justify-between mb-2">
              <div>
                <p className="text-sm font-medium">{record.itemDescription}</p>
                <p className="text-xs text-muted-foreground">{record.category} · {record.grams ? `${record.grams}g` : 'PC'}</p>
              </div>
              <StatusBadge status={record.status} />
            </div>
            <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
              <Truck className="h-3 w-3" />
              <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
              {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
            </div>
            {record.liverAdminRemarks && (
              <p className="text-xs text-muted-foreground/70 italic mb-2 truncate">{record.liverAdminRemarks}</p>
            )}
            <Select onValueChange={v => handleStatusChange(record, v)}>
              <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                <SelectValue placeholder="Set status..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
              </SelectContent>
            </Select>
          </div>
        ))}
      </div>

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcItemPrice, calcShippingFee, calcCCFee, calcTotalPaid, calcRemainingBalance, toAED, calcProfitAED } from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash'];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping'];

export default function FinancialsForm({ record, onUpdate }: Props) {
  const [saving, setSaving] = useState(false);
  const isLayaway = record.modeOfPayment === 'Layaway';
  const [form, setForm] = useState({
    goldRate: record.goldRate?.toString() || '',
    mc: record.mc || '',
    supplierRate: record.supplierRate || '',
    additionalCharges: record.additionalCharges || '',
    downpayment: record.downpayment || '',
    amountReceived: record.amountReceived || '',
    la1MonthPayment: record.la1MonthPayment || '',
    la2MonthPayment: record.la2MonthPayment || '',
    la3MonthPayment: record.la3MonthPayment || '',
    la4MonthPayment: record.la4MonthPayment || '',
    remittanceStatus: record.remittanceStatus || '',
    modeOfSale: record.modeOfSale || '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  // Auto-compute supplierRate = goldRate + mc
  useEffect(() => {
    const gr = parseFloat(form.goldRate) || 0;
    const mc = parseFloat(form.mc) || 0;
    if (gr > 0 || mc > 0) {
      setForm(p => ({ ...p, supplierRate: (gr + mc).toFixed(2) }));
    }
  }, [form.goldRate, form.mc]);

  const handleSave = async () => {
    setSaving(true);
    try {
      const previewRecord = buildPreview();
      const computedProfit = calcProfitAED(previewRecord).toFixed(2);
      await onUpdate(record.id, {
        goldRate: parseFloat(form.goldRate) || record.goldRate,
        supplierRate: form.supplierRate,
        mc: form.mc,
        additionalCharges: form.additionalCharges,
        downpayment: form.downpayment,
        amountReceived: form.amountReceived,
        la1MonthPayment: form.la1MonthPayment,
        la2MonthPayment: form.la2MonthPayment,
        la3MonthPayment: form.la3MonthPayment,
        la4MonthPayment: form.la4MonthPayment,
        remittanceStatus: form.remittanceStatus,
        modeOfSale: form.modeOfSale,
        profit: computedProfit,
      });
      toast.success('Financials saved');
    } finally {
      setSaving(false);
    }
  };

  const buildPreview = (): DatabaseRowType => ({
    ...record,
    goldRate: parseFloat(form.goldRate) || record.goldRate,
    supplierRate: form.supplierRate,
    mc: form.mc,
    additionalCharges: form.additionalCharges,
    downpayment: form.downpayment,
    amountReceived: form.amountReceived,
    la1MonthPayment: form.la1MonthPayment,
    la2MonthPayment: form.la2MonthPayment,
    la3MonthPayment: form.la3MonthPayment,
    la4MonthPayment: form.la4MonthPayment,
  });

  const previewRecord = buildPreview();
  const currency = record.currency || 'AED';
  const itemPrice = calcItemPrice(previewRecord);
  const itemPriceAED = toAED(itemPrice, currency);
  const shippingFee = calcShippingFee(previewRecord);
  const ccFee = calcCCFee(previewRecord);
  const totalPaid = calcTotalPaid(previewRecord);
  const remaining = calcRemainingBalance(previewRecord);
  const profitAED = calcProfitAED(previewRecord);

  const numField = (label: string, key: string, disabled = false) => (
    <div>
      <Label className="text-xs text-muted-foreground">{label}</Label>
      <Input
        type="number"
        value={form[key as keyof typeof form]}
        onChange={e => set(key, e.target.value)}
        disabled={disabled}
        className="h-8 text-xs bg-background border-border mt-0.5 disabled:opacity-50"
        placeholder="0.00"
      />
    </div>
  );

  return (
    <div className="border-t border-border pt-3 mt-2">
      <p className="text-xs font-medium text-muted-foreground mb-2 uppercase tracking-wide">Financials</p>

      {/* Mode of Sale */}
      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Mode of Sale</Label>
        <Select value={form.modeOfSale} onValueChange={v => set('modeOfSale', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select mode of sale..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {MODE_OF_SALE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      <div className="grid grid-cols-2 gap-2 mb-3">
        {numField('Gold Rate', 'goldRate')}
        {numField('MC (Making Charge)', 'mc')}
        <div>
          <Label className="text-xs text-muted-foreground">Supplier Rate <span className="text-primary/60">(auto)</span></Label>
          <Input
            type="number"
            value={form.supplierRate}
            onChange={e => set('supplierRate', e.target.value)}
            className="h-8 text-xs bg-background border-border mt-0.5"
            placeholder="0.00"
          />
        </div>
        {numField('Additional Fees (AED)', 'additionalCharges')}
        {numField('Downpayment', 'downpayment')}
        {numField('Amount Received (AED)', 'amountReceived')}
      </div>

      {/* Layaway Payments */}
      <div className={`grid grid-cols-2 gap-2 mb-3 ${!isLayaway ? 'opacity-40' : ''}`}>
        <p className="col-span-2 text-xs text-muted-foreground">Layaway Payments{!isLayaway ? ' (locked)' : ''}</p>
        {numField('Month 1', 'la1MonthPayment', !isLayaway)}
        {numField('Month 2', 'la2MonthPayment', !isLayaway)}
        {numField('Month 3', 'la3MonthPayment', !isLayaway)}
        {numField('Month 4', 'la4MonthPayment', !isLayaway)}
      </div>

      <div className="mb-3">
        <Label className="text-xs text-muted-foreground">Remittance Status</Label>
        <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
          <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
            <SelectValue placeholder="Select remittance..." />
          </SelectTrigger>
          <SelectContent className="bg-popover border-border">
            {REMITTANCE_OPTIONS.map(o => <SelectItem key={o} value={o} className="text-xs">{o}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>

      {/* Live computation summary */}
      <div className="bg-secondary/50 rounded-lg p-3 mb-3 space-y-1 text-xs">
        <div className="flex justify-between"><span className="text-muted-foreground">Item Price ({currency})</span><span>{currency} {itemPrice.toFixed(2)}</span></div>
        {currency !== 'AED' && <div className="flex justify-between"><span className="text-muted-foreground">Item Price (AED)</span><span>AED {itemPriceAED.toFixed(2)}</span></div>}
        <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>AED {shippingFee.toFixed(2)}</span></div>
        {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Fee</span><span>AED {ccFee.toFixed(2)}</span></div>}
        <div className="flex justify-between"><span className="text-muted-foreground">Total Paid</span><span>AED {totalPaid.toFixed(2)}</span></div>
        <div className={`flex justify-between font-bold pt-1 border-t border-border ${remaining > 0 ? 'text-destructive' : 'text-green-400'}`}>
          <span>Remaining Balance</span><span>AED {remaining.toFixed(2)}</span>
        </div>
        <div className="flex justify-between pt-1 border-t border-border">
          <span className="text-muted-foreground">Expected Profit</span>
          <span className={profitAED >= 0 ? 'text-primary font-medium' : 'text-destructive font-medium'}>AED {profitAED.toFixed(2)}</span>
        </div>
      </div>

      <Button onClick={handleSave} disabled={saving} className="w-full bg-primary text-primary-foreground text-xs h-8">
        {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Save Financials'}
      </Button>
    </div>
  );
}

