export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const isSilver = category.includes('silver');
  const rateAED = clientRateAED(record);
  // Strict fallback: if category blank AND client rate suspiciously low (<150 AED), treat as Silver
  const isSuspiciouslyLow = !record.category?.trim() && rateAED < 150;
  if (isSilver || isSuspiciouslyLow) return 0;
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const mc = n(record.mc);
  if (!grams) return rateAED - (n(record.supplierRate) + mc);
  return (rateAED * grams) - ((goldRate + mc) * grams);
}

