import { useState } from 'react';
import { FileText, Truck } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

/** Returns true if status options should be "Given to Shop" only (no Dispatched/Delivered) */
function isGivenToShopMode(record: DatabaseRowType): boolean {
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

export default function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const first = records[0];

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered') fields.deliveredDate = new Date().toISOString();

    // Save audit trail to Column AI (auditTrail), NOT to liverAdminRemarks
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail
        ? `${record.auditTrail} ${newEntry}`
        : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      {/* Header */}
      <div className="px-4 py-2.5 border-b border-border/50 flex items-center justify-between">
        <div>
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Live: {formatDate(first?.dateOfLive)}</span>
          </div>
        </div>
        <Button variant="outline" size="sm" className="border-primary/40 text-primary text-xs h-7" onClick={() => setShowInvoice(true)}>
          <FileText className="h-3 w-3 mr-1" /> Invoice
        </Button>
      </div>

      {/* Items — always visible */}
      <div className="px-3 py-2 space-y-2">
        {records.map(record => {
          const givenToShopMode = isGivenToShopMode(record);
          return (
            <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
              <div className="flex items-start justify-between mb-2">
                <div>
                  <p className="text-sm font-medium">{record.itemDescription}</p>
                  <p className="text-xs text-muted-foreground">{record.category} · {record.grams ? `${record.grams}g` : 'PC'}</p>
                </div>
                <StatusBadge status={record.status} />
              </div>
              <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                <Truck className="h-3 w-3" />
                <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
              </div>
              {record.liverAdminRemarks && (
                <p className="text-xs text-muted-foreground/70 italic mb-2 truncate">{record.liverAdminRemarks}</p>
              )}
              <Select onValueChange={v => handleStatusChange(record, v)}>
                <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                  <SelectValue placeholder="Set status..." />
                </SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {givenToShopMode ? (
                    <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                  ) : (
                    <>
                      <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                      <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                    </>
                  )}
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          );
        })}
      </div>

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Calendar } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps } from '@/types';
import { calcProfitAED, calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import { startOfWeek, startOfMonth, subMonths, isValid, parseISO, isAfter, isBefore } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);

  const filtered = useMemo(() => {
    // Exclude Cancelled items
    const base = records.filter(r => r.status !== 'Cancelled');
    if (range === 'all') return base;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseISO(r.dateOfLive);
      if (!isValid(d)) return false;
      if (isAfter(from, d)) return false;
      if (to && isBefore(to, d)) return false;
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const kpis = useMemo(() => {
    const totalProfit = filtered.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered').length;
    const outstanding = filtered
      .filter(r => r.status !== 'Cancelled')
      .reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    return { totalProfit, totalSold, outstanding };
  }, [filtered]);

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3">
          <KpiCard
            title="Total Expected Profit"
            value={`AED ${kpis.totalProfit.toFixed(2)}`}
            subtitle={`${filtered.length} active records (excl. Cancelled)`}
            highlight
          />
          <KpiCard
            title="Total Items Sold"
            value={kpis.totalSold.toString()}
            subtitle="Delivered items (excl. Cancelled)"
          />
          <KpiCard
            title="Outstanding Receivables"
            value={`AED ${kpis.outstanding.toFixed(2)}`}
            subtitle="Sum of remaining balances (excl. Cancelled)"
          />
        </div>
      </div>
    </div>
  );
}

interface Props {
  title: string;
  value: string;
  subtitle?: string;
  highlight?: boolean;
}

export default function KpiCard({ title, value, subtitle, highlight }: Props) {
  return (
    <div className={`rounded-xl border p-4 ${highlight ? 'border-primary/40 bg-accent/20' : 'border-border bg-card'}`}>
      <p className="text-xs text-muted-foreground uppercase tracking-wide mb-1">{title}</p>
      <p className={`font-cinzel text-2xl ${highlight ? 'text-primary' : 'text-foreground'}`}>{value}</p>
      {subtitle && <p className="text-xs text-muted-foreground mt-1">{subtitle}</p>}
    </div>
  );
}

import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

/** Robustly parse a date string from Google Sheets (handles ISO, MM/DD/YYYY, "March 04,2026", etc.) */
export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  if (!grams || isNaN(grams)) return true;
  if (record.category?.toLowerCase() === 'silver') return true;
  return false;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

/** Convert client rate to AED. PHP / 16.6, AED as-is. */
export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  if (record.currency === 'PHP') return rate / 16.6;
  return rate;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6;
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6;
  return value;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

export function calcItemCost(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  if (isPcItem(record)) return supplierRate + mc;
  return (n(record.goldRate) * n(record.grams)) + mc;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const isSilver = category.includes('silver');
  const rateAED = clientRateAED(record);
  // Strict fallback: if category blank AND client rate suspiciously low (<150 AED), treat as Silver
  const isSuspiciouslyLow = !record.category?.trim() && rateAED < 150;
  if (isSilver || isSuspiciouslyLow) return 0;
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const mc = n(record.mc);
  if (!grams) return rateAED - (n(record.supplierRate) + mc);
  return (rateAED * grams) - ((goldRate + mc) * grams);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCost(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

/** Due Date = Date of Live + 24 hours. */
export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

/** Overdue if status is Pending AND current time > due date. */
export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

export type DatabaseRowType = {
  orderId?: string;
  dateOfLive?: string;
  page?: string;
  liverName?: string;
  locationOfMiner?: string;
  minerName?: string;
  itemDescription?: string;
  grams?: number;
  source?: string;
  category?: string;
  mc?: string;
  goldRate?: number;
  supplierRate?: string;
  clientRate?: number;
  profit?: string;
  modeOfSale?: string;
  status?: string;
  modeOfPayment?: string;
  downpayment?: string;
  la1MonthPayment?: string;
  la2MonthPayment?: string;
  la3MonthPayment?: string;
  la4MonthPayment?: string;
  liverAdminRemarks?: string;
  dispatchDate?: string;
  deliveredDate?: string;
  reviewChasing?: string;
  fbProfileName?: string;
  regions?: string;
  remittanceStatus?: string;
  currency?: string;
  additionalCharges?: string;
  amountReceived?: string;
  freeSf?: string; // 'TRUE' | '' — stored as string in Google Sheets
  auditTrail?: string;
  id: number;
};

export type ClientGroup = {
  minerName: string;
  records: DatabaseRowType[];
};

export type TabProps = {
  records: DatabaseRowType[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
};

