import { useState, useEffect, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { Toaster } from '@/components/ui/sonner';
import { getRecords, updateRecord, GetRecordsOutputType } from 'zite-endpoints-sdk';
import { getUserRole, UserRole } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';

type ActiveTab = 'admin' | 'dispatch' | 'accounts' | 'bossing';

const SUPER_ADMIN = 'reynanteevillegas@gmail.com';

export default function App() {
  const { user, isLoading } = useAuth();
  const [activeTab, setActiveTab] = useState<ActiveTab>('admin');
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const role: UserRole = user ? getUserRole(user.email) : null;
  const isSuperAdmin = user?.email === SUPER_ADMIN;

  const fetchRecords = useCallback(async () => {
    setDataLoading(true);
    try {
      const data = await getRecords({}) as GetRecordsOutputType;
      setRecords((data as DatabaseRowType[]) || []);
    } finally {
      setDataLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!isLoading && user) {
      fetchRecords();
      // Set default tab based on role
      if (!isSuperAdmin) {
        if (role === 'dispatch') setActiveTab('dispatch');
        else if (role === 'accounts') setActiveTab('accounts');
        else if (role === 'bossing') setActiveTab('bossing');
        else setActiveTab('admin');
      }
    }
  }, [isLoading, user]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
  };

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user?.email,
  };

  if (isLoading || !user) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <LoadingSkeleton />
      </div>
    );
  }

  if (!role) {
    return <AccessDenied email={user.email} />;
  }

  const tabs: { key: ActiveTab; label: string }[] = [
    { key: 'admin', label: 'Admin' },
    { key: 'dispatch', label: 'Dispatch' },
    { key: 'accounts', label: 'Accounts' },
    { key: 'bossing', label: 'Bossing' },
  ];

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />

      {/* Tab navigation — super admin sees all tabs; others see only their tab */}
      {isSuperAdmin && (
        <div className="flex border-b border-border sticky top-0 z-30 bg-background">
          {tabs.map(t => (
            <button
              key={t.key}
              onClick={() => setActiveTab(t.key)}
              className={`flex-1 py-2.5 text-xs font-cinzel transition-colors ${
                activeTab === t.key
                  ? 'text-primary border-b-2 border-primary'
                  : 'text-muted-foreground'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      )}

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <>
          {(role === 'admin' || isSuperAdmin) && activeTab === 'admin' && <AdminPipeline {...tabProps} />}
          {(role === 'dispatch' || isSuperAdmin) && activeTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {(role === 'accounts' || isSuperAdmin) && activeTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {(role === 'bossing' || isSuperAdmin) && activeTab === 'bossing' && <BossingDashboard {...tabProps} />}
          <UploadMasterlistFAB onRefresh={fetchRecords} />
        </>
      )}
    </div>
  );
}

