import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';

type ActiveTab = 'admin' | 'dispatch' | 'accounts' | 'bossing';

const SUPER_ADMIN = 'reynanteevillegas@gmail.com';

export default function App() {
  const { user, isLoading } = useAuth();
  const [activeTab, setActiveTab] = useState<ActiveTab>('admin');
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dataLoading, setDataLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const role: UserRole = user ? getUserRole(user.email) : null;
  const isSuperAdmin = user?.email === SUPER_ADMIN;

  const fetchRecords = useCallback(async () => {
    setDataLoading(true);
    try {
      const data = await getRecords({}) as GetRecordsOutputType;
      setRecords((data as DatabaseRowType[]) || []);
    } finally {
      setDataLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!isLoading && user) {
      fetchRecords();
      // Set default tab based on role
      if (!isSuperAdmin) {
        if (role === 'dispatch') setActiveTab('dispatch');
        else if (role === 'accounts') setActiveTab('accounts');
