import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  if (!grams || isNaN(grams)) return true;
  if (record.category?.toLowerCase() === 'silver') return true;
  return false;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 15.5; 
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 15.5; 
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record.currency);
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const clientRateInAED = clientRateAED(record);
  if (isPcItem(record)) return clientRateInAED;
  return n(record.grams) * clientRateInAED;
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  const goldRate = n(record.goldRate);
  const isSilver = (record.category || '').toLowerCase().includes('silver');

  if (isPcItem(record) || isSilver) return supplierRate + mc;

  return (goldRate * n(record.grams)) + mc;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  const profit = totalSales - totalCost;

  return profit < 0 ? 0 : profit;
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCostAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

/** Due Date = Date of Live + 24 hours (Restored to 24h as requested) */
export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

/** Overdue if status is Pending AND current time > due date. */
export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { format, parseISO, isValid } from 'date-fns';
import { DatabaseRowType } from '@/types';

export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  try {
    const d = parseISO(dateStr);
    if (!isValid(d)) return dateStr;
    return format(d, 'MMM dd, yyyy');
  } catch {
    return dateStr;
  }
}

export function formatDateObj(date: Date | null): string {
  if (!date || !isValid(date)) return '—';
  return format(date, 'MMM dd, yyyy');
}

export function formatCurrency(value: number, currency?: string): string {
  const curr = currency || 'AED';
  return `${curr} ${value.toFixed(2)}`;
}

export function groupByMinerName(records: DatabaseRowType[]): Map<string, DatabaseRowType[]> {
  const map = new Map<string, DatabaseRowType[]>();
  for (const record of records) {
    const key = record.minerName || 'Unknown Client';
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(record);
  }
  return map;
}

export function groupByLocationSourceMiner(
  records: DatabaseRowType[]
): Map<string, Map<string, Map<string, DatabaseRowType[]>>> {
  const grouped = new Map<string, Map<string, Map<string, DatabaseRowType[]>>>();
  for (const record of records) {
    const location = record.locationOfMiner || 'Local'; 
    const source = record.source || 'Main Store'; // Fixed 'Unknown' issue
    const miner = record.minerName || 'Unknown Client';

    if (!grouped.has(location)) grouped.set(location, new Map());
    const byLocation = grouped.get(location)!;

    if (!byLocation.has(source)) byLocation.set(source, new Map());
    const bySource = byLocation.get(source)!;

    if (!bySource.has(miner)) bySource.set(miner, []);
    bySource.get(miner)!.push(record);
  }
  return grouped;
}

export function applySearch(records: DatabaseRowType[], query: string): DatabaseRowType[] {
  if (!query.trim()) return records;
  const q = query.toLowerCase();

  const matchingMiners = new Set<string>();
  for (const r of records) {
    if (
      r.minerName?.toLowerCase().includes(q) ||
      r.itemDescription?.toLowerCase().includes(q) ||
      r.orderId?.toLowerCase().includes(q)
    ) {
      if (r.minerName) matchingMiners.add(r.minerName);
    }
  }

  return records.filter(r => r.minerName && matchingMiners.has(r.minerName));
}

export const MOP_OPTIONS = [
  'Tabby', 'Tamara', 'COD', 'Bank Transfer', 'Credit Card',
  'GCash', 'Meet Up', 'Pick Up Shop', 'Layaway',
];

export const REGION_OPTIONS = [
  'Dubai', 'Abu Dhabi', 'Sharjah', 'Ajman', 'Western Region', 'UAQ', 'RAK', 'Fujairah',
];

export const STATUS_COLORS: Record<string, string> = {
  'Pending': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
  'Waiting for Details': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  'For Pullout': 'bg-purple-500/20 text-purple-400 border-purple-500/30',
  'Dispatched': 'bg-orange-500/20 text-orange-400 border-orange-500/30',
  'Delivered': 'bg-green-500/20 text-green-400 border-green-500/30',
  'Cancelled': 'bg-red-500/20 text-red-400 border-red-500/30',
};

import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate } from '@/lib/formatters';
import { calcProfitAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

// Group by Source first, then by Miner
function groupBySourceThenMiner(records: DatabaseRowType[]) {
  const grouped = new Map<string, Map<string, DatabaseRowType[]>>();
  for (const r of records) {
    const source = r.source || 'Main Store'; // Fixed 'Unknown' issue
    const miner = r.minerName || 'Unknown Client';

    if (!grouped.has(source)) grouped.set(source, new Map());
    const bySource = grouped.get(source)!;

    if (!bySource.has(miner)) bySource.set(miner, []);
    bySource.get(miner)!.push(r);
  }
  // Sort sources alphabetically
  return new Map([...grouped.entries()].sort((a, b) => a[0].localeCompare(b[0])));
}

export default function PulloutReport({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);

  const forPullout = records.filter(r => r.status === 'For Pullout');
  const grouped = groupBySourceThenMiner(forPullout);

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Pullout Report</title>
    <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
    <style>
      body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
      .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
      .internal-banner { border: 2px solid #dc2626; background: #fee2e2; padding: 8px 16px; text-align: center; font-weight: bold; color: #dc2626; margin-bottom: 12px; font-size: 13px; }
      h2 { font-size: 16px; margin-bottom: 4px; }
      table { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
      th { background: #f0f0f0; padding: 6px; text-align: left; font-size: 11px; border-bottom: 2px solid #ccc; }
      th.r, td.r { text-align: right; }
      td { padding: 6px; border-bottom: 1px solid #ddd; }
      .source-header { background: #111; color: #fff; padding: 6px 12px; font-size: 14px; margin-top: 16px; margin-bottom: 8px; border-radius: 4px; }
      .miner-header { border-bottom: 2px solid #C9A84C; padding-bottom: 4px; margin-bottom: 4px; margin-top: 16px; display: flex; justify-content: space-between; align-items: flex-end; }
      .miner-name { font-size: 13px; font-weight: bold; }
      .miner-date { font-size: 11px; color: #666; margin-left: 8px; font-weight: normal; }
    </style></head><body>
    <div class="internal-banner font-cinzel">⚠ INTERNAL PULLOUT — DO NOT SEND TO CLIENT ⚠</div>
    ${content}
    </body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Pullout Report — Internal Use Only</DialogTitle>
        </DialogHeader>

        <div ref={printRef} className="text-sm">
          <div className="border-2 border-destructive rounded-lg px-4 py-2 mb-4 text-center bg-destructive/10 no-print">
            <p className="text-destructive font-bold text-sm tracking-wide">⚠ INTERNAL PULLOUT — DO NOT SEND TO CLIENT ⚠</p>
          </div>

          <p className="text-xs text-muted-foreground mb-4">
            Generated: {new Date().toLocaleString()} · {forPullout.length} items for pullout
          </p>

          {grouped.size === 0 ? (
            <p className="text-center text-muted-foreground py-8">No items with "For Pullout" status.</p>
          ) : (
            Array.from(grouped.entries()).map(([source, byMiner]) => (
              <div key={source} className="mb-8">
                {/* SOURCE HEADER */}
                <div className="source-header bg-secondary text-foreground px-3 py-2 rounded-md font-bold mb-2">
                  <span className="font-cinzel text-primary">{source}</span>
                </div>

                {/* MINER / CLIENT GROUPING */}
                {Array.from(byMiner.entries()).map(([miner, items]) => {
                  const totalProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
                  const firstDate = formatDate(items[0]?.dateOfLive);

                  return (
                    <div key={miner} className="mb-6 pl-2">
                      <div className="miner-header flex justify-between items-end mb-2 pb-1 border-b border-primary/30">
                        <div>
                          <span className="miner-name text-sm font-bold text-foreground">{miner}</span>
                          <span className="miner-date text-xs text-muted-foreground ml-2">Live: {firstDate}</span>
                        </div>
                        <span className="text-xs font-medium text-muted-foreground">
                          {items.length} item{items.length !== 1 ? 's' : ''} · Profit: AED {totalProfit.toFixed(2)}
                        </span>
                      </div>

                      <table className="w-full text-xs">
                        <thead>
                          <tr className="text-muted-foreground">
                            <th className="text-left py-1 font-medium">Item</th>
                            <th className="text-left py-1 font-medium">Cat</th>
                            <th className="text-right py-1 font-medium">Grams</th>
                            <th className="text-right py-1 font-medium">Gold Rate</th>
                            <th className="text-right py-1 font-medium">Profit (AED)</th>
                          </tr>
                        </thead>
                        <tbody>
                          {items.map(r => (
                            <tr key={r.id} className="border-b border-border/40">
                              <td className="py-1.5 pr-2">{r.itemDescription}</td>
                              <td className="py-1.5">{r.category}</td>
                              <td className="py-1.5 text-right">{r.grams ? `${r.grams}g` : 'PC'}</td>
                              <td className="py-1.5 text-right">{r.goldRate ? Number(r.goldRate).toFixed(2) : '—'}</td>
                              <td className="py-1.5 text-right">{calcProfitAED(r).toFixed(2)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  );
                })}
              </div>
            ))
          )}
        </div>

        <Button onClick={handlePrint} className="w-full mt-4 bg-primary text-primary-foreground">
          <Printer className="h-4 w-4 mr-2" /> Print Report
        </Button>
      </DialogContent>
    </Dialog>
  );
}

