import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch all Database rows in batches, filtering out empty placeholder rows',
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const allRecords: unknown[] = [];
    let offset = 0;
    const limit = 500;
    while (true) {
      const batch = await Database.findAll({ offset, limit });
      if (!batch || batch.length === 0) break;
      // Filter out rows with no minerName AND no itemDescription (empty placeholder rows)
      const valid = batch.filter(r => r.minerName?.trim() || r.itemDescription?.trim());
      allRecords.push(...valid);
      if (batch.length < limit) break;
      offset += limit;
    }
    return allRecords;
  },
});

import { z } from 'zod';
import { createEndpoint, Uploads } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch all Uploads rows',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const records = await Uploads.findAll({});
    return records || [];
  },
});

