import { useState, useEffect } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue, isFreeSf } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = (remarks || '').toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('tamara approved')) return { modeOfPayment: 'Tamara', freeSf: 'TRUE' };
  if (/\bcod\b/.test(r)) return { modeOfPayment: 'COD' };
  if (/\bcc\b/.test(r) || r.includes('credit card')) return { modeOfPayment: 'Credit Card' };
  return null;
}

export default function AdminItemRow({ record, onUpdate, onGroupUpdate, userEmail }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const [resetKey, setResetKey] = useState(Date.now()); // Bulletproof reset key
  const overdue = isOverdue(record);

  useEffect(() => {
    if (!record.modeOfPayment && record.liverAdminRemarks) {
      const auto = detectAutoFill(record.liverAdminRemarks);
      if (auto) onGroupUpdate(auto);
    }
  }, [record.modeOfPayment, record.liverAdminRemarks, onGroupUpdate]);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const autoFill = detectAutoFill(val);
    await onUpdate(record.id, { liverAdminRemarks: val });
    if (autoFill) {
      await onGroupUpdate(autoFill);
      toast.success('Auto-filled MOP from remarks');
    }
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    if (mop === 'Tabby' || mop === 'Tamara') fields.freeSf = 'TRUE'; 
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    await onGroupUpdate({ regions: region });
  };

  const handleStatusChange = async (newStatus: string) => {
    // 1. Instantly force the dropdown component to remount so it clears visually
    setResetKey(Date.now());

    // 2. Run validations
    if (newStatus === 'Cancelled') { setShowCancel(true); return; }
    if (newStatus === 'For Pullout') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required for pullout'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }

    // 3. Process successful update
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> OVERDUE
              </span>
            )}
          </div>
        </div>
        <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">{record.grams ? `${record.grams}g` : 'PC'}</p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {record.locationOfMiner === 'Local' && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div>
          <Label className="text-xs text-muted-foreground">Liver/Admin Remarks</Label>
          <Textarea
            value={remarks}
            onChange={e => { setRemarks(e.target.value); debouncedRemarks(e.target.value); }}
            className="h-14 text-xs bg-background border-border mt-0.5 resize-none"
            placeholder="e.g. TABBY APPROVED, COD..."
          />
        </div>

        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Switch
              checked={isFreeSf(record)}
              onCheckedChange={v => onGroupUpdate({ freeSf: v ? 'TRUE' : '' })}
              className="scale-90"
            />
            <Label className="text-xs">FREE SF</Label>
          </div>

          {/* Using the resetKey here forces the component to clear its visual state on click */}
          <Select key={resetKey} onValueChange={handleStatusChange}>
            <SelectTrigger className="h-7 text-xs w-36 bg-background border-border">
              <SelectValue placeholder="Change status..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="For Pullout" className="text-xs">For Pullout</SelectItem>
              <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      <AlertDialog open={showCancel} onOpenChange={setShowCancel}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground"
              onClick={async () => { await onUpdate(record.id, { status: 'Cancelled' }); toast.success('Item cancelled'); }}
            >
              Cancel Item
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from 'react';
import { FileText, Truck, User, Upload, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

// FIX: Now correctly checks both Location and Region so Pinas works perfectly
function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

export default function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});
  const first = records[0];

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));

    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }

    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();

    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <div className="px-4 py-2.5 border-b border-border/50 flex items-center justify-between">
        <div>
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Live: {formatDate(first?.dateOfLive)}</span>
            {first?.fbProfileName && <span className="flex items-center gap-1"><User className="h-3 w-3" />{first.fbProfileName}</span>}
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <Button variant="outline" size="sm" className="border-primary/40 text-primary text-xs h-7" onClick={() => setShowInvoice(true)}>
          <FileText className="h-3 w-3 mr-1" /> Invoice
        </Button>
      </div>

      <div className="px-3 py-2 space-y-2">
        {records.map(record => {
          const givenToShopMode = isGivenToShopMode(record);
          const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;

          return (
            <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
              <div className="flex items-start justify-between mb-2">
                <div>
                  <p className="text-sm font-medium">{record.itemDescription}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {record.category} · {record.grams ? `${record.grams}g` : 'PC'} 
                    <span className="text-foreground font-medium ml-1">
                      · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                    </span>
                  </p>
                </div>
                <StatusBadge status={record.status} />
              </div>

              <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                <Truck className="h-3 w-3" />
                <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
              </div>

              {record.liverAdminRemarks && (
                <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                  Remarks: {record.liverAdminRemarks}
                </p>
              )}

              {latestAudit && (
                <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                  <History className="h-2.5 w-2.5" />
                  {latestAudit}
                </p>
              )}

              <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                  <SelectValue placeholder="Set status..." />
                </SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {givenToShopMode ? (
                    <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                  ) : (
                    <>
                      <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                      <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                    </>
                  )}
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          );
        })}
      </div>

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useMemo } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { calcRemainingBalance } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const { activeGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(records, searchQuery);

    const active = searched.filter(r => {
      // FIX: Accounts now tracks "Given to Shop" items as well!
      const isDeliveredOrLayaway = r.status === 'Delivered' || r.status === 'Given to Shop' || r.modeOfPayment === 'Layaway';
      if (!isDeliveredOrLayaway) return false;

      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received');
      if (isCleared) return false;

      const isPendingOrEmpty = !remStatus || remStatus === 'pending payment';
      const hasBalance = calcRemainingBalance(r) > 0;
      return isPendingOrEmpty || hasBalance;
    });

    const cleared = searched.filter(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      return remStatus.includes('secured') || remStatus.includes('received');
    });

    return {
      activeGroups: groupByMinerName(active),
      clearedGroups: groupByMinerName(cleared),
    };
  }, [records, searchQuery]);

  const renderGroups = (groups: Map<string, typeof records>) => (
    groups.size === 0 ? (
      <div className="text-center py-16 text-muted-foreground text-sm">No records found.</div>
    ) : (
      Array.from(groups.entries()).map(([minerName, items]) => (
        <AccountsClientCard key={minerName} minerName={minerName} records={items} onUpdate={onUpdate} />
      ))
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />
      <div className="px-4 pt-4">
        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({activeGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>
          <TabsContent value="active">{renderGroups(activeGroups)}</TabsContent>
          <TabsContent value="cleared">{renderGroups(clearedGroups)}</TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Calendar } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps } from '@/types';
import { calcProfitAED, calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import { startOfWeek, startOfMonth, subMonths, isValid, parseISO, isAfter, isBefore } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);

  const filtered = useMemo(() => {
    const base = records.filter(r => r.status !== 'Cancelled');
    if (range === 'all') return base;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseISO(r.dateOfLive);
      if (!isValid(d)) return false;
      if (isAfter(from, d)) return false;
      if (to && isBefore(to, d)) return false;
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const kpis = useMemo(() => {
    const totalProfit = filtered.reduce((sum, r) => sum + calcProfitAED(r), 0);
    // FIX: Ensure Given to Shop is counted as Sold!
    const totalSold = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;
    const outstanding = filtered
      .filter(r => r.status !== 'Cancelled')
      .reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    return { totalProfit, totalSold, outstanding };
  }, [filtered]);

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3">
          <KpiCard
            title="Total Expected Profit"
            value={`AED ${kpis.totalProfit.toFixed(2)}`}
            subtitle={`${filtered.length} active records (excl. Cancelled)`}
            highlight
          />
          <KpiCard
            title="Total Items Sold"
            value={kpis.totalSold.toString()}
            subtitle="Delivered/Given to Shop (excl. Cancelled)"
          />
          <KpiCard
            title="Outstanding Receivables"
            value={`AED ${kpis.outstanding.toFixed(2)}`}
            subtitle="Sum of remaining balances (excl. Cancelled)"
          />
        </div>
      </div>
    </div>
  );
}

import { format, parseISO, isValid } from 'date-fns';
import { DatabaseRowType } from '@/types';

export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  try {
    const d = parseISO(dateStr);
    if (!isValid(d)) return dateStr;
    return format(d, 'MMM dd, yyyy');
  } catch {
    return dateStr;
  }
}

export function formatDateObj(date: Date | null): string {
  if (!date || !isValid(date)) return '—';
  return format(date, 'MMM dd, yyyy');
}

export function formatCurrency(value: number, currency?: string): string {
  const curr = currency || 'AED';
  return `${curr} ${value.toFixed(2)}`;
}

export function groupByMinerName(records: DatabaseRowType[]): Map<string, DatabaseRowType[]> {
  const map = new Map<string, DatabaseRowType[]>();
  for (const record of records) {
    const key = record.minerName?.trim() || 'Unknown Client';
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(record);
  }
  return map;
}

export function groupByLocationSourceMiner(
  records: DatabaseRowType[]
): Map<string, Map<string, Map<string, DatabaseRowType[]>>> {
  const grouped = new Map<string, Map<string, Map<string, DatabaseRowType[]>>>();
  for (const record of records) {
    // FIX: Replaces blank data with beautiful defaults
    const location = record.locationOfMiner?.trim() || 'Local'; 
    const source = record.source?.trim() || 'Main Store'; 
    const miner = record.minerName?.trim() || 'Unknown Client';

    if (!grouped.has(location)) grouped.set(location, new Map());
    const byLocation = grouped.get(location)!;

    if (!byLocation.has(source)) byLocation.set(source, new Map());
    const bySource = byLocation.get(source)!;

    if (!bySource.has(miner)) bySource.set(miner, []);
    bySource.get(miner)!.push(record);
  }
  return grouped;
}

export function applySearch(records: DatabaseRowType[], query: string): DatabaseRowType[] {
  if (!query.trim()) return records;
  const q = query.toLowerCase();

  const matchingMiners = new Set<string>();
  for (const r of records) {
    if (
      r.minerName?.toLowerCase().includes(q) ||
      r.itemDescription?.toLowerCase().includes(q) ||
      r.orderId?.toLowerCase().includes(q)
    ) {
      if (r.minerName) matchingMiners.add(r.minerName);
    }
  }

  return records.filter(r => r.minerName && matchingMiners.has(r.minerName));
}

