import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch all Database rows, filtering out empty placeholder rows and normalizing data types',
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const allRecords: unknown[] = [];
    let offset = 0;
    const limit = 200;
    let hasMore = true;

    while (hasMore) {
      const batch = await Database.findAll({ offset, limit });
      if (!batch || batch.length === 0) break;

      // Filter out rows with no minerName AND no itemDescription
      const valid = batch
        .filter(r => r.minerName?.trim() || r.itemDescription?.trim())
        .map(r => ({
          ...r,
          // Pre-parse all numbers so the UI doesn't have to calculate strings
          grams: parseFloat(r.grams as string) || 0,
          goldRate: parseFloat(r.goldRate as string) || 0,
          supplierRate: parseFloat(r.supplierRate as string) || 0,
