          la3MonthPayment: parseFloat(r.la3MonthPayment as string) || 0,
          la4MonthPayment: parseFloat(r.la4MonthPayment as string) || 0,
          additionalCharges: parseFloat(r.additionalCharges as string) || 0,
          // Keep freeSf as the string 'TRUE' as that's what the UI Switch expects
          freeSf: (r.freeSf === 'TRUE' || r.freeSf === 'true' || r.freeSf === true) ? 'TRUE' : '',
        }));

      allRecords.push(...valid);
      hasMore = batch.length === limit;
      offset += limit;
    }

    return allRecords;
  },
});

