import { useState, useEffect } from 'react';
import { Search } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { useAuth } from 'zite-auth-sdk';
import { useDebouncedCallback } from 'use-debounce';

interface TabHeaderProps {
  title: string;
  subtitle?: string;
  searchQuery: string;
  onSearchChange: (q: string) => void;
  rightContent?: React.ReactNode;
}

export default function TabHeader({ title, subtitle, searchQuery, onSearchChange, rightContent }: TabHeaderProps) {
  const { user } = useAuth();

  // Local state for instantaneous typing feedback
  const [localQuery, setLocalQuery] = useState(searchQuery);

  // Sync local state if parent changes (e.g., cleared externally)
  useEffect(() => {
    setLocalQuery(searchQuery);
  }, [searchQuery]);

  // Wait 300ms after the user stops typing to trigger the heavy search functions
  const debouncedSearch = useDebouncedCallback((val: string) => {
    onSearchChange(val);
  }, 300);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setLocalQuery(val);
    debouncedSearch(val);
  };

  return (
    <div className="sticky top-0 z-20 bg-background border-b border-border">
      <div className="px-4 pt-4 pb-3">
        <div className="flex items-center justify-between mb-3">
          <div>
            <h1 className="font-cinzel text-lg text-primary leading-tight">{title}</h1>
            {subtitle && <p className="text-xs text-muted-foreground">{subtitle}</p>}
          </div>
          <div className="flex items-center gap-2">
            {rightContent}
            {user && <span className="text-xs text-muted-foreground">{user.email}</span>}
          </div>
        </div>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            value={localQuery}
            onChange={handleChange}
            placeholder="Search client, item, or order ID..."
            className="pl-9 bg-secondary border-border h-9 text-sm"
          />
        </div>
      </div>
    </div>
  );
}

