import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch Database rows, ignoring old archived items, and normalizing data',
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const allRecords: unknown[] = [];
    let offset = 0;
    const limit = 200;
    let hasMore = true;

    // Archiving: Calculate cutoff date (90 days ago)
    const archiveThreshold = new Date();
    archiveThreshold.setDate(archiveThreshold.getDate() - 90);
    const thresholdTime = archiveThreshold.getTime();

    while (hasMore) {
      const batch = await Database.findAll({ offset, limit });
      if (!batch || batch.length === 0) break;

      const valid = batch
        .filter(r => {
          // 1. Remove empty placeholder rows
          if (!r.minerName?.trim() && !r.itemDescription?.trim()) return false;

          // 2. ARCHIVE LOGIC: Hide Delivered/Cancelled items older than 90 days to save memory
          if (r.status === 'Delivered' || r.status === 'Cancelled' || r.status === 'Given to Shop') {
            if (r.dateOfLive) {
              const liveDate = new Date(r.dateOfLive as string).getTime();
              // If the date is valid and older than 90 days, skip sending it to the app
              if (!isNaN(liveDate) && liveDate < thresholdTime) {
                return false; 
              }
            }
          }
          return true;
        })
        .map(r => ({
          ...r,
          // Pre-parse all numbers so the UI doesn't have to calculate strings constantly
          grams: parseFloat(String(r.grams)) || 0,
          goldRate: parseFloat(String(r.goldRate)) || 0,
          supplierRate: parseFloat(String(r.supplierRate)) || 0,
          clientRate: parseFloat(String(r.clientRate)) || 0,
          mc: parseFloat(String(r.mc)) || 0,
          downpayment: parseFloat(String(r.downpayment)) || 0,
          amountReceived: parseFloat(String(r.amountReceived)) || 0,
          la1MonthPayment: parseFloat(String(r.la1MonthPayment)) || 0,
          la2MonthPayment: parseFloat(String(r.la2MonthPayment)) || 0,
          la3MonthPayment: parseFloat(String(r.la3MonthPayment)) || 0,
          la4MonthPayment: parseFloat(String(r.la4MonthPayment)) || 0,
          additionalCharges: parseFloat(String(r.additionalCharges)) || 0,
          freeSf: (r.freeSf === 'TRUE' || r.freeSf === 'true' || r.freeSf === true) ? 'TRUE' : '',
        }));

      allRecords.push(...valid);
      hasMore = batch.length === limit;
      offset += limit;
    }

    return allRecords;
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch user roles from the dynamic Roles sheet',
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    try {
      // We use require to avoid hard TypeScript crash if the integration isn't mapped yet
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const sdk = require('zite-integrations-backend-sdk');
      
      // If the user has mapped a 'Roles' table in Zite, fetch it
      if (sdk.Roles && typeof sdk.Roles.findAll === 'function') {
        const roles = await sdk.Roles.findAll({});
        return roles || [];
      }
      return [];
    } catch (err) {
      console.warn('Roles table not mapped yet or unavailable.', err);
      return [];
    }
  },
});

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'admin' | 'dispatch' | 'accounts' | 'bossing' | null;

// Super-admin: always has full admin access.
const SUPER_ADMIN_EMAIL = "reynanteevillegas@gmail.com";

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"], 
  dispatchEmails: [],
  accountsEmails: [],
  bossingEmails: [],
};

export function getUserRole(
  email: string, 
  dynamicRoles: { email?: string, role?: string }[]
): UserRole {
  const e = email.toLowerCase();

  // 1. OWNER check first
  if (e === SUPER_ADMIN_EMAIL.toLowerCase()) return 'admin'; 

  // 2. Dynamic Roles Check (from Google Sheets)
  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => r.email?.toLowerCase().trim() === e);
    if (found && found.role) {
      const assignedRole = found.role.toLowerCase().trim();
      if (['admin', 'dispatch', 'accounts', 'bossing'].includes(assignedRole)) {
        return assignedRole as UserRole;
      }
    }
    // Strict mode: if the sheet exists but you aren't in it, deny access.
    return null; 
  }

  // 3. Fallback Check (Hardcoded List)
  if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) return 'admin';
  if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) return 'dispatch';
  if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) return 'accounts';
  if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) return 'bossing';

  return null;
}

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole } from '@/config/roles';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';

const MY_EMAIL = "reynanteevillegas@gmail.com";

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<{email: string, role: string}[]>([]);
  const [dataLoading, setDataLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  const fetchInitialData = useCallback(() => {
    if (!user) return;
    setDataLoading(true);

    // Fetch both records and dynamic roles simultaneously
    Promise.all([
      getRecords({}),
      getRoles({}).catch(() => []) // Safely ignore if Roles table isn't mapped yet
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        setDynamicRoles((rolesData as any[]) || []);
      })
      .catch(() => toast.error('Failed to load records'))
      .finally(() => setDataLoading(false));
  }, [user]);

  useEffect(() => { fetchInitialData(); }, [fetchInitialData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      fetchInitialData();
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return null;

  // Pass dynamic roles into our role checker
  const role = getUserRole(user.email, dynamicRoles);
  if (!role) return <AccessDenied email={user.email} />;

  const isMe = user.email.toLowerCase() === MY_EMAIL.toLowerCase();

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />

      {/* NAVIGATION BAR: Only visible to YOU */}
      {isMe && (
        <div className="flex border-b border-border sticky top-0 z-30 bg-background">
          <button onClick={() => setActiveTab('admin')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
          <button onClick={() => setActiveTab('dispatch')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
          <button onClick={() => setActiveTab('accounts')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
          <button onClick={() => setActiveTab('bossing')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
        </div>
      )}

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0">
          {/* STRICT ROLE ISOLATION: If isMe, use activeTab. Otherwise, enforce role */}
          {(isMe ? activeTab === 'admin' : role === 'admin') && <AdminPipeline {...tabProps} />}

          {(isMe ? activeTab === 'dispatch' : role === 'dispatch') && <DispatchBoard {...tabProps} />}

          {(isMe ? activeTab === 'accounts' : role === 'accounts') && <AccountsTracking {...tabProps} />}

          {(isMe ? activeTab === 'bossing' : role === 'bossing') && <BossingDashboard {...tabProps} />}

          <UploadMasterlistFAB onRefresh={fetchInitialData} />
        </div>
      )}
    </div>
  );
}

