import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Fetch Database rows, ignoring old archived items, and normalizing data',
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    const allRecords: unknown[] = [];
    let offset = 0;
    const limit = 200;
    let hasMore = true;

    // Archiving: Calculate cutoff date (90 days ago)
    const archiveThreshold = new Date();
    archiveThreshold.setDate(archiveThreshold.getDate() - 90);
    const thresholdTime = archiveThreshold.getTime();

    while (hasMore) {
      const batch = await Database.findAll({ offset, limit });
      if (!batch || batch.length === 0) break;

      const valid = batch
        .filter(r => {
          // 1. Remove empty placeholder rows
          if (!r.minerName?.trim() && !r.itemDescription?.trim()) return false;

          // 2. ARCHIVE LOGIC: Hide Delivered/Cancelled items older than 90 days to save memory
          if (r.status === 'Delivered' || r.status === 'Cancelled' || r.status === 'Given to Shop') {
            if (r.dateOfLive) {
              const liveDate = new Date(r.dateOfLive as string).getTime();
              // If the date is valid and older than 90 days, skip sending it to the app
              if (!isNaN(liveDate) && liveDate < thresholdTime) {
                return false; 
              }
            }
          }
          return true;
        })
        .map(r => ({
          ...r,
          // Pre-parse all numbers so the UI doesn't have to calculate strings constantly
          grams: parseFloat(String(r.grams)) || 0,
          goldRate: parseFloat(String(r.goldRate)) || 0,
          supplierRate: parseFloat(String(r.supplierRate)) || 0,
          clientRate: parseFloat(String(r.clientRate)) || 0,
          mc: parseFloat(String(r.mc)) || 0,
          downpayment: parseFloat(String(r.downpayment)) || 0,
          amountReceived: parseFloat(String(r.amountReceived)) || 0,
          la1MonthPayment: parseFloat(String(r.la1MonthPayment)) || 0,
          la2MonthPayment: parseFloat(String(r.la2MonthPayment)) || 0,
          la3MonthPayment: parseFloat(String(r.la3MonthPayment)) || 0,
          la4MonthPayment: parseFloat(String(r.la4MonthPayment)) || 0,
          additionalCharges: parseFloat(String(r.additionalCharges)) || 0,
          freeSf: (r.freeSf === 'TRUE' || r.freeSf === 'true' || r.freeSf === true) ? 'TRUE' : '',
        }));

      allRecords.push(...valid);
      hasMore = batch.length === limit;
      offset += limit;
    }

    return allRecords;
  },
});

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'admin' | 'dispatch' | 'accounts' | 'bossing' | null;

// Super-admin: always has full admin access.
const SUPER_ADMIN_EMAIL = "reynanteevillegas@gmail.com";

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"], 
  dispatchEmails: [],
  accountsEmails: [],
  bossingEmails: [],
};

export function getUserRole(
  email: string, 
  dynamicRoles: { email?: string, role?: string }[]
): UserRole {
  const e = email.toLowerCase();

  // 1. OWNER check first
  if (e === SUPER_ADMIN_EMAIL.toLowerCase()) return 'admin'; 

  // 2. Dynamic Roles Check (from Google Sheets)
  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => r.email?.toLowerCase().trim() === e);
    if (found && found.role) {
      const assignedRole = found.role.toLowerCase().trim();
      if (['admin', 'dispatch', 'accounts', 'bossing'].includes(assignedRole)) {
        return assignedRole as UserRole;
      }
    }
    // Strict mode: if the sheet exists but you aren't in it, deny access.
    return null; 
  }

  // 3. Fallback Check (Hardcoded List)
  if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) return 'admin';
  if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) return 'dispatch';
  if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) return 'accounts';
  if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) return 'bossing';

  return null;
}

