import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

/** Robustly parse a date string from Google Sheets */
export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

// FIX: Only treat as "Per Piece" (PC) if grams are 0 or empty. 
// We no longer force "Silver" to be a PC item.
export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6; 
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6; 
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record.currency);
}

// FIX: Now correctly multiplies Grams * Rate for Silver and Gold
export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

// FIX: Now correctly multiplies Grams * Rate in AED
export function calcItemPriceAED(record: DatabaseRowType): number {
  const clientRateInAED = clientRateAED(record);
  if (isPcItem(record)) return clientRateInAED;
  return n(record.grams) * clientRateInAED;
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  const goldRate = n(record.goldRate);
  const grams = n(record.grams);
  const isSilver = (record.category || '').toLowerCase().includes('silver');

  // If it's a Per Piece item (0 grams), Cost = Supplier Rate + MC
  if (isPcItem(record)) return supplierRate + mc;

  // If Silver by weight, Cost = Gold Rate * Grams (MC is not applied to Silver)
  if (isSilver) return goldRate * grams;

  // If Gold by weight, Cost = (Gold Rate + MC) * Grams
  return (goldRate + mc) * grams;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  const profit = totalSales - totalCost;

  // SAFETY: Never return negative profit to the dashboard
  return profit < 0 ? 0 : profit;
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCostAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

