// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'admin' | 'dispatch' | 'accounts' | 'bossing' | null;

// Super-admins: always have full admin access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "your.second.email@gmail.com" // <-- Add your other email here!
];

export function getUserRole(
  email: string, 
  // Allow for any capitalization from the Google Sheets SDK
  dynamicRoles: any[] = []
): UserRole {
  if (!email) return null;
  const e = email.toLowerCase().trim();

  // 1. OWNER check first (Now checks the whole array of Super Admins)
  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) return 'admin'; 

  // 2. Dynamic Roles Check (from Google Sheets)
  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      // Handle Google Sheets auto-capitalization
      const rEmail = r.email || r.Email || r.EMAIL || r['Email Address'];
      return rEmail?.toLowerCase().trim() === e;
    });

    if (found) {
      const rRole = found.role || found.Role || found.ROLE;
      if (rRole) {
        let assignedRole = rRole.toLowerCase().trim();

        // If you type "super admin" in the sheet, let them be an admin
        if (assignedRole === 'super admin') assignedRole = 'admin';

        if (['admin', 'dispatch', 'accounts', 'bossing'].includes(assignedRole)) {
          return assignedRole as UserRole;
        }
      }
    }
  }

  // If the user is not the owner and not found in the Google Sheet, block them.
  return null;
}

