import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles'; // <-- Import the new array here
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);

  // State to hold the roles fetched from Google Sheets
  const [dynamicRoles, setDynamicRoles] = useState<any[]>([]);

  const [dataLoading, setDataLoading] = useState(true); 
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  const fetchData = useCallback(() => {
    if (!user) return;
    setDataLoading(true);

    // Fetch both Database Records and Roles simultaneously
    Promise.all([
      getRecords({}).catch(() => { toast.error('Failed to load records'); return []; }),
      getRoles({}).catch(() => { return []; })
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        setDynamicRoles((rolesData as any[]) || []);
      })
      .finally(() => setDataLoading(false));
  }, [user]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      fetchData();
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  // FIX: Allow anyone in the SUPER_ADMIN_EMAILS list to have God-Mode
  const isMe = SUPER_ADMIN_EMAILS.map(email => email.toLowerCase()).includes(user.email.toLowerCase());

  // FIX: Pass the fetched Google Sheets roles into your custom function!
  const role = getUserRole(user.email, dynamicRoles);

  // Prevent flash of Access Denied while roles are downloading
  if (dataLoading && !role && !isMe) return <LoadingSkeleton />;

  if (!role && !isMe) return <AccessDenied email={user.email} />;

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto">
      <Toaster richColors position="top-center" />

      {isMe && (
        <div className="flex border-b border-border sticky top-0 z-30 bg-background">
          <button onClick={() => setActiveTab('admin')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
          <button onClick={() => setActiveTab('dispatch')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
          <button onClick={() => setActiveTab('accounts')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
          <button onClick={() => setActiveTab('bossing')} className={`flex-1 py-2.5 text-xs font-cinzel ${activeTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
        </div>
      )}

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0">
          {(isMe ? activeTab === 'admin' : role === 'admin') && <AdminPipeline {...tabProps} />}
          {(isMe ? activeTab === 'dispatch' : role === 'dispatch') && <DispatchBoard {...tabProps} />}
          {(isMe ? activeTab === 'accounts' : role === 'accounts') && <AccountsTracking {...tabProps} />}
          {(isMe ? activeTab === 'bossing' : role === 'bossing') && <BossingDashboard {...tabProps} />}

          <UploadMasterlistFAB onRefresh={fetchData} />
        </div>
      )}
    </div>
  );
}

