import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles'; 
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[]>([]);

  const [dataLoading, setDataLoading] = useState(true); 
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  const fetchData = useCallback(() => {
    if (!user) return;
    setDataLoading(true);

    Promise.all([
      getRecords({}).catch(() => { toast.error('Failed to load records'); return []; }),
      getRoles({}).catch(() => { return []; })
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        setDynamicRoles((rolesData as any[]) || []);
      })
      .finally(() => setDataLoading(false));
  }, [user]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      fetchData();
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  const role = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = role === 'super_admin';

  if (dataLoading && !role) return <LoadingSkeleton />;
  if (!role) return <AccessDenied email={user.email} />;

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      {/* GLOBAL TOP NAVIGATION BAR */}
      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">
          {isSuperAdmin ? (
            <div className="flex h-full items-center">
              <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
            </div>
          ) : (
            <span className="font-cinzel text-sm text-primary font-bold tracking-widest">MYKABAYAN</span>
          )}
        </div>

        {/* RIGHT SIDE: Email & Upload Button */}
        <div className="flex items-center gap-3">
          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[120px] sm:max-w-none">
            {user.email}
          </span>

          {/* The Upload button now lives perfectly beside the email! */}
          {(isSuperAdmin || role === 'admin') && (
            <UploadMasterlistFAB onRefresh={fetchData} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {(isSuperAdmin ? activeTab === 'admin' : role === 'admin') && <AdminPipeline {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'dispatch' : role === 'dispatch') && <DispatchBoard {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'accounts' : role === 'accounts') && <AccountsTracking {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'bossing' : role === 'bossing') && <BossingDashboard {...tabProps} />}
        </div>
      )}

import { Search } from 'lucide-react';
import { Input } from '@/components/ui/input';

interface Props {
  title: string;
  subtitle?: string;
  searchQuery: string;
  onSearchChange: (val: string) => void;
  rightContent?: React.ReactNode;
}

export default function TabHeader({ title, subtitle, searchQuery, onSearchChange, rightContent }: Props) {
  return (
    <div className="px-4 pt-6 pb-2">
      <div className="flex items-start justify-between mb-4">
        <div>
          <h1 className="font-cinzel text-xl sm:text-2xl font-bold text-primary tracking-wide uppercase">{title}</h1>
          {subtitle && <p className="text-xs text-muted-foreground mt-0.5">{subtitle}</p>}
        </div>
        {rightContent && (
          <div className="flex items-center">
            {rightContent}
          </div>
        )}
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <Input
          value={searchQuery}
          onChange={(e) => onSearchChange(e.target.value)}
          placeholder="Search client, item, or order ID..."
          className="pl-9 h-10 bg-secondary/30 border-border text-sm"
        />
      </div>
    </div>
  );
}

import { useState, useRef } from 'react';
import { Upload, X, Loader2, CheckCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Sheet, SheetContent, SheetHeader, SheetTitle } from '@/components/ui/sheet';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { uploadFile } from 'zite-file-upload-sdk';
import { createUpload } from 'zite-endpoints-sdk';

interface Props {
  onRefresh: () => void;
}

export default function UploadMasterlistFAB({ onRefresh }: Props) {
  const [open, setOpen] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  const handleUpload = async () => {
    if (!selectedFile) { toast.error('Please select a file'); return; }
    setUploading(true);
    try {
      const { fileUrl } = await uploadFile({ data: selectedFile, filename: selectedFile.name });
      await createUpload({ masterlistFile: fileUrl, status: 'Uploaded' });
      toast.success('File uploaded successfully! Refresh the records when processing is complete.');
      setOpen(false);
      setSelectedFile(null);
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  };

  return (
    <>
<Button size="sm" className="h-7 px-2 text-[10px] sm:text-xs bg-primary text-primary-foreground">
  <Upload className="h-3 w-3 sm:mr-1" />
  <span className="hidden sm:inline">Upload Masterlist</span>
  <span className="sm:hidden">Upload</span>
</Button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent side="bottom" className="bg-card border-border pb-8">
          <SheetHeader className="mb-4">
            <SheetTitle className="font-cinzel text-primary">Upload Masterlist</SheetTitle>
          </SheetHeader>
          <div className="space-y-4">
            <div>
              <Label className="text-sm text-muted-foreground mb-2 block">Select Excel / CSV File</Label>
              <div
                className="border-2 border-dashed border-border rounded-lg p-6 text-center cursor-pointer"
                onClick={() => fileRef.current?.click()}
              >
                {selectedFile ? (
                  <div className="flex items-center justify-center gap-2">
                    <CheckCircle className="h-4 w-4 text-primary" />
                    <span className="text-sm text-foreground">{selectedFile.name}</span>
                    <button onClick={e => { e.stopPropagation(); setSelectedFile(null); }}>
                      <X className="h-4 w-4 text-muted-foreground" />
                    </button>
                  </div>
                ) : (
                  <div>
                    <Upload className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Tap to select file</p>
                  </div>
                )}
              </div>
              <input ref={fileRef} type="file" className="hidden" onChange={e => setSelectedFile(e.target.files?.[0] || null)} />
            </div>
            <Button onClick={handleUpload} disabled={uploading || !selectedFile} className="w-full bg-primary text-primary-foreground">
              {uploading ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" /> Uploading...</> : 'Upload File'}
            </Button>
          </div>
        </SheetContent>
      </Sheet>
    </>
  );
}

