import { useMemo } from 'react';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {

  // 1. Main pipeline: Pending / Waiting for Details, grouped by miner
  const grouped = useMemo(() => {
    const filtered = records.filter(r => r.status === 'Pending' || r.status === 'Waiting for Details');
    return groupByMinerName(applySearch(filtered, searchQuery));
  }, [records, searchQuery]);

  const totalCount = useMemo(() => {
    let count = 0;
    grouped.forEach(items => { count += items.length; });
    return count;
  }, [grouped]);

  // 2. Review Chasing: Delivered within last 3 days, not Skipped/Completed
  const reviewChasingRecords = useMemo(() => {
    const now = new Date();
    const filtered = records.filter(r => {
      if (r.status !== 'Delivered') return false;
      if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
      if (!r.deliveredDate) return false;
      const delivered = parseDateRobust(r.deliveredDate);
      if (!delivered) return false;
      const diffDays = differenceInDays(now, delivered);
      return diffDays >= 0 && diffDays <= 3;
    });
    return applySearch(filtered, searchQuery);
  }, [records, searchQuery]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle={`${grouped.size} clients · ${totalCount} items`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />
      <div className="px-4 pt-4">
        {grouped.size === 0 ? (
          <div className="text-center py-12 border border-dashed border-border rounded-xl">
            <p className="text-sm text-muted-foreground">No pending records found.</p>
            {searchQuery && <p className="text-xs mt-1">Try clearing your search.</p>}
          </div>
        ) : (
          Array.from(grouped.entries()).map(([minerName, items]) => (
            <AdminClientCard
              key={minerName}
              minerName={minerName}
              records={items}
              onUpdate={onUpdate}
              userEmail={userEmail}
            />
          ))
        )}
      </div>

      {/* REVIEW CHASING SECTION */}
      {reviewChasingRecords.length > 0 && (
        <div className="mt-8 px-4 border-t border-border pt-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="font-cinzel text-lg font-bold text-primary">Review Chasing</h2>
              <p className="text-[10px] text-muted-foreground mt-0.5">Delivered within the last 3 days</p>
            </div>
            <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium">
              {reviewChasingRecords.length}
            </span>
          </div>
          <div className="grid grid-cols-1 gap-3">
            {reviewChasingRecords.map(r => (
              <ReviewChasingCard key={r.id} record={r} onUpdate={onUpdate} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

