import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, MapPin, Store, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByLocationSourceMiner } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(true);
  const [showDispatched, setShowDispatched] = useState(true);

  const { forPullout, dispatched } = useMemo(() => {
    const filtered = records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatched');
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByLocationSourceMiner(searched.filter(r => r.status === 'For Pullout')),
      dispatched: groupByLocationSourceMiner(searched.filter(r => r.status === 'Dispatched')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout').length, [records]);

  // Helper function to render the nested 3-level Map (Location -> Source -> Miner)
  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }

    return Array.from(groupedData.entries()).map(([location, sources]) => (
      <div key={location} className="mb-8">
        <div className="flex items-center gap-2 mb-4">
          <MapPin className="h-5 w-5 text-primary" />
          <h2 className="font-cinzel text-lg text-primary tracking-wide uppercase">{location}</h2>
        </div>

        <div className="pl-2 sm:pl-6 border-l-2 border-border/50 space-y-6">
          {Array.from(sources.entries()).map(([source, miners]) => (
            <div key={source}>
              <div className="flex items-center gap-2 mb-3">
                <Store className="h-4 w-4 text-muted-foreground" />
                <h3 className="text-sm font-bold text-foreground">{source}</h3>
              </div>

              <div className="pl-2 sm:pl-6">
                {Array.from(miners.entries()).map(([miner, items]) => (
                  <DispatchClientCard 
                    key={miner} 
                    minerName={miner} 
                    records={items} 
                    onUpdate={onUpdate} 
                    userEmail={userEmail} 
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    ));
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">
        {/* FOR PULLOUT section */}
        <button 
          className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none"
          onClick={() => setShowPullout(!showPullout)}
        >
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>

        {showPullout && (
          <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">
            {renderGroupedRecords(forPullout)}
          </div>
        )}

        {/* DISPATCHED section */}
        <button 
          className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none"
          onClick={() => setShowDispatched(!showDispatched)}
        >
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED</span>
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>

        {showDispatched && (
          <div className="animate-in fade-in slide-in-from-top-2 duration-200">
            {renderGroupedRecords(dispatched)}
          </div>
        )}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useState, memo } from 'react';
import { FileText, Truck, User, Upload, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});
  const first = records[0];

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));

    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }

    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();

    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <div className="px-4 py-2.5 border-b border-border/50 flex items-center justify-between">
        <div>
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Live: {formatDate(first?.dateOfLive)}</span>
            {first?.fbProfileName && <span className="flex items-center gap-1"><User className="h-3 w-3" />{first.fbProfileName}</span>}
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <Button variant="outline" size="sm" className="border-primary/40 text-primary text-xs h-7" onClick={() => setShowInvoice(true)}>
          <FileText className="h-3 w-3 mr-1" /> Invoice
        </Button>
      </div>

      <div className="px-3 py-2 space-y-2">
        {records.map(record => {
          const givenToShopMode = isGivenToShopMode(record);
          const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;

          return (
            <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
              <div className="flex items-start justify-between mb-2">
                <div>
                  <p className="text-sm font-medium">{record.itemDescription}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {record.category} · {record.grams ? `${record.grams}g` : 'PC'} 
                    <span className="text-foreground font-medium ml-1">
                      · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                    </span>
                  </p>
                </div>
                <StatusBadge status={record.status} />
              </div>

              <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                <Truck className="h-3 w-3" />
                <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
              </div>

              {record.liverAdminRemarks && (
                <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                  Remarks: {record.liverAdminRemarks}
                </p>
              )}

              {latestAudit && (
                <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                  <History className="h-2.5 w-2.5" />
                  {latestAudit}
                </p>
              )}

              <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                  <SelectValue placeholder="Set status..." />
                </SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {givenToShopMode ? (
                    <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                  ) : (
                    <>
                      <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                      <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                    </>
                  )}
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          );
        })}
      </div>

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// MEMO: Prevent re-rendering unchanged clients
export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

/** Robustly parse a date string from Google Sheets */
export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

// FIX: Only treat as "Per Piece" (PC) if grams are 0 or empty. 
// We no longer force "Silver" to be a PC item.
export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6; 
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6; 
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record.currency);
}

// FIX: Now correctly multiplies Grams * Rate for Silver and Gold
export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

// FIX: Now correctly multiplies Grams * Rate in AED
export function calcItemPriceAED(record: DatabaseRowType): number {
  const clientRateInAED = clientRateAED(record);
  if (isPcItem(record)) return clientRateInAED;
  return n(record.grams) * clientRateInAED;
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  const goldRate = n(record.goldRate);
  const grams = n(record.grams);
  const isSilver = (record.category || '').toLowerCase().includes('silver');

  // If it's a Per Piece item (0 grams), Cost = Supplier Rate + MC
  if (isPcItem(record)) return supplierRate + mc;

  // If Silver by weight, Cost = Gold Rate * Grams (MC is not applied to Silver)
  if (isSilver) return goldRate * grams;

  // If Gold by weight, Cost = (Gold Rate + MC) * Grams
  return (goldRate + mc) * grams;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  const profit = totalSales - totalCost;

  // SAFETY: Never return negative profit to the dashboard
  return profit < 0 ? 0 : profit;
}

export function calcProfit(record: DatabaseRowType): number {
  return calcItemPrice(record) - calcItemCostAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;
  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    return 30;
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { 
  calcProfitAED, 
  calcRemainingBalance, 
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});

  const dateFiltered = useMemo(() => {
    const base = records.filter(r => r.status !== 'Cancelled');

    if (range === 'all') return base;

    const now = new Date();
    let from: Date;

    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0); 

    const to = range === 'custom' ? customTo : undefined;

    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;

      const itemTime = d.getTime();
      if (itemTime < from.getTime()) return false;

      if (to) {
        const endOfToDay = new Date(to);
        endOfToDay.setHours(23, 59, 59, 999);
        if (itemTime > endOfToDay.getTime()) return false;
      }

      return true;
    });
  }, [records, range, customFrom, customTo]);

  // FIX: Apply the search query to the date-filtered data
  const filtered = useMemo(() => {
    return applySearch(dateFiltered, searchQuery);
  }, [dateFiltered, searchQuery]);

  const kpis = useMemo(() => {
    const totalProfit = filtered.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;
    const outstanding = filtered
      .filter(r => r.status !== 'Cancelled')
      .reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    return { totalProfit, totalSold, outstanding };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const toggleStatus = (status: string) => {
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));
  };

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  const handlePrintReport = () => {
    const win = window.open('', '_blank');
    if (!win) return;

    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin-bottom: 4px; font-size: 24px; color: #111; }
        .summary { margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-radius: 8px; border: 1px solid #ddd; }
        .summary p { margin: 6px 0; font-size: 14px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
        th { background: #111; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
        th.r, td.r { text-align: right; }
        td { padding: 8px; border-bottom: 1px solid #ddd; }
        .status-header { font-size: 16px; margin-top: 24px; margin-bottom: 8px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px;}
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
      </style></head><body>

      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>

      <div class="summary">
        <p>Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></p>
        <p>Total Items Sold: ${kpis.totalSold}</p>
        <p>Outstanding Receivables: AED ${kpis.outstanding.toFixed(2)}</p>
        <p style="font-size: 11px; color: #666; font-weight: normal; margin-top: 12px;">Date Range: ${dateRangeLabel} | Generated: ${new Date().toLocaleString()}</p>
      </div>
    `;

    Array.from(statusGroups.entries()).sort().forEach(([status, items]) => {
      const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
      html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} (${items.length} items | Profit: AED ${statusProfit.toFixed(2)})</h2>`;
      html += `<table><thead><tr>
        <th>Client</th>
        <th>Item</th>
        <th>Date</th>
        <th class="r">Price (AED)</th>
        <th class="r">Cost (AED)</th>
        <th class="r">Profit (AED)</th>
      </tr></thead><tbody>`;

      items.forEach(r => {
         const profit = calcProfitAED(r);
         const profitClass = profit >= 0 ? 'profit-pos' : 'profit-neg';
         html += `<tr>
           <td><strong>${r.minerName || '—'}</strong></td>
           <td>${r.itemDescription || '—'}</td>
           <td>${formatDate(r.dateOfLive)}</td>
           <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
           <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
           <td class="r"><strong class="${profitClass}">${profit.toFixed(2)}</strong></td>
         </tr>`;
      });

      html += `</tbody></table>`;
    });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3 mb-6">
          <KpiCard
            title="Total Expected Profit"
            value={`AED ${kpis.totalProfit.toFixed(2)}`}
            subtitle={`${filtered.length} active records (excl. Cancelled)`}
            highlight
          />
          <KpiCard
            title="Total Items Sold"
            value={kpis.totalSold.toString()}
            subtitle="Delivered/Given to Shop (excl. Cancelled)"
          />
          <KpiCard
            title="Outstanding Receivables"
            value={`AED ${kpis.outstanding.toFixed(2)}`}
            subtitle="Sum of remaining balances (excl. Cancelled)"
          />
        </div>

        <div className="flex items-center justify-between mb-4">
          <h2 className="font-cinzel text-lg text-primary">Detailed Breakdown</h2>
          <Button variant="outline" size="sm" className="h-8 text-xs border-primary/40 text-primary" onClick={handlePrintReport}>
            <Printer className="h-3.5 w-3.5 mr-1.5" /> Print Report
          </Button>
        </div>

        <div className="space-y-3">
          {Array.from(statusGroups.entries()).sort().map(([status, items]) => {
            const totalProfit = items.reduce((sum, r) => sum + calcProfitAED(r), 0);
            const isExpanded = expandedStatuses[status];

            return (
              <div key={status} className="rounded-xl border border-border bg-card overflow-hidden">
                <button 
                  onClick={() => toggleStatus(status)} 
                  className="w-full flex items-center justify-between p-4 text-left focus:outline-none"
                >
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <StatusBadge status={status} />
                      <span className="text-xs text-muted-foreground">{items.length} items</span>
                    </div>
                    <p className="text-xs font-medium">
                      Profit: <span className={totalProfit >= 0 ? 'text-green-400' : 'text-destructive'}>AED {totalProfit.toFixed(2)}</span>
                    </p>
                  </div>
                  <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {isExpanded && (
                  <div className="px-4 pb-4 border-t border-border pt-4 space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                    {items.map(record => {
                      const profit = calcProfitAED(record);
                      return (
                        <div key={record.id} className="flex justify-between items-start border-b border-border/40 pb-3 last:border-0 last:pb-0">
                          <div className="flex-1 pr-2">
                            <p className="text-sm font-medium">{record.minerName || 'Unknown'}</p>
                            <p className="text-xs text-muted-foreground mt-0.5 truncate">{record.itemDescription} ({record.grams ? `${record.grams}g` : 'PC'})</p>
                            <p className="text-[10px] text-muted-foreground mt-1">Live: {formatDate(record.dateOfLive)}</p>
                          </div>
                          <div className="text-right shrink-0">
                            <p className={`text-sm font-medium ${profit >= 0 ? 'text-foreground' : 'text-destructive'}`}>
                              AED {profit.toFixed(2)}
                            </p>
                            <p className="text-[10px] text-muted-foreground mt-0.5">Profit</p>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          })}

          {statusGroups.size === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No records found for this period.</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

