import { useMemo } from 'react';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {

  // 1. Main pipeline: Pending / Waiting for Details, grouped by miner
  const grouped = useMemo(() => {
    const filtered = records.filter(r => r.status === 'Pending' || r.status === 'Waiting for Details');
    return groupByMinerName(applySearch(filtered, searchQuery));
  }, [records, searchQuery]);

  const totalCount = useMemo(() => {
    let count = 0;
    grouped.forEach(items => { count += items.length; });
    return count;
  }, [grouped]);

  // 2. Review Chasing: Delivered within last 3 days, not Skipped/Completed
  const reviewChasingRecords = useMemo(() => {
    const now = new Date();
    const filtered = records.filter(r => {
      if (r.status !== 'Delivered') return false;
      if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
      if (!r.deliveredDate) return false;
      const delivered = parseDateRobust(r.deliveredDate);
      if (!delivered) return false;
      const diffDays = differenceInDays(now, delivered);
      return diffDays >= 0 && diffDays <= 3;
    });
    return applySearch(filtered, searchQuery);
  }, [records, searchQuery]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle={`${grouped.size} clients · ${totalCount} items`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />
      <div className="px-4 pt-4">
        {grouped.size === 0 ? (
          <div className="text-center py-12 border border-dashed border-border rounded-xl">
            <p className="text-sm text-muted-foreground">No pending records found.</p>
            {searchQuery && <p className="text-xs mt-1">Try clearing your search.</p>}
          </div>
        ) : (
          Array.from(grouped.entries()).map(([minerName, items]) => (
            <AdminClientCard
              key={minerName}
              minerName={minerName}
              records={items}
              onUpdate={onUpdate}
              userEmail={userEmail}
            />
          ))
        )}
      </div>

      {/* REVIEW CHASING SECTION */}
      {reviewChasingRecords.length > 0 && (
        <div className="mt-8 px-4 border-t border-border pt-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="font-cinzel text-lg font-bold text-primary">Review Chasing</h2>
              <p className="text-[10px] text-muted-foreground mt-0.5">Delivered within the last 3 days</p>
            </div>
            <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium">
              {reviewChasingRecords.length}
            </span>
          </div>
          <div className="grid grid-cols-1 gap-3">
            {reviewChasingRecords.map(r => (
              <ReviewChasingCard key={r.id} record={r} onUpdate={onUpdate} />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, memo } from 'react';
import { ChevronDown, FileText, MapPin, User, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue, calcDueDate } from '@/lib/calculations';
import { formatDate, formatDateObj } from '@/lib/formatters';
import AdminItemRow from './AdminItemRow';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function AdminClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const first = records[0];
  const hasOverdue = records.some(isOverdue);
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    await Promise.all(records.map(r => onUpdate(r.id, fields)));
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {hasOverdue && (
              <span className="shrink-0 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">OVERDUE</span>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{first?.locationOfMiner || '—'}</span>
            {first?.fbProfileName && <span className="flex items-center gap-1"><User className="h-3 w-3" />{first.fbProfileName}</span>}
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
          </div>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>Live: {formatDate(first?.dateOfLive)}</span>
            <span>Due: {dueDate}</span>
          </div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {records.map(record => (
            <AdminItemRow
              key={record.id}
              record={record}
              onUpdate={onUpdate}
              onGroupUpdate={handleGroupUpdate}
              userEmail={userEmail}
            />
          ))}
          <Button
            variant="outline"
            size="sm"
            className="w-full mt-2 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
    </div>
  );
}

// MEMO: Prevent re-rendering unchanged clients
export default memo(AdminClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

