import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles'; 
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[]>([]);

  const [dataLoading, setDataLoading] = useState(true); 
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  const fetchData = useCallback(() => {
    if (!user) return;
    setDataLoading(true);

    Promise.all([
      getRecords({}).catch(() => { toast.error('Failed to load records'); return []; }),
      getRoles({}).catch(() => { return []; })
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        setDynamicRoles((rolesData as any[]) || []);
      })
      .finally(() => setDataLoading(false));
  }, [user]);

  useEffect(() => { fetchData(); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));
    try {
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });
    } catch {
      toast.error('Failed to save changes');
      fetchData();
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  const role = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = role === 'super_admin';

  if (dataLoading && !role) return <LoadingSkeleton />;
  if (!role) return <AccessDenied email={user.email} />;

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">

          {/* Small Top Bar Logo */}
          <img 
            src="https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png" 
            alt="Logo" 
            className="h-6 sm:h-8 w-auto object-contain mr-2 sm:mr-4" 
          />

          {isSuperAdmin && (
            <div className="flex h-full items-center border-l border-border pl-2 sm:pl-4">
              <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${activeTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
            </div>
          )}
        </div>

        <div className="flex items-center gap-3">
          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[120px] sm:max-w-none">
            {user.email}
          </span>

          {(isSuperAdmin || role === 'admin') && (
            <UploadMasterlistFAB onRefresh={fetchData} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {(isSuperAdmin ? activeTab === 'admin' : role === 'admin') && <AdminPipeline {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'dispatch' : role === 'dispatch') && <DispatchBoard {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'accounts' : role === 'accounts') && <AccountsTracking {...tabProps} />}
          {(isSuperAdmin ? activeTab === 'bossing' : role === 'bossing') && <BossingDashboard {...tabProps} />}
        </div>
      )}
    </div>
  );
}
} catch {
      toast.error('Failed to save changes');
      fetchData(); // <-- This is heavy
    }

