  auditTrail?: string; // "Audit Trail"
  id: number;
};

/**
 * Type definition for a row in the "Uploads" sheet
 */
export type UploadsRowType = {
  uploadId?: string; // "Staff/Uploader"
  masterlistFile?: string; // "Masterlist File"
  status?: string; // "Status"
