  return (
    <div className="bg-card border border-border rounded-lg p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
      <div>
        <h3 className="font-medium text-sm">{record.minerName || 'Unknown Client'}</h3>
        <p className="text-xs text-muted-foreground mt-1">{record.itemDescription}</p>
        <p className="text-[10px] text-muted-foreground mt-1">
          Delivered: {record.deliveredDate ? formatDate(record.deliveredDate) : 'Unknown'}
        </p>
      </div>
      
      <div className="flex items-center gap-2">
        <Select
          value={status}
          onValueChange={(val) => onUpdate(record.id, { reviewChasing: val })}
