          Delivered: {record.deliveredDate ? formatDate(record.deliveredDate) : 'Unknown'}
        </p>
      </div>

      <div className="flex items-center gap-2">
        <Select
          value={status}
          onValueChange={(val) => onUpdate(record.id, { reviewChasing: val })}
        >
          <SelectTrigger className="w-[130px] h-8 text-xs border-border bg-secondary/30">
            <SelectValue placeholder="Select status" />
          </SelectTrigger>
          <SelectContent className="border-border">
            <SelectItem value="Pending">Pending</SelectItem>
            <SelectItem value="Chased">Chased</SelectItem>
            <SelectItem value="Skipped">Skipped</SelectItem>
            <SelectItem value="Completed">Completed</SelectItem>
          </SelectContent>
        </Select>
      </div>
    </div>
  );
}

export default memo(ReviewChasingCard, (prev, next) => {
  return prev.record === next.record;
});

