import { useMemo, useState } from 'react';
import { ChevronDown } from 'lucide-react';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [minedExpanded, setMinedExpanded] = useState(true);
  const [reviewExpanded, setReviewExpanded] = useState(true);

  const grouped = useMemo(() => {
    const filtered = records.filter(r => r.status === 'Pending' || r.status === 'Waiting for Details');
    return groupByMinerName(applySearch(filtered, searchQuery));
  }, [records, searchQuery]);

  const totalCount = useMemo(() => {
    let count = 0;
    grouped.forEach(items => { count += items.length; });
    return count;
  }, [grouped]);

  const reviewChasingGroups = useMemo(() => {
    const now = new Date();
    const filtered = records.filter(r => {
      if (r.status !== 'Delivered') return false;
      if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
      if (!r.deliveredDate) return false;
      const delivered = parseDateRobust(r.deliveredDate);
      if (!delivered) return false;
      const diffDays = differenceInDays(now, delivered);
      return diffDays >= 0 && diffDays <= 3;
    });

    const searched = applySearch(filtered, searchQuery);
    const groupedByClient = groupByMinerName(searched);

    // Convert to array and sort: Pending first, Chased last
    return Array.from(groupedByClient.entries()).map(([minerName, items]) => {
      const isChased = items.every(i => i.reviewChasing === 'Chased');
      return { minerName, items, isChased };
    }).sort((a, b) => {
      if (a.isChased === b.isChased) return 0;
      return a.isChased ? 1 : -1; // Pushes Chased items to the bottom
    });
  }, [records, searchQuery]);

  const reviewChasingTotal = useMemo(() => {
    return reviewChasingGroups.reduce((acc, group) => acc + group.items.length, 0);
  }, [reviewChasingGroups]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle={`${grouped.size} clients · ${totalCount} items`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* MINED ITEMS SECTION */}
        <button
          className="flex w-full items-center gap-3 mb-4 text-left focus:outline-none group"
          onClick={() => setMinedExpanded(e => !e)}
        >
          <span className="font-cinzel text-sm font-bold text-foreground whitespace-nowrap">
            MINED ITEMS
          </span>
          <span className="text-xs text-muted-foreground whitespace-nowrap">
            {grouped.size} clients · {totalCount} items
          </span>
          <div className="h-px flex-1 bg-border" />
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${minedExpanded ? 'rotate-180' : ''}`} />
        </button>

        {minedExpanded && (
          <div className="mb-2 animate-in fade-in slide-in-from-top-2 duration-200">
            {grouped.size === 0 ? (
              <div className="text-center py-12 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No pending records found.</p>
                {searchQuery && <p className="text-xs mt-1">Try clearing your search.</p>}
              </div>
            ) : (
              Array.from(grouped.entries()).map(([minerName, items]) => (
                <AdminClientCard
                  key={minerName}
                  minerName={minerName}
                  records={items}
                  onUpdate={onUpdate}
                  userEmail={userEmail}
                />
              ))
            )}
          </div>
        )}

        {/* REVIEW CHASING SECTION */}
        {reviewChasingGroups.length > 0 && (
          <div className="mt-6">
            <div className="h-px bg-border mb-6" />

            <button
              className="flex w-full items-center gap-3 mb-4 text-left focus:outline-none"
              onClick={() => setReviewExpanded(e => !e)}
            >
              <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap">
                REVIEW CHASING
              </span>
              <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium whitespace-nowrap">
                {reviewChasingTotal} items
              </span>
              <div className="h-px flex-1 bg-border" />
              <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${reviewExpanded ? 'rotate-180' : ''}`} />
            </button>

            {reviewExpanded && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                <p className="text-[10px] text-muted-foreground mb-3">Delivered within the last 3 days</p>
                <div className="grid grid-cols-1 gap-3">
                  {reviewChasingGroups.map(group => (
                    <ReviewChasingCard 
                      key={group.minerName} 
                      minerName={group.minerName}
                      records={group.items} 
                      onUpdate={onUpdate} 
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, MapPin, Store, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByLocationSourceMiner } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(true);
  const [showDispatched, setShowDispatched] = useState(true);

  const { forPullout, dispatched } = useMemo(() => {
    const filtered = records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatched');
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByLocationSourceMiner(searched.filter(r => r.status === 'For Pullout')),
      dispatched: groupByLocationSourceMiner(searched.filter(r => r.status === 'Dispatched')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout').length, [records]);

  // Helper function to render the nested 3-level Map (Location -> Source -> Miner)
  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }

    return Array.from(groupedData.entries()).map(([location, sources]) => (
      <div key={location} className="mb-8">
        <div className="flex items-center gap-2 mb-4">
          <MapPin className="h-5 w-5 text-primary" />
          <h2 className="font-cinzel text-lg text-primary tracking-wide uppercase">{location}</h2>
        </div>

        <div className="pl-2 sm:pl-6 border-l-2 border-border/50 space-y-6">
          {Array.from(sources.entries()).map(([source, miners]) => (
            <div key={source}>
              <div className="flex items-center gap-2 mb-3">
                <Store className="h-4 w-4 text-muted-foreground" />
                <h3 className="text-sm font-bold text-foreground">{source}</h3>
              </div>

              <div className="pl-2 sm:pl-6">
                {Array.from(miners.entries()).map(([miner, items]) => (
                  <DispatchClientCard 
                    key={miner} 
                    minerName={miner} 
                    records={items} 
                    onUpdate={onUpdate} 
                    userEmail={userEmail} 
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    ));
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">
        {/* FOR PULLOUT section */}
        <button 
          className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none"
          onClick={() => setShowPullout(!showPullout)}
        >
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>

        {showPullout && (
          <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">
            {renderGroupedRecords(forPullout)}
          </div>
        )}

        {/* DISPATCHED section */}
        <button 
          className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none"
          onClick={() => setShowDispatched(!showDispatched)}
        >
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED</span>
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>

        {showDispatched && (
          <div className="animate-in fade-in slide-in-from-top-2 duration-200">
            {renderGroupedRecords(dispatched)}
          </div>
        )}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useState, memo } from 'react';
import { FileText, Truck, User, Upload, History, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function getDeliveryLabel(record: DatabaseRowType): string {
  const mop = record.modeOfPayment || '';
  const region = record.regions ? `(${record.regions})` : '';
  if (mop === 'Pick Up Shop') return 'Pick Up Shop';
  if (mop === 'Meet Up') return 'Meet Up';
  if (mop === 'Layaway') return 'Layaway';
  if (region) return `${mop} ${region}`.trim();
  return mop || 'Unknown';
}

function getDeliverySummary(records: DatabaseRowType[]): string {
  const labels = records.map(getDeliveryLabel);
  const unique = [...new Set(labels)];
  if (unique.length === 1) return unique[0];
  return `🔴 MIXED: ${unique.join(', ')}`;
}

function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});
  const first = records[0];
  const deliverySummary = getDeliverySummary(records);

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      {/* Header — always visible, click to toggle */}
      <button
        className="w-full px-4 py-2.5 border-b border-border/50 flex items-center justify-between text-left focus:outline-none"
        onClick={() => setIsExpanded(prev => !prev)}
      >
        <div className="flex-1 min-w-0">
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span className={deliverySummary.startsWith('🔴') ? 'text-destructive font-medium' : ''}>
              {deliverySummary}
            </span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 ml-2 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="border-primary/40 text-primary text-xs h-7"
            onClick={e => { e.stopPropagation(); setShowInvoice(true); }}
          >
            <FileText className="h-3 w-3 mr-1" /> Invoice
          </Button>
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {/* Expanded content */}
      {isExpanded && (
        <div className="px-3 py-2 space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          {records.map(record => {
            const givenToShopMode = isGivenToShopMode(record);
            const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;
            return (
              <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <p className="text-sm font-medium">{record.itemDescription}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {record.category} · {record.grams ? `${record.grams}g` : 'PC'}
                      <span className="text-foreground font-medium ml-1">
                        · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                      </span>
                    </p>
                  </div>
                  <StatusBadge status={record.status} />
                </div>
                <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                  <Truck className="h-3 w-3" />
                  <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                  {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
                </div>
                {record.liverAdminRemarks && (
                  <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                    Remarks: {record.liverAdminRemarks}
                  </p>
                )}
                {latestAudit && (
                  <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                    <History className="h-2.5 w-2.5" />
                    {latestAudit}
                  </p>
                )}
                <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                  <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                    <SelectValue placeholder="Set status..." />
                  </SelectTrigger>
                  <SelectContent className="bg-popover border-border">
                    {givenToShopMode ? (
                      <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                    ) : (
                      <>
                        <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                        <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                      </>
                    )}
                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            );
          })}
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

import { useRef } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Printer } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { formatDate, formatDateObj } from '@/lib/formatters';
import { calcItemPrice, calcShippingFee, calcCCFee, calcDueDate, fromAED } from '@/lib/calculations';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const first = records[0];
  const currency = first?.currency || 'AED';

  // All amounts in client currency
  const subtotal = records.reduce((sum, r) => sum + calcItemPrice(r), 0);
  const shippingFeeAED = first ? calcShippingFee(first) : 0;
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const additionalChargesAED = parseFloat(first?.additionalCharges || '0') || 0;
  const shippingFee = fromAED(shippingFeeAED, currency);
  const ccFee = fromAED(ccFeeAED, currency);
  const additionalCharges = fromAED(additionalChargesAED, currency);
  const grandTotal = subtotal + shippingFee + ccFee + additionalCharges;
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<html><head><title>Invoice</title><style>
      body { font-family: 'Lato', sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; }
      h1, h2, .cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
      table { width: 100%; border-collapse: collapse; margin-top: 12px; }
      th { background: #f5f0e8; padding: 8px; text-align: left; font-size: 12px; }
      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 13px; }
      .total-row td { font-weight: bold; border-top: 2px solid #C9A84C; }
      .gold { color: #C9A84C; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Client Invoice</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <div className="mb-4 pb-4 border-b border-border">
            <h2 className="font-cinzel text-lg text-primary mb-1">INVOICE</h2>
            <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
              <span>Client: <span className="text-foreground font-medium">{first?.minerName}</span></span>
              <span>Date: <span className="text-foreground">{formatDate(first?.dateOfLive)}</span></span>
              <span>Region: <span className="text-foreground">{first?.regions || '—'}</span></span>
              <span>Due: <span className="text-foreground">{dueDate}</span></span>
              <span className="col-span-2">Payment: <span className="text-foreground">{first?.modeOfPayment || '—'}</span></span>
            </div>
          </div>
          <table className="w-full text-xs mb-4">
            <thead>
              <tr className="border-b border-border">
                <th className="text-left py-1 text-muted-foreground font-medium">Item</th>
                <th className="text-left py-1 text-muted-foreground font-medium">Cat</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Grams</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Rate</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Price</th>
              </tr>
            </thead>
            <tbody>
              {records.map(r => (
                <tr key={r.id} className="border-b border-border/50">
                  <td className="py-1.5 pr-2">{r.itemDescription}</td>
                  <td className="py-1.5">{r.category}</td>
                  <td className="py-1.5 text-right">{r.grams || 'PC'}</td>
                  <td className="py-1.5 text-right">{currency} {Number(r.clientRate || 0).toFixed(2)}</td>
                  <td className="py-1.5 text-right">{currency} {calcItemPrice(r).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="space-y-1 text-xs border-t border-border pt-3">
            <div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span>{currency} {subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>{currency} {shippingFee.toFixed(2)}</span></div>
            {additionalCharges > 0 && <div className="flex justify-between"><span className="text-muted-foreground">Additional Charges</span><span>{currency} {additionalCharges.toFixed(2)}</span></div>}
            {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Surcharge</span><span>{currency} {ccFee.toFixed(2)}</span></div>}
            <div className="flex justify-between font-bold text-sm pt-2 border-t border-primary/30">
              <span className="font-cinzel text-primary">GRAND TOTAL</span>
              <span className="text-primary">{currency} {grandTotal.toFixed(2)}</span>
            </div>
          </div>
        </div>
        <Button onClick={handlePrint} className="w-full mt-2 bg-primary text-primary-foreground">
          <Printer className="h-4 w-4 mr-2" /> Print / Save as PDF
        </Button>
      </DialogContent>
    </Dialog>
  );
}

