export function calcItemCostAED(record: DatabaseRowType): number {
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);
  const goldRate = n(record.goldRate);
  const grams = n(record.grams);
  const category = (record.category || '').toLowerCase();

  // Per Piece (0 grams): Cost = Supplier Rate + MC
  if (isPcItem(record)) return supplierRate + mc;

  // Silver Branded (check before Silver): fixed AED rate
  if (category.includes('silver branded')) return 32 * grams;

  // Silver: fixed AED rate
  if (category.includes('silver')) return 15 * grams;

  // Gold / default: (Gold Rate + MC) * Grams
  return (goldRate + mc) * grams;
}

