import { format, parseISO, isValid } from 'date-fns';
import { DatabaseRowType } from '@/types';

export function formatDate(dateStr?: string): string {
  if (!dateStr) return '—';
  try {
    const d = parseISO(dateStr);
    if (!isValid(d)) return dateStr;
    return format(d, 'MMM dd, yyyy');
  } catch {
    return dateStr;
  }
}

export function formatDateObj(date: Date | null): string {
  if (!date || !isValid(date)) return '—';
  return format(date, 'MMM dd, yyyy');
}

export function formatCurrency(value: number, currency?: string): string {
  const curr = currency || 'AED';
  return `${curr} ${value.toFixed(2)}`;
}

export function groupByMinerName(records: DatabaseRowType[]): Map<string, DatabaseRowType[]> {
  const map = new Map<string, DatabaseRowType[]>();
  for (const record of records) {
    const key = record.minerName?.trim() || 'Unknown Client';
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(record);
  }
  return map;
}

export function groupByLocationSourceMiner(
  records: DatabaseRowType[]
): Map<string, Map<string, Map<string, DatabaseRowType[]>>> {
  const grouped = new Map<string, Map<string, Map<string, DatabaseRowType[]>>>();
  for (const record of records) {
    const location = record.locationOfMiner?.trim() || 'Local'; 
    const source = record.source?.trim() || 'Main Store'; 
    const miner = record.minerName?.trim() || 'Unknown Client';

    if (!grouped.has(location)) grouped.set(location, new Map());
    const byLocation = grouped.get(location)!;

    if (!byLocation.has(source)) byLocation.set(source, new Map());
    const bySource = byLocation.get(source)!;

    if (!bySource.has(miner)) bySource.set(miner, []);
    bySource.get(miner)!.push(record);
  }
  return grouped;
}

export function applySearch(records: DatabaseRowType[], query: string): DatabaseRowType[] {
  if (!query.trim()) return records;
  const q = query.toLowerCase();

  const matchingMiners = new Set<string>();
  for (const r of records) {
    if (
      r.minerName?.toLowerCase().includes(q) ||
      r.itemDescription?.toLowerCase().includes(q) ||
      r.orderId?.toLowerCase().includes(q)
    ) {
      if (r.minerName) matchingMiners.add(r.minerName);
    }
  }

  return records.filter(r => r.minerName && matchingMiners.has(r.minerName));
}

export const MOP_OPTIONS = [
  'Tabby', 'Tamara', 'COD', 'Bank Transfer', 'Credit Card',
  'GCash', 'Meet Up', 'Pick Up Shop', 'Layaway',
];

export const REGION_OPTIONS = [
  'Dubai', 'Abu Dhabi', 'Sharjah', 'Ajman', 'Western Region', 'UAQ', 'RAK', 'Fujairah',
];

export const STATUS_COLORS: Record<string, string> = {
  'Pending': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
  'Waiting for Details': 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  'Paid but Item Hold': 'bg-indigo-500/20 text-indigo-400 border-indigo-500/30',
  'For Pullout': 'bg-purple-500/20 text-purple-400 border-purple-500/30',
  'Dispatch': 'bg-fuchsia-500/20 text-fuchsia-400 border-fuchsia-500/30',
  'Dispatched': 'bg-orange-500/20 text-orange-400 border-orange-500/30',
  'Delivered': 'bg-green-500/20 text-green-400 border-green-500/30',
  'Cancelled': 'bg-red-500/20 text-red-400 border-red-500/30',
};

import { useMemo, useState } from 'react';
import { ChevronDown } from 'lucide-react';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [minedExpanded, setMinedExpanded] = useState(true);
  const [reviewExpanded, setReviewExpanded] = useState(true);

  const grouped = useMemo(() => {
    const filtered = records.filter(r => 
      r.status === 'Pending' || 
      r.status === 'Waiting for Details' || 
      r.status === 'Paid but Item Hold'
    );
    return groupByMinerName(applySearch(filtered, searchQuery));
  }, [records, searchQuery]);

  const totalCount = useMemo(() => {
    let count = 0;
    grouped.forEach(items => { count += items.length; });
    return count;
  }, [grouped]);

  const reviewChasingGroups = useMemo(() => {
    const now = new Date();
    const filtered = records.filter(r => {
      if (r.status !== 'Delivered') return false;
      if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
      if (!r.deliveredDate) return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      const delivered = parseDateRobust(r.deliveredDate);
      if (!delivered) return false;
      const diffDays = differenceInDays(now, delivered);
      return diffDays >= 0 && diffDays <= 3;
    });

    const searched = applySearch(filtered, searchQuery);
    const groupedByClient = groupByMinerName(searched);

    return Array.from(groupedByClient.entries()).map(([minerName, items]) => {
      const isChased = items.every(i => i.reviewChasing === 'Chased');
      return { minerName, items, isChased };
    }).sort((a, b) => {
      if (a.isChased === b.isChased) return 0;
      return a.isChased ? 1 : -1; 
    });
  }, [records, searchQuery]);

  const reviewChasingTotal = useMemo(() => {
    return reviewChasingGroups.reduce((acc, group) => acc + group.items.length, 0);
  }, [reviewChasingGroups]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle={`${grouped.size} clients · ${totalCount} items`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        <button
          className="flex w-full items-center gap-3 mb-4 text-left focus:outline-none group"
          onClick={() => setMinedExpanded(e => !e)}
        >
          <span className="font-cinzel text-sm font-bold text-foreground whitespace-nowrap">
            MINED ITEMS
          </span>
          <span className="text-xs text-muted-foreground whitespace-nowrap">
            {grouped.size} clients · {totalCount} items
          </span>
          <div className="h-px flex-1 bg-border" />
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${minedExpanded ? 'rotate-180' : ''}`} />
        </button>

        {minedExpanded && (
          <div className="mb-2 animate-in fade-in slide-in-from-top-2 duration-200">
            {grouped.size === 0 ? (
              <div className="text-center py-12 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No pending records found.</p>
                {searchQuery && <p className="text-xs mt-1">Try clearing your search.</p>}
              </div>
            ) : (
              Array.from(grouped.entries()).map(([minerName, items]) => (
                <AdminClientCard
                  key={minerName}
                  minerName={minerName}
                  records={items}
                  onUpdate={onUpdate}
                  userEmail={userEmail}
                />
              ))
            )}
          </div>
        )}

        {reviewChasingGroups.length > 0 && (
          <div className="mt-6">
            <div className="h-px bg-border mb-6" />

            <button
              className="flex w-full items-center gap-3 mb-4 text-left focus:outline-none"
              onClick={() => setReviewExpanded(e => !e)}
            >
              <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap">
                REVIEW CHASING
              </span>
              <span className="text-xs bg-primary/20 text-primary px-2 py-0.5 rounded-full font-medium whitespace-nowrap">
                {reviewChasingTotal} items
              </span>
              <div className="h-px flex-1 bg-border" />
              <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${reviewExpanded ? 'rotate-180' : ''}`} />
            </button>

            {reviewExpanded && (
              <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                <p className="text-[10px] text-muted-foreground mb-3">Delivered within the last 3 days</p>
                <div className="grid grid-cols-1 gap-3">
                  {reviewChasingGroups.map(group => (
                    <ReviewChasingCard 
                      key={group.minerName} 
                      minerName={group.minerName}
                      records={group.items} 
                      onUpdate={onUpdate} 
                    />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, memo } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue, isFreeSf } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

const TOG_OPTIONS = ['18K', 'VCA', '21K', '24K', 'S-925'];

function isInStore(record: DatabaseRowType): boolean {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  return mos === 'in-store' || mos === 'walk-in' || mos === 'walk in';
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = (remarks || '').toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('tamara approved')) return { modeOfPayment: 'Tamara', freeSf: 'TRUE' };
  if (/\bcod\b/.test(r)) return { modeOfPayment: 'COD' };
  if (/\bcc\b/.test(r) || r.includes('credit card')) return { modeOfPayment: 'Credit Card' };
  return null;
}

function AdminItemRow({ record, onUpdate, onGroupUpdate, userEmail }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const [pureWeight, setPureWeight] = useState(record.pureWeight || '');
  const [resetKey, setResetKey] = useState(Date.now());
  const overdue = isOverdue(record);
  const inStore = isInStore(record);

  useEffect(() => {
    if (!record.modeOfPayment && record.liverAdminRemarks) {
      const auto = detectAutoFill(record.liverAdminRemarks);
      if (auto) onGroupUpdate(auto);
    }
  }, [record.modeOfPayment, record.liverAdminRemarks, onGroupUpdate]);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const autoFill = detectAutoFill(val);
    await onUpdate(record.id, { liverAdminRemarks: val });
    if (autoFill) {
      await onGroupUpdate(autoFill);
      toast.success('Auto-filled MOP from remarks');
    }
  }, 700);

  const debouncedPureWeight = useDebouncedCallback(async (val: string) => {
    await onUpdate(record.id, { pureWeight: val });
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    if (mop === 'Tabby' || mop === 'Tamara') fields.freeSf = 'TRUE';
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    await onGroupUpdate({ regions: region });
  };

  const handleTogChange = async (tog: string) => {
    await onUpdate(record.id, { tog });
  };

  const handleStatusChange = async (newStatus: string) => {
    setResetKey(Date.now());

    if (newStatus === 'Cancelled') { setShowCancel(true); return; }
    if (newStatus === 'For Pullout' || newStatus === 'Dispatch') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }

    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> OVERDUE
              </span>
            )}
          </div>
        </div>
        <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">{record.grams ? `${record.grams}g` : 'PC'}</p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {!inStore && record.locationOfMiner === 'Local' && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="grid grid-cols-2 gap-2">
          <div>
            <Label className="text-xs text-muted-foreground">T.O.G</Label>
            <Select value={record.tog || ''} onValueChange={handleTogChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {TOG_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Pure Weight</Label>
