      td { padding: 8px; border-bottom: 1px solid #eee; font-size: 13px; }
      .total-row td { font-weight: bold; border-top: 2px solid #C9A84C; }
      .gold { color: #C9A84C; }
    </style></head><body>${content}</body></html>`);
    win.document.close();
    win.print();
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Client Invoice</DialogTitle>
        </DialogHeader>
        <div ref={printRef} className="text-sm">
          <div className="mb-4 pb-4 border-b border-border">
            <h2 className="font-cinzel text-lg text-primary mb-1">INVOICE</h2>
            {first?.orderId && <p className="text-xs text-muted-foreground mb-1">Order ID / Barcode: <span className="text-foreground font-medium">{first.orderId}</span></p>}
            <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
              <span>Client: <span className="text-foreground font-medium">{first?.minerName}</span></span>
              <span>Date: <span className="text-foreground">{formatDate(first?.dateOfLive)}</span></span>
              {!inStore && <span>Region: <span className="text-foreground">{first?.regions || '—'}</span></span>}
              {!inStore && <span>Due: <span className="text-foreground">{dueDate}</span></span>}
              {!inStore && first?.page && <span>Page: <span className="text-foreground">{first.page}</span></span>}
              {!inStore && first?.fbProfileName && <span>FB Profile: <span className="text-foreground">{first.fbProfileName}</span></span>}
              <span className="col-span-2">Payment: <span className="text-foreground">{first?.modeOfPayment || '—'}</span></span>
            </div>
          </div>
          <table className="w-full text-xs mb-4">
            <thead>
              <tr className="border-b border-border">
                <th className="text-left py-1 text-muted-foreground font-medium">Item</th>
                <th className="text-left py-1 text-muted-foreground font-medium">Cat</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Grams</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Rate</th>
                <th className="text-right py-1 text-muted-foreground font-medium">Price</th>
              </tr>
            </thead>
            <tbody>
              {records.map(r => (
                <tr key={r.id} className="border-b border-border/50">
                  <td className="py-1.5 pr-2">{r.itemDescription}</td>
                  <td className="py-1.5">{r.category}</td>
                  <td className="py-1.5 text-right">{r.grams || 'PC'}</td>
                  <td className="py-1.5 text-right">{currency} {Number(r.clientRate || 0).toFixed(2)}</td>
                  <td className="py-1.5 text-right">{currency} {calcItemPrice(r).toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="space-y-1 text-xs border-t border-border pt-3">
            <div className="flex justify-between"><span className="text-muted-foreground">Subtotal</span><span>{currency} {subtotal.toFixed(2)}</span></div>
            <div className="flex justify-between"><span className="text-muted-foreground">Shipping Fee</span><span>{currency} {shippingFee.toFixed(2)}</span></div>
            {additionalCharges > 0 && <div className="flex justify-between"><span className="text-muted-foreground">Additional Charges</span><span>{currency} {additionalCharges.toFixed(2)}</span></div>}
            {ccFee > 0 && <div className="flex justify-between"><span className="text-muted-foreground">CC Surcharge</span><span>{currency} {ccFee.toFixed(2)}</span></div>}
            <div className="flex justify-between font-bold text-sm pt-2 border-t border-primary/30">
              <span className="font-cinzel text-primary">GRAND TOTAL</span>
              <span className="text-primary">{currency} {grandTotal.toFixed(2)}</span>
            </div>
          </div>
        </div>
        <Button onClick={handlePrint} className="w-full mt-2 bg-primary text-primary-foreground">
