import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcShippingFee, calcCCFee, fromAED, clientRateAED } from '@/lib/calculations';
import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const LOGO_URL = 'https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/nmxTQmYsvWabJKiVqbDnEL/pasted-image-1773062648203.jpeg';

const NOTES = [
  'WE CAN ONLY HOLD UNPAID ITEMS FOR MAXIMUM 3 DAYS ONLY FROM THE INVOICE DATE.',
