import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6; 
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6; 
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record.currency);
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();

  // IF SCREW TYPE, MULTIPLY BY QTY
  if (category.includes('screw type')) {
    return clientRate * (n(record.qty) || 1);
  }

  if (isPcItem(record)) return clientRate;
  return n(record.grams) * clientRate;
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const clientRateInAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();

  // IF SCREW TYPE, MULTIPLY BY QTY
  if (category.includes('screw type')) {
    return clientRateInAED * (n(record.qty) || 1);
  }

  if (isPcItem(record)) return clientRateInAED;
  return n(record.grams) * clientRateInAED;
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  let rateForGold = n(record.goldRate) > 0 ? n(record.goldRate) : n(record.supplierRate);
  let mc = n(record.mc);

  // IF SCREW TYPE, MULTIPLY COST BY QTY
  if (category.includes('screw type')) {
    mc = 0;
    if (rateForGold === 0) rateForGold = 115;
    return rateForGold * (n(record.qty) || 1);
  }

  const grams = n(record.grams);

  if (category.includes('silver branded')) {
    return 32 * grams;
  }

  if (category.includes('silver')) {
    return 15 * grams;
  }

  // Automatic MC Fallback
  if (mc === 0) {
    if (category.includes('special price ef')) {
      mc = 25;
    } else if (category.includes('special price')) {
      mc = 21;
    } else {
      mc = 16;
    }
  }

  if (isPcItem(record)) {
    return rateForGold + mc;
  }

  return (rateForGold + mc) * grams;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  return totalSales - totalCost;
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record); 
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30; // Al Ain shipping fee set to 30
    return 30; 
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return (itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid;
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcShippingFee, calcCCFee, fromAED, clientRateAED, isPcItem } from '@/lib/calculations';
import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const LOGO_URL = 'https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';

const NOTES = [
  'WE CAN ONLY HOLD UNPAID ITEMS FOR MAXIMUM 3 DAYS ONLY FROM THE INVOICE DATE.',
  'FAILURE TO SETTLE AFTER 3 DAYS, ADDITIONAL CHARGES MAY OCCUR.',
  'UNPAID ITEMS WILL BE AUTOMATICALLY CANCELED AFTER THE GRACE PERIOD WITHOUT PRIOR NOTICE.',
  'ALL ITEMS UNDERGO QUALITY CHECKING AFTER LIVE AND BEFORE DISPATCH.',
  'UNBOXING VIDEO IS A MUST. NO UNBOXING VIDEO, NO REFUND AND NO EXCHANGE.',
  'NO CASH REFUND. STORE CREDIT ONLY.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;

export default function InvoicePrintContent({ records, currency }: Props) {
  const first = records[0];

  const fmtAmt = (v: number) =>
    `${currency} ${v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const items = records.map(r => {
    const priceAED = calcItemPriceAED(r);
    const price = fromAED(priceAED, currency);
    const rateAED = clientRateAED(r);
    const rate = fromAED(rateAED, currency);

    const category = (r.category || '').toLowerCase();
    const isScrewType = category.includes('screw type');
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = n(r.qty) || 1;

    // Formatting for the Grams/Qty column
    let gramsDisplay = '';
    if (isScrewType) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = isPc || gramsValue === 0 ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: isPc || isScrewType,
      rate,
      amount: price,
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  const shippingAED = first ? calcShippingFee(first) : 0;
  const shipping = fromAED(shippingAED, currency);
  const additionalAED = n(first?.additionalCharges);
  const additional = fromAED(additionalAED, currency);
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const ccFee = fromAED(ccFeeAED, currency);
  const total = subtotal + shipping + additional + ccFee;

  // Do not add screw types to the total grams count
  const totalGrams = records.reduce((s, r) => {
    if ((r.category || '').toLowerCase().includes('screw type')) return s;
    return s + n(r.grams);
  }, 0);

  const amountInWords = numberToWords(total, currency);

  const rawDate = formatDate(first?.dateOfLive);
  const invoiceDate = rawDate === '—'
    ? new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
    : rawDate;

  const summaryRows = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>
      <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0 }}>
        <em style={{ fontSize: 14 }}>Invoice</em>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <tbody>
          <tr>
            <td style={{ width: '65%', padding: '12px 16px', verticalAlign: 'top', border: '1px solid #999' }}>
              <div style={{ fontWeight: 900, fontSize: 24, letterSpacing: 1 }}>MYKABAYAN JEWELLERY</div>
              <div style={{ marginTop: 8, textAlign: 'left', fontSize: 11 }}>SATWA, DUBAI, UNITED ARAB EMIRATES</div>
              <div style={{ marginTop: 4, fontSize: 11 }}>Whatsapp &amp; Contact no.: +971 52 825 2405</div>
            </td>
            <td style={{ width: '35%', padding: '12px 16px', verticalAlign: 'middle', textAlign: 'right', border: '1px solid #999' }}>
              <img src={LOGO_URL} alt="Logo" style={{ maxWidth: '100%', maxHeight: '80px', objectFit: 'contain' }} />
            </td>
          </tr>
          <tr>
            <td style={{ padding: '10px 16px', verticalAlign: 'middle', border: '1px solid #999' }}>
              <div style={{ fontWeight: 700, fontSize: 20, textAlign: 'center', letterSpacing: 1 }}>
                {(first?.minerName || '').toUpperCase()}
              </div>
            </td>
            <td style={{ padding: '8px', textAlign: 'center', border: '1px solid #999' }}>
              <div style={{ fontWeight: 600, fontSize: 13 }}>{invoiceDate}</div>
              <div style={{ fontSize: 11, marginTop: 4 }}>Invoice Date</div>
            </td>
          </tr>
        </tbody>
      </table>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ background: '#e0e0e0' }}>
            {['Code', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
              <th key={h} style={{ border: '1px solid #999', padding: '6px 8px', textAlign: 'center', fontSize: 11 }}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {items.map((item, i) => (
            <tr key={i}>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.code}</td>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, fontWeight: 600 }}>{item.desc.toUpperCase()}</td>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.tog.toUpperCase()}</td>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: item.isPc ? 'red' : '#111', fontWeight: item.isPc ? 700 : 400 }}>
                {item.gramsDisplay}
              </td>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.rate.toFixed(2)}</td>
              <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'right', fontSize: 11 }}>{fmtAmt(item.amount)}</td>
            </tr>
          ))}
          {Array.from({ length: emptyRows }).map((_, i) => (
            <tr key={`empty-${i}`} style={{ height: 22 }}>
              {[1,2,3,4,5,6].map(c => <td key={c} style={{ border: '1px solid #999' }}>&nbsp;</td>)}
            </tr>
          ))}
        </tbody>
      </table>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <tbody>
          <tr>
            <td style={{ width: '50%', padding: '16px', verticalAlign: 'middle', border: '1px solid #999' }}>
              <div style={{ fontWeight: 900, fontSize: 26, lineHeight: 1.2, textAlign: 'center' }}>
                CUSTOMER'S INVOICE<br />COPY
              </div>
            </td>
            <td style={{ padding: 0, verticalAlign: 'top', border: '1px solid #999' }}>
              {summaryRows.map((row, i) => (
                <div key={i} style={{ display: 'flex', justifyContent: 'space-between', background: i % 2 === 0 ? '#e0e0e0' : '#f5f5f5', padding: '5px 10px', borderBottom: '1px solid #ccc' }}>
                  <span style={{ fontWeight: 700, fontSize: 11 }}>{row.label}</span>
                  <span style={{ fontSize: 11 }}>{row.value}</span>
                </div>
              ))}
            </td>
          </tr>
        </tbody>
      </table>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <tbody>
          <tr>
            <td style={{ padding: '4px 12px', border: '1px solid #999', borderBottom: 'none' }}>
              <span style={{ color: 'red', fontWeight: 700, fontSize: 11 }}>Amount in Words:</span>
            </td>
          </tr>
          <tr>
            <td style={{ padding: '4px 12px 10px', textAlign: 'center', fontWeight: 700, fontSize: 13, border: '1px solid #999' }}>
              {amountInWords}
            </td>
          </tr>
        </tbody>
      </table>

      <div style={{ padding: '8px 12px', border: '1px solid #999', marginTop: -1 }}>
        <div style={{ color: 'red', fontWeight: 700, fontSize: 12, marginBottom: 4 }}>NOTE:</div>
        {NOTES.map((note, i) => (
          <div key={i} style={{ fontSize: 10, marginBottom: 2 }}>{i + 1}. {note}</div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect, memo } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue, isFreeSf } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

const TOG_OPTIONS = ['18K', 'VCA', '21K', '24K', 'S-925'];

function isInStore(record: DatabaseRowType): boolean {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  return mos === 'in-store' || mos === 'walk-in' || mos === 'walk in';
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = (remarks || '').toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('tamara approved')) return { modeOfPayment: 'Tamara', freeSf: 'TRUE' };
  if (/\bcod\b/.test(r)) return { modeOfPayment: 'COD' };
  if (/\bcc\b/.test(r) || r.includes('credit card')) return { modeOfPayment: 'Credit Card' };
  return null;
}

function AdminItemRow({ record, onUpdate, onGroupUpdate, userEmail }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const [pureWeight, setPureWeight] = useState(record.pureWeight || '');
  const [resetKey, setResetKey] = useState(Date.now());
  const overdue = isOverdue(record);
  const inStore = isInStore(record);

  useEffect(() => {
    if (!record.modeOfPayment && record.liverAdminRemarks) {
      const auto = detectAutoFill(record.liverAdminRemarks);
      if (auto) onGroupUpdate(auto);
    }
  }, [record.modeOfPayment, record.liverAdminRemarks, onGroupUpdate]);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const autoFill = detectAutoFill(val);
    await onUpdate(record.id, { liverAdminRemarks: val });
    if (autoFill) {
      await onGroupUpdate(autoFill);
      toast.success('Auto-filled MOP from remarks');
    }
  }, 700);

  const debouncedPureWeight = useDebouncedCallback(async (val: string) => {
    await onUpdate(record.id, { pureWeight: val });
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    if (mop === 'Tabby' || mop === 'Tamara') fields.freeSf = 'TRUE';
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    await onGroupUpdate({ regions: region });
  };

  const handleTogChange = async (tog: string) => {
    await onUpdate(record.id, { tog });
  };

  const handleStatusChange = async (newStatus: string) => {
    setResetKey(Date.now());

    if (newStatus === 'Cancelled') { setShowCancel(true); return; }

    // REMOVED 'Reseller' from this gatekeep check
    if (newStatus === 'For Pullout' || newStatus === 'Dispatch') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }

    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }

    await onUpdate(record.id, fields);
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> OVERDUE
              </span>
            )}
          </div>
        </div>
       <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">
            {(record.category || '').toLowerCase().includes('screw type') 
              ? `${record.qty || 1} PCS` 
              : (record.grams ? `${record.grams}g` : 'PC')}
          </p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {!inStore && record.locationOfMiner === 'Local' && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="grid grid-cols-2 gap-2">
          <div>
            <Label className="text-xs text-muted-foreground">T.O.G</Label>
            <Select value={record.tog || ''} onValueChange={handleTogChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {TOG_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Pure Weight</Label>
            <Input type="number" value={pureWeight} onChange={e => { setPureWeight(e.target.value); debouncedPureWeight(e.target.value); }} className="h-8 text-xs bg-background border-border mt-0.5" placeholder="0.00" />
          </div>
        </div>

        <div>
          <Label className="text-xs text-muted-foreground">Liver/Admin Remarks</Label>
          <Textarea value={remarks} onChange={e => { setRemarks(e.target.value); debouncedRemarks(e.target.value); }} className="h-14 text-xs bg-background border-border mt-0.5 resize-none" placeholder="e.g. TABBY APPROVED, COD..." />
        </div>

        <div className="flex items-center justify-between">
          {!inStore ? (
            <div className="flex items-center gap-2">
              <Switch checked={isFreeSf(record)} onCheckedChange={v => onGroupUpdate({ freeSf: v ? 'TRUE' : '' })} className="scale-90" />
              <Label className="text-xs">FREE SF</Label>
            </div>
          ) : <div />}

          <Select key={resetKey} onValueChange={handleStatusChange}>
            <SelectTrigger className="h-7 text-xs w-36 bg-background border-border">
              <SelectValue placeholder="Change status..." />
            </SelectTrigger>
           <SelectContent className="bg-popover border-border">
              {inStore ? (
                <>
                  <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              ) : (
                <>
                  <SelectItem value="For Pullout" className="text-xs">For Pullout</SelectItem>
                  <SelectItem value="Dispatch" className="text-xs">Dispatch</SelectItem>
                  <SelectItem value="Reseller" className="text-xs">Reseller</SelectItem>
                  <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem> {/* <--- UPDATED */}
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              )}
            </SelectContent>
          </Select>
        </div>
      </div>

      <AlertDialog open={showCancel} onOpenChange={setShowCancel}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => { await onUpdate(record.id, { status: 'Cancelled' }); toast.success('Item cancelled'); }}>
              Cancel Item
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(AdminItemRow, (prevProps, nextProps) => {
  return prevProps.record === nextProps.record && prevProps.userEmail === nextProps.userEmail;
});

import { useState, memo } from 'react';
import { FileText, Truck, User, Upload, History, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function getDeliveryLabel(record: DatabaseRowType): string {
  const mop = record.modeOfPayment || '';
  const region = record.regions ? `(${record.regions})` : '';
  if (mop === 'Pick Up Shop') return 'Pick Up Shop';
  if (mop === 'Meet Up') return 'Meet Up';
  if (mop === 'Layaway') return 'Layaway';
  if (region) return `${mop} ${region}`.trim();
  return mop || 'Unknown';
}

function getDeliverySummary(records: DatabaseRowType[]): string {
  const labels = records.map(getDeliveryLabel);
  const unique = [...new Set(labels)];
  if (unique.length === 1) return unique[0];
  return `🔴 MIXED: ${unique.join(', ')}`;
}

function DispatchClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});
  const first = records[0];
  const deliverySummary = getDeliverySummary(records);

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      {/* Header — always visible, click to toggle */}
      <button
        className="w-full px-4 py-2.5 border-b border-border/50 flex items-center justify-between text-left focus:outline-none"
        onClick={() => setIsExpanded(prev => !prev)}
      >
        <div className="flex-1 min-w-0">
          <span className="font-cinzel text-sm text-primary">{minerName}</span>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span className={deliverySummary.startsWith('🔴') ? 'text-destructive font-medium' : ''}>
              {deliverySummary}
            </span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 ml-2 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="border-primary/40 text-primary text-xs h-7"
            onClick={e => { e.stopPropagation(); setShowInvoice(true); }}
          >
            <FileText className="h-3 w-3 mr-1" /> Invoice
          </Button>
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {/* Expanded content */}
      {isExpanded && (
        <div className="px-3 py-2 space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          {records.map(record => {
            const givenToShopMode = isGivenToShopMode(record);
            const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;
            return (
              <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <p className="text-sm font-medium">{record.itemDescription}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${record.qty || 1} PCS` : (record.grams ? `${record.grams}g` : 'PC')}
                      <span className="text-foreground font-medium ml-1">
                        · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                      </span>
                    </p>
                  </div>
                  <StatusBadge status={record.status} />
                </div>
                <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                  <Truck className="h-3 w-3" />
                  <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                  {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
                </div>
                {record.liverAdminRemarks && (
                  <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                    Remarks: {record.liverAdminRemarks}
                  </p>
                )}
                {latestAudit && (
                  <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                    <History className="h-2.5 w-2.5" />
                    {latestAudit}
                  </p>
                )}
                <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                  <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                    <SelectValue placeholder="Set status..." />
                  </SelectTrigger>
                 <SelectContent className="bg-popover border-border">
                    {givenToShopMode ? (
                      <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                    ) : (
                      <>
                        <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                        <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                      </>
                    )}
                    <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem> {/* <--- UPDATED */}
                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            );
          })}
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

