import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType } from 'zite-integrations-backend-sdk';

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
  'auditTrail', 'tog', 'pureWeight',
]);

export default createEndpoint({
  description: 'Create a new Database row manually',
  inputSchema: z.object({
    fields: z.record(z.unknown()),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input }) => {
    const sanitized: Partial<DatabaseRowType> = {};
    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') as boolean;
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
      }
    }
    await Database.create({ row: sanitized });
    return { success: true };
  },
});

export type DatabaseRowType = {
  orderId?: string;
  dateOfLive?: string;
  page?: string;
  liverName?: string;
  locationOfMiner?: string;
  minerName?: string;
  itemDescription?: string;
  grams?: number;
  source?: string;
  category?: string;
  mc?: string;
  goldRate?: number;
  supplierRate?: string;
  clientRate?: number;
  profit?: string;
  modeOfSale?: string;
  status?: string;
  modeOfPayment?: string;
  downpayment?: string;
  la1MonthPayment?: string;
  la2MonthPayment?: string;
  la3MonthPayment?: string;
  la4MonthPayment?: string;
  liverAdminRemarks?: string;
  dispatchDate?: string;
  deliveredDate?: string;
  reviewChasing?: string;
  fbProfileName?: string;
  regions?: string;
  remittanceStatus?: string;
  currency?: string;
  additionalCharges?: string;
  amountReceived?: string;
  freeSf?: string; // 'TRUE' | '' — stored as string in Google Sheets
  auditTrail?: string;
  tog?: string;
  pureWeight?: string;
  qty?: number;
  id: number;
};

export type ClientGroup = {
  minerName: string;
  records: DatabaseRowType[];
};

export type TabProps = {
  records: DatabaseRowType[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
};

import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { calcRemainingBalance } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import AddClientModal from './AddClientModal';

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [otherExpanded, setOtherExpanded] = useState(true);

  const { deliveredGroups, otherActiveGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(records, searchQuery);

    const active = searched.filter(r => {
      const isDeliveredOrLayaway = r.status === 'Delivered' || r.status === 'Given to Shop' || r.modeOfPayment === 'Layaway';
      if (!isDeliveredOrLayaway) return false;

      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received');
      if (isCleared) return false;

      const isPendingOrEmpty = !remStatus || remStatus === 'pending payment';
      const hasBalance = calcRemainingBalance(r) > 0;
      return isPendingOrEmpty || hasBalance;
    });

    const delivered = active.filter(r => r.status === 'Delivered');
    const others = active.filter(r => r.status !== 'Delivered');

    const cleared = searched.filter(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      return remStatus.includes('secured') || remStatus.includes('received');
    });

    return {
      deliveredGroups: groupByMinerName(delivered),
      otherActiveGroups: groupByMinerName(others),
      clearedGroups: groupByMinerName(cleared),
    };
  }, [records, searchQuery]);

  const renderGroups = (groups: Map<string, typeof records>) => (
    groups.size === 0 ? (
      <div className="text-center py-10 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      Array.from(groups.entries()).map(([minerName, items]) => (
        <AccountsClientCard key={minerName} minerName={minerName} records={items} onUpdate={onUpdate} />
      ))
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${deliveredGroups.size + otherActiveGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* ADD CLIENT BUTTON */}
        <div className="flex justify-end mb-4">
          <Button 
            onClick={() => setShowAddModal(true)} 
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" /> 
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({deliveredGroups.size + otherActiveGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* DELIVERED SECTION - Collapsible */}
            <div className="mb-6">
              <button
                className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none"
                onClick={() => setDeliveredExpanded(!deliveredExpanded)}
              >
                <span className="font-cinzel text-sm font-bold text-green-500 whitespace-nowrap tracking-wide">
                  DELIVERED
                </span>
                <span className="text-xs bg-green-500/10 text-green-500 px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-green-500/20">
                  {deliveredGroups.size} clients
                </span>
                <div className="h-px flex-1 bg-green-500/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>

              {deliveredExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(deliveredGroups)}
                </div>
              )}
            </div>

            {/* OTHER ACTIVE SECTION - Collapsible */}
            <div className="mb-4">
              <button
                className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none"
                onClick={() => setOtherExpanded(!otherExpanded)}
              >
                <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap tracking-wide">
                  OTHER ACTIVE (LAYAWAY/SHOP)
                </span>
                <span className="text-xs bg-primary/10 text-primary px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-primary/20">
                  {otherActiveGroups.size} clients
                </span>
                <div className="h-px flex-1 bg-primary/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${otherExpanded ? 'rotate-180' : ''}`} />
              </button>

              {otherExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(otherActiveGroups)}
                </div>
              )}
            </div>
          </TabsContent>

          <TabsContent value="cleared">
            <div className="space-y-3">
              {renderGroups(clearedGroups)}
            </div>
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} />}
    </div>
  );
}

