            <Button variant="outline" className="flex-1 text-xs h-8 border-border" onClick={onClose}>Cancel</Button>
            <Button onClick={handleSave} disabled={saving} className="flex-1 text-xs h-8 bg-primary text-primary-foreground">
              {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Create Record'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { TabProps } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { calcRemainingBalance } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import AddClientModal from './AddClientModal';

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [otherExpanded, setOtherExpanded] = useState(true);

  const { deliveredGroups, otherActiveGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(records, searchQuery);

    const active = searched.filter(r => {
      const isDeliveredOrLayaway = r.status === 'Delivered' || r.status === 'Given to Shop' || r.modeOfPayment === 'Layaway';
      if (!isDeliveredOrLayaway) return false;

      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received');
      if (isCleared) return false;

      const isPendingOrEmpty = !remStatus || remStatus === 'pending payment';
      const hasBalance = calcRemainingBalance(r) > 0;
      return isPendingOrEmpty || hasBalance;
    });

    const delivered = active.filter(r => r.status === 'Delivered');
    const others = active.filter(r => r.status !== 'Delivered');

    const cleared = searched.filter(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      return remStatus.includes('secured') || remStatus.includes('received');
    });

    return {
      deliveredGroups: groupByMinerName(delivered),
      otherActiveGroups: groupByMinerName(others),
      clearedGroups: groupByMinerName(cleared),
    };
  }, [records, searchQuery]);

  const renderGroups = (groups: Map<string, typeof records>) => (
    groups.size === 0 ? (
      <div className="text-center py-10 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      Array.from(groups.entries()).map(([minerName, items]) => (
        <AccountsClientCard key={minerName} minerName={minerName} records={items} onUpdate={onUpdate} />
      ))
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${deliveredGroups.size + otherActiveGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* ADD CLIENT BUTTON */}
        <div className="flex justify-end mb-4">
          <Button 
            onClick={() => setShowAddModal(true)} 
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" /> 
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({deliveredGroups.size + otherActiveGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* DELIVERED SECTION - Collapsible */}
            <div className="mb-6">
              <button
                className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none"
                onClick={() => setDeliveredExpanded(!deliveredExpanded)}
              >
                <span className="font-cinzel text-sm font-bold text-green-500 whitespace-nowrap tracking-wide">
                  DELIVERED
                </span>
                <span className="text-xs bg-green-500/10 text-green-500 px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-green-500/20">
                  {deliveredGroups.size} clients
                </span>
                <div className="h-px flex-1 bg-green-500/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>

              {deliveredExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(deliveredGroups)}
                </div>
              )}
            </div>

            {/* OTHER ACTIVE SECTION - Collapsible */}
            <div className="mb-4">
              <button
                className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none"
                onClick={() => setOtherExpanded(!otherExpanded)}
              >
                <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap tracking-wide">
                  OTHER ACTIVE (LAYAWAY/SHOP)
                </span>
                <span className="text-xs bg-primary/10 text-primary px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-primary/20">
                  {otherActiveGroups.size} clients
                </span>
                <div className="h-px flex-1 bg-primary/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${otherExpanded ? 'rotate-180' : ''}`} />
              </button>

              {otherExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(otherActiveGroups)}
                </div>
              )}
            </div>
          </TabsContent>

          <TabsContent value="cleared">
            <div className="space-y-3">
              {renderGroups(clearedGroups)}
            </div>
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMinerName } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [expandedPages, setExpandedPages] = useState<Record<string, boolean>>({});

  // DYNAMIC GROUPING: This detects all unique pages automatically
  const pageGroups = useMemo(() => {
    const searched = applySearch(records, searchQuery);
    const now = new Date();

    // 1. PRE-FILTER: Only keep items that actually belong in the Admin Pipeline right now
    const activeAdminRecords = searched.filter(r => {
      const status = r.status || '';

      // Mined Items
      if (status === 'Pending' || status === 'Waiting for Details' || status === 'Paid/DP but Item Hold') return true;

      // Resellers
      if (status === 'Reseller') return true;

      // Review Chasing logic
      if (status === 'Delivered') {
        if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
        if (!r.deliveredDate) return false;
        const mos = (r.modeOfSale || '').toLowerCase().trim();
        if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
        const delivered = parseDateRobust(r.deliveredDate);
        if (!delivered) return false;
        const diffDays = differenceInDays(now, delivered);
        return diffDays >= 0 && diffDays <= 3;
      }

      return false;
    });

    const groups: Record<string, DatabaseRowType[]> = {};

    activeAdminRecords.forEach(r => {
      let pageRaw = (r.page || 'Other').trim();
      let pageKey = pageRaw;

      // Rule: Keep MYK and MYK Silver together
      if (pageRaw.toUpperCase().includes('MYK')) {
        pageKey = 'MYK';
      } else if (pageRaw.toUpperCase().includes('EMPIRE')) {
        pageKey = 'Empire Gold By ETG';
      }

      if (!groups[pageKey]) {
        groups[pageKey] = [];
      }
      groups[pageKey].push(r);
    });

    // Sort pages: MYK first, then Empire, then alphabetical
    return Object.keys(groups)
      .sort((a, b) => {
        if (a === 'MYK') return -1;
        if (b === 'MYK') return 1;
        if (a === 'Empire Gold By ETG') return -1;
        if (b === 'Empire Gold By ETG') return 1;
        return a.localeCompare(b);
      })
      .reduce((acc, key) => {
        acc[key] = groups[key];
        return acc;
      }, {} as Record<string, DatabaseRowType[]>);
  }, [records, searchQuery]);

  const togglePage = (page: string) => {
    setExpandedPages(prev => ({ 
      ...prev, 
      [page]: prev[page] === undefined ? false : !prev[page] 
    }));
  };

  const renderPageSection = (pageName: string, pageRecords: DatabaseRowType[]) => {
    // Default to expanded (true) if never clicked
    const isExpanded = expandedPages[pageName] !== false;

    // Since we pre-filtered above, we just separate them into their respective buckets here
    const minedItems = pageRecords.filter(r => 
      r.status === 'Pending' || 
      r.status === 'Waiting for Details' || 
      r.status === 'Paid/DP but Item Hold'
    );
    const resellerItems = pageRecords.filter(r => r.status === 'Reseller');
    const reviewChasingItems = pageRecords.filter(r => r.status === 'Delivered');

    const minedGrouped = groupByMinerName(minedItems);
    const resellerGrouped = groupByMinerName(resellerItems);
    const reviewChasingGroups = groupByMinerName(reviewChasingItems);

    return (
      <div key={pageName} className="mb-10">
        <div 
          className="flex items-center gap-3 py-2.5 px-4 bg-secondary/40 rounded-xl cursor-pointer mb-4 border border-primary/10 hover:bg-secondary/60 transition-colors"
          onClick={() => togglePage(pageName)}
        >
          {pageName === 'MYK' ? (
            <Crown className="h-5 w-5 text-yellow-500" />
          ) : pageName === 'Empire Gold By ETG' ? (
            <BookOpen className="h-5 w-5 text-primary" />
          ) : (
            <Layout className="h-5 w-5 text-muted-foreground" />
          )}

          <h2 className="font-cinzel text-base font-bold text-primary tracking-widest uppercase">{pageName}</h2>
          <div className="h-px flex-1 bg-primary/10" />
          <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">
            {pageRecords.length}
          </span>
          <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>

        {isExpanded && (
          <div className="pl-2 sm:pl-4 space-y-8 animate-in fade-in slide-in-from-top-2 duration-300">
            {/* MINED ITEMS */}
            {minedGrouped.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-4">
                  <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] pl-1">Mined Items</span>
                  <div className="h-px flex-1 bg-border/60" />
                </div>
                {Array.from(minedGrouped.entries()).map(([name, items]) => (
                  <AdminClientCard key={name} minerName={name} records={items} onUpdate={onUpdate} userEmail={userEmail} />
                ))}
              </div>
            )}

            {/* RESELLERS */}
            {resellerGrouped.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-4">
                  <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                  <div className="h-px flex-1 bg-teal-500/20" />
                </div>
                {Array.from(resellerGrouped.entries()).map(([name, items]) => (
                  <AdminClientCard key={name} minerName={name} records={items} onUpdate={onUpdate} userEmail={userEmail} />
                ))}
              </div>
            )}

            {/* REVIEW CHASING */}
            {reviewChasingGroups.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-4">
                  <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                  <div className="h-px flex-1 bg-primary/20" />
                </div>
                <div className="grid grid-cols-1 gap-3">
                  {Array.from(reviewChasingGroups.entries()).map(([name, items]) => (
                    <ReviewChasingCard key={name} minerName={name} records={items} onUpdate={onUpdate} />
                  ))}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Admin Pipeline"
        subtitle="Future-Ready Page Segregation"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-6">
        {Object.keys(pageGroups).length > 0 ? (
          Object.keys(pageGroups).map(page => renderPageSection(page, pageGroups[page]))
        ) : (
          <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
            <p className="text-sm text-muted-foreground font-medium">No records found matching your search.</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { RefreshCw } from 'lucide-react'; // <-- Added refresh icon
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles'; 
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[]>([]);

  const [dataLoading, setDataLoading] = useState(true); 
  const [isSyncing, setIsSyncing] = useState(false); // Track silent background syncs
  const [searchQuery, setSearchQuery] = useState('');

  // Keep track of what tab they click, but we'll validate it later
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  // Add a "silent" flag so it doesn't show the skeleton loader when refreshing in the background
  const fetchData = useCallback((silent = false) => {
    if (!user) return;

    if (silent) {
      setIsSyncing(true);
    } else {
      setDataLoading(true);
    }

    Promise.all([
      getRecords({}).catch(() => { toast.error('Failed to load records'); return []; }),
      getRoles({}).catch(() => { return []; })
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        setDynamicRoles((rolesData as any[]) || []);
      })
      .finally(() => {
        setDataLoading(false);
        setIsSyncing(false);
      });
  }, [user]);

  useEffect(() => { fetchData(false); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    // 1. Optimistic UI update (makes the app feel instantly responsive)
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));

    try {
      // 2. Save to Google Sheets
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });

      // 3. Silent Background Refresh (pulls everyone else's changes automatically)
      fetchData(true);
    } catch {
      toast.error('Failed to save changes');
      fetchData(true); // Revert the UI if the save fails
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  // role is now an ARRAY: e.g., ['admin', 'dispatch']
  const roles = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = roles.includes('super_admin');

  // Check if they have zero roles
  if (dataLoading && roles.length === 0) return <LoadingSkeleton />;
  if (!dataLoading && roles.length === 0) return <AccessDenied email={user.email} />;

  // Determine exactly which tabs this user is allowed to see
  const ALL_TABS = ['admin', 'dispatch', 'accounts', 'bossing'] as const;
  const allowedTabs = isSuperAdmin 
    ? ALL_TABS 
    : ALL_TABS.filter(t => roles.includes(t as any));

  // Smart routing: if their selected activeTab isn't in their allowed list, default to their first allowed tab
  const currentTab = allowedTabs.includes(activeTab) ? activeTab : allowedTabs[0];

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">

          {/* Small Top Bar Logo */}
          <img 
            src="https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png" 
            alt="Logo" 
            className="h-6 sm:h-8 w-auto object-contain mr-2 sm:mr-4" 
          />

          {/* Show Navigation Tabs if they are a super admin OR if they have more than 1 role */}
          {allowedTabs.length > 1 && (
            <div className="flex h-full items-center border-l border-border pl-2 sm:pl-4">
              {allowedTabs.includes('admin') && (
                <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              )}
              {allowedTabs.includes('dispatch') && (
                <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              )}
              {allowedTabs.includes('accounts') && (
                <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              )}
              {allowedTabs.includes('bossing') && (
                <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 sm:gap-3">
          {/* Manual Refresh Button */}
          <button 
            onClick={() => fetchData(true)}
            disabled={isSyncing}
            className={`p-1.5 rounded-full hover:bg-secondary transition-colors ${isSyncing ? 'animate-spin text-primary' : 'text-muted-foreground'}`}
            title="Sync latest data"
          >
            <RefreshCw className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          </button>

          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[100px] sm:max-w-none">
            {user.email}
          </span>

          {(isSuperAdmin || roles.includes('admin')) && (
            <UploadMasterlistFAB onRefresh={() => fetchData(false)} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {currentTab === 'admin' && <AdminPipeline {...tabProps} />}
          {currentTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {currentTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {currentTab === 'bossing' && <BossingDashboard {...tabProps} />}
        </div>
      )}
    </div>
  );
}

