import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => parseFloat(String(v ?? 0)) || 0;

/** Round price: .1-.4 → floor, .5-.9 → ceil (standard rounding) */
export function roundPrice(v: number): number { return Math.round(v); }

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return record.freeSf === 'TRUE' || record.freeSf === 'true' || (record.freeSf as unknown) === true;
}

export function toAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value * 3.67;
  if (currency === 'PHP') return value / 16.6; 
  return value;
}

export function fromAED(value: number, currency?: string): number {
  if (!currency || currency === 'AED') return value;
  if (currency === 'USD') return value / 3.67;
  if (currency === 'PHP') return value * 16.6; 
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record.currency);
}

// --- SMART QTY EXTRACTOR ---
export function getQty(record: DatabaseRowType): number {
  const parsedQty = n(record.qty);
  if (parsedQty > 0) return parsedQty;

  // Fallback: extract from item description (e.g., "2 PCS SCREW EARRINGS")
  const desc = (record.itemDescription || '').toUpperCase();
  const match = desc.match(/(?:^|\s)(\d+)\s*PCS?\b/);
  if (match) {
    return parseInt(match[1], 10);
  }

  return 1;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();

  // IF SCREW TYPE, MULTIPLY BY QTY
  if (category.includes('screw type')) {
    return roundPrice(clientRate * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRate);
  return roundPrice(n(record.grams) * clientRate);
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const clientRateInAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();

  // IF SCREW TYPE, MULTIPLY BY QTY
  if (category.includes('screw type')) {
    return roundPrice(clientRateInAED * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRateInAED);
  return roundPrice(n(record.grams) * clientRateInAED);
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();

  let rateForGold = n(record.goldRate) > 0 ? n(record.goldRate) : n(record.supplierRate);
  let mc = n(record.mc);

  // IF SCREW TYPE, MULTIPLY COST BY QTY
  if (category.includes('screw type')) {
    mc = 0;

    if (rateForGold === 0) {
      rateForGold = 115;
      if (desc.includes('buy 1 take 1') || desc.includes('b1t1')) {
        rateForGold = rateForGold * 2;
      }
    }

    return roundPrice(rateForGold * getQty(record));
  }

  const grams = n(record.grams);

  if (category.includes('silver branded')) {
    return roundPrice(32 * grams);
  }

  if (category.includes('silver')) {
    return roundPrice(15 * grams);
  }

  // Automatic MC Fallback 
  if (mc === 0 && !category.includes('screw type') && !category.includes('silver')) {
    if (category.includes('special price ef')) {
      mc = 25;
    } else if (category.includes('special price')) {
      mc = 21;
    } else {
      mc = 16;
    }
  }

  if (isPcItem(record)) {
    return roundPrice(rateForGold + mc);
  }

  return roundPrice((rateForGold + mc) * grams);
}

export function calcProfitAED(record: DatabaseRowType): number {
  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  return roundPrice(totalSales - totalCost);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record); 
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  if (record.locationOfMiner === 'Local') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30; // Al Ain shipping fee set to 30
    return 30; 
  }
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  return n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) +
    n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = toAED(calcItemPrice(record), record.currency);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return roundPrice((itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid);
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { useState, useMemo } from 'react';
import { Loader2 } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { createRecord } from 'zite-endpoints-sdk';
import { MOP_OPTIONS, REGION_OPTIONS } from '@/lib/formatters';
import { calcItemCostAED, calcItemPriceAED } from '@/lib/calculations';
import { DatabaseRowType } from '@/types';

interface Props {
  onClose: () => void;
  userFirstName?: string;
  userEmail?: string;
  onRefresh?: () => void;
}

const LOCATION_OPTIONS = ['Local', 'Pinas', 'International'];
const CURRENCY_OPTIONS = ['AED', 'PHP', 'USD'];
const STATUS_OPTIONS = ['Pending', 'Waiting for Details', 'Paid/DP but Item Hold', 'Reseller', 'Walk-in', 'In-Store'];
const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash', 'Secured via Tabby', 'Secured via Tamara'];
const CATEGORY_OPTIONS = ['Normal', 'Special Price', 'Special Price EF', 'Silver', 'VCA', 'Screw Type', 'Other'];
const PAGE_OPTIONS = ['MYK', 'EMPIRE GOLD BY ETG'];
const TOG_OPTIONS = ['S-925', '18K', '21K', '24K'];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store', 'Offline', 'Reseller'];
const SOURCE_OPTIONS = ['MYK SHOP', 'CROWN', 'DG', 'MSET SHOP', 'SATWA OFFICE', 'UMAAR SUPPLIER'];

export default function AddClientModal({ onClose, userFirstName, userEmail, onRefresh }: Props) {
  const [saving, setSaving] = useState(false);
  const [phpRate, setPhpRate] = useState('16.6');
  const [form, setForm] = useState({
    minerName: '',
    itemDescription: '',
    category: '',
    mc: '',
    grams: '',
    clientRate: '',
    goldRate: '',
    orderId: '',
    currency: 'AED',
    modeOfPayment: '',
    modeOfSale: '',
    source: '',
    locationOfMiner: 'Local',
    regions: '',
    status: 'Walk-in',
    remittanceStatus: 'Pending Payment',
    dateOfLive: new Date().toISOString().split('T')[0],
    liverName: userFirstName || '',
    page: '',
    tog: '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  // Supplier rate = gold rate + mc (auto-computed, read-only)
  const supplierRate = useMemo(() => {
    const gr = parseFloat(form.goldRate) || 0;
    const mc = parseFloat(form.mc) || 0;
    return gr > 0 || mc > 0 ? (gr + mc).toFixed(2) : '';
  }, [form.goldRate, form.mc]);

  // Pure weight = grams - 0.05 (read-only)
  const pureWeight = useMemo(() => {
    const g = parseFloat(form.grams) || 0;
    return g > 0 ? Math.max(0, g - 0.05).toFixed(2) : '';
  }, [form.grams]);

  const handleCategoryChange = (val: string) => {
    let newMc = form.mc;
    if (val === 'Normal') newMc = '16';
    else if (val === 'Special Price') newMc = '21';
    else if (val === 'Special Price EF') newMc = '25';
    else if (val === 'Silver' || val === 'Screw Type') newMc = '0';
    setForm(p => ({ ...p, category: val, mc: newMc }));
  };

  const handleSave = async () => {
    if (!form.minerName.trim() || !form.itemDescription.trim()) {
      toast.error('Client name and item description are required');
      return;
    }
    if (!form.page) {
      toast.error('Page is required');
      return;
    }
    setSaving(true);
    try {
      const preview: DatabaseRowType = {
        id: 0,
        minerName: form.minerName.trim(),
        itemDescription: form.itemDescription.trim(),
        category: form.category,
        mc: form.mc,
        grams: form.grams ? parseFloat(form.grams) : undefined,
        clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
        goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
        supplierRate: supplierRate || undefined,
        currency: form.currency,
        tog: form.tog || undefined,
      };
      const profit = (calcItemPriceAED(preview) - calcItemCostAED(preview)).toFixed(2);

      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const creator = userEmail ? userEmail.split('@')[0] : (form.liverName || 'unknown');
      const auditTrail = `[Created by ${creator} on ${timestamp}]`;

      await createRecord({
        fields: {
          minerName: form.minerName.trim(),
          itemDescription: form.itemDescription.trim(),
          category: form.category,
          orderId: form.orderId || undefined,
          mc: form.mc ? parseFloat(form.mc) : undefined,
          grams: form.grams ? parseFloat(form.grams) : undefined,
          clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
          goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
          supplierRate: supplierRate || undefined,
          pureWeight: pureWeight || undefined,
          currency: form.currency,
          modeOfPayment: form.modeOfPayment || undefined,
          modeOfSale: form.modeOfSale || undefined,
          source: form.source || undefined,
          locationOfMiner: form.locationOfMiner,
          regions: form.regions || undefined,
          status: form.status,
          remittanceStatus: form.remittanceStatus,
          dateOfLive: form.dateOfLive,
          liverName: form.liverName || undefined,
          page: form.page,
          tog: form.tog || undefined,
          reviewChasing: 'Pending',
          profit,
          auditTrail,
        },
      });
      toast.success('Client record created');
      onRefresh?.();
      onClose();
    } catch {
      toast.error('Failed to create record');
    } finally {
      setSaving(false);
    }
  };

  const isPinas = form.locationOfMiner === 'Pinas';

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-md bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Add Client Record</DialogTitle>
        </DialogHeader>

        <div className="space-y-3 text-sm">
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Client Name *</Label>
              <Input value={form.minerName} onChange={e => set('minerName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Miner / Client name" />
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Item Description *</Label>
              <Input value={form.itemDescription} onChange={e => set('itemDescription', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="e.g. Gold Ring 18K" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Page *</Label>
              <Select value={form.page} onValueChange={v => set('page', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {PAGE_OPTIONS.map(p => <SelectItem key={p} value={p} className="text-xs">{p}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Liver Name</Label>
              <Input value={form.liverName} onChange={e => set('liverName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Liver name" />
            </div>

