export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();

  let rateForGold = n(record.goldRate) > 0 ? n(record.goldRate) : n(record.supplierRate);
  let mc = n(record.mc);

  // Diamond: MC=0, GoldRate=0, cost = supplierRate * qty
  if (category.includes('diamond')) {
    return roundPrice(n(record.supplierRate) * getQty(record));
  }

  // Per PC or Screw Type: cost = supplierRate * qty (MC=0)
  if (category.includes('per pc') || category.includes('screw type')) {
    mc = 0;
    // Fallback for legacy records with no supplier rate
    if (rateForGold === 0) {
      rateForGold = 115;
      if (desc.includes('buy 1 take 1') || desc.includes('b1t1')) {
        rateForGold = rateForGold * 2;
      }
    }
    return roundPrice(rateForGold * getQty(record));
  }

  const grams = n(record.grams);

  if (category.includes('silver branded')) {
    return roundPrice(32 * grams);
  }

  if (category.includes('silver')) {
    return roundPrice(15 * grams);
  }

  // Automatic MC Fallback 
  if (mc === 0 && !category.includes('silver')) {
    if (category.includes('special price ef')) {
      mc = 25;
    } else if (category.includes('special price')) {
      mc = 21;
    } else {
      mc = 16;
    }
  }

  if (isPcItem(record)) {
    return roundPrice(rateForGold + mc);
  }

  return roundPrice((rateForGold + mc) * grams);
}

