import { useState, memo, useMemo } from 'react';
import { ChevronDown, FileText, MapPin, User, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import AdminItemRow from './AdminItemRow';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function AdminClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const first = records[0];
  const hasOverdue = records.some(isOverdue);
  const inStore = ['in-store', 'walk-in', 'walk in'].includes((first?.modeOfSale || '').toLowerCase().trim());

  // Group records by date for display
  const byDate = useMemo(() => {
    const map = new Map<string, DatabaseRowType[]>();
    for (const r of records) {
      const date = r.dateOfLive || 'Unknown Date';
      if (!map.has(date)) map.set(date, []);
      map.get(date)!.push(r);
    }
    // Sort dates ascending (oldest first)
    return new Map([...map.entries()].sort((a, b) => a[0].localeCompare(b[0])));
  }, [records]);

  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    await Promise.all(records.map(r => onUpdate(r.id, fields)));
  };

  const uniqueDates = byDate.size;

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {hasOverdue && (
              <span className="shrink-0 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">OVERDUE</span>
            )}
          </div>
