                <span className="text-[11px] font-bold text-primary uppercase tracking-widest">📅 {formatDate(date)}</span>
                <div className="h-px flex-1 bg-border/50" />
              </div>

              {Object.entries(grouped[date]).map(([liver, statuses]) => (
