import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen, Plus, Calendar } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMiner, groupByMinerName, formatDate } from '@/lib/formatters';
import { differenceInDays } from 'date-fns';
import { parseDateRobust } from '@/lib/calculations';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';
import AddClientModal from '@/components/accounts/AddClientModal';
import { Button } from '@/components/ui/button';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail, userFirstName, onRefresh }: TabProps) {
  const [expandedPages, setExpandedPages] = useState<Record<string, boolean>>({});
  const [expandedResellers, setExpandedResellers] = useState<Record<string, boolean>>({});
  const [expandedReviewChasing, setExpandedReviewChasing] = useState<Record<string, boolean>>({});
  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});
  const [showAddModal, setShowAddModal] = useState(false);

  const pageGroups = useMemo(() => {
    const searched = applySearch(records, searchQuery);
    const now = new Date();
    const activeAdminRecords = searched.filter(r => {
      const status = r.status || '';
      if (status === 'Pending' || status === 'Waiting for Details' || status === 'Paid/DP but Item Hold') return true;
      if (status === 'Reseller') return true;
      if (status === 'Delivered') {
        if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
        if (!r.deliveredDate) return false;
        const mos = (r.modeOfSale || '').toLowerCase().trim();
        if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
        const delivered = parseDateRobust(r.deliveredDate);
        if (!delivered) return false;
        const diffDays = differenceInDays(now, delivered);
        return diffDays >= 0 && diffDays <= 3;
      }
      return false;
    });

    const groups: Record<string, DatabaseRowType[]> = {};
    activeAdminRecords.forEach(r => {
      let pageKey = (r.page || 'Other').trim();
      if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
      else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
      if (!groups[pageKey]) groups[pageKey] = [];
      groups[pageKey].push(r);
    });

    return Object.keys(groups)
      .sort((a, b) => {
        if (a === 'MYK') return -1; if (b === 'MYK') return 1;
        if (a === 'Empire Gold By ETG') return -1; if (b === 'Empire Gold By ETG') return 1;
        return a.localeCompare(b);
      })
      .reduce((acc, key) => { acc[key] = groups[key]; return acc; }, {} as Record<string, DatabaseRowType[]>);
  }, [records, searchQuery]);

  const togglePage = (page: string) =>
    setExpandedPages(prev => ({ ...prev, [page]: prev[page] === undefined ? false : !prev[page] }));

  const toggleDate = (key: string) =>
    setExpandedDates(prev => ({ ...prev, [key]: prev[key] === undefined ? false : !prev[key] }));

  // Group mined items by date → miner
  const groupMinedByDate = (minedItems: DatabaseRowType[]): Map<string, Map<string, DatabaseRowType[]>> => {
    const byDate = new Map<string, Map<string, DatabaseRowType[]>>();
    for (const r of minedItems) {
      const date = r.dateOfLive || 'Unknown Date';
      const miner = r.minerName?.trim() || 'Unknown Client';
      if (!byDate.has(date)) byDate.set(date, new Map());
      const byMiner = byDate.get(date)!;
      if (!byMiner.has(miner)) byMiner.set(miner, []);
      byMiner.get(miner)!.push(r);
    }
    return new Map([...byDate.entries()].sort((a, b) => b[0].localeCompare(a[0]))); // newest first
  };

  const renderPageSection = (pageName: string, pageRecords: DatabaseRowType[]) => {
    const isExpanded = expandedPages[pageName] !== false;
    const minedItems = pageRecords.filter(r =>
      r.status === 'Pending' || r.status === 'Waiting for Details' || r.status === 'Paid/DP but Item Hold'
    );
    const resellerItems = pageRecords.filter(r => r.status === 'Reseller');
    const reviewChasingItems = pageRecords.filter(r => r.status === 'Delivered');
    const minedByDate = groupMinedByDate(minedItems);
    const resellerGrouped = groupByMiner(resellerItems);
    const reviewChasingGroups = groupByMinerName(reviewChasingItems);

    return (
      <div key={pageName} className="mb-10">
        {/* Page header */}
        <div
          className="flex items-center gap-3 py-2.5 px-4 bg-secondary/40 rounded-xl cursor-pointer mb-4 border border-primary/10 hover:bg-secondary/60 transition-colors"
          onClick={() => togglePage(pageName)}
        >
          {pageName === 'MYK' ? <Crown className="h-5 w-5 text-yellow-500" />
            : pageName === 'Empire Gold By ETG' ? <BookOpen className="h-5 w-5 text-primary" />
            : <Layout className="h-5 w-5 text-muted-foreground" />}
          <h2 className="font-cinzel text-base font-bold text-primary tracking-widest uppercase">{pageName}</h2>
          <div className="h-px flex-1 bg-primary/10" />
          <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{pageRecords.length}</span>
          <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>

        {isExpanded && (
          <div className="pl-2 sm:pl-4 space-y-8 animate-in fade-in slide-in-from-top-2 duration-300">
            {/* MINED ITEMS grouped by date */}
            {minedByDate.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] pl-1">Mined Items</span>
                  <div className="h-px flex-1 bg-border/60" />
                </div>
                {Array.from(minedByDate.entries()).map(([date, minerMap]) => {
                  const dateKey = `${pageName}__${date}`;
                  const isDateExpanded = expandedDates[dateKey] !== false;
                  const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                  return (
                    <div key={date} className="mb-3">
                      {/* Date collapsible header — styled like MYK/MINED ITEMS */}
                      <div
                        className="flex items-center gap-2 py-2 px-3 bg-primary/10 rounded-lg cursor-pointer mb-2 border border-primary/20 hover:bg-primary/15 transition-colors"
                        onClick={() => toggleDate(dateKey)}
                      >
                        <Calendar className="h-3.5 w-3.5 text-primary" />
                        <span className="text-xs font-bold text-primary uppercase tracking-widest">{formatDate(date)}</span>
                        <div className="h-px flex-1 bg-primary/20" />
                        <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
                        <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                      </div>
                      {isDateExpanded && (
                        <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                          {Array.from(minerMap.entries()).map(([name, items]) => (
                            <AdminClientCard key={name} minerName={name} records={items} onUpdate={onUpdate} userEmail={userEmail} />
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {/* RESELLERS */}
            {resellerGrouped.size > 0 && (() => {
              const isResellerExpanded = expandedResellers[pageName] !== false;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedResellers(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                    <div className="h-px flex-1 bg-teal-500/20" />
                    <span className="text-[10px] font-bold bg-teal-500/20 text-teal-500 px-2 py-0.5 rounded-md">{resellerGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-500 transition-transform duration-200 ${isResellerExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isResellerExpanded && Array.from(resellerGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {/* REVIEW CHASING */}
            {reviewChasingGroups.size > 0 && (() => {
              const isReviewExpanded = expandedReviewChasing[pageName] !== false;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedReviewChasing(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                    <div className="h-px flex-1 bg-primary/20" />
                    <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{reviewChasingGroups.size}</span>
                    <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isReviewExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isReviewExpanded && (
                    <div className="grid grid-cols-1 gap-3">
                      {Array.from(reviewChasingGroups.entries()).map(([name, items]) => (
                        <ReviewChasingCard key={name} minerName={name} records={items} onUpdate={onUpdate} />
                      ))}
                    </div>
                  )}
                </div>
              );
            })()}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Admin Pipeline" subtitle="Future-Ready Page Segregation" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex justify-end mb-4">
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>
      </div>
      <div className="px-4">
        {Object.keys(pageGroups).length > 0
          ? Object.keys(pageGroups).map(page => renderPageSection(page, pageGroups[page]))
          : (
            <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
              <p className="text-sm text-muted-foreground font-medium">No records found matching your search.</p>
            </div>
          )}
      </div>
      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, MapPin, Store, ChevronDown, PauseCircle, Users } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByLocationSourceLiverDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(true);
  const [showHold, setShowHold] = useState(true);
  const [showReseller, setShowReseller] = useState(true);
  const [showDispatched, setShowDispatched] = useState(true);

  const { forPullout, onHold, reseller, dispatched } = useMemo(() => {
    const filtered = records.filter(r => {
      // UPDATED FILTER
      if (r.status !== 'For Pullout' && r.status !== 'Dispatch' && r.status !== 'Dispatched' && r.status !== 'Paid/DP but Item Hold' && r.status !== 'Reseller') return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      return true;
    });

    const searched = applySearch(filtered, searchQuery);

    return {
      forPullout: groupByLocationSourceLiverDateMiner(searched.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch')),
      onHold: groupByLocationSourceLiverDateMiner(searched.filter(r => r.status === 'Paid/DP but Item Hold')),
      reseller: groupByLocationSourceLiverDateMiner(searched.filter(r => r.status === 'Reseller')),
      dispatched: groupByLocationSourceLiverDateMiner(searched.filter(r => r.status === 'Dispatched')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch').length, [records]);

  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, Map<string, Map<string, DatabaseRowType[]>>>>>) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }

    return Array.from(groupedData.entries()).map(([location, sources]) => (
      <div key={location} className="mb-8">
        <div className="flex items-center gap-2 mb-4">
          <MapPin className="h-5 w-5 text-primary" />
          <h2 className="font-cinzel text-lg text-primary tracking-wide uppercase">{location}</h2>
        </div>

        <div className="pl-2 sm:pl-6 border-l-2 border-border/50 space-y-4">
          {Array.from(sources.entries()).map(([source, livers]) => (
            <div key={source}>
              <div className="flex items-center gap-2 mb-3">
                <Store className="h-4 w-4 text-muted-foreground" />
                <h3 className="text-sm font-bold text-foreground">{source}</h3>
              </div>

              <div className="pl-2 sm:pl-6 space-y-2">
                {Array.from(livers.entries()).sort((a, b) => a[0].localeCompare(b[0])).map(([liver, dates]) => (
                  <CollapsibleGroup key={liver} label={liver} colorClass="text-primary/70" lineClass="bg-primary/10">
                    {Array.from(dates.entries()).sort((a, b) => b[0].localeCompare(a[0])).map(([date, miners]) => (
                      <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent>
                        {Array.from(miners.entries()).map(([miner, items]) => (
                          <DispatchClientCard key={miner} minerName={miner} records={items} onUpdate={onUpdate} userEmail={userEmail} />
                        ))}
                      </CollapsibleGroup>
                    ))}
                  </CollapsibleGroup>
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    ));
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">

        {/* FOR PULLOUT SECTION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPullout(!showPullout)}>
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>
        {showPullout && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(forPullout)}</div>}

        {/* RESELLER SECTION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowReseller(!showReseller)}>
          <Users className="h-4 w-4 text-teal-400" />
          <span className="font-cinzel text-xs text-teal-400 font-bold">RESELLER</span>
          <div className="h-px flex-1 bg-teal-400/30" />
          <ChevronDown className={`h-4 w-4 text-teal-400 transition-transform ${showReseller ? 'rotate-180' : ''}`} />
        </button>
        {showReseller && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(reseller)}</div>}

        {/* PAID BUT ON HOLD SECTION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowHold(!showHold)}>
          <PauseCircle className="h-4 w-4 text-indigo-400" />
          {/* UPDATED HEADER NAME HERE */}
          <span className="font-cinzel text-xs text-indigo-400 font-bold">PAID/DP BUT ON HOLD</span>
          <div className="h-px flex-1 bg-indigo-400/30" />
          <ChevronDown className={`h-4 w-4 text-indigo-400 transition-transform ${showHold ? 'rotate-180' : ''}`} />
        </button>
        {showHold && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(onHold)}</div>}

        {/* DISPATCHED SECTION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDispatched(!showDispatched)}>
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED</span>
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>
        {showDispatched && <div className="animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(dispatched)}</div>}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByLiverDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import { calcRemainingBalance, parseDateRobust } from '@/lib/calculations';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus, Calendar } from 'lucide-react';
import AddClientModal from './AddClientModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' },
  { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [otherExpanded, setOtherExpanded] = useState(true);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    let base = records;

    // Liver filter
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }

    // Date filter
    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;

      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) {
          const end = new Date(to); end.setHours(23, 59, 59, 999);
          if (d.getTime() > end.getTime()) return false;
        }
        return true;
      });
    }

    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  const { deliveredGroups, otherActiveGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);

    const active = searched.filter(r => {
      const isDeliveredOrLayaway = r.status === 'Delivered' || r.status === 'Given to Shop' || r.modeOfPayment === 'Layaway';
      if (!isDeliveredOrLayaway) return false;
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received');
      if (isCleared) return false;
      const isPendingOrEmpty = !remStatus || remStatus === 'pending payment';
      const hasBalance = calcRemainingBalance(r) > 0;
      return isPendingOrEmpty || hasBalance;
    });

    const delivered = active.filter(r => r.status === 'Delivered');
    const others = active.filter(r => r.status !== 'Delivered');
    const cleared = searched.filter(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      return remStatus.includes('secured') || remStatus.includes('received');
    });

    return {
      deliveredGroups: groupByLiverDateMiner(delivered, 'asc'),
      otherActiveGroups: groupByLiverDateMiner(others, 'asc'),
      clearedGroups: groupByLiverDateMiner(cleared, 'asc'),
    };
  }, [filteredRecords, searchQuery]);

  const renderGroups = (groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => (
    groups.size === 0 ? (
      <div className="text-center py-10 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      <div>
        {Array.from(groups.entries()).map(([liver, dateMap]) => (
          <CollapsibleGroup key={liver} label={liver} colorClass="text-primary/70" lineClass="bg-primary/10">
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent>
                <div className="space-y-3">
                  {Array.from(minerMap.entries()).map(([minerName, items]) => (
                    <AccountsClientCard key={minerName} minerName={minerName} records={items} onUpdate={onUpdate} />
                  ))}
                </div>
              </CollapsibleGroup>
            ))}
          </CollapsibleGroup>
        ))}
      </div>
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${deliveredGroups.size + otherActiveGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* FILTERS ROW */}
        <div className="flex flex-wrap gap-2 mb-3">
          {/* Liver filter */}
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          {/* Date range buttons */}
          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {/* Custom date pickers */}
        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        {/* ADD CLIENT BUTTON */}
        <div className="flex justify-end mb-4">
          <Button
            onClick={() => setShowAddModal(true)}
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" />
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({deliveredGroups.size + otherActiveGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            <div className="mb-6">
              <button className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none" onClick={() => setDeliveredExpanded(!deliveredExpanded)}>
                <span className="font-cinzel text-sm font-bold text-green-500 whitespace-nowrap tracking-wide">DELIVERED</span>
                <span className="text-xs bg-green-500/10 text-green-500 px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-green-500/20">{deliveredGroups.size} clients</span>
                <div className="h-px flex-1 bg-green-500/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>
              {deliveredExpanded && <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroups(deliveredGroups)}</div>}
            </div>

            <div className="mb-4">
              <button className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none" onClick={() => setOtherExpanded(!otherExpanded)}>
                <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap tracking-wide">OTHER ACTIVE (LAYAWAY/SHOP)</span>
                <span className="text-xs bg-primary/10 text-primary px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-primary/20">{otherActiveGroups.size} clients</span>
                <div className="h-px flex-1 bg-primary/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${otherExpanded ? 'rotate-180' : ''}`} />
              </button>
              {otherExpanded && <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroups(otherActiveGroups)}</div>}
            </div>
          </TabsContent>

          <TabsContent value="cleared">
            <div className="space-y-3">{renderGroups(clearedGroups)}</div>
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { 
  calcProfitAED, 
  calcRemainingBalance, 
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    const base = records; 

    if (range === 'all') return base;

    const now = new Date();
    let from: Date;

    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0); 

    const to = range === 'custom' ? customTo : undefined;

    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;

      const itemTime = d.getTime();
      if (itemTime < from.getTime()) return false;

      if (to) {
        const endOfToDay = new Date(to);
        endOfToDay.setHours(23, 59, 59, 999);
        if (itemTime > endOfToDay.getTime()) return false;
      }

      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    const activeRecords = filtered.filter(r => r.status !== 'Cancelled');

    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

    return { 
      totalProfit, 
      totalSold, 
      outstanding,
      activeCount: activeRecords.length 
    };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const toggleStatus = (status: string) => {
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));
  };

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  const handlePrintReport = () => {
    const win = window.open('', '_blank');
    if (!win) return;

    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin-bottom: 4px; font-size: 24px; color: #111; }
        .summary { margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-radius: 8px; border: 1px solid #ddd; }
        .summary p { margin: 6px 0; font-size: 14px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
        th { background: #111; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
        th.r, td.r { text-align: right; }
        td { padding: 8px; border-bottom: 1px solid #ddd; }
        .status-header { font-size: 16px; margin-top: 24px; margin-bottom: 8px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px;}
        .liver-header { font-size: 13px; font-weight: bold; margin-top: 14px; margin-bottom: 4px; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; }
        .date-header { font-size: 11px; font-weight: bold; margin-top: 8px; margin-bottom: 2px; color: #555; padding: 3px 8px; background: #f0f0f0; border-left: 3px solid #C9A84C; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
      </style></head><body>

      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>

      <div class="summary">
        <p>Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></p>
        <p>Total Items Sold: ${kpis.totalSold}</p>
        <p>Outstanding Receivables: AED ${kpis.outstanding.toFixed(2)}</p>
        <p style="font-size: 11px; color: #666; font-weight: normal; margin-top: 12px;">Date Range: ${dateRangeLabel} | Generated: ${new Date().toLocaleString()}</p>
      </div>
    `;

    Array.from(statusGroups.entries()).sort((a, b) => {
      if (a[0] === 'Cancelled') return 1;
      if (b[0] === 'Cancelled') return -1;
      return a[0].localeCompare(b[0]);
    }).forEach(([status, items]) => {
      const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
      const profitText = status === 'Cancelled' ? '' : ` | Profit: AED ${statusProfit.toFixed(2)}`;
      html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} (${items.length} items${profitText})</h2>`;

      // Group by liver, then by date
      const byLiver = new Map<string, Map<string, DatabaseRowType[]>>();
      for (const r of items) {
        const liver = (r.liverName?.trim().toUpperCase()) || 'UNKNOWN LIVER';
        const date = formatDate(r.dateOfLive);
        if (!byLiver.has(liver)) byLiver.set(liver, new Map());
        const byDate = byLiver.get(liver)!;
        if (!byDate.has(date)) byDate.set(date, []);
        byDate.get(date)!.push(r);
      }

      const profitHeader = status === 'Cancelled' ? '' : `<th class="r">Profit (AED)</th>`;

      Array.from(byLiver.entries()).sort((a, b) => a[0].localeCompare(b[0])).forEach(([liver, dateMap]) => {
        html += `<div class="liver-header">🧑 ${liver}</div>`;

        Array.from(dateMap.entries()).sort((a, b) => a[0].localeCompare(b[0])).forEach(([date, rows]) => {
          const dateProfit = rows.reduce((s, r) => s + calcProfitAED(r), 0);
          const dateProfitText = status === 'Cancelled' ? '' : ` — Profit: AED ${dateProfit.toFixed(2)}`;
          html += `<div class="date-header">📅 ${date}${dateProfitText}</div>`;
          html += `<table><thead><tr>
            <th>Client</th><th>Item</th>
            <th class="r">Price (AED)</th><th class="r">Cost (AED)</th>
            ${profitHeader}
          </tr></thead><tbody>`;

          html += rows.map(r => {
            const profit = calcProfitAED(r);
            const profitClass = profit >= 0 ? 'profit-pos' : 'profit-neg';
            const profitCell = status === 'Cancelled' ? '' : `<td class="r"><strong class="${profitClass}">${profit.toFixed(2)}</strong></td>`;
            return `<tr>
              <td><strong>${r.minerName || '—'}</strong></td>
              <td>${r.itemDescription || '—'}</td>
              <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
              <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
              ${profitCell}
            </tr>`;
          }).join('');

          html += `</tbody></table>`;
        });
      });
    });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
