import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const LOGO_URL = 'https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';

const NOTES = [
  'WE CAN ONLY HOLD UNPAID ITEMS FOR MAXIMUM 3 DAYS ONLY FROM THE INVOICE DATE.',
  'FAILURE TO SETTLE AFTER 3 DAYS, ADDITIONAL CHARGES MAY OCCUR.',
  'UNPAID ITEMS WILL BE AUTOMATICALLY CANCELED AFTER THE GRACE PERIOD WITHOUT PRIOR NOTICE.',
  'ALL ITEMS UNDERGO QUALITY CHECKING AFTER LIVE AND BEFORE DISPATCH.',
  'UNBOXING VIDEO IS A MUST. NO UNBOXING VIDEO, NO REFUND AND NO EXCHANGE.',
  'NO CASH REFUND. STORE CREDIT ONLY.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;

export default function InvoicePrintContent({ records, currency }: Props) {
  const first = records[0];

  const fmtAmt = (v: number) =>
    `${currency} ${v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const items = records.map(r => {
    // If invoice currency matches record currency, compute directly (no AED round-trip rounding error)
    const sameCurrency = (r.currency || 'AED') === currency;
    const price = sameCurrency ? calcItemPrice(r) : fromAED(calcItemPriceAED(r), currency);
    const rate = sameCurrency ? n(r.clientRate) : fromAED(clientRateAED(r), currency);

    const category = (r.category || '').toLowerCase();
    const isScrewType = category.includes('screw type');
    const isPerPc = category.includes('per pc');
    const isSilverBranded = category.includes('silver branded');
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = getQty(r);

    // Formatting for the Grams/Qty column
    let gramsDisplay = '';
    if (isScrewType || isPerPc || isSilverBranded) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = isPc || gramsValue === 0 ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: isPc || isScrewType || isPerPc || isSilverBranded,
      rate,
      amount: price,
      liver: r.liverName?.trim() || '',
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  const shippingAED = first ? calcShippingFee(first) : 0;
  const shipping = fromAED(shippingAED, currency);
  const additionalAED = n(first?.additionalCharges);
  const additional = fromAED(additionalAED, currency);
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const ccFee = fromAED(ccFeeAED, currency);
  const total = subtotal + shipping + additional + ccFee;

  // Do not add screw types to the total grams count
  const totalGrams = records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('silver branded')) return s;
    return s + n(r.grams);
  }, 0);

  const amountInWords = numberToWords(total, currency);

  const rawDate = formatDate(first?.dateOfLive);
  const invoiceDate = rawDate === '—'
    ? new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
    : rawDate;

  const summaryRows = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>
      <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0 }}>
        <em style={{ fontSize: 14 }}>Invoice</em>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <tbody>
