import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

// Generates the next sequential invoice number for a given MMDDYY prefix
// Format: MMDDYY001, MMDDYY002, ... resets per day
export default createEndpoint({
  description: 'Generate next sequential invoice number for a given date prefix (MMDDYY)',
  inputSchema: z.object({
    prefix: z.string().length(6), // MMDDYY e.g. "031026"
  }),
  outputSchema: z.object({
    invoiceNumber: z.string(),
  }),
  execute: async ({ input }) => {
    const { prefix } = input;

    // Fetch all records to find existing invoice numbers for this day
    const allRecords = await Database.findAll({});
    const records = allRecords || [];

    // Find all invoice numbers matching this day's prefix (e.g. "031026001")
    const regex = new RegExp(`^${prefix}(\\d{3})$`);
    let maxSeq = 0;

    for (const r of records) {
      if (r.pureWeight) {
        const match = r.pureWeight.match(regex);
        if (match) {
          const seq = parseInt(match[1], 10);
          if (seq > maxSeq) maxSeq = seq;
        }
      }
    }

    const nextSeq = maxSeq + 1;
    const invoiceNumber = `${prefix}${String(nextSeq).padStart(3, '0')}`;

    return { invoiceNumber };
  },
});

