import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

// Generates a deterministic invoice number for a record based on its position
// among all records with the same dateOfLive, sorted by row ID.
// Format: MMDDYY001, MMDDYY002, ... unique per client per day
export default createEndpoint({
  description: 'Generate a deterministic invoice number for a record based on its position among same-date records',
  inputSchema: z.object({
    prefix: z.string().length(6), // MMDDYY e.g. "031126"
    recordId: z.number(),         // The row ID of the record needing an invoice number
    dateOfLive: z.string(),       // The raw dateOfLive string to match against other records
  }),
  outputSchema: z.object({
    invoiceNumber: z.string(),
  }),
  execute: async ({ input }) => {
    const { prefix, recordId, dateOfLive } = input;

    // Fetch all records
    const allRecords = await Database.findAll({});
    const records = allRecords || [];

    // Find all records with the same dateOfLive value
    const sameDate = records
      .filter(r => r.dateOfLive === dateOfLive)
      .sort((a, b) => a.id - b.id);

    // Find the 1-based position of this record among same-date records
    const position = sameDate.findIndex(r => r.id === recordId);

    // If record not found (shouldn't happen), fall back to scanning existing invoice numbers
    if (position === -1) {
      const regex = new RegExp(`^${prefix}(\\d{3})$`);
      let maxSeq = 0;
      for (const r of records) {
        if (r.pureWeight) {
          const match = r.pureWeight.match(regex);
          if (match) {
            const seq = parseInt(match[1], 10);
            if (seq > maxSeq) maxSeq = seq;
          }
        }
      }
      return { invoiceNumber: `${prefix}${String(maxSeq + 1).padStart(3, '0')}` };
    }

    const seq = position + 1;
    return { invoiceNumber: `${prefix}${String(seq).padStart(3, '0')}` };
  },
});

