import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

// Generates a deterministic invoice number per CLIENT per date.
// All items belonging to the same minerName+dateOfLive share the same invoice number.
// Clients are ordered by their earliest record ID on that date.
// Format: MMDDYY001 (NingNing), MMDDYY002 (Dhel), etc.
export default createEndpoint({
  description: 'Generate a deterministic, per-client invoice number based on client order by row ID on the same date',
  inputSchema: z.object({
    prefix: z.string().length(6),  // MMDDYY e.g. "031126"
    recordId: z.number(),          // The row ID of the record needing an invoice number
    dateOfLive: z.string(),        // Raw dateOfLive string to match other records
    minerName: z.string(),         // Client name to group by
  }),
  outputSchema: z.object({
    invoiceNumber: z.string(),
  }),
  execute: async ({ input }) => {
    const { prefix, recordId, dateOfLive, minerName } = input;

    // Fetch all records
    const allRecords = await Database.findAll({});
    const records = allRecords || [];

    // Filter to same date
    const sameDate = records.filter(r => r.dateOfLive === dateOfLive);

    // Group records by minerName (case-insensitive trim), track earliest ID per client
    const clientMap = new Map<string, { minId: number; names: string[] }>();
    for (const r of sameDate) {
      const key = (r.minerName || '').toLowerCase().trim();
      if (!key) continue;
      const existing = clientMap.get(key);
      if (!existing) {
        clientMap.set(key, { minId: r.id, names: [r.minerName || ''] });
      } else {
        if (r.id < existing.minId) existing.minId = r.id;
      }
    }

    // Sort clients by their earliest record ID (first appearance = lower sequence)
    const sortedClients = Array.from(clientMap.entries())
      .sort((a, b) => a[1].minId - b[1].minId);

    // Find this client's position (1-based)
    const myKey = minerName.toLowerCase().trim();
    const clientIndex = sortedClients.findIndex(([key]) => key === myKey);

    if (clientIndex === -1) {
      // Client not found in same-date records — assign next available sequence
      const seq = sortedClients.length + 1;
      return { invoiceNumber: `${prefix}${String(seq).padStart(3, '0')}` };
    }

    const seq = clientIndex + 1;
    return { invoiceNumber: `${prefix}${String(seq).padStart(3, '0')}` };
  },
});

