/**
 * PHP conversion rate store — persisted in localStorage.
 * Key: dateOfLive string (e.g. "2026-03-11")
 * Value: AED → PHP rate (e.g. 16.8)
 *
 * Smart locking: once a rate is set for a date, ALL Pinas clients
 * on that same date automatically use the same rate.
 */

const STORAGE_KEY = 'phpRates_v1';

function loadRates(): Record<string, number> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveRates(rates: Record<string, number>) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(rates));
}

export function getPhpRate(date: string): number | null {
  const rates = loadRates();
  return rates[date] ?? null;
}

export function setPhpRate(date: string, rate: number) {
  const rates = loadRates();
  rates[date] = rate;
  saveRates(rates);
}

export function hasPhpRate(date: string): boolean {
  return getPhpRate(date) !== null;
}

