  const rate = n(record.clientRate);
  let currency = (record.currency || '').trim();
  // Smart fallback: Pinas clients pay in PHP when currency is not explicitly set
  if (!currency && record.locationOfMiner === 'Pinas') {
    currency = 'PHP';
  }
  return toAED(rate, currency);
}
