import { useState, useMemo } from 'react';
import { Loader2 } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { createRecord } from 'zite-endpoints-sdk';
import { MOP_OPTIONS, REGION_OPTIONS } from '@/lib/formatters';
import { calcItemCostAED, calcItemPriceAED } from '@/lib/calculations';
import { DatabaseRowType } from '@/types';

interface Props {
  onClose: () => void;
  userFirstName?: string;
  userEmail?: string;
  onRefresh?: () => void;
}

const LOCATION_OPTIONS = ['Local', 'Pinas', 'International'];
const CURRENCY_OPTIONS = ['AED', 'PHP', 'USD'];
const STATUS_OPTIONS = ['Pending', 'Waiting for Details', 'Paid/DP but Item Hold', 'Reseller', 'Walk-in', 'In-Store'];
const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash', 'Secured via Tabby', 'Secured via Tamara'];
const CATEGORY_OPTIONS = ['Normal', 'Special Price', 'Special Price EF', 'Silver', 'VCA', 'Per PC', 'Diamond', 'Other'];
const PAGE_OPTIONS = ['MYK', 'EMPIRE GOLD BY ETG'];
const TOG_OPTIONS = ['S-925', '18K', '21K', '24K'];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store', 'Offline', 'Reseller'];
const SOURCE_OPTIONS = ['MYK SHOP', 'CROWN', 'DG', 'MSET SHOP', 'SATWA OFFICE', 'UMAAR SUPPLIER'];

export default function AddClientModal({ onClose, userFirstName, userEmail, onRefresh }: Props) {
  const [saving, setSaving] = useState(false);
  const [phpRate, setPhpRate] = useState('16.6');
  const [form, setForm] = useState({
    minerName: '',
    itemDescription: '',
    category: '',
    mc: '',
    grams: '',
    clientRate: '',
    goldRate: '',
    orderId: '',
    currency: 'AED',
    modeOfPayment: '',
    modeOfSale: '',
    source: '',
    locationOfMiner: 'Local',
    regions: '',
    status: 'Walk-in',
    remittanceStatus: 'Pending Payment',
    dateOfLive: new Date().toISOString().split('T')[0],
    liverName: userFirstName || '',
    page: '',
    tog: '',
    supplierRateOverride: '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  // Supplier rate = gold rate + mc (auto-computed) OR manual override for Diamond/Per PC
  const isManualSupplierRate = form.category === 'Diamond' || form.category === 'Per PC';
  const autoSupplierRate = useMemo(() => {
    const gr = parseFloat(form.goldRate) || 0;
    const mc = parseFloat(form.mc) || 0;
    return gr > 0 || mc > 0 ? (gr + mc).toFixed(2) : '';
  }, [form.goldRate, form.mc]);
  const supplierRate = isManualSupplierRate ? form.supplierRateOverride : autoSupplierRate;

  // Pure weight = grams - 0.05 (read-only)
  const pureWeight = useMemo(() => {
    const g = parseFloat(form.grams) || 0;
    return g > 0 ? Math.max(0, g - 0.05).toFixed(2) : '';
  }, [form.grams]);

  const getPerPcSupplierRate = (tog: string, category: string) => {
    if (category === 'Per PC') {
      if (tog === 'S-925') return '32';
      return '115'; // 18K, 21K, 24K, or unset → default 115
    }
    return '';
  };

  const handleCategoryChange = (val: string) => {
    let newMc = form.mc;
    let newGoldRate = form.goldRate;
    let newSupplierRateOverride = form.supplierRateOverride;

    if (val === 'Normal') newMc = '16';
    else if (val === 'Special Price') newMc = '21';
    else if (val === 'Special Price EF') newMc = '25';
    else if (val === 'Silver') newMc = '0';
    else if (val === 'Diamond') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = ''; // manual entry
    } else if (val === 'Per PC') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = getPerPcSupplierRate(form.tog, val);
    }
    setForm(p => ({ ...p, category: val, mc: newMc, goldRate: newGoldRate, supplierRateOverride: newSupplierRateOverride }));
  };

  const handleTogChange = (val: string) => {
    const updates: Partial<typeof form> = { tog: val };
    if (form.category === 'Per PC') {
      updates.supplierRateOverride = getPerPcSupplierRate(val, 'Per PC');
    }
    setForm(p => ({ ...p, ...updates }));
  };

  const handleSave = async () => {
    if (!form.minerName.trim() || !form.itemDescription.trim()) {
      toast.error('Client name and item description are required');
      return;
    }
    if (!form.page) {
      toast.error('Page is required');
      return;
    }
    setSaving(true);
    try {
      const preview: DatabaseRowType = {
        id: 0,
        minerName: form.minerName.trim(),
        itemDescription: form.itemDescription.trim(),
        category: form.category,
        mc: form.mc,
        grams: form.grams ? parseFloat(form.grams) : undefined,
        clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
        goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
        supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
        currency: form.currency,
        tog: form.tog || undefined,
      };
      const profit = (calcItemPriceAED(preview) - calcItemCostAED(preview)).toFixed(2);

      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const creator = userEmail ? userEmail.split('@')[0] : (form.liverName || 'unknown');
      const auditTrail = `[Created by ${creator} on ${timestamp}]`;

      await createRecord({
        fields: {
          minerName: form.minerName.trim(),
          itemDescription: form.itemDescription.trim(),
          category: form.category,
          orderId: form.orderId || undefined,
          mc: form.mc ? parseFloat(form.mc) : undefined,
          grams: form.grams ? parseFloat(form.grams) : undefined,
          clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
          goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
          supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
          pureWeight: pureWeight || undefined,
          currency: form.currency,
          modeOfPayment: form.modeOfPayment || undefined,
          modeOfSale: form.modeOfSale || undefined,
          source: form.source || undefined,
          locationOfMiner: form.locationOfMiner,
          regions: form.regions || undefined,
          status: form.status,
          remittanceStatus: form.remittanceStatus,
          dateOfLive: form.dateOfLive,
          liverName: form.liverName || undefined,
          page: form.page,
          tog: form.tog || undefined,
          reviewChasing: 'Pending',
          profit,
          auditTrail,
        },
      });
      toast.success('Client record created');
      onRefresh?.();
      onClose();
    } catch {
      toast.error('Failed to create record');
    } finally {
      setSaving(false);
    }
  };

  const isPinas = form.locationOfMiner === 'Pinas';

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-md bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Add Client Record</DialogTitle>
        </DialogHeader>

        <div className="space-y-3 text-sm">
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Client Name *</Label>
              <Input value={form.minerName} onChange={e => set('minerName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Miner / Client name" />
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Item Description *</Label>
              <Input value={form.itemDescription} onChange={e => set('itemDescription', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="e.g. Gold Ring 18K" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Page *</Label>
              <Select value={form.page} onValueChange={v => set('page', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {PAGE_OPTIONS.map(p => <SelectItem key={p} value={p} className="text-xs">{p}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Liver Name</Label>
              <Input value={form.liverName} onChange={e => set('liverName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Liver name" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Category</Label>
              <Select value={form.category} onValueChange={handleCategoryChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CATEGORY_OPTIONS.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">T.O.G</Label>
              <Select value={form.tog} onValueChange={handleTogChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {TOG_OPTIONS.map(t => <SelectItem key={t} value={t} className="text-xs">{t}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Order ID / Barcode</Label>
              <Input value={form.orderId} onChange={e => set('orderId', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="e.g. AM-SL-030909" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Grams (0 = PC)</Label>
              <Input type="number" value={form.grams} onChange={e => set('grams', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Pure Wt <span className="text-primary/60">(Grams − 0.05, auto)</span></Label>
              <Input value={pureWeight} readOnly className="h-8 text-xs mt-0.5 bg-muted border-border opacity-70 cursor-not-allowed" placeholder="Auto" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">MC (Making Charge)</Label>
              <Input type="number" value={form.mc} onChange={e => set('mc', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Gold Rate</Label>
              <Input type="number" value={form.goldRate} onChange={e => set('goldRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Client Rate</Label>
              <Input type="number" value={form.clientRate} onChange={e => set('clientRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">
                Supplier Rate{' '}
                {!isManualSupplierRate && <span className="text-primary/60">(auto)</span>}
                {form.category === 'Diamond' && <span className="text-yellow-400">(manual)</span>}
                {form.category === 'Per PC' && <span className="text-primary/60">(preset)</span>}
              </Label>
              {isManualSupplierRate ? (
                <Input
                  type="number"
                  value={form.supplierRateOverride}
                  onChange={e => set('supplierRateOverride', e.target.value)}
                  className="h-8 text-xs mt-0.5 bg-background border-border"
                  placeholder={form.category === 'Diamond' ? 'Enter supplier rate' : '115'}
                />
              ) : (
                <Input value={supplierRate} readOnly className="h-8 text-xs mt-0.5 bg-muted border-border opacity-70 cursor-not-allowed" placeholder="Auto-calculated" />
              )}
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Currency</Label>
              <Select value={form.currency} onValueChange={v => set('currency', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CURRENCY_OPTIONS.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Mode of Sale</Label>
              <Select value={form.modeOfSale} onValueChange={v => set('modeOfSale', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {MODE_OF_SALE_OPTIONS.map(m => <SelectItem key={m} value={m} className="text-xs">{m}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Source</Label>
              <Select value={form.source} onValueChange={v => set('source', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {SOURCE_OPTIONS.map(s => <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Location</Label>
              <Select value={form.locationOfMiner} onValueChange={v => set('locationOfMiner', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {LOCATION_OPTIONS.map(l => <SelectItem key={l} value={l} className="text-xs">{l}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            {/* PHP Conversion Rate — shown only when location is Pinas */}
            {isPinas && (
              <div className="col-span-2 bg-primary/10 border border-primary/20 rounded-lg p-2">
                <Label className="text-xs text-primary font-semibold">PHP Conversion Rate (AED → PHP)</Label>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-xs text-muted-foreground">1 AED =</span>
                  <Input
                    type="number"
                    value={phpRate}
                    onChange={e => setPhpRate(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24"
                    step="0.1"
                  />
                  <span className="text-xs text-muted-foreground">PHP</span>
                </div>
              </div>
            )}

            {form.locationOfMiner === 'Local' && (
              <div>
                <Label className="text-xs text-muted-foreground">Region</Label>
                <Select value={form.regions} onValueChange={v => set('regions', v)}>
                  <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                  <SelectContent className="bg-popover border-border">
                    {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div>
              <Label className="text-xs text-muted-foreground">Mode of Payment</Label>
              <Select value={form.modeOfPayment} onValueChange={v => set('modeOfPayment', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {MOP_OPTIONS.map(m => <SelectItem key={m} value={m} className="text-xs">{m}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Status</Label>
              <Select value={form.status} onValueChange={v => set('status', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {STATUS_OPTIONS.map(s => <SelectItem key={s} value={s} className="text-xs">{s}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Remittance Status</Label>
              <Select value={form.remittanceStatus} onValueChange={v => set('remittanceStatus', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {REMITTANCE_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Date of Live</Label>
              <Input type="date" value={form.dateOfLive} onChange={e => set('dateOfLive', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" />
            </div>
          </div>

          <div className="flex gap-2 pt-2">
            <Button variant="outline" className="flex-1 text-xs h-8 border-border" onClick={onClose}>Cancel</Button>
            <Button onClick={handleSave} disabled={saving} className="flex-1 text-xs h-8 bg-primary text-primary-foreground">
              {saving ? <><Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> Saving...</> : 'Create Record'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { memo } from 'react';
import { DatabaseRowType } from '@/types';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { formatDate } from '@/lib/formatters';
import { toast } from 'sonner';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (id: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function ReviewChasingCard({ minerName, records, onUpdate }: Props) {
  // Use the first record to dictate display values
  const firstRecord = records[0];
  const status = firstRecord.reviewChasing || 'Pending';
  const isChased = status === 'Chased';

  const handleStatusChange = async (val: string) => {
    // Update all matching items for this client simultaneously
    await Promise.all(records.map(r => onUpdate(r.id, { reviewChasing: val })));
    toast.success(`Marked ${minerName} as ${val}`);
  };

  return (
    <div className={`bg-card border border-border rounded-lg p-4 transition-all duration-500 ease-in-out ${isChased ? 'opacity-50 scale-[0.98] py-2.5' : ''}`}>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div className="flex-1 min-w-0">
          <h3 className={`font-medium truncate ${isChased ? 'text-xs' : 'text-sm'}`}>
            {minerName || 'Unknown Client'}
          </h3>

          {/* Hide the item descriptions when chased to save space (auto-minimize) */}
          {!isChased && (
            <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
              {records.map(r => r.itemDescription).join(', ')}
            </p>
          )}

          <p className="text-[10px] text-muted-foreground mt-1">
            Delivered: {firstRecord.deliveredDate ? formatDate(firstRecord.deliveredDate) : 'Unknown'}
            {records.length > 1 && ` · ${records.length} items`}
          </p>
        </div>

        <div className="flex items-center gap-2 shrink-0">
          <Select
            value={status}
            onValueChange={handleStatusChange}
          >
            <SelectTrigger className={`w-[130px] border-border bg-secondary/30 ${isChased ? 'h-7 text-[10px]' : 'h-8 text-xs'}`}>
              <SelectValue placeholder="Select status" />
            </SelectTrigger>
            <SelectContent className="border-border">
              <SelectItem value="Pending">Pending</SelectItem>
              <SelectItem value="Chased">Chased</SelectItem>
              <SelectItem value="Skipped">Skipped</SelectItem>
              <SelectItem value="Completed">Completed</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>
    </div>
  );
}

// MEMO: Prevent re-rendering unchanged clients for performance
export default memo(ReviewChasingCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

import { useState, memo, useMemo, useEffect } from 'react';
import { ChevronDown, FileText, MapPin, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { getPhpRate, setPhpRate, hasPhpRate } from '@/lib/phpRateStore';
import StatusBadge from '@/components/StatusBadge';
import AdminItemRow from './AdminItemRow';
import PhpRateDialog from './PhpRateDialog';
import InvoiceModal from '@/components/InvoiceModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isPinasRecord(r: DatabaseRowType) {
  return r.locationOfMiner === 'Pinas' || r.currency === 'PHP';
}

function AdminClientCard({ minerName, records, onUpdate, userEmail }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [phpRateDialogDate, setPhpRateDialogDate] = useState<string | null>(null);
  const [phpRates, setPhpRates] = useState<Record<string, number>>({});
  const first = records[0];
  const hasOverdue = records.some(isOverdue);

  // Unique sorted dates for header display
  const uniqueDates = useMemo(() => {
    const dates = [...new Set(records.map(r => r.dateOfLive).filter(Boolean) as string[])].sort();
    return dates;
  }, [records]);

  const dateLabel = uniqueDates.length === 1
    ? formatDate(uniqueDates[0])
    : uniqueDates.length > 1
      ? `${formatDate(uniqueDates[0])} – ${formatDate(uniqueDates[uniqueDates.length - 1])}`
      : '—';

  // Group: Date → Liver → Status
  const grouped = useMemo(() => {
    const map: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'Unknown Date';
      const liver = r.liverName?.trim().toUpperCase() || 'UNKNOWN LIVER';
      const status = r.status || 'No Status';
      if (!map[date]) map[date] = {};
      if (!map[date][liver]) map[date][liver] = {};
      if (!map[date][liver][status]) map[date][liver][status] = [];
      map[date][liver][status].push(r);
    }
    return map;
  }, [records]);

  const sortedDates = Object.keys(grouped).sort();

  const toggleDate = (date: string) =>
    setCollapsedDates(prev => ({ ...prev, [date]: !prev[date] }));

  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    await Promise.all(records.map(r => onUpdate(r.id, fields)));
  };

  // When expanded, check if any Pinas records need a rate prompt
  useEffect(() => {
    if (!expanded) return;
    const hasPinas = records.some(isPinasRecord);
    if (!hasPinas) return;

    // Load existing rates into state
    const loaded: Record<string, number> = {};
    for (const date of uniqueDates) {
      const r = getPhpRate(date);
      if (r !== null) loaded[date] = r;
    }
    setPhpRates(loaded);

    // Find first Pinas date without a rate
    const pinasRecords = records.filter(isPinasRecord);
    const pinasDates = [...new Set(pinasRecords.map(r => r.dateOfLive).filter(Boolean) as string[])];
    const needsRate = pinasDates.find(d => !hasPhpRate(d));
    if (needsRate) setPhpRateDialogDate(needsRate);
  }, [expanded]);

  const handleRateConfirm = (rate: number) => {
    if (!phpRateDialogDate) return;
    setPhpRate(phpRateDialogDate, rate);
    setPhpRates(prev => ({ ...prev, [phpRateDialogDate]: rate }));
    setPhpRateDialogDate(null);
  };

  // Get the PHP rate to use for the invoice (use first Pinas date's rate)
  const invoicePhpRate = useMemo(() => {
    const pinasRecords = records.filter(isPinasRecord);
    if (pinasRecords.length === 0) return undefined;
    const date = pinasRecords[0].dateOfLive;
    if (!date) return undefined;
    return phpRates[date] ?? getPhpRate(date) ?? undefined;
  }, [records, phpRates]);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      {/* Client header row */}
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {hasOverdue && (
              <span className="shrink-0 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">OVERDUE</span>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{first?.locationOfMiner || '—'}</span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
          </div>
          <div className="text-[11px] text-primary/70 font-semibold mt-0.5">📅 {dateLabel}</div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {/* PHP rate indicator */}
          {records.some(isPinasRecord) && invoicePhpRate && (
            <div className="flex items-center justify-between mb-2 px-2 py-1.5 rounded-lg bg-amber-500/10 border border-amber-500/20">
              <span className="text-xs text-amber-400 font-medium">
                💱 1 AED = {invoicePhpRate} PHP
              </span>
              <button
                className="text-[10px] text-amber-400/70 underline"
                onClick={() => setPhpRateDialogDate(records.filter(isPinasRecord)[0]?.dateOfLive || null)}
              >
                Change
              </button>
            </div>
          )}

          {/* ── Generate Invoice pinned at TOP ── */}
          <Button
            variant="outline"
            size="sm"
            className="w-full mb-3 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice ({records.length} items)
          </Button>

          {/* ── Collapsible Date sections ── */}
          {sortedDates.map(date => {
            const isDateCollapsed = collapsedDates[date];
            const dateRecordCount = Object.values(grouped[date])
              .flatMap(s => Object.values(s))
              .flat().length;

            return (
              <div key={date} className="mb-3 rounded-lg border border-border/40 overflow-hidden">
                <button
                  className="w-full flex items-center justify-between px-3 py-2 bg-secondary/30 text-left"
                  onClick={() => toggleDate(date)}
                >
                  <span className="text-[11px] font-bold text-primary uppercase tracking-widest">
                    📅 {formatDate(date)}
                  </span>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] text-muted-foreground">{dateRecordCount} item{dateRecordCount !== 1 ? 's' : ''}</span>
                    <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform ${isDateCollapsed ? '' : 'rotate-180'}`} />
                  </div>
                </button>

                {!isDateCollapsed && (
                  <div className="px-3 pt-2 pb-2">
                    {Object.entries(grouped[date]).map(([liver, statuses]) => (
                      <div key={liver} className="mb-2">
                        <div className="text-[10px] font-semibold text-primary/70 uppercase tracking-wide mb-1 px-0.5">
                          🧑 {liver}
                        </div>
                        {Object.entries(statuses).map(([status, items]) => (
                          <div key={status} className="mb-2 ml-2">
                            <div className="flex items-center gap-1.5 mb-1">
                              <StatusBadge status={status} />
                              <span className="text-[10px] text-muted-foreground">({items.length})</span>
                              <div className="h-px flex-1 bg-border/30" />
                            </div>
                            {items.map(record => (
                              <AdminItemRow
                                key={record.id}
                                record={record}
                                onUpdate={onUpdate}
                                onGroupUpdate={handleGroupUpdate}
                                userEmail={userEmail}
                              />
                            ))}
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {phpRateDialogDate && (
        <PhpRateDialog
          date={phpRateDialogDate}
          onConfirm={handleRateConfirm}
          onSkip={() => setPhpRateDialogDate(null)}
        />
      )}

      {showInvoice && (
        <InvoiceModal
          records={records}
          onClose={() => setShowInvoice(false)}
          phpRate={invoicePhpRate}
        />
      )}
    </div>
  );
}

export default memo(AdminClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  return true;
});

import { useState, useEffect, useRef, memo } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle, Pencil } from 'lucide-react';
import EditItemDialog from '@/components/admin/EditItemDialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue, isFreeSf, getQty } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, getLocationFromRegion, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import { generateInvoiceNumber } from 'zite-endpoints-sdk';
import { parseDateRobust } from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

const TOG_OPTIONS = ['18K', 'VCA', '21K', '24K', 'S-925'];

function isInStore(record: DatabaseRowType): boolean {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  return mos === 'in-store' || mos === 'walk-in' || mos === 'walk in';
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = (remarks || '').toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('tamara approved')) return { modeOfPayment: 'Tamara', freeSf: 'TRUE' };
  if (/\bcod\b/.test(r)) return { modeOfPayment: 'COD' };
  if (/\bcc\b/.test(r) || r.includes('credit card')) return { modeOfPayment: 'Credit Card' };
  return null;
}

/** Returns MMDDYY prefix from the record's dateOfLive (falls back to today) */
function getDatePrefix(dateOfLive?: string): string {
  const d = dateOfLive ? parseDateRobust(dateOfLive) : null;
  const date = d || new Date();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const yy = String(date.getFullYear()).slice(-2);
  return `${mm}${dd}${yy}`;
}

function AdminItemRow({ record, onUpdate, onGroupUpdate, userEmail }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const [invoiceNum, setInvoiceNum] = useState(record.pureWeight || '');
  const [resetKey, setResetKey] = useState(Date.now());
  const [hasDownpayment, setHasDownpayment] = useState(!!record.downpayment);
  const [downpayment, setDownpayment] = useState(record.downpayment || '');
  const generatingRef = useRef(false);
  const overdue = isOverdue(record);
  const inStore = isInStore(record);

  // Auto-generate invoice number if missing
  useEffect(() => {
    if (!record.pureWeight && !generatingRef.current) {
      generatingRef.current = true;
      const prefix = getDatePrefix(record.dateOfLive);
      generateInvoiceNumber({ prefix, recordId: record.id, dateOfLive: record.dateOfLive || '', minerName: record.minerName || '' })
        .then(({ invoiceNumber }) => {
          setInvoiceNum(invoiceNumber);
          return onUpdate(record.id, { pureWeight: invoiceNumber });
        })
        .catch(() => { /* silently fail */ })
        .finally(() => { generatingRef.current = false; });
    }
  }, [record.id, record.pureWeight, onUpdate]);

  // Sync if record.pureWeight changes externally
  useEffect(() => {
    if (record.pureWeight) setInvoiceNum(record.pureWeight);
  }, [record.pureWeight]);

  useEffect(() => {
    if (!record.modeOfPayment && record.liverAdminRemarks) {
      const auto = detectAutoFill(record.liverAdminRemarks);
      if (auto) onGroupUpdate(auto);
    }
  }, [record.modeOfPayment, record.liverAdminRemarks, onGroupUpdate]);

  const debouncedDownpayment = useDebouncedCallback(async (val: string) => {
    await onUpdate(record.id, { downpayment: val });
  }, 700);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const autoFill = detectAutoFill(val);
    await onUpdate(record.id, { liverAdminRemarks: val });
    if (autoFill) {
      await onGroupUpdate(autoFill);
      toast.success('Auto-filled MOP from remarks');
    }
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    if (mop === 'Tabby' || mop === 'Tamara') fields.freeSf = 'TRUE';
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    const newLocation = getLocationFromRegion(region);
    await onGroupUpdate({ regions: region, locationOfMiner: newLocation });
  };

  const handleTogChange = async (tog: string) => {
    await onUpdate(record.id, { tog });
  };

  const isWaitingForDP = record.status === 'Waiting for Downpayment';
  const hasDPAmount = hasDownpayment && !!downpayment && parseFloat(downpayment) > 0;
  const dpLocked = isWaitingForDP && !hasDPAmount;

  const handleStatusChange = async (newStatus: string) => {
    setResetKey(Date.now());
    if (newStatus === 'Cancelled') { setShowCancel(true); return; }
    if (dpLocked) {
      toast.error('Enter a downpayment amount to enable other status options');
      return;
    }
    if (newStatus === 'For Pullout') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
            <button onClick={() => setShowEdit(true)} className="shrink-0 text-muted-foreground hover:text-primary transition-colors" title="Edit item details">
              <Pencil className="h-3 w-3" />
            </button>
          </div>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> OVERDUE
              </span>
            )}
          </div>
        </div>
        <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">
            {(record.category || '').toLowerCase().includes('screw type')
              ? `${getQty(record)} PCS`
              : (record.grams ? `${record.grams}g` : 'PC')}
          </p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {!inStore && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="grid grid-cols-3 gap-2">
          <div>
            <Label className="text-xs text-muted-foreground">T.O.G</Label>
            <Select value={record.tog || ''} onValueChange={handleTogChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {TOG_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs text-primary/80 font-semibold">Invoice #</Label>
            <Input
              type="text"
              value={invoiceNum || ''}
              readOnly
              className="h-8 text-xs bg-muted/40 border-border mt-0.5 cursor-not-allowed font-mono"
              placeholder="Generating..."
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Qty</Label>
            <Input
              type="number"
              defaultValue={getQty(record)}
              onChange={e => onUpdate(record.id, { qty: Number(e.target.value) })}
              className="h-8 text-xs bg-background border-border mt-0.5"
              placeholder="1"
            />
          </div>
        </div>

        <div>
          <Label className="text-xs text-muted-foreground">Liver/Admin Remarks</Label>
          <Textarea value={remarks} onChange={e => { setRemarks(e.target.value); debouncedRemarks(e.target.value); }} className="h-14 text-xs bg-background border-border mt-0.5 resize-none" placeholder="e.g. TABBY APPROVED, COD..." />
        </div>

        {/* Downpayment */}
        <div className="space-y-1.5">
          <div className="flex items-center gap-2">
            <Checkbox
              id={`dp-${record.id}`}
              checked={hasDownpayment}
              onCheckedChange={(checked) => {
                const on = !!checked;
                setHasDownpayment(on);
                if (!on) {
                  setDownpayment('');
                  onUpdate(record.id, { downpayment: '' });
                }
              }}
            />
            <Label htmlFor={`dp-${record.id}`} className="text-xs cursor-pointer">Downpayment</Label>
            {hasDownpayment && downpayment && (
              <span className="text-xs text-primary font-medium ml-1">{record.currency || 'AED'} {downpayment}</span>
            )}
          </div>
          {hasDownpayment && (
            <Input
              type="number"
              value={downpayment}
              onChange={e => {
                setDownpayment(e.target.value);
                debouncedDownpayment(e.target.value);
              }}
              className="h-8 text-xs bg-background border-border"
              placeholder="Enter downpayment amount..."
            />
          )}
        </div>

        <div className="flex items-center justify-between">
          {!inStore ? (
            <div className="flex items-center gap-2">
              <Switch checked={isFreeSf(record)} onCheckedChange={v => onGroupUpdate({ freeSf: v ? 'TRUE' : '' })} className="scale-90" />
              <Label className="text-xs">FREE SF</Label>
            </div>
          ) : <div />}

          <Select key={resetKey} onValueChange={handleStatusChange}>
            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="Change status..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {inStore ? (
                <>
                  <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              ) : (
                <>
                  <SelectItem value="Waiting for Downpayment" className="text-xs text-amber-400">Waiting for Downpayment</SelectItem>
                  <SelectItem value="Paid/DP but Item Hold" className="text-xs text-blue-400">Paid/DP but Item Hold</SelectItem>
                  <SelectItem value="For Pullout" disabled={dpLocked} className={`text-xs ${dpLocked ? 'opacity-40' : ''}`}>For Pullout</SelectItem>
                  <SelectItem value="Reseller" disabled={dpLocked} className={`text-xs ${dpLocked ? 'opacity-40' : ''}`}>Reseller</SelectItem>
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              )}
            </SelectContent>
          </Select>
        </div>
      </div>

      {showEdit && (
        <EditItemDialog
          record={record}
          onSave={fields => onUpdate(record.id, fields)}
          onClose={() => setShowEdit(false)}
        />
      )}

      <AlertDialog open={showCancel} onOpenChange={setShowCancel}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => { await onUpdate(record.id, { status: 'Cancelled' }); toast.success('Item cancelled'); }}>
              Cancel Item
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(AdminItemRow, (prevProps, nextProps) => {
  return prevProps.record === nextProps.record && prevProps.userEmail === nextProps.userEmail;
