              <div style={{ fontSize: 11, marginTop: 4 }}>Invoice Date</div>
              {(() => {
                const invoiceNo = records.map(r => r.pureWeight).find(Boolean);
                return invoiceNo ? (
                  <div style={{ marginTop: 8, borderTop: '1px solid #ccc', paddingTop: 6 }}>
                    <div style={{ fontWeight: 700, fontSize: 13, fontFamily: 'monospace', color: '#c00' }}>{invoiceNo}</div>
                    <div style={{ fontSize: 10, color: '#666', marginTop: 2 }}>Invoice #</div>
                  </div>
                ) : null;
              })()}
            </td>
          </tr>
        </tbody>
      </table>

      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ background: '#e0e0e0' }}>
            {['Code', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
