/**
 * PHP conversion rate store — persisted in localStorage.
 * Key: dateOfLive string (e.g. "2026-03-11")
 * Value: AED → PHP rate (e.g. 16.8)
 *
 * Smart locking: once a rate is set for a date, ALL Pinas clients
 * on that same date automatically use the same rate.
 */

const STORAGE_KEY = 'phpRates_v1';

function loadRates(): Record<string, number> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveRates(rates: Record<string, number>) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(rates));
}

export function getPhpRate(date: string): number | null {
  const rates = loadRates();
  return rates[date] ?? null;
}

export function setPhpRate(date: string, rate: number) {
  const rates = loadRates();
  rates[date] = rate;
  saveRates(rates);
}

export function hasPhpRate(date: string): boolean {
  return getPhpRate(date) !== null;
}

import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';

const n = (v: unknown): number => {
  if (typeof v === 'number') return v;
  if (!v) return 0;
  const s = String(v).replace(/,/g, '');
  const match = s.match(/-?\d+(\.\d+)?/);
  return match ? parseFloat(match[0]) : 0;
};

export function roundPrice(v: number): number { return Math.round(v); }

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return String(record.freeSf).toLowerCase() === 'true';
}

function normCurrency(currency?: string): string {
  return (currency || '').toUpperCase().trim();
}

export function getEffectiveCurrency(record: DatabaseRowType): string {
  const curr = normCurrency(record.currency);
  if (!curr && normCurrency(record.locationOfMiner) === 'PINAS') return 'PHP';
  return curr || 'AED';
}

// 1. PERFECT AED CONVERTER (Divides PHP to make it AED)
export function toAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value * 3.67;
  if (curr === 'PHP') return value / 16.6; 
  return value;
}

// 2. PERFECT NATIVE CONVERTER (Multiplies AED to make it PHP)
export function fromAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value / 3.67;
  if (curr === 'PHP') return value * 16.6;
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record);
}

export function getQty(record: DatabaseRowType): number {
  const parsedQty = n(record.qty);
  if (parsedQty > 0) return parsedQty;
  const desc = (record.itemDescription || '').toUpperCase();
  const match = desc.match(/(?:^|\s)(\d+)\s*PCS?\b/);
  if (match) return parseInt(match[1], 10);
  return 1;
}

export const SILVER_RATE = 45;
export const SILVER_BRANDED_RATE = 60;

export function getSilverRate(category: string): number | null {
  const cat = (category || '').toLowerCase();
  if (cat.includes('silver branded')) return SILVER_BRANDED_RATE;
  if (cat.includes('silver')) return SILVER_RATE;
  return null;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category);

  if (silverRate !== null) {
    if (clientRate > 0) return roundPrice(n(record.grams) * clientRate);
    return roundPrice(fromAED(n(record.grams) * silverRate, record));
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(clientRate * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRate);
  const price = roundPrice(n(record.grams) * clientRate);
  return price > 0 ? price : (clientRate > 0 ? roundPrice(clientRate) : 0);
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const rateAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category);

  if (silverRate !== null) {
    if (n(record.clientRate) > 0) return roundPrice(n(record.grams) * rateAED);
    return roundPrice(n(record.grams) * silverRate);
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(rateAED * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(rateAED);
  const price = roundPrice(n(record.grams) * rateAED);
  return price > 0 ? price : (rateAED > 0 ? roundPrice(rateAED) : 0);
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);

  if (category.includes('diamond')) return roundPrice(supplierRate * getQty(record));

  if (category.includes('per pc') || category.includes('screw type')) {
    let rate = supplierRate > 0 ? supplierRate : goldRate > 0 ? goldRate : 115;
    if (rate === 115 && (desc.includes('buy 1 take 1') || desc.includes('b1t1'))) rate *= 2;
    return roundPrice(rate * getQty(record));
  }

  // FIXED SILVER COSTS (AED)
  if (category.includes('silver branded')) return roundPrice(32 * grams);
  if (category.includes('silver')) return roundPrice(15 * grams);

  if (goldRate > 0) {
    const effectiveMc = mc > 0 ? mc : category.includes('special price ef') ? 25 : category.includes('special price') ? 21 : 16;
    if (isPcItem(record)) return roundPrice(goldRate + effectiveMc);
    return roundPrice((goldRate + effectiveMc) * grams);
  }

  if (supplierRate > 0) {
    if (isPcItem(record)) return roundPrice(supplierRate);
    return roundPrice(supplierRate * grams);
  }

  return 0;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const grams = n(record.grams);
  const isSilver = getSilverRate(category) !== null;
  const isPerPcType = category.includes('per pc') || category.includes('screw type') || category.includes('diamond');

  if (!isSilver && !isPerPcType && grams > 0) {
    const goldRate = n(record.goldRate);
    const supplierRate = n(record.supplierRate);
    if (goldRate === 0 && supplierRate === 0) return 0;
  }

  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  return roundPrice(totalSales - totalCost);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  const loc = normCurrency(record.locationOfMiner);
  if (loc === 'LOCAL') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30;
    return 30; 
  }

  if (loc === 'INTERNATIONAL' || loc === 'PINAS') return 299;
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  return record.modeOfPayment === 'Credit Card' ? 5 : 0;
}

export function calcTotalPaid(record: DatabaseRowType): number {
  const raw = n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) + n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
  return toAED(raw, record);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = calcItemPriceAED(record);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return roundPrice((itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid);
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details' && record.status !== 'Waiting for Downpayment') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { TabProps, DatabaseRowType } from '@/types';
import {
  calcProfitAED,
  calcRemainingBalance,
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [selectedPrintStatuses, setSelectedPrintStatuses] = useState<Set<string>>(new Set());

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    const base = records;
    if (range === 'all') return base;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      const itemTime = d.getTime();
      if (itemTime < from.getTime()) return false;
      if (to) {
        const endOfToDay = new Date(to);
        endOfToDay.setHours(23, 59, 59, 999);
        if (itemTime > endOfToDay.getTime()) return false;
      }
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    const activeRecords = filtered.filter(r => r.status !== 'Cancelled');
    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    return { totalProfit, totalSold, outstanding, activeCount: activeRecords.length };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const toggleStatus = (status: string) => {
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));
  };

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  const openPrintDialog = () => {
    // Pre-select all statuses
    setSelectedPrintStatuses(new Set(statusGroups.keys()));
    setShowPrintDialog(true);
  };

  const togglePrintStatus = (status: string) => {
    setSelectedPrintStatuses(prev => {
      const next = new Set(prev);
      if (next.has(status)) next.delete(status);
      else next.add(status);
      return next;
    });
  };

  const handlePrintReport = () => {
    setShowPrintDialog(false);
    const win = window.open('', '_blank');
    if (!win) return;

    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin-bottom: 4px; font-size: 24px; color: #111; }
        .summary { margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-radius: 8px; border: 1px solid #ddd; }
        .summary p { margin: 6px 0; font-size: 14px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
        th { background: #111; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
        th.r, td.r { text-align: right; }
        td { padding: 8px; border-bottom: 1px solid #ddd; }
        .status-header { font-size: 16px; margin-top: 24px; margin-bottom: 8px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px;}
        .page-header { font-size: 13px; font-weight: bold; margin-top: 14px; margin-bottom: 4px; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; }
        .date-header { font-size: 11px; font-weight: bold; margin-top: 8px; margin-bottom: 2px; color: #555; padding: 3px 8px; background: #f0f0f0; border-left: 3px solid #C9A84C; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
      </style></head><body>

      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>

      <div class="summary">
        <p>Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></p>
        <p>Total Items Sold: ${kpis.totalSold}</p>
        <p>Outstanding Receivables: AED ${kpis.outstanding.toFixed(2)}</p>
        <p style="font-size: 11px; color: #666; font-weight: normal; margin-top: 12px;">Date Range: ${dateRangeLabel} | Generated: ${new Date().toLocaleString()}</p>
      </div>
    `;

    Array.from(statusGroups.entries())
      .filter(([status]) => selectedPrintStatuses.has(status))
      .sort((a, b) => {
        if (a[0] === 'Cancelled') return 1;
        if (b[0] === 'Cancelled') return -1;
        return a[0].localeCompare(b[0]);
      }).forEach(([status, items]) => {
        const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
        const profitText = status === 'Cancelled' ? '' : ` | Profit: AED ${statusProfit.toFixed(2)}`;
        html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} (${items.length} items${profitText})</h2>`;

        // Group by page, then by date
        const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
        for (const r of items) {
          let pageKey = (r.page || 'Other').trim();
          if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
          else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
          const date = formatDate(r.dateOfLive);
          if (!byPage.has(pageKey)) byPage.set(pageKey, new Map());
          const byDate = byPage.get(pageKey)!;
          if (!byDate.has(date)) byDate.set(date, []);
          byDate.get(date)!.push(r);
        }

        const profitHeader = status === 'Cancelled' ? '' : `<th class="r">Profit (AED)</th>`;

        Array.from(byPage.entries()).sort((a, b) => {
          if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
          if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
          return a[0].localeCompare(b[0]);
        }).forEach(([page, dateMap]) => {
          html += `<div class="page-header">📄 ${page}</div>`;

          Array.from(dateMap.entries()).sort((a, b) => b[0].localeCompare(a[0])).forEach(([date, rows]) => {
            const dateProfit = rows.reduce((s, r) => s + calcProfitAED(r), 0);
            const dateProfitText = status === 'Cancelled' ? '' : ` — Profit: AED ${dateProfit.toFixed(2)}`;
            html += `<div class="date-header">📅 ${date}${dateProfitText}</div>`;
            html += `<table><thead><tr>
              <th>Client</th><th>Item</th>
              <th class="r">Price (AED)</th><th class="r">Cost (AED)</th>
              ${profitHeader}
            </tr></thead><tbody>`;

            html += rows.map(r => {
              const profit = calcProfitAED(r);
              const profitClass = profit >= 0 ? 'profit-pos' : 'profit-neg';
              const profitCell = status === 'Cancelled' ? '' : `<td class="r"><strong class="${profitClass}">${profit.toFixed(2)}</strong></td>`;
              return `<tr>
                <td><strong>${r.minerName || '—'}</strong></td>
                <td>${r.itemDescription || '—'}</td>
                <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
                <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
                ${profitCell}
              </tr>`;
            }).join('');

            html += `</tbody></table>`;
          });
        });
      });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        {/* Liver name filter */}
        <div className="mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-44 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3 mb-6">
          <KpiCard title="Total Expected Profit" value={`AED ${kpis.totalProfit.toFixed(2)}`} subtitle={`${kpis.activeCount} active records (excl. Cancelled)`} highlight />
          <KpiCard title="Total Items Sold" value={kpis.totalSold.toString()} subtitle="Delivered/Given to Shop (excl. Cancelled)" />
          <KpiCard title="Outstanding Receivables" value={`AED ${kpis.outstanding.toFixed(2)}`} subtitle="Sum of remaining balances (excl. Cancelled)" />
        </div>

        <div className="flex items-center justify-between mb-4">
          <h2 className="font-cinzel text-lg text-primary">Detailed Breakdown</h2>
          <Button variant="outline" size="sm" className="h-8 text-xs border-primary/40 text-primary" onClick={openPrintDialog}>
            <Printer className="h-3.5 w-3.5 mr-1.5" /> Print Report
          </Button>
        </div>

        <div className="space-y-3">
          {Array.from(statusGroups.entries()).sort((a, b) => {
            if (a[0] === 'Cancelled') return 1;
            if (b[0] === 'Cancelled') return -1;
            return a[0].localeCompare(b[0]);
          }).map(([status, items]) => {
            const totalProfit = items.reduce((sum, r) => sum + calcProfitAED(r), 0);
            const isExpanded = expandedStatuses[status];

            return (
              <div key={status} className="rounded-xl border border-border bg-card overflow-hidden">
                <button
                  onClick={() => toggleStatus(status)}
                  className="w-full flex items-center justify-between p-4 text-left focus:outline-none"
                >
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <StatusBadge status={status} />
                      <span className="text-xs text-muted-foreground">{items.length} items</span>
                    </div>
                    {status !== 'Cancelled' && (
                      <p className="text-xs font-medium">
                        Profit: <span className={totalProfit >= 0 ? 'text-green-400' : 'text-destructive'}>AED {totalProfit.toFixed(2)}</span>
                      </p>
                    )}
                  </div>
                  <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {isExpanded && (() => {
                  const statusLiver = statusLiverFilters[status] || 'all';
                  const statusLiverNames = [...new Set(items.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean) as string[])].sort();
                  const visibleItems = statusLiver === 'all' ? items : items.filter(r => r.liverName?.trim().toUpperCase() === statusLiver);

                  // Group by Page → Date → Name
                  const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
                  for (const r of visibleItems) {
                    let pageKey = (r.page || 'Other').trim();
                    if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
                    else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
                    const d = r.dateOfLive || 'Unknown Date';
                    if (!byPage.has(pageKey)) byPage.set(pageKey, new Map());
                    const byDate = byPage.get(pageKey)!;
                    if (!byDate.has(d)) byDate.set(d, []);
                    byDate.get(d)!.push(r);
                  }

                  const sortedPages = [...byPage.entries()].sort((a, b) => {
                    if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
                    if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
                    return a[0].localeCompare(b[0]);
                  });

                  return (
                    <div className="px-4 pb-4 border-t border-border pt-3 animate-in fade-in slide-in-from-top-2 duration-200">
                      {statusLiverNames.length > 1 && (
                        <div className="mb-3">
                          <Select value={statusLiver} onValueChange={v => setStatusLiverFilters(prev => ({ ...prev, [status]: v }))}>
                            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
                              <SelectValue placeholder="All Livers" />
                            </SelectTrigger>
                            <SelectContent className="bg-popover border-border">
                              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
                              {statusLiverNames.map(name => (
                                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                      <div className="space-y-4">
                        {sortedPages.map(([page, dateMap]) => {
                          const sortedDates = [...dateMap.entries()].sort((a, b) => b[0].localeCompare(a[0]));
                          return (
                            <div key={page}>
                              {/* Page separator */}
                              <div className="flex items-center gap-2 mb-2">
                                <span className="text-[10px] font-bold text-primary/70 uppercase tracking-widest">📄 {page}</span>
                                <div className="h-px flex-1 bg-border/50" />
                                <span className="text-[10px] text-muted-foreground">{Array.from(dateMap.values()).reduce((s, v) => s + v.length, 0)}</span>
                              </div>
                              <div className="space-y-3 ml-2">
                                {sortedDates.map(([date, dateItems]) => (
                                  <div key={date}>
                                    {/* Date sub-header */}
                                    <div className="flex items-center gap-1.5 mb-1.5">
                                      <span className="text-[9px] font-semibold text-muted-foreground uppercase tracking-widest">📅 {formatDate(date)}</span>
                                      <div className="h-px flex-1 bg-border/30" />
                                      <span className="text-[9px] text-muted-foreground">{dateItems.length}</span>
                                    </div>
                                    <div className="space-y-2 ml-2">
                                      {dateItems.map(record => {
                                        const profit = calcProfitAED(record);
                                        return (
                                          <div key={record.id} className="flex justify-between items-start border-b border-border/40 pb-2 last:border-0 last:pb-0">
                                            <div className="flex-1 pr-2">
                                              <p className="text-sm font-medium">{record.minerName || 'Unknown'}</p>
                                              <p className="text-xs text-muted-foreground mt-0.5 truncate">{record.itemDescription} ({record.grams ? `${record.grams}g` : 'PC'})</p>
                                            </div>
                                            {status !== 'Cancelled' && (
                                              <div className="text-right shrink-0">
                                                <p className={`text-sm font-medium ${profit >= 0 ? 'text-foreground' : 'text-destructive'}`}>AED {profit.toFixed(2)}</p>
                                                <p className="text-[10px] text-muted-foreground mt-0.5">Profit</p>
                                              </div>
                                            )}
                                          </div>
                                        );
                                      })}
                                    </div>
                                  </div>
                                ))}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })()}
              </div>
            );
          })}

          {statusGroups.size === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No records found for this period.</p>
            </div>
          )}
        </div>
      </div>

      {/* Print Status Selection Dialog */}
      <Dialog open={showPrintDialog} onOpenChange={setShowPrintDialog}>
        <DialogContent className="bg-card border-border max-w-sm">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary text-base">Select Statuses to Print</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="flex gap-2 mb-2">
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set(statusGroups.keys()))}>Select All</Button>
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set())}>Clear All</Button>
            </div>
            {Array.from(statusGroups.entries()).sort((a, b) => {
              if (a[0] === 'Cancelled') return 1;
              if (b[0] === 'Cancelled') return -1;
              return a[0].localeCompare(b[0]);
            }).map(([status, items]) => (
              <div key={status} className="flex items-center gap-3">
                <Checkbox
                  id={`print-${status}`}
                  checked={selectedPrintStatuses.has(status)}
                  onCheckedChange={() => togglePrintStatus(status)}
                />
                <Label htmlFor={`print-${status}`} className="text-sm cursor-pointer flex-1">
                  {status}
                  <span className="text-xs text-muted-foreground ml-2">({items.length} items)</span>
                </Label>
              </div>
            ))}
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" className="text-xs border-border" onClick={() => setShowPrintDialog(false)}>Cancel</Button>
            <Button
              size="sm"
              className="text-xs bg-primary text-primary-foreground"
              disabled={selectedPrintStatuses.size === 0}
              onClick={handlePrintReport}
            >
              <Printer className="h-3.5 w-3.5 mr-1.5" /> Print
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { RefreshCw } from 'lucide-react'; // <-- Added refresh icon
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles'; 
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[] | null>(null);
  const [rolesError, setRolesError] = useState(false);

  const [dataLoading, setDataLoading] = useState(true); 
  const [isSyncing, setIsSyncing] = useState(false); // Track silent background syncs
  const [searchQuery, setSearchQuery] = useState('');

  // Keep track of what tab they click, but we'll validate it later
  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing'>('admin');

  // Add a "silent" flag so it doesn't show the skeleton loader when refreshing in the background
  const fetchData = useCallback((silent = false) => {
    if (!user) return;

    if (silent) {
      setIsSyncing(true);
    } else {
      setDataLoading(true);
    }

    Promise.all([
      getRecords({}).catch(() => { toast.error('Failed to load records'); return []; }),
      getRoles({}).catch((err) => { 
        console.error('getRoles failed — failing closed for security:', err);
        setRolesError(true);
        return null;
      })
    ])
      .then(([recordsData, rolesData]) => {
        setRecords((recordsData as DatabaseRowType[]) || []);
        if (rolesData !== null) {
          setDynamicRoles((rolesData as any[]) || []);
        }
      })
      .finally(() => {
        setDataLoading(false);
        setIsSyncing(false);
      });
  }, [user]);

  useEffect(() => { fetchData(false); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    // 1. Optimistic UI update (makes the app feel instantly responsive)
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));

    try {
      // 2. Save to Google Sheets
      await updateRecord({ rowId, fields: fields as Record<string, unknown> });

      // 3. Silent Background Refresh (pulls everyone else's changes automatically)
      fetchData(true);
    } catch {
      toast.error('Failed to save changes');
      fetchData(true); // Revert the UI if the save fails
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  // role is now an ARRAY: e.g., ['admin', 'dispatch']
  const roles = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = roles.includes('super_admin');

  // Check if they have zero roles
  if (rolesError) return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <div className="text-center space-y-3 p-8 max-w-sm">
        <p className="text-destructive font-semibold">Failed to load roles</p>
        <p className="text-sm text-muted-foreground">Could not verify your permissions. Please refresh the page to try again.</p>
        <button onClick={() => { setRolesError(false); fetchData(false); }} className="text-xs text-primary underline">Retry</button>
      </div>
    </div>
  );
  if (dataLoading && dynamicRoles === null) return <LoadingSkeleton />;
  if (!dataLoading && roles.length === 0) return <AccessDenied email={user.email} />;

  // Determine exactly which tabs this user is allowed to see
  const ALL_TABS = ['admin', 'dispatch', 'accounts', 'bossing'] as const;
  const allowedTabs = isSuperAdmin 
    ? ALL_TABS 
    : ALL_TABS.filter(t => roles.includes(t as any));

  // Smart routing: if their selected activeTab isn't in their allowed list, default to their first allowed tab
  const currentTab = allowedTabs.includes(activeTab) ? activeTab : allowedTabs[0];

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
    userFirstName: user.firstName,
    onRefresh: () => fetchData(true),
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">

          {/* Small Top Bar Logo */}
          <img 
            src="https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png" 
            alt="Logo" 
            className="h-6 sm:h-8 w-auto object-contain mr-2 sm:mr-4" 
          />

          {/* Show Navigation Tabs if they are a super admin OR if they have more than 1 role */}
          {allowedTabs.length > 1 && (
            <div className="flex h-full items-center border-l border-border pl-2 sm:pl-4">
              {allowedTabs.includes('admin') && (
                <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              )}
              {allowedTabs.includes('dispatch') && (
                <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              )}
              {allowedTabs.includes('accounts') && (
                <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              )}
              {allowedTabs.includes('bossing') && (
                <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 sm:gap-3">
          {/* Manual Refresh Button */}
          <button 
            onClick={() => fetchData(true)}
            disabled={isSyncing}
            className={`p-1.5 rounded-full hover:bg-secondary transition-colors ${isSyncing ? 'animate-spin text-primary' : 'text-muted-foreground'}`}
            title="Sync latest data"
          >
            <RefreshCw className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          </button>

          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[100px] sm:max-w-none">
            {user.email}
          </span>

          {(isSuperAdmin || roles.includes('admin')) && (
            <UploadMasterlistFAB onRefresh={() => fetchData(false)} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {currentTab === 'admin' && <AdminPipeline {...tabProps} />}
          {currentTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {currentTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {currentTab === 'bossing' && <BossingDashboard {...tabProps} />}
        </div>
      )}
    </div>
  );
}

