export function getSilverRate(category: string, record?: DatabaseRowType): number | null {
  const cat = (category || '').toLowerCase();
  const date = record?.dateOfLive;
  if (cat.includes('silver branded')) {
    const custom = date ? getSilverBrandedRateForDate(date) : null;
    return custom ?? SILVER_BRANDED_RATE;
  }
  if (cat.includes('silver')) {
    const custom = date ? getSilverRateForDate(date) : null;
    return custom ?? SILVER_RATE;
  }
  return null;
}

