import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  customerId: string;
  minerName: string;
  allRecords: DatabaseRowType[];
  onClose: () => void;
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg bg-secondary/30 border border-border px-3 py-2 text-center">
      <div className="text-[10px] text-muted-foreground uppercase tracking-wide mb-0.5">{label}</div>
      <div className="text-sm font-bold text-primary">{value}</div>
    </div>
  );
}

export default function CustomerHistoryModal({ customerId, minerName, allRecords, onClose }: Props) {
  const history = useMemo(
    () => allRecords.filter(r => r.customerId === customerId),
    [allRecords, customerId],
  );

  const totalItems = history.length;
  const totalSpent = history.reduce((s, r) => s + calcItemPriceAED(r), 0);
  const totalOutstanding = history.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);

  const sorted = useMemo(
    () => [...history].sort((a, b) => (b.dateOfLive || '').localeCompare(a.dateOfLive || '')),
    [history],
  );

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary text-base">
            {minerName}
            <span className="ml-2 text-xs text-muted-foreground font-mono font-normal">{customerId}</span>
          </DialogTitle>
        </DialogHeader>

        {/* Summary */}
        <div className="grid grid-cols-3 gap-2 mb-4">
          <StatCard label="Total Lifetime Items" value={totalItems.toString()} />
          <StatCard label="Total Lifetime Spent (AED)" value={`AED ${totalSpent.toFixed(2)}`} />
          <StatCard label="Total Outstanding (AED)" value={`AED ${totalOutstanding.toFixed(2)}`} />
        </div>

        {/* History table */}
        {sorted.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-8">No history found for this customer ID.</p>
        ) : (
          <div className="rounded-lg border border-border overflow-hidden">
            <table className="w-full text-xs">
              <thead>
                <tr className="bg-secondary/40 border-b border-border">
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Date</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Item</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium hidden sm:table-cell">Category</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Status</th>
                  <th className="text-right px-3 py-2 text-muted-foreground font-medium">Amount</th>
                </tr>
              </thead>
              <tbody>
                {sorted.map((r, i) => (
                  <tr key={r.id} className={`border-b border-border/40 ${i % 2 === 0 ? '' : 'bg-secondary/10'}`}>
                    <td className="px-3 py-2 text-muted-foreground whitespace-nowrap">{r.dateOfLive ? formatDate(r.dateOfLive) : '—'}</td>
                    <td className="px-3 py-2 max-w-[160px] truncate">{r.itemDescription || '—'}</td>
                    <td className="px-3 py-2 text-muted-foreground hidden sm:table-cell">{r.category || '—'}</td>
                    <td className="px-3 py-2"><StatusBadge status={r.status || '—'} /></td>
                    <td className="px-3 py-2 text-right font-medium text-primary">AED {calcItemPriceAED(r).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

