import { useState, memo, useMemo, useEffect } from 'react';
import { ChevronDown, FileText, MapPin, Upload, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { isOverdue } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { getPhpRate, setPhpRate, hasPhpRate, setSilverRate, setSilverBrandedRate } from '@/lib/ratesStore';
import StatusBadge from '@/components/StatusBadge';
import AdminItemRow from './AdminItemRow';
import PhpRateDialog from './PhpRateDialog';
import InvoiceModal from '@/components/InvoiceModal';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isPinasRecord(r: DatabaseRowType) {
  return r.locationOfMiner === 'Pinas' || r.currency === 'PHP';
}

function AdminClientCard({ minerName, records, allRecords, onUpdate, userEmail }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [phpRateDialogDate, setPhpRateDialogDate] = useState<string | null>(null);
  const [phpRates, setPhpRates] = useState<Record<string, number>>({});
  const first = records[0];
  const hasOverdue = records.some(isOverdue);

  const uniqueDates = useMemo(() => {
    const dates = [...new Set(records.map(r => r.dateOfLive).filter(Boolean) as string[])].sort();
    return dates;
  }, [records]);

  const dateLabel = uniqueDates.length === 1
    ? formatDate(uniqueDates[0])
    : uniqueDates.length > 1
      ? `${formatDate(uniqueDates[0])} – ${formatDate(uniqueDates[uniqueDates.length - 1])}`
      : '—';

  const grouped = useMemo(() => {
    const map: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'Unknown Date';
      const liver = r.liverName?.trim().toUpperCase() || 'UNKNOWN LIVER';
      const status = r.status || 'No Status';
      if (!map[date]) map[date] = {};
      if (!map[date][liver]) map[date][liver] = {};
      if (!map[date][liver][status]) map[date][liver][status] = [];
      map[date][liver][status].push(r);
    }
    return map;
  }, [records]);

  const sortedDates = Object.keys(grouped).sort();

  const toggleDate = (date: string) =>
    setCollapsedDates(prev => ({ ...prev, [date]: !prev[date] }));

  const handleGroupUpdate = async (fields: Partial<DatabaseRowType>) => {
    for (const r of records) {
      await onUpdate(r.id, fields);
      await new Promise(res => setTimeout(res, 300));
    }
  };

  useEffect(() => {
    if (!expanded) return;
    const hasPinas = records.some(isPinasRecord);
    if (!hasPinas) return;

    const loaded: Record<string, number> = {};
    for (const date of uniqueDates) {
      const r = getPhpRate(date);
      if (r !== null) loaded[date] = r;
    }
    setPhpRates(loaded);

    const pinasRecords = records.filter(isPinasRecord);
    const pinasDates = [...new Set(pinasRecords.map(r => r.dateOfLive).filter(Boolean) as string[])];
    const needsRate = pinasDates.find(d => !hasPhpRate(d));
    if (needsRate) setPhpRateDialogDate(needsRate);
  }, [expanded, records, uniqueDates]);

  const handleRateConfirm = (phpRate: number, silverRate?: number, silverBrandedRate?: number) => {
    if (!phpRateDialogDate) return;
    setPhpRate(phpRateDialogDate, phpRate);
    if (silverRate) setSilverRate(phpRateDialogDate, silverRate);
    if (silverBrandedRate) setSilverBrandedRate(phpRateDialogDate, silverBrandedRate);
    setPhpRates(prev => ({ ...prev, [phpRateDialogDate]: phpRate }));
    setPhpRateDialogDate(null);
  };

  const invoicePhpRate = useMemo(() => {
    const pinasRecords = records.filter(isPinasRecord);
    if (pinasRecords.length === 0) return undefined;
    const date = pinasRecords[0].dateOfLive;
    if (!date) return undefined;
    return phpRates[date] ?? getPhpRate(date) ?? undefined;
  }, [records, phpRates]);

  const hasInvoiceNumber = first?.pureWeight && first.pureWeight.trim() !== '';

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full text-left px-4 py-3 flex items-center justify-between"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-cinzel text-sm text-primary truncate">{minerName}</span>
            {hasOverdue && (
              <span className="shrink-0 text-xs font-bold text-destructive bg-destructive/10 border border-destructive/30 px-1.5 py-0.5 rounded animate-pulse">OVERDUE</span>
            )}
            {first?.customerId && (
              <button
                className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-muted-foreground">
            <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{first?.locationOfMiner || '—'}</span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
          </div>
          <div className="text-[11px] text-primary/70 font-semibold mt-0.5">📅 {dateLabel}</div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {records.some(isPinasRecord) && invoicePhpRate && (
            <div className="flex items-center justify-between mb-2 px-2 py-1.5 rounded-lg bg-amber-500/10 border border-amber-500/20">
              <span className="text-xs text-amber-400 font-medium">
                💱 1 AED = {invoicePhpRate} PHP
              </span>
              <button
                className="text-[10px] text-amber-400/70 underline"
                onClick={() => setPhpRateDialogDate(records.filter(isPinasRecord)[0]?.dateOfLive || null)}
              >
                Change
              </button>
            </div>
          )}

          <Button
            variant="outline"
            size="sm"
            onClick={(e) => {
              if (!hasInvoiceNumber) {
                e.preventDefault();
                e.stopPropagation();
                return;
              }
              setShowInvoice(true);
            }}
            disabled={!hasInvoiceNumber}
            className={`w-full mb-3 text-xs ${!hasInvoiceNumber ? 'opacity-50 cursor-not-allowed pointer-events-none bg-secondary/50 text-muted-foreground border-border' : 'border-primary/40 text-primary hover:bg-primary/10'}`}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> 
            {hasInvoiceNumber ? `Generate Invoice (${records.length} items)` : 'Click "Gen" on an item below to unlock'}
          </Button>

          {sortedDates.map(date => {
            const isDateCollapsed = collapsedDates[date];
            const dateRecordCount = Object.values(grouped[date])
              .flatMap(s => Object.values(s))
              .flat().length;

            return (
              <div key={date} className="mb-3 rounded-lg border border-border/40 overflow-hidden">
                <button
                  className="w-full flex items-center justify-between px-3 py-2 bg-secondary/30 text-left"
                  onClick={() => toggleDate(date)}
                >
                  <span className="text-[11px] font-bold text-primary uppercase tracking-widest">
                    📅 {formatDate(date)}
                  </span>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] text-muted-foreground">{dateRecordCount} item{dateRecordCount !== 1 ? 's' : ''}</span>
                    <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground transition-transform ${isDateCollapsed ? '' : 'rotate-180'}`} />
                  </div>
                </button>

                {!isDateCollapsed && (
                  <div className="px-3 pt-2 pb-2">
                    {Object.entries(grouped[date]).map(([liver, statuses]) => (
                      <div key={liver} className="mb-2">
                        <div className="text-[10px] font-semibold text-primary/70 uppercase tracking-wide mb-1 px-0.5">
                          🧑 {liver}
                        </div>
                        {Object.entries(statuses).map(([status, items]) => (
                          <div key={status} className="mb-2 ml-2">
                            <div className="flex items-center gap-1.5 mb-1">
                              <StatusBadge status={status} />
                              <span className="text-[10px] text-muted-foreground">({items.length})</span>
                              <div className="h-px flex-1 bg-border/30" />
                            </div>
                            {items.map(record => (
                              <AdminItemRow
                                key={record.id}
                                record={record}
                                onUpdate={onUpdate}
                                onGroupUpdate={handleGroupUpdate}
                                userEmail={userEmail}
                              />
                            ))}
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}

      {phpRateDialogDate && (
        <PhpRateDialog
          date={phpRateDialogDate}
          onConfirm={handleRateConfirm}
          onSkip={() => setPhpRateDialogDate(null)}
        />
      )}

      {showInvoice && (
        <InvoiceModal
          records={allRecords.filter(r => r.minerName?.trim().toLowerCase() === minerName.trim().toLowerCase())}
          onClose={() => setShowInvoice(false)}
        />
      )}

      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

export default memo(AdminClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useState, memo } from 'react';
import { FileText, Truck, Upload, History, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf, getQty } from '@/lib/calculations';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function getDeliveryLabel(record: DatabaseRowType): string {
  const mop = record.modeOfPayment || '';
  const region = record.regions ? `(${record.regions})` : '';
  if (mop === 'Pick Up Shop') return 'Pick Up Shop';
  if (mop === 'Meet Up') return 'Meet Up';
  if (mop === 'Layaway') return 'Layaway';
  if (region) return `${mop} ${region}`.trim();
  return mop || 'Unknown';
}

function getDeliverySummary(records: DatabaseRowType[]): string {
  const labels = records.map(getDeliveryLabel);
  const unique = [...new Set(labels)];
  if (unique.length === 1) return unique[0];
  return `🔴 MIXED: ${unique.join(', ')}`;
}

function DispatchClientCard({ minerName, records, allRecords, onUpdate, userEmail }: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});

  const [showHistory, setShowHistory] = useState(false);

  const first = records[0];
  const deliverySummary = getDeliverySummary(records);

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full px-4 py-2.5 border-b border-border/50 flex items-center justify-between text-left focus:outline-none"
        onClick={() => setIsExpanded(prev => !prev)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <span className="font-cinzel text-sm text-primary">{minerName}</span>
            {first?.customerId && (
              <button
                className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span className={deliverySummary.startsWith('🔴') ? 'text-destructive font-medium' : ''}>
              {deliverySummary}
            </span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 ml-2 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="border-primary/40 text-primary text-xs h-7"
            onClick={e => { e.stopPropagation(); setShowInvoice(true); }}
          >
            <FileText className="h-3 w-3 mr-1" /> Invoice
          </Button>
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {isExpanded && (
        <div className="px-3 py-2 space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          {records.map(record => {
            const givenToShopMode = isGivenToShopMode(record);
            const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;
            return (
              <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <p className="text-sm font-medium">{record.itemDescription}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')}
                      <span className="text-foreground font-medium ml-1">
                        · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                      </span>
                    </p>
                  </div>
                  <StatusBadge status={record.status} />
                </div>

                <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                  <Truck className="h-3 w-3" />
                  <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                  {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
                </div>

                {record.liverAdminRemarks && (
                  <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                    Remarks: {record.liverAdminRemarks}
                  </p>
                )}

                {latestAudit && (
                  <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                    <History className="h-2.5 w-2.5" />
                    {latestAudit}
                  </p>
                )}

                {record.status !== 'Cancelled' && (
                <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                  <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                    <SelectValue placeholder="Set status..." />
                  </SelectTrigger>
                 <SelectContent className="bg-popover border-border">
                    {givenToShopMode ? (
                      <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                    ) : (
                      <>
                        <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                        <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                      </>
                    )}
                    <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem>
                    <SelectItem value="Returned Item" className="text-xs">Returned Item</SelectItem>
                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
                )}
              </div>
            );
          })}
        </div>
      )}

      {showInvoice && (
        <InvoiceModal
          records={allRecords.filter(r => r.minerName?.trim().toLowerCase() === minerName.trim().toLowerCase())}
          onClose={() => setShowInvoice(false)}
        />
      )}

      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords} 
          onClose={() => setShowHistory(false)}
        />
      )}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

