import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';

interface Props {
  customerId: string;
  minerName: string;
  allRecords: DatabaseRowType[];
  onClose: () => void;
}

function StatCard({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-lg bg-secondary/30 border border-border px-3 py-2 text-center">
      <div className="text-[10px] text-muted-foreground uppercase tracking-wide mb-0.5">{label}</div>
      <div className="text-sm font-bold text-primary">{value}</div>
    </div>
  );
}

export default function CustomerHistoryModal({ customerId, minerName, allRecords, onClose }: Props) {
  const history = useMemo(() => {
    const targetName = minerName.trim().toLowerCase();
    return allRecords.filter(r =>
      (r.customerId && r.customerId === customerId) ||
      (!r.customerId && r.minerName?.trim().toLowerCase() === targetName)
    );
  }, [allRecords, customerId, minerName]);

  // FIX: Exclude Cancelled and Returned items from the lifetime math
  const activeHistory = history.filter(r => r.status !== 'Cancelled' && r.status !== 'Returned Item');

  const totalItems = activeHistory.length;
  const totalSpent = activeHistory.reduce((s, r) => s + calcItemPriceAED(r), 0);
  const totalOutstanding = activeHistory.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);

  const sorted = useMemo(
    () => [...history].sort((a, b) => (b.dateOfLive || '').localeCompare(a.dateOfLive || '')),
    [history],
  );

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-2xl bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary text-base">
            {minerName}
            <span className="ml-2 text-xs text-muted-foreground font-mono font-normal">{customerId}</span>
          </DialogTitle>
        </DialogHeader>

        <div className="grid grid-cols-3 gap-2 mb-4">
          <StatCard label="Valid Lifetime Items" value={totalItems.toString()} />
          <StatCard label="Total Lifetime Spent (AED)" value={`AED ${totalSpent.toFixed(2)}`} />
          <StatCard label="Total Outstanding (AED)" value={`AED ${totalOutstanding.toFixed(2)}`} />
        </div>

        {sorted.length === 0 ? (
          <p className="text-sm text-muted-foreground text-center py-8">No history found for this customer ID.</p>
        ) : (
          <div className="rounded-lg border border-border overflow-hidden">
            <table className="w-full text-xs">
              <thead>
                <tr className="bg-secondary/40 border-b border-border">
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Date</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Item</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium hidden sm:table-cell">Category</th>
                  <th className="text-left px-3 py-2 text-muted-foreground font-medium">Status</th>
                  <th className="text-right px-3 py-2 text-muted-foreground font-medium">Amount</th>
                </tr>
              </thead>
              <tbody>
                {sorted.map((r, i) => (
                  <tr key={r.id} className={`border-b border-border/40 ${i % 2 === 0 ? '' : 'bg-secondary/10'}`}>
                    <td className="px-3 py-2 text-muted-foreground whitespace-nowrap">{r.dateOfLive ? formatDate(r.dateOfLive) : '—'}</td>
                    <td className="px-3 py-2 max-w-[160px] truncate">{r.itemDescription || '—'}</td>
                    <td className="px-3 py-2 text-muted-foreground hidden sm:table-cell">{r.category || '—'}</td>
                    <td className="px-3 py-2"><StatusBadge status={r.status || '—'} /></td>
                    <td className="px-3 py-2 text-right font-medium text-primary">AED {calcItemPriceAED(r).toFixed(2)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen, Plus, Calendar } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMiner, groupByMinerName, formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';
import AddClientModal from '@/components/accounts/AddClientModal';
import { Button } from '@/components/ui/button';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail, userFirstName, onRefresh }: TabProps) {
  const [expandedPages, setExpandedPages] = useState<Record<string, boolean>>({});
  const [expandedResellers, setExpandedResellers] = useState<Record<string, boolean>>({});
  const [expandedReviewChasing, setExpandedReviewChasing] = useState<Record<string, boolean>>({});
  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});
  const [showAddModal, setShowAddModal] = useState(false);

  const pageGroups = useMemo(() => {
    const searched = applySearch(records, searchQuery);

    // FIX: The 3-day restriction is removed. Delivered items stay forever UNTIL explicitly skipped or completed.
    const activeAdminRecords = searched.filter(r => {
      const status = r.status || '';
      if (status === 'Pending' || status === 'Waiting for Details' || status === 'Waiting for Downpayment') return true;
      if (status === 'Reseller') return true;
      if (status === 'Delivered') {
        if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
        return true; 
      }
      return false;
    });

    const groups: Record<string, DatabaseRowType[]> = {};
    activeAdminRecords.forEach(r => {
      let pageKey = (r.page || 'Other').trim();
      if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
      else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
      if (!groups[pageKey]) groups[pageKey] = [];
      groups[pageKey].push(r);
    });

    return Object.keys(groups)
      .sort((a, b) => {
        if (a === 'MYK') return -1; if (b === 'MYK') return 1;
        if (a === 'Empire Gold By ETG') return -1; if (b === 'Empire Gold By ETG') return 1;
        return a.localeCompare(b);
      })
      .reduce((acc, key) => { acc[key] = groups[key]; return acc; }, {} as Record<string, DatabaseRowType[]>);
  }, [records, searchQuery]);

  const togglePage = (page: string) =>
    setExpandedPages(prev => ({ ...prev, [page]: !prev[page] }));

  const toggleDate = (key: string) =>
    setExpandedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const groupMinedByDate = (minedItems: DatabaseRowType[]): Map<string, Map<string, DatabaseRowType[]>> => {
    const byDate = new Map<string, Map<string, DatabaseRowType[]>>();
    for (const r of minedItems) {
      const date = r.dateOfLive || 'Unknown Date';
      const miner = r.minerName?.trim() || 'Unknown Client';
      if (!byDate.has(date)) byDate.set(date, new Map());
      const byMiner = byDate.get(date)!;
      if (!byMiner.has(miner)) byMiner.set(miner, []);
      byMiner.get(miner)!.push(r);
    }
    return new Map([...byDate.entries()].sort((a, b) => b[0].localeCompare(a[0])));
  };

  const renderPageSection = (pageName: string, pageRecords: DatabaseRowType[]) => {
    const isExpanded = expandedPages[pageName] === true;
    const minedItems = pageRecords.filter(r =>
      r.status === 'Pending' || r.status === 'Waiting for Details' || r.status === 'Waiting for Downpayment'
    );
    const resellerItems = pageRecords.filter(r => r.status === 'Reseller');
    const reviewChasingItems = pageRecords.filter(r => r.status === 'Delivered');
    const minedByDate = groupMinedByDate(minedItems);
    const resellerGrouped = groupByMiner(resellerItems);
    const reviewChasingGroups = groupByMinerName(reviewChasingItems);

    return (
      <div key={pageName} className="mb-10">
        <div
          className="flex items-center gap-3 py-2.5 px-4 bg-secondary/40 rounded-xl cursor-pointer mb-4 border border-primary/10 hover:bg-secondary/60 transition-colors"
          onClick={() => togglePage(pageName)}
        >
          {pageName === 'MYK' ? <Crown className="h-5 w-5 text-yellow-500" />
            : pageName === 'Empire Gold By ETG' ? <BookOpen className="h-5 w-5 text-primary" />
            : <Layout className="h-5 w-5 text-muted-foreground" />}
          <h2 className="font-cinzel text-base font-bold text-primary tracking-widest uppercase">{pageName}</h2>
          <div className="h-px flex-1 bg-primary/10" />
          <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{pageRecords.length}</span>
          <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>

        {isExpanded && (
          <div className="pl-2 sm:pl-4 space-y-8 animate-in fade-in slide-in-from-top-2 duration-300">
            {minedByDate.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] pl-1">Mined Items</span>
                  <div className="h-px flex-1 bg-border/60" />
                </div>
                {Array.from(minedByDate.entries()).map(([date, minerMap]) => {
                  const dateKey = `${pageName}__${date}`;
                  const isDateExpanded = expandedDates[dateKey] === true;
                  const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                  return (
                    <div key={date} className="mb-3">
                      <div
                        className="flex items-center gap-2 py-2 px-3 bg-primary/10 rounded-lg cursor-pointer mb-2 border border-primary/20 hover:bg-primary/15 transition-colors"
                        onClick={() => toggleDate(dateKey)}
                      >
                        <Calendar className="h-3.5 w-3.5 text-primary" />
                        <span className="text-xs font-bold text-primary uppercase tracking-widest">{formatDate(date)}</span>
                        <div className="h-px flex-1 bg-primary/20" />
                        <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
                        <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                      </div>
                      {isDateExpanded && (
                        <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                          {Array.from(minerMap.entries()).map(([name, items]) => (
                            <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {resellerGrouped.size > 0 && (() => {
              const isResellerExpanded = expandedResellers[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedResellers(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                    <div className="h-px flex-1 bg-teal-500/20" />
                    <span className="text-[10px] font-bold bg-teal-500/20 text-teal-500 px-2 py-0.5 rounded-md">{resellerGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-500 transition-transform duration-200 ${isResellerExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isResellerExpanded && Array.from(resellerGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {reviewChasingGroups.size > 0 && (() => {
              const isReviewExpanded = expandedReviewChasing[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedReviewChasing(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                    <div className="h-px flex-1 bg-primary/20" />
                    <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{reviewChasingGroups.size}</span>
                    <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isReviewExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isReviewExpanded && (
                    <div className="grid grid-cols-1 gap-3">
                      {Array.from(reviewChasingGroups.entries()).map(([name, items]) => (
                        <ReviewChasingCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} />
                      ))}
                    </div>
                  )}
                </div>
              );
            })()}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Admin Pipeline" subtitle="Active Tasks & Pipeline" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex justify-end mb-4">
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>
      </div>
      <div className="px-4">
        {Object.keys(pageGroups).length > 0
          ? Object.keys(pageGroups).map(page => renderPageSection(page, pageGroups[page]))
          : (
            <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
              <p className="text-sm text-muted-foreground font-medium">No records found matching your search.</p>
            </div>
          )}
      </div>
      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} existingRecords={records} />}
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Loader2, CopyPlus } from 'lucide-react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { toast } from 'sonner';
import { createRecord } from 'zite-endpoints-sdk';
import { MOP_OPTIONS, REGION_OPTIONS } from '@/lib/formatters';
import { calcItemCostAED, calcItemPriceAED } from '@/lib/calculations';
import { setPhpRate as savePhpRate } from '@/lib/phpRateStore';
import { DatabaseRowType } from '@/types';

function generateCustomerId(): string {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let id = 'CUST-';
  for (let i = 0; i < 5; i++) id += chars[Math.floor(Math.random() * chars.length)];
  return id;
}

function resolveCustomerId(minerName: string, existingRecords: DatabaseRowType[]): string {
  const key = minerName.trim().toLowerCase();
  const match = existingRecords.find(r => r.minerName?.trim().toLowerCase() === key && r.customerId);
  return match?.customerId || generateCustomerId();
}

interface Props {
  onClose: () => void;
  userFirstName?: string;
  userEmail?: string;
  onRefresh?: () => void;
  existingRecords?: DatabaseRowType[];
}

const LOCATION_OPTIONS = ['Local', 'Pinas', 'International'];
const CURRENCY_OPTIONS = ['AED', 'PHP', 'USD'];
const STATUS_OPTIONS = ['Pending', 'Waiting for Details', 'Paid/DP but Item Hold', 'Reseller', 'Walk-in', 'In-Store'];
const REMITTANCE_OPTIONS = ['Pending Payment', 'Secured via Courier', 'Secured via Bank Transfer', 'Secured via Cash', 'Secured via Tabby', 'Secured via Tamara'];
const CATEGORY_OPTIONS = ['Normal', 'Special Price', 'Special Price EF', 'Silver', 'Silver Branded', 'VCA', 'Per PC', 'Diamond', 'Other'];
const PAGE_OPTIONS = ['MYK', 'EMPIRE GOLD BY ETG'];
const TOG_OPTIONS = ['S-925', '18K', '21K', '24K'];
const MODE_OF_SALE_OPTIONS = ['Live', 'Outsource', 'Dropshipping', 'In-Store', 'Offline', 'Reseller'];
const SOURCE_OPTIONS = ['MYK SHOP', 'CROWN', 'DG', 'MSET SHOP', 'SATWA OFFICE', 'UMAAR SUPPLIER'];

export default function AddClientModal({ onClose, userFirstName, userEmail, onRefresh, existingRecords = [] }: Props) {
  const [saving, setSaving] = useState(false);
  const [phpRate, setPhpRate] = useState('16.6');
  const [form, setForm] = useState({
    minerName: '',
    itemDescription: '',
    category: '',
    mc: '',
    grams: '',
    clientRate: '',
    goldRate: '',
    orderId: '',
    currency: 'AED',
    modeOfPayment: '',
    modeOfSale: '',
    source: '',
    locationOfMiner: 'Local',
    regions: '',
    status: 'Walk-in',
    remittanceStatus: 'Pending Payment',
    dateOfLive: new Date().toISOString().split('T')[0],
    liverName: userFirstName || '',
    page: '',
    tog: '',
    supplierRateOverride: '',
  });

  const set = (key: string, val: string) => setForm(p => ({ ...p, [key]: val }));

  const isManualSupplierRate = form.category === 'Diamond' || form.category === 'Per PC';
  const autoSupplierRate = useMemo(() => {
    const gr = parseFloat(form.goldRate) || 0;
    const mc = parseFloat(form.mc) || 0;
    return gr > 0 || mc > 0 ? (gr + mc).toFixed(2) : '';
  }, [form.goldRate, form.mc]);
  const supplierRate = isManualSupplierRate ? form.supplierRateOverride : autoSupplierRate;

  const pureWeight = useMemo(() => {
    const g = parseFloat(form.grams) || 0;
    return g > 0 ? Math.max(0, g - 0.05).toFixed(2) : '';
  }, [form.grams]);

  const getPerPcSupplierRate = (tog: string, category: string) => {
    if (category === 'Per PC') {
      if (tog === 'S-925') return '32';
      return '115';
    }
    return '';
  };

  const handleCategoryChange = (val: string) => {
    let newMc = form.mc;
    let newGoldRate = form.goldRate;
    let newSupplierRateOverride = form.supplierRateOverride;

    if (val === 'Normal') newMc = '16';
    else if (val === 'Special Price') newMc = '21';
    else if (val === 'Special Price EF') newMc = '25';
    else if (val === 'Silver' || val === 'Silver Branded') newMc = '0';
    else if (val === 'Diamond') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = '';
    } else if (val === 'Per PC') {
      newMc = '0';
      newGoldRate = '0';
      newSupplierRateOverride = getPerPcSupplierRate(form.tog, val);
    }
    setForm(p => ({ ...p, category: val, mc: newMc, goldRate: newGoldRate, supplierRateOverride: newSupplierRateOverride }));
  };

  const handleTogChange = (val: string) => {
    const updates: Partial<typeof form> = { tog: val };
    if (form.category === 'Per PC') {
      updates.supplierRateOverride = getPerPcSupplierRate(val, 'Per PC');
    }
    setForm(p => ({ ...p, ...updates }));
  };

  // FIX: Added boolean to check if they want to add another item for the same client
  const handleSave = async (isBulkAdd: boolean) => {
    if (!form.minerName.trim() || !form.itemDescription.trim()) {
      toast.error('Client name and item description are required');
      return;
    }
    if (!form.page) {
      toast.error('Page is required');
      return;
    }
    setSaving(true);
    try {
      const preview: DatabaseRowType = {
        id: 0,
        minerName: form.minerName.trim(),
        itemDescription: form.itemDescription.trim(),
        category: form.category,
        mc: form.mc,
        grams: form.grams ? parseFloat(form.grams) : undefined,
        clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
        goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
        supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
        currency: form.currency,
        tog: form.tog || undefined,
      };
      const profit = (calcItemPriceAED(preview) - calcItemCostAED(preview)).toFixed(2);

      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const creator = userEmail ? userEmail.split('@')[0] : (form.liverName || 'unknown');
      const auditTrail = `[Created by ${creator} on ${timestamp}]`;
      const customerId = resolveCustomerId(form.minerName, existingRecords);

      await createRecord({
        fields: {
          minerName: form.minerName.trim(),
          itemDescription: form.itemDescription.trim(),
          category: form.category,
          orderId: form.orderId || undefined,
          mc: form.mc ? parseFloat(form.mc) : undefined,
          grams: form.grams ? parseFloat(form.grams) : undefined,
          clientRate: form.clientRate ? parseFloat(form.clientRate) : undefined,
          goldRate: form.goldRate ? parseFloat(form.goldRate) : undefined,
          supplierRate: (isManualSupplierRate ? form.supplierRateOverride : supplierRate) || undefined,
          pureWeight: pureWeight || undefined,
          currency: form.currency,
          modeOfPayment: form.modeOfPayment || undefined,
          modeOfSale: form.modeOfSale || undefined,
          source: form.source || undefined,
          locationOfMiner: form.locationOfMiner,
          regions: form.regions || undefined,
          status: form.status,
          remittanceStatus: form.remittanceStatus,
          dateOfLive: form.dateOfLive,
          liverName: form.liverName || undefined,
          page: form.page,
          tog: form.tog || undefined,
          reviewChasing: 'Pending',
          profit,
          auditTrail,
          customerId,
        },
      });
      if (isPinas && phpRate) {
        savePhpRate(form.dateOfLive, parseFloat(phpRate));
      }

      toast.success(isBulkAdd ? 'Item added! Ready for next item.' : 'Client record created');
      onRefresh?.();

      if (isBulkAdd) {
        // Only clear the item-specific boxes, leave the client details perfectly intact!
        setForm(p => ({ 
          ...p, 
          itemDescription: '', 
          grams: '', 
          orderId: '', 
          tog: '', 
          category: '', 
          mc: '', 
          goldRate: '', 
          clientRate: '', 
          supplierRateOverride: '' 
        }));
      } else {
        onClose();
      }

    } catch {
      toast.error('Failed to create record');
    } finally {
      setSaving(false);
    }
  };

  const isPinas = form.locationOfMiner === 'Pinas';

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-md bg-card border-border max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary">Add Client Record</DialogTitle>
        </DialogHeader>

        <div className="space-y-3 text-sm">
          <div className="grid grid-cols-2 gap-2">
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Client Name *</Label>
              <Input value={form.minerName} onChange={e => set('minerName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Miner / Client name" />
            </div>
            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Item Description *</Label>
              <Input value={form.itemDescription} onChange={e => set('itemDescription', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="e.g. Gold Ring 18K" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Page *</Label>
              <Select value={form.page} onValueChange={v => set('page', v)}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {PAGE_OPTIONS.map(p => <SelectItem key={p} value={p} className="text-xs">{p}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Liver Name</Label>
              <Input value={form.liverName} onChange={e => set('liverName', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="Liver name" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Category</Label>
              <Select value={form.category} onValueChange={handleCategoryChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {CATEGORY_OPTIONS.map(c => <SelectItem key={c} value={c} className="text-xs">{c}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">T.O.G</Label>
              <Select value={form.tog} onValueChange={handleTogChange}>
                <SelectTrigger className="h-8 text-xs mt-0.5 bg-background border-border"><SelectValue placeholder="Select..." /></SelectTrigger>
                <SelectContent className="bg-popover border-border">
                  {TOG_OPTIONS.map(t => <SelectItem key={t} value={t} className="text-xs">{t}</SelectItem>)}
                </SelectContent>
              </Select>
            </div>

            <div className="col-span-2">
              <Label className="text-xs text-muted-foreground">Order ID / Barcode</Label>
              <Input value={form.orderId} onChange={e => set('orderId', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="e.g. AM-SL-030909" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Grams (0 = PC)</Label>
              <Input type="number" value={form.grams} onChange={e => set('grams', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Pure Wt <span className="text-primary/60">(Grams − 0.05, auto)</span></Label>
              <Input value={pureWeight} readOnly className="h-8 text-xs mt-0.5 bg-muted border-border opacity-70 cursor-not-allowed" placeholder="Auto" />
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">MC (Making Charge)</Label>
              <Input type="number" value={form.mc} onChange={e => set('mc', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Gold Rate</Label>
              <Input type="number" value={form.goldRate} onChange={e => set('goldRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">Client Rate</Label>
              <Input type="number" value={form.clientRate} onChange={e => set('clientRate', e.target.value)} className="h-8 text-xs mt-0.5 bg-background border-border" placeholder="0.00" />
            </div>
            <div>
              <Label className="text-xs text-muted-foreground">
                Supplier Rate{' '}
                {!isManualSupplierRate && <span className="text-primary/60">(auto)</span>}
                {form.category === 'Diamond' && <span className="text-yellow-400">(manual)</span>}
                {form.category === 'Per PC' && <span className="text-primary/60">(preset)</span>}
              </Label>
              {isManualSupplierRate ? (
                <Input
                  type="number"
                  value={form.supplierRateOverride}
                  onChange={e => set('supplierRateOverride', e.target.value)}
                  className="h-8 text-xs mt-0.5 bg-background border-border"
                  placeholder={form.category === 'Diamond' ? 'Enter supplier rate' : '115'}
                />
              ) : (
                <Input value={supplierRate} readOnly className="h-8 text-xs mt-0.5 bg-muted border-border opacity-70 cursor-not-allowed" placeholder="Auto-calculated" />
              )}
            </div>

            <div>
              <Label className="text-xs text-muted-foreground">Currency</Label>
