import { useRef, useState, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, MessageSquare } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust, calcItemPriceAED, calcShippingFee, calcCCFee, calcTotalPaid } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);

  const activeRecords = useMemo(() => {
    const excludedStatuses = ['Cancelled', 'Delivered', 'Dispatched', 'Returned Item'];
    return records
      .filter(r => {
        const status = r.status || '';
        return !excludedStatuses.includes(status);
      })
      .sort((a, b) => {
        const dateA = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
        const dateB = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
        return dateA - dateB;
      });
  }, [records]);

  const baseRecord = activeRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleMetaShare = async () => {
    if (activeRecords.length === 0) return;

    const clientName = baseRecord.minerName || 'Client';
    const totalItems = activeRecords.length;

    // Calculate raw AED totals
    const subtotalAED = activeRecords.reduce((sum, r) => sum + calcItemPriceAED(r), 0);
    const shippingAED = calcShippingFee(baseRecord);
    const additionalAED = parseFloat(String(baseRecord.additionalCharges || 0));
    const ccFeeAED = calcCCFee(baseRecord);
    const totalAED = subtotalAED + shippingAED + additionalAED + ccFeeAED;
    const totalPaidAED = records.reduce((s, r) => s + calcTotalPaid(r), 0);
    const balanceAED = Math.max(0, totalAED - totalPaidAED);

    // Build the message
    let message = `*Statement of Account*\n`;
    message += `MYKabayan Jewellery\n\n`;
    message += `Hello ${clientName.toUpperCase()},\n`;
    message += `Here is the summary of your active items:\n\n`;

    activeRecords.forEach(r => {
      const desc = r.itemDescription || 'Item';
      const price = calcItemPriceAED(r).toFixed(2);
      message += `- ${desc}: AED ${price}\n`;
    });

    message += `\n*Total Items:* ${totalItems}\n`;
    message += `*Subtotal:* AED ${subtotalAED.toFixed(2)}\n`;

    if (shippingAED > 0) message += `*Shipping:* AED ${shippingAED.toFixed(2)}\n`;
    if (additionalAED > 0) message += `*Additional Fees:* AED ${additionalAED.toFixed(2)}\n`;

    message += `*Total Invoice:* AED ${totalAED.toFixed(2)}\n`;

    if (totalPaidAED > 0) {
      message += `*Total Paid:* -AED ${totalPaidAED.toFixed(2)}\n`;
      message += `*REMAINING BALANCE:* AED ${balanceAED.toFixed(2)}\n`;
    }

    message += `\nThank you for choosing MYKabayan Jewellery!`;

    try {
      await navigator.clipboard.writeText(message);
      toast.success("Invoice copied! Open Meta Business Suite to paste.");
      window.open('https://business.facebook.com/latest/inbox/', '_blank');
    } catch (err) {
      toast.error("Failed to copy to clipboard.");
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0">
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex items-center justify-between gap-4">
            <DialogTitle className="text-base font-bold text-foreground">
              Statement of Account (Active)
            </DialogTitle>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger className="h-8 w-24 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CURRENCIES.map(c => (
                      <SelectItem key={c} value={c}>{c}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {/* Meta Business Suite Button */}
              <Button 
                onClick={handleMetaShare} 
                size="sm" 
                variant="outline" 
                className="h-8 border-blue-600 text-blue-700 hover:bg-blue-50" 
                disabled={activeRecords.length === 0}
              >
                <MessageSquare className="h-3.5 w-3.5 mr-1.5" /> Share via Meta
              </Button>

              <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={activeRecords.length === 0}>
                <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
              </Button>
            </div>
          </div>
        </DialogHeader>

        {activeRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Active Items</p>
            <p className="text-xs">This client's items have all been Delivered, Dispatched, or Cancelled.</p>
          </div>
        )}

        {activeRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4">
              <InvoicePrintContent records={activeRecords} currency={currency} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

