import { useState, useMemo } from 'react';
import { Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DatabaseRowType, TabProps } from '@/types';
import { applySearch } from '@/lib/formatters';
import ClientCard from './ClientCard';
import AddClientModal from './AddClientModal';
import TabHeader from '@/components/TabHeader';

export default function AccountsTracker({ records, searchQuery, onSearchChange }: TabProps) {
  const [showAdd, setShowAdd] = useState(false);
  const [statusFilter, setStatusFilter] = useState('Active');

  // 1. FIXED FILTERING LOGIC
  const filteredRecords = useMemo(() => {
    let base = applySearch(records, searchQuery);

    if (statusFilter === 'Active') {
      // EXCLUSION LIST: Hides only the dead statuses so ALL active, walk-in, and old blank items show up!
      const deadStatuses = ['Cancelled', 'Delivered', 'Dispatched', 'Returned Item'];
      base = base.filter(r => {
        const s = (r.status || '').trim();
        return !deadStatuses.includes(s);
      });
    } else if (statusFilter === 'Completed') {
      const completedStatuses = ['Delivered', 'Dispatched'];
      base = base.filter(r => completedStatuses.includes((r.status || '').trim()));
    } else if (statusFilter === 'Cancelled') {
      const cancelledStatuses = ['Cancelled', 'Returned Item'];
      base = base.filter(r => cancelledStatuses.includes((r.status || '').trim()));
    }

    return base;
  }, [records, searchQuery, statusFilter]);

  // 2. FIXED GROUPING LOGIC
  const groupedClients = useMemo(() => {
    const groups = new Map<string, DatabaseRowType[]>();

    filteredRecords.forEach(record => {
      // Safe fallback to Miner Name just in case older records don't have a CUST- ID yet
      const key = record.customerId || (record.minerName || 'UNKNOWN').trim().toUpperCase();
      if (!groups.has(key)) {
        groups.set(key, []);
      }
      groups.get(key)!.push(record);
    });

    // Sort groups so the clients with the newest items appear at the top
    return Array.from(groups.entries()).sort((a, b) => {
      const aLatest = Math.max(...a[1].map(r => new Date(r.dateOfLive || 0).getTime()));
      const bLatest = Math.max(...b[1].map(r => new Date(r.dateOfLive || 0).getTime()));
      return bLatest - aLatest;
    });
  }, [filteredRecords]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader 
        title="Accounts Tracker" 
        subtitle="Manage clients and financials" 
        searchQuery={searchQuery} 
        onSearchChange={onSearchChange} 
      />

      <div className="px-4 pt-4">
        <div className="flex items-center justify-between mb-4">
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[160px] h-9 text-xs bg-card border-border">
              <SelectValue />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="Active" className="text-xs">Active Clients</SelectItem>
              <SelectItem value="Completed" className="text-xs">Completed</SelectItem>
              <SelectItem value="Cancelled" className="text-xs">Cancelled</SelectItem>
              <SelectItem value="All" className="text-xs">All Records</SelectItem>
            </SelectContent>
          </Select>

          <Button onClick={() => setShowAdd(true)} size="sm" className="h-9 bg-primary text-primary-foreground text-xs">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>

        <div className="space-y-3">
          {groupedClients.map(([key, clientRecords]) => (
            <ClientCard key={key} records={clientRecords} />
          ))}

          {groupedClients.length === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No clients found matching the criteria.</p>
            </div>
          )}
        </div>
      </div>

      {showAdd && (
        <AddClientModal 
          onClose={() => setShowAdd(false)} 
          existingRecords={records}
        />
      )}
    </div>
  );
}

