import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';
import { getSilverRateForDate, getSilverBrandedRateForDate, getPhpRate } from '@/lib/ratesStore';

const n = (v: unknown): number => {
  if (typeof v === 'number') return v;
  if (!v) return 0;
  const s = String(v).replace(/,/g, '').trim();
  const parsed = Number(s);
  return isNaN(parsed) ? 0 : parsed;
};

export function roundPrice(v: number): number { return Math.round(v); }

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;
  const iso = parseISO(dateStr);
  if (isValid(iso)) return iso;
  const native = new Date(dateStr);
  if (!isNaN(native.getTime())) return native;
  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(dateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return String(record.freeSf).toLowerCase() === 'true';
}

function normCurrency(currency?: string): string {
  return (currency || '').toUpperCase().trim();
}

export function getEffectiveCurrency(record: DatabaseRowType): string {
  const curr = normCurrency(record.currency);
  if (!curr && normCurrency(record.locationOfMiner) === 'PINAS') return 'PHP';
  return curr || 'AED';
}

// 1. PERFECT AED CONVERTER (Respects Custom PHP Rate!)
export function toAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value * 3.75;
  if (curr === 'PHP') {
    // Dynamically uses your custom rate instead of hardcoded 16.6
    const rate = record?.dateOfLive ? getPhpRate(record.dateOfLive) || 16.7 : 16.7;
    return value / rate;
  }
  return value;
}

// 2. PERFECT NATIVE CONVERTER (Respects Custom PHP Rate!)
export function fromAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value / 3.75;
  if (curr === 'PHP') {
    // Dynamically uses your custom rate instead of hardcoded 16.6
    const rate = record?.dateOfLive ? getPhpRate(record.dateOfLive) || 16.7 : 16.7;
    return value * rate;
  }
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  return toAED(rate, record);
}

export function getQty(record: DatabaseRowType): number {
  const parsedQty = n(record.qty);
  if (parsedQty > 0) return parsedQty;
  const desc = (record.itemDescription || '').toUpperCase();
  const match = desc.match(/(?:^|\s)(\d+)\s*PCS?\b/);
  if (match) return parseInt(match[1], 10);
  return 1;
}

export const SILVER_RATE = 45;
export const SILVER_BRANDED_RATE = 60;

export function getSilverRate(category: string, record?: DatabaseRowType): number | null {
  const cat = (category || '').toLowerCase();
  const date = record?.dateOfLive;
  if (cat.includes('silver branded')) {
    const custom = date ? getSilverBrandedRateForDate(date) : null;
    return custom ?? SILVER_BRANDED_RATE;
  }
  if (cat.includes('silver')) {
    const custom = date ? getSilverRateForDate(date) : null;
    return custom ?? SILVER_RATE;
  }
  return null;
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (clientRate > 0) return roundPrice(n(record.grams) * clientRate);
    return roundPrice(fromAED(n(record.grams) * silverRate, record));
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(clientRate * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRate);
  const price = roundPrice(n(record.grams) * clientRate);
  return price > 0 ? price : (clientRate > 0 ? roundPrice(clientRate) : 0);
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const rateAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (n(record.clientRate) > 0) return roundPrice(n(record.grams) * rateAED);
    return roundPrice(n(record.grams) * silverRate);
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(rateAED * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(rateAED);
  const price = roundPrice(n(record.grams) * rateAED);
  return price > 0 ? price : (rateAED > 0 ? roundPrice(rateAED) : 0);
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);

  if (category.includes('diamond')) return roundPrice(supplierRate * getQty(record));

  if (category.includes('per pc') || category.includes('screw type')) {
    let rate = supplierRate > 0 ? supplierRate : goldRate > 0 ? goldRate : 115;
    if (rate === 115 && (desc.includes('buy 1 take 1') || desc.includes('b1t1'))) rate *= 2;
    return roundPrice(rate * getQty(record));
  }

  if (category.includes('silver branded')) return roundPrice(32 * grams);
  if (category.includes('silver')) return roundPrice(15 * grams);

  if (goldRate > 0) {
    const effectiveMc = mc > 0 ? mc : category.includes('special price ef') ? 25 : category.includes('special price') ? 21 : 16;
    if (isPcItem(record)) return roundPrice(goldRate + effectiveMc);
    return roundPrice((goldRate + effectiveMc) * grams);
  }

  if (supplierRate > 0) {
    if (isPcItem(record)) return roundPrice(supplierRate);
    return roundPrice(supplierRate * grams);
  }

  return 0;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const grams = n(record.grams);
  const isSilver = getSilverRate(category, record) !== null;
  const isPerPcType = category.includes('per pc') || category.includes('screw type') || category.includes('diamond');

  if (!isSilver && !isPerPcType && grams > 0) {
    const goldRate = n(record.goldRate);
    const supplierRate = n(record.supplierRate);
    if (goldRate === 0 && supplierRate === 0) return 0;
  }

  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  return roundPrice(totalSales - totalCost);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  const loc = normCurrency(record.locationOfMiner);
  if (loc === 'LOCAL') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30;
    return 30; 
  }

  if (loc === 'INTERNATIONAL' || loc === 'PINAS') return 299;
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  if (record.modeOfPayment !== 'Credit Card') return 0;
  const basePrice = calcItemPriceAED(record);
  return roundPrice(basePrice * 0.05);
}

export function calcTotalPaid(record: DatabaseRowType): number {
  const raw = n(record.downpayment) + n(record.la1MonthPayment) + n(record.la2MonthPayment) + n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
  return toAED(raw, record);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = calcItemPriceAED(record);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return roundPrice((itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid);
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details' && record.status !== 'Waiting for Downpayment') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

import { DatabaseRowType } from '@/types';
import { calcShippingFee, calcCCFee, clientRateAED, isPcItem, getQty, getSilverRate, calcTotalPaid } from '@/lib/calculations';
import { getPhpRate } from '@/lib/phpRateStore'; 
import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';

const NOTES = [
  'We can hold unpaid items for a maximum of 3 days from the invoice date.',
  'Failure to settle within 3 days may result in additional charges.',
  'Unpaid items will be automatically cancelled after the grace period without prior notice.',
  'All items undergo strict quality checking before dispatch.',
  'An unboxing video is strictly required. No video, no refund, no exchange.',
  'No cash refund. Store credit only.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;
const rnd = (v: number) => Math.round(v);

export default function InvoicePrintContent({ records, currency }: Props) {
  const first = records[0];

  const phpRate = getPhpRate(first?.dateOfLive || '') || 16.7;
  const convertFromAED = (aedValue: number): number => {
    if (currency === 'PHP') return aedValue * phpRate;
    if (currency === 'USD') return aedValue / 3.75;
    return aedValue; 
  };

  const fmtAmt = (v: number) =>
    `${currency} ${rnd(v).toLocaleString('en-US')}`;

  const items = records.map(r => {
    const category = (r.category || '').toLowerCase();
    const isScrewType = category.includes('screw type');
    const isPerPc = category.includes('per pc');
    const isSilver = getSilverRate(category) !== null;
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = getQty(r);

    let aedRate: number;
    if (isSilver && n(r.clientRate) > 0) {
      aedRate = clientRateAED(r);
    } else if (isSilver) {
      aedRate = getSilverRate(category)!;
    } else {
      aedRate = clientRateAED(r);
    }
    const displayRate = rnd(convertFromAED(aedRate));

    let amount: number;
    if (!isSilver && (isScrewType || isPerPc)) {
      amount = rnd(displayRate * qtyValue);
    } else if (!isSilver && (isPc || gramsValue === 0)) {
      amount = displayRate;
    } else {
      amount = rnd(displayRate * gramsValue);
    }

    let gramsDisplay = '';
    if (!isSilver && (isScrewType || isPerPc)) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = (!isSilver && (isPc || gramsValue === 0)) ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: !isSilver && (isPc || isScrewType || isPerPc),
      rate: displayRate,
      amount,
      liver: r.liverName?.trim() || '',
      date: formatDate(r.dateOfLive) 
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  const shippingAED = first ? calcShippingFee(first) : 0;
  const shipping = convertFromAED(shippingAED);
  const additionalAED = n(first?.additionalCharges);
  const additional = convertFromAED(additionalAED);
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const ccFee = convertFromAED(ccFeeAED);
  const total = subtotal + shipping + additional + ccFee;

  const totalPaidAED = records.reduce((s, r) => s + calcTotalPaid(r), 0);
  const totalPaidConverted = convertFromAED(totalPaidAED);
  const balanceDue = total - totalPaidConverted;

  const totalGrams = records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('diamond')) return s;
    return s + n(r.grams);
  }, 0);

  const amountForWords = Math.max(0, totalPaidConverted > 0 ? balanceDue : total);
  const amountInWords = numberToWords(amountForWords, currency);

  const mopLabel = (() => {
    const mop = (first?.modeOfPayment || '').toLowerCase();
    if (mop === 'layaway') return 'LAYAWAY';
    if (mop === 'tabby') return 'TABBY';
    if (mop === 'tamara') return 'TAMARA';
    return null;
  })();

  const invoiceDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const invoiceNo = records.map(r => r.pureWeight).find(Boolean);

  const summaryRows: { label: string; value: string; red?: boolean }[] = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
    ...(totalPaidConverted > 0 ? [
      { label: 'TOTAL PAID', value: `- ${fmtAmt(totalPaidConverted)}`, red: true },
      { label: 'BALANCE DUE', value: fmtAmt(balanceDue), red: true },
    ] : []),
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ position: 'relative', fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>

      {/* ANTI-TAMPER SECURITY WATERMARK */}
      <div style={{
        position: 'absolute',
        top: '40%',
        left: '50%',
        transform: 'translate(-50%, -50%) rotate(-35deg)',
        fontSize: '65px',
        color: 'rgba(150, 150, 150, 0.12)',
        fontWeight: 900,
        whiteSpace: 'nowrap',
        pointerEvents: 'none',
        zIndex: 0,
        userSelect: 'none',
        textAlign: 'center'
      }}>
        MYKABAYAN OFFICIAL<br/>
        {invoiceNo || ''}
      </div>

      <div style={{ position: 'relative', zIndex: 1 }}>
        <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0, background: '#fff' }}>
          <em style={{ fontSize: 14 }}>Statement of Account</em>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '65%', padding: '12px 16px', verticalAlign: 'top', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 24, letterSpacing: 1 }}>MYKABAYAN JEWELLERY</div>
                <div style={{ marginTop: 8, textAlign: 'left', fontSize: 11 }}>SATWA, DUBAI, UNITED ARAB EMIRATES</div>
                <div style={{ marginTop: 4, fontSize: 11 }}>WhatsApp &amp; Contact no.: +971 52 825 2405</div>
              </td>
              <td style={{ width: '35%', padding: '12px 16px', verticalAlign: 'middle', textAlign: 'center', border: '1px solid #999' }}>
                <img src={LOGO_URL} crossOrigin="anonymous" alt="Logo" style={{ width: '80px', height: '80px', objectFit: 'contain', display: 'block', margin: '0 auto' }} />
              </td>
            </tr>
            <tr>
              <td style={{ padding: '10px 16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 700, fontSize: 20, textAlign: 'center', letterSpacing: 1 }}>
                  {(first?.minerName || '').toUpperCase()}
                </div>
              </td>
              <td style={{ padding: '8px', textAlign: 'center', border: '1px solid #999' }}>
                <div style={{ fontWeight: 600, fontSize: 13 }}>{invoiceDate}</div>
                <div style={{ fontSize: 11, marginTop: 4 }}>Date Printed</div>
                {invoiceNo && (
                  <div style={{ marginTop: 8, borderTop: '1px solid #ccc', paddingTop: 6 }}>
                    <div style={{ fontWeight: 700, fontSize: 13, fontFamily: 'monospace', color: '#c00' }}>{invoiceNo}</div>
                    <div style={{ fontSize: 10, color: '#666', marginTop: 2 }}>Account ID / Invoice #</div>
                  </div>
                )}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <thead>
            <tr style={{ background: 'rgba(224, 224, 224, 0.9)' }}>
              {['Date', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
                <th key={h} style={{ border: '1px solid #999', padding: '6px 8px', textAlign: 'center', fontSize: 11 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => (
              <tr key={i}>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#666' }}>{item.date}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, fontWeight: 600 }}>
                  {item.desc.toUpperCase()}
                  {item.liver && <div style={{ fontSize: 9, fontWeight: 400, color: '#888', marginTop: 2 }}>Liver: {item.liver}</div>}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.tog.toUpperCase()}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: item.isPc ? 'red' : '#111', fontWeight: item.isPc ? 700 : 400 }}>
                  {item.gramsDisplay}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.rate.toLocaleString('en-US')}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'right', fontSize: 11 }}>{fmtAmt(item.amount)}</td>
              </tr>
            ))}
            {Array.from({ length: emptyRows }).map((_, i) => (
              <tr key={`empty-${i}`} style={{ height: 22 }}>
                {[1,2,3,4,5,6].map(c => <td key={c} style={{ border: '1px solid #999' }}>&nbsp;</td>)}
              </tr>
            ))}
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '50%', padding: '16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 26, lineHeight: 1.2, textAlign: 'center' }}>
                  CUSTOMER'S INVOICE<br />COPY
                </div>
                {mopLabel && (
                  <div style={{ marginTop: '8px', textAlign: 'center' }}>
                    <div style={{ display: 'inline-block', border: '2px solid red', color: 'red', padding: '4px 12px', fontWeight: 900, fontSize: '18px', letterSpacing: '2px', textTransform: 'uppercase' }}>
                      {mopLabel}
                    </div>
                  </div>
                )}
              </td>
              <td style={{ padding: 0, verticalAlign: 'top', border: '1px solid #999' }}>
                {summaryRows.map((row, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', background: row.red ? 'rgba(255, 240, 240, 0.9)' : (i % 2 === 0 ? 'rgba(224, 224, 224, 0.9)' : 'rgba(245, 245, 245, 0.9)'), padding: '5px 10px', borderBottom: '1px solid #ccc' }}>
                    <span style={{ fontWeight: 700, fontSize: 11, color: row.red ? '#cc0000' : '#111' }}>{row.label}</span>
                    <span style={{ fontSize: 11, fontWeight: row.red ? 700 : 400, color: row.red ? '#cc0000' : '#111' }}>{row.value}</span>
                  </div>
                ))}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ padding: '4px 12px', border: '1px solid #999', borderBottom: 'none' }}>
                <span style={{ color: 'red', fontWeight: 700, fontSize: 11 }}>Amount in Words:</span>
              </td>
            </tr>
            <tr>
              <td style={{ padding: '4px 12px 10px', textAlign: 'center', fontWeight: 700, fontSize: 13, border: '1px solid #999' }}>
                {amountInWords}
              </td>
            </tr>
          </tbody>
        </table>

        <div style={{ padding: '8px 12px', border: '1px solid #999', marginTop: -1, background: '#fff' }}>
          <div style={{ color: 'red', fontWeight: 700, fontSize: 12, marginBottom: 4 }}>NOTE:</div>
          {NOTES.map((note, i) => (
            <div key={i} style={{ fontSize: 10, marginBottom: 2 }}>{i + 1}. {note}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

