import { Search, X } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { useState, useEffect } from 'react';

interface Props {
  title: string;
  subtitle?: string;
  searchQuery: string;
  onSearchChange: (q: string) => void;
}

export default function TabHeader({ title, subtitle, searchQuery, onSearchChange }: Props) {
  // Local state to hold the text while the user is actively typing
  const [localQuery, setLocalQuery] = useState(searchQuery);

  // DEBOUNCE LOGIC: Waits 300ms after the user stops typing before telling the app to search
  useEffect(() => {
    const timer = setTimeout(() => {
      onSearchChange(localQuery);
    }, 300);
    return () => clearTimeout(timer);
  }, [localQuery, onSearchChange]);

  // If the search is cleared externally (like switching tabs), reset the local box
  useEffect(() => {
    if (searchQuery === '') setLocalQuery('');
  }, [searchQuery]);

  return (
    <div className="sticky top-0 z-20 bg-background/95 backdrop-blur supports-[backdrop-filter]:bg-background/80 border-b border-border pb-4 pt-4 px-4">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-cinzel font-bold text-primary">{title}</h1>
          {subtitle && <p className="text-xs text-muted-foreground mt-1 uppercase tracking-wider">{subtitle}</p>}
        </div>

        <div className="relative w-full md:w-72">
          <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search clients, items, or IDs..."
            value={localQuery}
            onChange={(e) => setLocalQuery(e.target.value)}
            className="pl-9 pr-9 h-9 text-xs bg-card border-border focus-visible:ring-primary/50 transition-all"
          />

          {/* CLEAR FILTERS BUTTON */}
          {localQuery && (
            <button
              onClick={() => { setLocalQuery(''); onSearchChange(''); }}
              className="absolute right-2.5 top-2.5 text-muted-foreground hover:text-destructive transition-colors"
              title="Clear search"
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

