/**
 * Rates store — persisted in localStorage, keyed by dateOfLive.
 * Stores: phpRate, silverRate, silverBrandedRate
 */

function load(key: string): Record<string, number> {
  try { return JSON.parse(localStorage.getItem(key) || '{}'); } catch { return {}; }
}
function save(key: string, data: Record<string, number>) {
  localStorage.setItem(key, JSON.stringify(data));
}

// ── PHP Rate ──────────────────────────────────────────────────
const PHP_KEY = 'phpRates_v1';
export function getPhpRate(date: string): number | null { return load(PHP_KEY)[date] ?? null; }
export function setPhpRate(date: string, rate: number) { const r = load(PHP_KEY); r[date] = rate; save(PHP_KEY, r); }
export function hasPhpRate(date: string): boolean { return getPhpRate(date) !== null; }

// ── Silver Rate ───────────────────────────────────────────────
const SILVER_KEY = 'silverRates_v1';
export function getSilverRateForDate(date: string): number | null { return load(SILVER_KEY)[date] ?? null; }
export function setSilverRate(date: string, rate: number) { const r = load(SILVER_KEY); r[date] = rate; save(SILVER_KEY, r); }

// ── Silver Branded Rate ───────────────────────────────────────
const SILVER_BRANDED_KEY = 'silverBrandedRates_v1';
export function getSilverBrandedRateForDate(date: string): number | null { return load(SILVER_BRANDED_KEY)[date] ?? null; }
export function setSilverBrandedRate(date: string, rate: number) { const r = load(SILVER_BRANDED_KEY); r[date] = rate; save(SILVER_BRANDED_KEY, r); }

// Strict Global Fallback Baseline
const GLOBAL_DEFAULT_PHP_RATE = 16.7;

/**
 * Saves a specific exchange rate for a specific live date.
 */
export function setPhpRate(dateOfLive: string, rate: number) {
  if (!dateOfLive || isNaN(rate) || rate <= 0) return;
  try {
    const key = `phpRate_${dateOfLive}`;
    localStorage.setItem(key, rate.toString());
  } catch (e) {
    console.error('Failed to save PHP rate:', e);
  }
}

/**
 * Retrieves the specific exchange rate for a live date.
 * If none was specifically set by the admin on that computer, it strictly defaults to 16.7
 */
export function getPhpRate(dateOfLive: string): number {
  if (!dateOfLive) return GLOBAL_DEFAULT_PHP_RATE;
  try {
    const key = `phpRate_${dateOfLive}`;
    const stored = localStorage.getItem(key);
    if (stored) {
      const parsed = parseFloat(stored);
      if (!isNaN(parsed) && parsed > 0) return parsed;
    }
  } catch (e) {
    console.error('Failed to read PHP rate:', e);
  }

  // Enforces the Master Anchor fallback
  return GLOBAL_DEFAULT_PHP_RATE;
}

import { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { formatDate } from '@/lib/formatters';

interface Props {
  date: string;
  onConfirm: (phpRate: number, silverRate?: number, silverBrandedRate?: number) => void;
  onSkip: () => void;
}

export default function PhpRateDialog({ date, onConfirm, onSkip }: Props) {
  const [phpRate, setPhpRateVal] = useState('');
  const [silverRate, setSilverRateVal] = useState('');
  const [silverBrandedRate, setSilverBrandedRateVal] = useState('');

  const phpParsed = parseFloat(phpRate);
  const isValid = !isNaN(phpParsed) && phpParsed > 0;

  const handleConfirm = () => {
    if (!isValid) return;
    const sr = parseFloat(silverRate);
    const sbr = parseFloat(silverBrandedRate);
    onConfirm(phpParsed, isNaN(sr) ? undefined : sr, isNaN(sbr) ? undefined : sbr);
  };

  return (
    <Dialog open onOpenChange={onSkip}>
      <DialogContent className="bg-card border-border max-w-sm">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary text-base">
            Set Rates for {formatDate(date)}
          </DialogTitle>
        </DialogHeader>
        <div className="py-2 space-y-4">
          <p className="text-xs text-muted-foreground">
            Pinas client detected. Set today's rates — these will be locked for all clients on this date.
          </p>

          <div>
            <Label className="text-xs text-muted-foreground">PHP Conversion Rate (1 AED =)</Label>
            <div className="flex items-center gap-2 mt-1">
              <Input type="number" step="0.01" value={phpRate} onChange={e => setPhpRateVal(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleConfirm()}
                placeholder="e.g. 16.80" className="h-9 text-sm bg-background border-border" autoFocus />
              <span className="text-sm font-semibold shrink-0">PHP</span>
            </div>
          </div>

          <div>
            <Label className="text-xs text-muted-foreground">Silver Rate (AED/gram) — optional</Label>
            <div className="flex items-center gap-2 mt-1">
              <Input type="number" step="0.5" value={silverRate} onChange={e => setSilverRateVal(e.target.value)}
                placeholder={`default: 45`} className="h-9 text-sm bg-background border-border" />
              <span className="text-sm font-semibold shrink-0">AED</span>
            </div>
          </div>

          <div>
            <Label className="text-xs text-muted-foreground">Silver Branded Rate (AED/gram) — optional</Label>
            <div className="flex items-center gap-2 mt-1">
              <Input type="number" step="0.5" value={silverBrandedRate} onChange={e => setSilverBrandedRateVal(e.target.value)}
                placeholder={`default: 60`} className="h-9 text-sm bg-background border-border" />
              <span className="text-sm font-semibold shrink-0">AED</span>
            </div>
          </div>
        </div>
        <DialogFooter className="gap-2">
          <Button variant="outline" size="sm" className="text-xs border-border" onClick={onSkip}>Skip</Button>
          <Button size="sm" className="text-xs bg-primary text-primary-foreground" disabled={!isValid} onClick={handleConfirm}>
            Lock Rates
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

