export function getPhpRate(date: string): number {
  return load(PHP_KEY)[date] ?? DEFAULT_PHP_RATE;
}
export function setPhpRate(date: string, rate: number) {
  const r = load(PHP_KEY); r[date] = rate; save(PHP_KEY, r);
}
export function hasPhpRate(date: string): boolean {
  return load(PHP_KEY)[date] !== undefined;
}

