import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType, Roles } from 'zite-integrations-backend-sdk';

const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "roseannaranez2@gmail.com"
];

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
  'auditTrail', 'tog', 'pureWeight', 'qty', 'customerId',
]);

const ZERO_PROFIT_STATUSES = new Set(['cancelled', 'returned item']);

// Strip commas before parsing — prevents "1,500" → 1
const n = (val: any): number => {
  const cleaned = String(val ?? '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
};

interface RateConfig {
  phpRate: number;
  silverSellRate: number;
  silverBrandedSellRate: number;
  silverCostRate: number;
  silverBrandedCostRate: number;
}

function calculateServerProfit(fields: any, rates: RateConfig): string {
  // Ghost Profit prevention: zero out cancelled/returned items
  const status = String(fields.status || '').toLowerCase().trim();
  if (ZERO_PROFIT_STATUSES.has(status)) return '0.00';

  const grams = n(fields.grams);
  const clientRate = n(fields.clientRate);
  const category = String(fields.category || '').toLowerCase();
  const currency = String(fields.currency || 'AED').toUpperCase();
  const qty = n(fields.qty) || 1;

  let rateAED = clientRate;
  if (currency === 'PHP') rateAED = clientRate / rates.phpRate;
  else if (currency === 'USD') rateAED = clientRate * 3.67;

  let totalSales = 0;
  let totalCost = 0;

  if (category.includes('screw type') || category.includes('per pc')) {
    totalSales = rateAED * qty;
    let sr = n(fields.supplierRate) > 0 ? n(fields.supplierRate) : (n(fields.goldRate) > 0 ? n(fields.goldRate) : 115);
    if (sr === 115 && String(fields.itemDescription || '').toUpperCase().includes('B1T1')) sr *= 2;
    totalCost = sr * qty;
  } else if (category.includes('silver branded')) {
    // Smart Snap: snap to the daily sell rate anchor if within ±2 AED
    const anchor = rates.silverBrandedSellRate;
    if (rateAED > 0 && Math.abs(rateAED - anchor) <= 2) rateAED = anchor;
    totalSales = (clientRate > 0 ? rateAED : anchor) * grams;
    totalCost = rates.silverBrandedCostRate * grams;  // daily supplier cost
  } else if (category.includes('silver')) {
    // Smart Snap: snap to the daily sell rate anchor if within ±2 AED
    const anchor = rates.silverSellRate;
    if (rateAED > 0 && Math.abs(rateAED - anchor) <= 2) rateAED = anchor;
    totalSales = (clientRate > 0 ? rateAED : anchor) * grams;
    totalCost = rates.silverCostRate * grams;  // daily supplier cost
  } else if (category.includes('diamond')) {
    totalSales = rateAED * qty;
    totalCost = n(fields.supplierRate) * qty;
  } else {
    totalSales = rateAED * grams;
    const gr = n(fields.goldRate);
    const sr = n(fields.supplierRate);
    if (gr > 0) {
      let mc = n(fields.mc);
      if (mc <= 0) {
        if (category.includes('special price ef')) mc = 25;
        else if (category.includes('special price')) mc = 21;
        else mc = 16;
      }
      totalCost = (gr + mc) * grams;
    } else if (sr > 0) {
      totalCost = sr * grams;
    }
  }
  return Math.round(totalSales - totalCost).toFixed(2);
}

export default createEndpoint({
  description: 'Create a new Database row securely',
  authenticated: true,
  inputSchema: z.object({
    fields: z.record(z.unknown()),
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    const sanitized: Partial<DatabaseRowType> = {};
    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? 'TRUE' : 'FALSE';
      } else if (key === 'profit') {
        continue; // Always recalculate server-side
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
      }
    }

    (sanitized as Record<string, unknown>).profit = Number(
      calculateServerProfit(sanitized, {
        phpRate: input.phpRate,
        silverSellRate: input.silverSellRate,
        silverBrandedSellRate: input.silverBrandedSellRate,
        silverCostRate: input.silverCostRate,
        silverBrandedCostRate: input.silverBrandedCostRate,
      })
    );

    await Database.create({ row: sanitized });
    return { success: true };
  },
});

