import { useState, useEffect } from 'react';
import { ChevronDown, Settings2, Check } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import {
  getPhpRate, setPhpRate,
  getSilverSellRate, setSilverSellRate,
  getSilverBrandedSellRate, setSilverBrandedSellRate,
  getSilverCostRate, setSilverCostRate,
  getSilverBrandedCostRate, setSilverBrandedCostRate,
  DEFAULT_PHP_RATE,
  DEFAULT_SILVER_SELL_RATE,
  DEFAULT_SILVER_BRANDED_SELL_RATE,
  DEFAULT_SILVER_COST_RATE,
  DEFAULT_SILVER_BRANDED_COST_RATE,
} from '@/lib/ratesStore';

interface Props {
  date: string; // yyyy-mm-dd
}

export default function DailyRatesEditor({ date }: Props) {
  const [open, setOpen] = useState(false);

  const [phpRate, setPhpRateVal] = useState('');
  const [silverSell, setSilverSellVal] = useState('');
  const [silverBrandedSell, setSilverBrandedSellVal] = useState('');
  const [silverCost, setSilverCostVal] = useState('');
  const [silverBrandedCost, setSilverBrandedCostVal] = useState('');

  // Load stored values whenever date or panel opens
  useEffect(() => {
    setPhpRateVal(String(getPhpRate(date)));
    setSilverSellVal(String(getSilverSellRate(date)));
    setSilverBrandedSellVal(String(getSilverBrandedSellRate(date)));
    setSilverCostVal(String(getSilverCostRate(date)));
    setSilverBrandedCostVal(String(getSilverBrandedCostRate(date)));
  }, [date, open]);

  const save = () => {
    const php = parseFloat(phpRate);
    const ss = parseFloat(silverSell);
    const sbs = parseFloat(silverBrandedSell);
    const sc = parseFloat(silverCost);
    const sbc = parseFloat(silverBrandedCost);

    if ([php, ss, sbs, sc, sbc].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }

    setPhpRate(date, php);
    setSilverSellRate(date, ss);
    setSilverBrandedSellRate(date, sbs);
    setSilverCostRate(date, sc);
    setSilverBrandedCostRate(date, sbc);

    toast.success(`Rates locked for ${date}`);
    setOpen(false);
