          {/* PHP Rate */}
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-36 shrink-0">PHP Rate (1 AED =)</span>
            <Input
              type="number" step="0.01" value={phpRate}
              onChange={e => setPhpRateVal(e.target.value)}
              placeholder={String(DEFAULT_PHP_RATE)}
              className="h-7 text-xs bg-background border-border w-20"
            />
            <span className="text-[10px] text-muted-foreground">PHP &nbsp;(default: {DEFAULT_PHP_RATE})</span>
          </div>

          <div className="h-px bg-border" />

