          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver (non-branded)</p>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Sell Rate (AED/g)</span>
            <Input
              type="number" step="0.5" value={silverSell}
              onChange={e => setSilverSellVal(e.target.value)}
              placeholder={String(DEFAULT_SILVER_SELL_RATE)}
              className="h-7 text-xs bg-background border-border w-20"
            />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_SILVER_SELL_RATE}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Cost Rate (AED/g)</span>
            <Input
              type="number" step="0.5" value={silverCost}
              onChange={e => setSilverCostVal(e.target.value)}
              placeholder={String(DEFAULT_SILVER_COST_RATE)}
              className="h-7 text-xs bg-background border-border w-20"
            />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_SILVER_COST_RATE}</span>
          </div>

          <div className="h-px bg-border" />

          {/* Silver Branded */}
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver Branded</p>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Sell Rate (AED/g)</span>
            <Input
              type="number" step="0.5" value={silverBrandedSell}
              onChange={e => setSilverBrandedSellVal(e.target.value)}
              placeholder={String(DEFAULT_SILVER_BRANDED_SELL_RATE)}
              className="h-7 text-xs bg-background border-border w-20"
            />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_SILVER_BRANDED_SELL_RATE}</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Cost Rate (AED/g)</span>
            <Input
              type="number" step="0.5" value={silverBrandedCost}
              onChange={e => setSilverBrandedCostVal(e.target.value)}
              placeholder={String(DEFAULT_SILVER_BRANDED_COST_RATE)}
              className="h-7 text-xs bg-background border-border w-20"
            />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_SILVER_BRANDED_COST_RATE}</span>
          </div>

          <div className="flex gap-2 pt-1">
            <Button variant="outline" size="sm" className="text-xs h-7 border-border" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button size="sm" className="text-xs h-7 bg-primary text-primary-foreground" onClick={save}>
              <Check className="h-3 w-3 mr-1" /> Lock Rates
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

