// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

/**
 * Historical Rate Locking Store
 *
 * Saves and retrieves a snapshot of all 5 financial rates keyed by exact date.
 * Editing an old record uses that day's locked rates — never today's market prices.
 *
 * DEFAULTS (used when no snapshot exists for a date):
 *   phpRate              → 16.7
 *   silverSellRate       → 45   (AED/gram — what clients pay)
 *   silverCostRate       → 15   (AED/gram — what we pay supplier)
 *   silverBrandedSellRate→ 60
 *   silverBrandedCostRate→ 32
 */

export interface RateSnapshot {
  phpRate: number;
  silverSellRate: number;
  silverCostRate: number;
  silverBrandedSellRate: number;
  silverBrandedCostRate: number;
}

export const DEFAULT_RATES: RateSnapshot = {
  phpRate: 16.7,
  silverSellRate: 45,
  silverCostRate: 15,
  silverBrandedSellRate: 60,
  silverBrandedCostRate: 32,
};

const KEY = (date: string) => `rates_${date}`;

/** Save a full rate snapshot for a specific date */
export function saveRatesForDate(date: string, rates: RateSnapshot): void {
  if (!date) return;
  try {
    localStorage.setItem(KEY(date), JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save', e);
  }
}

/** Retrieve the rate snapshot for a specific date. Falls back to DEFAULT_RATES if none stored. */
export function getRatesForDate(date: string): RateSnapshot {
  if (!date) return { ...DEFAULT_RATES };
  try {
    const raw = localStorage.getItem(KEY(date));
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
      return {
        phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
        silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
        silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
        silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
        silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
      };
    }
  } catch (e) {
    console.error('ratesStore: failed to read', e);
  }
  return { ...DEFAULT_RATES };
}

// ── Convenience getters (used in DailyRatesEditor & AddClientModal) ──────────

export const DEFAULT_PHP_RATE = DEFAULT_RATES.phpRate;
export const DEFAULT_SILVER_SELL_RATE = DEFAULT_RATES.silverSellRate;
export const DEFAULT_SILVER_BRANDED_SELL_RATE = DEFAULT_RATES.silverBrandedSellRate;
export const DEFAULT_SILVER_COST_RATE = DEFAULT_RATES.silverCostRate;
export const DEFAULT_SILVER_BRANDED_COST_RATE = DEFAULT_RATES.silverBrandedCostRate;

export function getPhpRate(date: string): number { return getRatesForDate(date).phpRate; }
export function getSilverSellRate(date: string): number { return getRatesForDate(date).silverSellRate; }
export function getSilverBrandedSellRate(date: string): number { return getRatesForDate(date).silverBrandedSellRate; }
export function getSilverCostRate(date: string): number { return getRatesForDate(date).silverCostRate; }
export function getSilverBrandedCostRate(date: string): number { return getRatesForDate(date).silverBrandedCostRate; }

// Individual setters — update only one field, preserving the rest of the snapshot
function patchDate(date: string, patch: Partial<RateSnapshot>) {
  saveRatesForDate(date, { ...getRatesForDate(date), ...patch });
}
export function setPhpRate(date: string, rate: number) { patchDate(date, { phpRate: rate }); }
export function setSilverSellRate(date: string, rate: number) { patchDate(date, { silverSellRate: rate }); }
export function setSilverBrandedSellRate(date: string, rate: number) { patchDate(date, { silverBrandedSellRate: rate }); }
export function setSilverCostRate(date: string, rate: number) { patchDate(date, { silverCostRate: rate }); }
export function setSilverBrandedCostRate(date: string, rate: number) { patchDate(date, { silverBrandedCostRate: rate }); }

// Legacy aliases
/** @deprecated Use getRatesForDate(date).silverSellRate */
export function getSilverRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverSellRate */
export function setSilverRate(date: string, rate: number) { setSilverSellRate(date, rate); }
/** @deprecated Use getRatesForDate(date).silverBrandedSellRate */
export function getSilverBrandedRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverBrandedSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverBrandedSellRate */
export function setSilverBrandedRate(date: string, rate: number) { setSilverBrandedSellRate(date, rate); }
export function hasPhpRate(date: string): boolean { return localStorage.getItem(KEY(date)) !== null; }

import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType, Roles } from 'zite-integrations-backend-sdk';

const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "roseannaranez2@gmail.com"
];

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
  'auditTrail', 'tog', 'pureWeight', 'qty', 'customerId',
]);

const ZERO_PROFIT_STATUSES = new Set(['cancelled', 'returned item']);

// Strip commas before parsing — prevents "1,500" → 1
const n = (val: any): number => {
  const cleaned = String(val ?? '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
};

interface RateConfig {
  phpRate: number;
  silverSellRate: number;
  silverBrandedSellRate: number;
  silverCostRate: number;
  silverBrandedCostRate: number;
}

/** Historical rate-locked profit calculator. Uses the injected daily snapshot — never hardcoded values. */
function calculateServerProfit(fields: any, rates: RateConfig): string {
  // Ghost Profit prevention
  const status = String(fields.status || '').toLowerCase().trim();
  if (ZERO_PROFIT_STATUSES.has(status)) return '0.00';

  const grams = n(fields.grams);
  const clientRate = n(fields.clientRate);
  const category = String(fields.category || '').toLowerCase();
  const currency = String(fields.currency || 'AED').toUpperCase();
  const qty = n(fields.qty) || 1;

  let rateAED = clientRate;
  if (currency === 'PHP') rateAED = clientRate / rates.phpRate;
  else if (currency === 'USD') rateAED = clientRate * 3.67;

  let totalSales = 0;
  let totalCost = 0;

  if (category.includes('screw type') || category.includes('per pc')) {
    totalSales = rateAED * qty;
    let sr = n(fields.supplierRate) > 0 ? n(fields.supplierRate) : (n(fields.goldRate) > 0 ? n(fields.goldRate) : 115);
    if (sr === 115 && String(fields.itemDescription || '').toUpperCase().includes('B1T1')) sr *= 2;
    totalCost = sr * qty;
  } else if (category.includes('silver branded')) {
    // Smart Snap to the daily branded sell rate anchor
    if (rateAED > 0 && Math.abs(rateAED - rates.silverBrandedSellRate) <= 2) rateAED = rates.silverBrandedSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverBrandedSellRate) * grams;
    totalCost = rates.silverBrandedCostRate * grams;
  } else if (category.includes('silver')) {
    // Smart Snap to the daily silver sell rate anchor
    if (rateAED > 0 && Math.abs(rateAED - rates.silverSellRate) <= 2) rateAED = rates.silverSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverSellRate) * grams;
    totalCost = rates.silverCostRate * grams;
  } else if (category.includes('diamond')) {
    totalSales = rateAED * qty;
    totalCost = n(fields.supplierRate) * qty;
  } else {
    totalSales = rateAED * grams;
    const gr = n(fields.goldRate);
    const sr = n(fields.supplierRate);
    if (gr > 0) {
      let mc = n(fields.mc);
      if (mc <= 0) {
        if (category.includes('special price ef')) mc = 25;
        else if (category.includes('special price')) mc = 21;
        else mc = 16;
      }
      totalCost = (gr + mc) * grams;
    } else if (sr > 0) {
      totalCost = sr * grams;
    }
  }
  return Math.round(totalSales - totalCost).toFixed(2);
}

export default createEndpoint({
  description: 'Create a new Database row securely with historical rate locking',
  authenticated: true,
  inputSchema: z.object({
    fields: z.record(z.unknown()),
    // Daily rate snapshot — keyed by the record's dateOfLive on the frontend
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    const sanitized: Partial<DatabaseRowType> = {};
    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? 'TRUE' : 'FALSE';
      } else if (key === 'profit') {
        continue; // Always recalculate server-side
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
      }
    }

    (sanitized as Record<string, unknown>).profit = Number(
      calculateServerProfit(sanitized, {
        phpRate: input.phpRate,
        silverSellRate: input.silverSellRate,
        silverBrandedSellRate: input.silverBrandedSellRate,
        silverCostRate: input.silverCostRate,
        silverBrandedCostRate: input.silverBrandedCostRate,
      })
    );

    await Database.create({ row: sanitized });
    return { success: true };
  },
});

