import { useState, useEffect } from 'react';
import { ChevronDown, Settings2, Check } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { toast } from 'sonner';
import { getRatesForDate, saveRatesForDate, DEFAULT_RATES } from '@/lib/ratesStore';

interface Props {
  date: string; // yyyy-mm-dd
}

export default function DailyRatesEditor({ date }: Props) {
  const [open, setOpen] = useState(false);
  const [phpRate, setPhpRateVal] = useState('');
  const [silverSell, setSilverSellVal] = useState('');
  const [silverBrandedSell, setSilverBrandedSellVal] = useState('');

  // Load stored snapshot whenever date changes or panel opens
  useEffect(() => {
    const snap = getRatesForDate(date);
    setPhpRateVal(String(snap.phpRate));
    setSilverSellVal(String(snap.silverSellRate));
    setSilverBrandedSellVal(String(snap.silverBrandedSellRate));
  }, [date, open]);

  const save = () => {
    const php = parseFloat(phpRate);
    const ss = parseFloat(silverSell);
    const sbs = parseFloat(silverBrandedSell);

    if ([php, ss, sbs].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }

    // Save the full snapshot — preserve cost rates from any previously stored snapshot
    const existing = getRatesForDate(date);
    saveRatesForDate(date, {
      ...existing,
      phpRate: php,
      silverSellRate: ss,
      silverBrandedSellRate: sbs,
    });

    toast.success(`Rates locked for ${date}`);
    setOpen(false);
  };

  const snap = getRatesForDate(date);

  return (
    <div className="mb-4">
      {/* Collapsed Summary Bar */}
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center gap-2 px-3 py-2 rounded-lg bg-card border border-border hover:bg-secondary/40 transition-colors text-left"
      >
        <Settings2 className="h-3.5 w-3.5 text-primary shrink-0" />
        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Daily Rates</span>
        <span className="text-[10px] text-foreground ml-1">
          PHP <span className="text-primary font-semibold">{snap.phpRate}</span>
          &nbsp;·&nbsp; Ag <span className="text-primary font-semibold">{snap.silverSellRate}</span>
          &nbsp;·&nbsp; Ag★ <span className="text-primary font-semibold">{snap.silverBrandedSellRate}</span>
        </span>
        <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground ml-auto transition-transform duration-200 ${open ? 'rotate-180' : ''}`} />
      </button>

      {/* Expanded Editor */}
      {open && (
        <div className="mt-2 px-3 py-3 rounded-lg bg-card border border-border space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
          <p className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
            Editing rates for <span className="text-primary">{date}</span>
          </p>

          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">PHP Rate (1 AED =)</span>
            <Input type="number" step="0.01" value={phpRate}
              onChange={e => setPhpRateVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.phpRate)}
              className="h-7 text-xs bg-background border-border w-24" />
            <span className="text-[10px] text-muted-foreground">PHP &nbsp;(default: {DEFAULT_RATES.phpRate})</span>
          </div>

          <div className="h-px bg-border" />

          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver (non-branded)</p>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Rate (AED/g)</span>
            <Input type="number" step="0.5" value={silverSell}
              onChange={e => setSilverSellVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.silverSellRate)}
              className="h-7 text-xs bg-background border-border w-24" />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_RATES.silverSellRate}</span>
          </div>

          <div className="h-px bg-border" />

          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver Branded</p>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Rate (AED/g)</span>
            <Input type="number" step="0.5" value={silverBrandedSell}
              onChange={e => setSilverBrandedSellVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.silverBrandedSellRate)}
              className="h-7 text-xs bg-background border-border w-24" />
            <span className="text-[10px] text-muted-foreground">default: {DEFAULT_RATES.silverBrandedSellRate}</span>
          </div>

          <div className="flex gap-2 pt-1">
            <Button variant="outline" size="sm" className="text-xs h-7 border-border" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button size="sm" className="text-xs h-7 bg-primary text-primary-foreground" onClick={save}>
              <Check className="h-3 w-3 mr-1" /> Lock Rates
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, memo } from 'react';
import { FileText, Truck, Upload, History, ChevronDown } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { calcShippingFee, isFreeSf, getQty } from '@/lib/calculations';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

function isGivenToShopMode(record: DatabaseRowType): boolean {
  const location = (record.locationOfMiner || '').toLowerCase();
  const region = (record.regions || '').toLowerCase();
  return (
    record.modeOfPayment === 'Layaway' ||
    location.includes('pinas') ||
    location.includes('international') ||
    region.includes('pinas') ||
    region.includes('international')
  );
}

function getDeliveryLabel(record: DatabaseRowType): string {
  const mop = record.modeOfPayment || '';
  const region = record.regions ? `(${record.regions})` : '';
  if (mop === 'Pick Up Shop') return 'Pick Up Shop';
  if (mop === 'Meet Up') return 'Meet Up';
  if (mop === 'Layaway') return 'Layaway';
  if (region) return `${mop} ${region}`.trim();
  return mop || 'Unknown';
}

function getDeliverySummary(records: DatabaseRowType[]): string {
  const labels = records.map(getDeliveryLabel);
  const unique = [...new Set(labels)];
  if (unique.length === 1) return unique[0];
  return `🔴 MIXED: ${unique.join(', ')}`;
}

function DispatchClientCard({ minerName, records, allRecords, onUpdate, userEmail }: Props) {
  const [isExpanded, setIsExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [cancelRecord, setCancelRecord] = useState<DatabaseRowType | null>(null);
  const [resetKeys, setResetKeys] = useState<Record<number, number>>({});

  const [showHistory, setShowHistory] = useState(false);

  const first = records[0];
  const deliverySummary = getDeliverySummary(records);

  const handleStatusChange = async (record: DatabaseRowType, newStatus: string) => {
    setResetKeys(prev => ({ ...prev, [record.id]: (prev[record.id] || 0) + 1 }));
    if (newStatus === 'Cancelled') { setCancelRecord(record); return; }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (newStatus === 'Dispatched') fields.dispatchDate = new Date().toISOString();
    if (newStatus === 'Delivered' || newStatus === 'Given to Shop') fields.deliveredDate = new Date().toISOString();
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status: ${newStatus}`);
  };

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        className="w-full px-4 py-2.5 border-b border-border/50 flex items-center justify-between text-left focus:outline-none"
        onClick={() => setIsExpanded(prev => !prev)}
      >
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
            <span className="font-cinzel text-sm text-primary">{minerName}</span>
            {first?.customerId && (
              <button
                className="shrink-0 text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span className={deliverySummary.startsWith('🔴') ? 'text-destructive font-medium' : ''}>
              {deliverySummary}
            </span>
            {first?.liverName && <span className="flex items-center gap-1"><Upload className="h-3 w-3" />{first.liverName}</span>}
          </div>
        </div>
        <div className="flex items-center gap-2 ml-2 shrink-0">
          <Button
            variant="outline"
            size="sm"
            className="border-primary/40 text-primary text-xs h-7"
            onClick={e => { e.stopPropagation(); setShowInvoice(true); }}
          >
            <FileText className="h-3 w-3 mr-1" /> Invoice
          </Button>
          <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </button>

      {isExpanded && (
        <div className="px-3 py-2 space-y-2 animate-in fade-in slide-in-from-top-2 duration-200">
          {records.map(record => {
            const givenToShopMode = isGivenToShopMode(record);
            const latestAudit = record.auditTrail ? record.auditTrail.split(/(?=\[)/).pop() : null;
            return (
              <div key={record.id} className="rounded-lg border border-border/50 bg-secondary/20 p-3">
                <div className="flex items-start justify-between mb-2">
                  <div>
                    <p className="text-sm font-medium">{record.itemDescription}</p>
                    <p className="text-xs text-muted-foreground mt-0.5">
                      {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')}
                      <span className="text-foreground font-medium ml-1">
                        · {record.modeOfPayment || 'No MOP'} {record.regions && `(${record.regions})`}
                      </span>
                    </p>
                  </div>
                  <StatusBadge status={record.status} />
                </div>

                <div className="flex items-center gap-1 text-xs text-muted-foreground mb-2">
                  <Truck className="h-3 w-3" />
                  <span>SF: AED {calcShippingFee(record).toFixed(2)}</span>
                  {isFreeSf(record) && <span className="text-primary">(FREE)</span>}
                </div>

                {record.liverAdminRemarks && (
                  <p className="text-xs text-muted-foreground/70 italic mb-1.5 truncate">
                    Remarks: {record.liverAdminRemarks}
                  </p>
                )}

                {latestAudit && (
                  <p className="text-[10px] text-primary/60 mb-2 truncate flex items-center gap-1" title={record.auditTrail}>
                    <History className="h-2.5 w-2.5" />
                    {latestAudit}
                  </p>
                )}

                {record.status !== 'Cancelled' && (
                <Select key={`status-dropdown-${record.id}-${resetKeys[record.id] || 0}`} onValueChange={v => handleStatusChange(record, v)}>
                  <SelectTrigger className="h-7 text-xs w-full bg-background border-border">
                    <SelectValue placeholder="Set status..." />
                  </SelectTrigger>
                 <SelectContent className="bg-popover border-border">
                    {givenToShopMode ? (
                      <SelectItem value="Given to Shop" className="text-xs">Given to Shop</SelectItem>
                    ) : (
                      <>
                        <SelectItem value="Dispatched" className="text-xs">Dispatched</SelectItem>
                        <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                      </>
                    )}
                    <SelectItem value="Paid/DP but Item Hold" className="text-xs">Paid/DP but Item Hold</SelectItem>
                    <SelectItem value="Payment for Verification" className="text-xs">Payment for Verification</SelectItem>
                    <SelectItem value="Returned Item" className="text-xs">Returned Item</SelectItem>
                    <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
                )}
              </div>
            );
          })}
        </div>
      )}

      {showInvoice && (
        <InvoiceModal
          records={allRecords.filter(r => r.minerName?.trim().toLowerCase() === minerName.trim().toLowerCase())}
          onClose={() => setShowInvoice(false)}
        />
      )}

      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords} 
          onClose={() => setShowHistory(false)}
        />
      )}

      <AlertDialog open={!!cancelRecord} onOpenChange={() => setCancelRecord(null)}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => {
              if (cancelRecord) {
                await onUpdate(cancelRecord.id, { status: 'Cancelled' });
                toast.success('Cancelled');
                setCancelRecord(null);
              }
            }}>Cancel Item</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(DispatchClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType, Roles } from 'zite-integrations-backend-sdk';

const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "roseannaranez2@gmail.com"
];

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
  'auditTrail', 'tog', 'pureWeight', 'qty', 'customerId',
]);

const ZERO_PROFIT_STATUSES = new Set(['cancelled', 'returned item']);

// Strip commas before parsing — prevents "1,500" → 1
const n = (val: any): number => {
  const cleaned = String(val ?? '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
};

interface RateConfig {
  phpRate: number;
  silverSellRate: number;
  silverBrandedSellRate: number;
  silverCostRate: number;
  silverBrandedCostRate: number;
}

/** Historical rate-locked profit calculator. Uses the injected daily snapshot — never hardcoded values. */
function calculateServerProfit(fields: any, rates: RateConfig): string {
  // Ghost Profit prevention
  const status = String(fields.status || '').toLowerCase().trim();
  if (ZERO_PROFIT_STATUSES.has(status)) return '0.00';

  const grams = n(fields.grams);
  const clientRate = n(fields.clientRate);
  const category = String(fields.category || '').toLowerCase();
  const currency = String(fields.currency || 'AED').toUpperCase();
  const qty = n(fields.qty) || 1;

  let rateAED = clientRate;
  if (currency === 'PHP') rateAED = clientRate / rates.phpRate;
  else if (currency === 'USD') rateAED = clientRate * 3.67;

  let totalSales = 0;
  let totalCost = 0;

  if (category.includes('screw type') || category.includes('per pc')) {
    totalSales = rateAED * qty;
    let sr = n(fields.supplierRate) > 0 ? n(fields.supplierRate) : (n(fields.goldRate) > 0 ? n(fields.goldRate) : 115);
    if (sr === 115 && String(fields.itemDescription || '').toUpperCase().includes('B1T1')) sr *= 2;
    totalCost = sr * qty;
  } else if (category.includes('silver branded')) {
    // Smart Snap to the daily branded sell rate anchor
    if (rateAED > 0 && Math.abs(rateAED - rates.silverBrandedSellRate) <= 2) rateAED = rates.silverBrandedSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverBrandedSellRate) * grams;
    totalCost = rates.silverBrandedCostRate * grams;
  } else if (category.includes('silver')) {
    // Smart Snap to the daily silver sell rate anchor
    if (rateAED > 0 && Math.abs(rateAED - rates.silverSellRate) <= 2) rateAED = rates.silverSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverSellRate) * grams;
    totalCost = rates.silverCostRate * grams;
  } else if (category.includes('diamond')) {
    totalSales = rateAED * qty;
    totalCost = n(fields.supplierRate) * qty;
  } else {
    totalSales = rateAED * grams;
    const gr = n(fields.goldRate);
    const sr = n(fields.supplierRate);
    if (gr > 0) {
      let mc = n(fields.mc);
      if (mc <= 0) {
        if (category.includes('special price ef')) mc = 25;
        else if (category.includes('special price')) mc = 21;
        else mc = 16;
      }
      totalCost = (gr + mc) * grams;
    } else if (sr > 0) {
      totalCost = sr * grams;
    }
  }
  return Math.round(totalSales - totalCost).toFixed(2);
}

export default createEndpoint({
  description: 'Create a new Database row securely with historical rate locking',
  authenticated: true,
  inputSchema: z.object({
    fields: z.record(z.unknown()),
    // Daily rate snapshot — keyed by the record's dateOfLive on the frontend
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    const sanitized: Partial<DatabaseRowType> = {};
    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? 'TRUE' : 'FALSE';
      } else if (key === 'profit') {
        continue; // Always recalculate server-side
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
      }
    }

    (sanitized as Record<string, unknown>).profit = Number(
      calculateServerProfit(sanitized, {
        phpRate: input.phpRate,
        silverSellRate: input.silverSellRate,
        silverBrandedSellRate: input.silverBrandedSellRate,
        silverCostRate: input.silverCostRate,
        silverBrandedCostRate: input.silverBrandedCostRate,
      })
    );

    await Database.create({ row: sanitized });
    return { success: true };
  },
});

import { z } from 'zod';
import { createEndpoint, Database, DatabaseRowType, Roles } from 'zite-integrations-backend-sdk';

const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "roseannaranez2@gmail.com"
];

const VALID_FIELDS = new Set<keyof DatabaseRowType>([
  'orderId', 'dateOfLive', 'page', 'liverName', 'locationOfMiner', 'minerName',
  'itemDescription', 'grams', 'source', 'category', 'mc', 'goldRate', 'supplierRate',
  'clientRate', 'profit', 'modeOfSale', 'status', 'modeOfPayment', 'downpayment',
  'la1MonthPayment', 'la2MonthPayment', 'la3MonthPayment', 'la4MonthPayment',
  'liverAdminRemarks', 'dispatchDate', 'deliveredDate', 'reviewChasing', 'fbProfileName',
  'regions', 'remittanceStatus', 'currency', 'additionalCharges', 'amountReceived', 'freeSf',
  'auditTrail', 'tog', 'pureWeight', 'customerId', 'qty',
]);

const ZERO_PROFIT_STATUSES = new Set(['cancelled', 'returned item']);

// Strip commas before parsing — prevents "1,500" → 1
const n = (val: any): number => {
  const cleaned = String(val ?? '').replace(/,/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
};

// Fields that trigger a profit recalculation when updated
const PROFIT_FIELDS = new Set([
  'grams', 'clientRate', 'category', 'currency', 'qty',
  'supplierRate', 'goldRate', 'mc', 'itemDescription', 'status',
]);

interface RateConfig {
  phpRate: number;
  silverSellRate: number;
  silverBrandedSellRate: number;
  silverCostRate: number;
  silverBrandedCostRate: number;
}

/** Historical rate-locked profit calculator. Uses the injected daily snapshot — never hardcoded values. */
function calculateServerProfit(fields: any, rates: RateConfig): string {
  // Ghost Profit prevention
  const status = String(fields.status || '').toLowerCase().trim();
  if (ZERO_PROFIT_STATUSES.has(status)) return '0.00';

  const grams = n(fields.grams);
  const clientRate = n(fields.clientRate);
  const category = String(fields.category || '').toLowerCase();
  const currency = String(fields.currency || 'AED').toUpperCase();
  const qty = n(fields.qty) || 1;

  let rateAED = clientRate;
  if (currency === 'PHP') rateAED = clientRate / rates.phpRate;
  else if (currency === 'USD') rateAED = clientRate * 3.67;

  let totalSales = 0;
  let totalCost = 0;

  if (category.includes('screw type') || category.includes('per pc')) {
    totalSales = rateAED * qty;
    let sr = n(fields.supplierRate) > 0 ? n(fields.supplierRate) : (n(fields.goldRate) > 0 ? n(fields.goldRate) : 115);
    if (sr === 115 && String(fields.itemDescription || '').toUpperCase().includes('B1T1')) sr *= 2;
    totalCost = sr * qty;
  } else if (category.includes('silver branded')) {
    if (rateAED > 0 && Math.abs(rateAED - rates.silverBrandedSellRate) <= 2) rateAED = rates.silverBrandedSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverBrandedSellRate) * grams;
    totalCost = rates.silverBrandedCostRate * grams;
  } else if (category.includes('silver')) {
    if (rateAED > 0 && Math.abs(rateAED - rates.silverSellRate) <= 2) rateAED = rates.silverSellRate;
    totalSales = (clientRate > 0 ? rateAED : rates.silverSellRate) * grams;
    totalCost = rates.silverCostRate * grams;
  } else if (category.includes('diamond')) {
    totalSales = rateAED * qty;
    totalCost = n(fields.supplierRate) * qty;
  } else {
    totalSales = rateAED * grams;
    const gr = n(fields.goldRate);
    const sr = n(fields.supplierRate);
    if (gr > 0) {
      let mc = n(fields.mc);
      if (mc <= 0) {
        if (category.includes('special price ef')) mc = 25;
        else if (category.includes('special price')) mc = 21;
        else mc = 16;
      }
      totalCost = (gr + mc) * grams;
    } else if (sr > 0) {
      totalCost = sr * grams;
    }
  }
  return Math.round(totalSales - totalCost).toFixed(2);
}

export default createEndpoint({
  description: 'Update a Database row securely with historical rate locking',
  authenticated: true,
  inputSchema: z.object({
    rowId: z.number(),
    fields: z.record(z.unknown()),
    // Daily rate snapshot — keyed by the record's dateOfLive on the frontend
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    const sanitized: Partial<DatabaseRowType> = {};
    let needsProfitRecalc = false;

    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? 'TRUE' : 'FALSE';
      } else if (key === 'profit') {
        continue; // Always recalculate server-side
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
        if (PROFIT_FIELDS.has(key)) needsProfitRecalc = true;
      }
    }

    if (needsProfitRecalc) {
      (sanitized as Record<string, unknown>).profit = Number(
        calculateServerProfit(sanitized, {
          phpRate: input.phpRate,
          silverSellRate: input.silverSellRate,
          silverBrandedSellRate: input.silverBrandedSellRate,
          silverCostRate: input.silverCostRate,
          silverBrandedCostRate: input.silverBrandedCostRate,
        })
      );
    }

    await Database.update({ rowId: input.rowId, row: sanitized });
    return { success: true };
  },
});

/**
 * Historical Rate Locking Store
 *
 * Saves and retrieves a snapshot of all 5 financial rates keyed by exact date.
 * Editing an old record uses that day's locked rates — never today's market prices.
 *
 * DEFAULTS (used when no snapshot exists for a date):
 *   phpRate              → 16.7
 *   silverSellRate       → 45   (AED/gram — what clients pay)
 *   silverCostRate       → 15   (AED/gram — what we pay supplier)
 *   silverBrandedSellRate→ 60
 *   silverBrandedCostRate→ 32
 */

export interface RateSnapshot {
  phpRate: number;
  silverSellRate: number;
  silverCostRate: number;
  silverBrandedSellRate: number;
  silverBrandedCostRate: number;
}

export const DEFAULT_RATES: RateSnapshot = {
  phpRate: 16.7,
  silverSellRate: 45,
  silverCostRate: 15,
  silverBrandedSellRate: 60,
  silverBrandedCostRate: 32,
};

const KEY = (date: string) => `rates_${date}`;

/** Save a full rate snapshot for a specific date */
export function saveRatesForDate(date: string, rates: RateSnapshot): void {
  if (!date) return;
  try {
    localStorage.setItem(KEY(date), JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save', e);
  }
}

/** Retrieve the rate snapshot for a specific date. Falls back to DEFAULT_RATES if none stored. */
export function getRatesForDate(date: string): RateSnapshot {
  if (!date) return { ...DEFAULT_RATES };
  try {
    const raw = localStorage.getItem(KEY(date));
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
      return {
        phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
        silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
        silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
        silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
        silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
      };
    }
  } catch (e) {
    console.error('ratesStore: failed to read', e);
  }
  return { ...DEFAULT_RATES };
}

// ── Convenience getters (used in DailyRatesEditor & AddClientModal) ──────────

export const DEFAULT_PHP_RATE = DEFAULT_RATES.phpRate;
export const DEFAULT_SILVER_SELL_RATE = DEFAULT_RATES.silverSellRate;
export const DEFAULT_SILVER_BRANDED_SELL_RATE = DEFAULT_RATES.silverBrandedSellRate;
export const DEFAULT_SILVER_COST_RATE = DEFAULT_RATES.silverCostRate;
export const DEFAULT_SILVER_BRANDED_COST_RATE = DEFAULT_RATES.silverBrandedCostRate;

export function getPhpRate(date: string): number { return getRatesForDate(date).phpRate; }
export function getSilverSellRate(date: string): number { return getRatesForDate(date).silverSellRate; }
export function getSilverBrandedSellRate(date: string): number { return getRatesForDate(date).silverBrandedSellRate; }
export function getSilverCostRate(date: string): number { return getRatesForDate(date).silverCostRate; }
export function getSilverBrandedCostRate(date: string): number { return getRatesForDate(date).silverBrandedCostRate; }

// Individual setters — update only one field, preserving the rest of the snapshot
function patchDate(date: string, patch: Partial<RateSnapshot>) {
  saveRatesForDate(date, { ...getRatesForDate(date), ...patch });
}
export function setPhpRate(date: string, rate: number) { patchDate(date, { phpRate: rate }); }
export function setSilverSellRate(date: string, rate: number) { patchDate(date, { silverSellRate: rate }); }
export function setSilverBrandedSellRate(date: string, rate: number) { patchDate(date, { silverBrandedSellRate: rate }); }
export function setSilverCostRate(date: string, rate: number) { patchDate(date, { silverCostRate: rate }); }
export function setSilverBrandedCostRate(date: string, rate: number) { patchDate(date, { silverBrandedCostRate: rate }); }

// Legacy aliases
/** @deprecated Use getRatesForDate(date).silverSellRate */
export function getSilverRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverSellRate */
export function setSilverRate(date: string, rate: number) { setSilverSellRate(date, rate); }
/** @deprecated Use getRatesForDate(date).silverBrandedSellRate */
export function getSilverBrandedRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverBrandedSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverBrandedSellRate */
export function setSilverBrandedRate(date: string, rate: number) { setSilverBrandedSellRate(date, rate); }
export function hasPhpRate(date: string): boolean { return localStorage.getItem(KEY(date)) !== null; }

