import { DatabaseRowType } from '@/types';
import { calcShippingFee, calcCCFee, clientRateAED, isPcItem, getQty, getSilverRate, calcTotalPaid } from '@/lib/calculations';
import { getPhpRate } from '@/lib/phpRateStore'; 
import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';

const NOTES = [
  'We can hold unpaid items for a maximum of 3 days from the invoice date.',
  'Failure to settle within 3 days may result in additional charges.',
  'Unpaid items will be automatically cancelled after the grace period without prior notice.',
  'All items undergo strict quality checking before dispatch.',
  'An unboxing video is strictly required. No video, no refund, no exchange.',
  'No cash refund. Store credit only.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;
const rnd = (v: number) => Math.round(v);

export default function InvoicePrintContent({ records, currency }: Props) {
  const first = records[0];

  const phpRate = getPhpRate(first?.dateOfLive || '') || 16.7;

  const convertFromAED = (aedValue: number): number => {
    if (currency === 'PHP') return aedValue * phpRate;
    if (currency === 'USD') return aedValue / 3.67;
    return aedValue; 
  };

  const fmtAmt = (v: number) =>
    `${currency} ${rnd(v).toLocaleString('en-US')}`;

  const items = records.map(r => {
    const category = (r.category || '').toLowerCase().trim();
    const isScrewType = category.includes('screw type');
    const isPerPc = category.includes('per pc');
    const isSilver = category === 'silver';
    const isSilverBranded = category === 'silver branded';
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = getQty(r);

    let trueAedRate = 0;
    if (isSilver || isSilverBranded) {
      trueAedRate = n(r.clientRate) > 0 ? clientRateAED(r) : getSilverRate(category, r)!;
    } else {
      trueAedRate = clientRateAED(r);
    }

    const displayRate = rnd(convertFromAED(trueAedRate));

    let amount: number;
    if (isScrewType || isPerPc) {
      amount = rnd(displayRate * qtyValue);
    } else if (isPc || gramsValue === 0) {
      amount = displayRate;
    } else {
      amount = rnd(displayRate * gramsValue);
    }

    let gramsDisplay = '';
    if (isScrewType || isPerPc) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = (isPc || gramsValue === 0) ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: (isPc || isScrewType || isPerPc),
      rate: displayRate,
      amount,
      liver: r.liverName?.trim() || '',
      date: formatDate(r.dateOfLive) 
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  const shippingAED = first ? calcShippingFee(first) : 0;
  const shipping = rnd(convertFromAED(shippingAED));
  const additionalAED = n(first?.additionalCharges);
  const additional = rnd(convertFromAED(additionalAED));
  const ccFeeAED = first ? calcCCFee(first) : 0;
  const ccFee = rnd(convertFromAED(ccFeeAED));
  const total = subtotal + shipping + additional + ccFee;

  const totalPaidAED = records.reduce((s, r) => s + calcTotalPaid(r), 0);
  const totalPaidConverted = rnd(convertFromAED(totalPaidAED));
  const balanceDue = total - totalPaidConverted;

  const totalGrams = records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('diamond')) return s;
    return s + n(r.grams);
  }, 0);

  const amountForWords = Math.max(0, totalPaidConverted > 0 ? balanceDue : total);
  const amountInWords = numberToWords(amountForWords, currency);

  const mopLabel = (() => {
    const mop = (first?.modeOfPayment || '').trim();
    if (!mop) return null;
    return mop.toUpperCase();
  })();

  const invoiceDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const invoiceNo = records.map(r => r.pureWeight).find(Boolean);

  const summaryRows: { label: string; value: string; red?: boolean }[] = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
    ...(totalPaidConverted > 0 ? [
      { label: 'TOTAL PAID', value: `- ${fmtAmt(totalPaidConverted)}`, red: true },
      { label: 'BALANCE DUE', value: fmtAmt(balanceDue), red: true },
    ] : []),
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ position: 'relative', fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>

      <div style={{
        position: 'absolute',
        top: '40%',
        left: '50%',
        transform: 'translate(-50%, -50%) rotate(-35deg)',
        fontSize: '65px',
        color: 'rgba(150, 150, 150, 0.12)',
        fontWeight: 900,
        whiteSpace: 'nowrap',
        pointerEvents: 'none',
        zIndex: 0,
        userSelect: 'none',
        textAlign: 'center'
      }}>
        MYKABAYAN OFFICIAL<br/>
        {invoiceNo || ''}
      </div>

      <div style={{ position: 'relative', zIndex: 1 }}>
        <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0, background: '#fff' }}>
          <em style={{ fontSize: 14 }}>Statement of Account</em>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '65%', padding: '12px 16px', verticalAlign: 'top', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 24, letterSpacing: 1 }}>MYKABAYAN JEWELLERY</div>
                <div style={{ marginTop: 8, textAlign: 'left', fontSize: 11 }}>SATWA, DUBAI, UNITED ARAB EMIRATES</div>
                <div style={{ marginTop: 4, fontSize: 11 }}>WhatsApp &amp; Contact no.: +971 52 825 2405</div>
              </td>
              <td style={{ width: '35%', padding: '12px 16px', verticalAlign: 'middle', textAlign: 'center', border: '1px solid #999' }}>
                <img src={LOGO_URL} crossOrigin="anonymous" alt="Logo" style={{ width: '80px', height: '80px', objectFit: 'contain', display: 'block', margin: '0 auto' }} />
              </td>
            </tr>
            <tr>
              <td style={{ padding: '10px 16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 700, fontSize: 20, textAlign: 'center', letterSpacing: 1 }}>
                  {(first?.minerName || '').toUpperCase()}
                </div>
              </td>
              <td style={{ padding: '8px', textAlign: 'center', border: '1px solid #999' }}>
                <div style={{ fontWeight: 600, fontSize: 13 }}>{invoiceDate}</div>
                <div style={{ fontSize: 11, marginTop: 4 }}>Date Printed</div>
                {invoiceNo && (
                  <div style={{ marginTop: 8, borderTop: '1px solid #ccc', paddingTop: 6 }}>
                    <div style={{ fontWeight: 700, fontSize: 13, fontFamily: 'monospace', color: '#c00' }}>{invoiceNo}</div>
                    <div style={{ fontSize: 10, color: '#666', marginTop: 2 }}>Account ID / Invoice #</div>
                  </div>
                )}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <thead>
            <tr style={{ background: 'rgba(224, 224, 224, 0.9)' }}>
              {['Date', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
                <th key={h} style={{ border: '1px solid #999', padding: '6px 8px', textAlign: 'center', fontSize: 11 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => (
              <tr key={i}>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#666' }}>{item.date}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, fontWeight: 600 }}>
                  {item.desc.toUpperCase()}
                  {item.liver && <div style={{ fontSize: 9, fontWeight: 400, color: '#888', marginTop: 2 }}>Liver: {item.liver}</div>}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.tog.toUpperCase()}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: item.isPc ? 'red' : '#111', fontWeight: item.isPc ? 700 : 400 }}>
                  {item.gramsDisplay}
                </td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11 }}>{item.rate.toLocaleString('en-US')}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'right', fontSize: 11 }}>{fmtAmt(item.amount)}</td>
              </tr>
            ))}
            {Array.from({ length: emptyRows }).map((_, i) => (
              <tr key={`empty-${i}`} style={{ height: 22 }}>
                {[1,2,3,4,5,6].map(c => <td key={c} style={{ border: '1px solid #999' }}>&nbsp;</td>)}
              </tr>
            ))}
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '50%', padding: '16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 26, lineHeight: 1.2, textAlign: 'center' }}>
                  CUSTOMER'S INVOICE<br />COPY
                </div>
                {mopLabel && (
                  <div style={{ marginTop: '8px', textAlign: 'center' }}>
                    <div style={{ display: 'inline-block', border: '2px solid red', color: 'red', padding: '4px 12px', fontWeight: 900, fontSize: '18px', letterSpacing: '2px', textTransform: 'uppercase' }}>
                      {mopLabel}
                    </div>
                  </div>
                )}
              </td>
              <td style={{ padding: 0, verticalAlign: 'top', border: '1px solid #999' }}>
                {summaryRows.map((row, i) => (
                  <div key={i} style={{ display: 'flex', justifyContent: 'space-between', background: row.red ? 'rgba(255, 240, 240, 0.9)' : (i % 2 === 0 ? 'rgba(224, 224, 224, 0.9)' : 'rgba(245, 245, 245, 0.9)'), padding: '5px 10px', borderBottom: '1px solid #ccc' }}>
                    <span style={{ fontWeight: 700, fontSize: 11, color: row.red ? '#cc0000' : '#111' }}>{row.label}</span>
                    <span style={{ fontSize: 11, fontWeight: row.red ? 700 : 400, color: row.red ? '#cc0000' : '#111' }}>{row.value}</span>
                  </div>
                ))}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ padding: '4px 12px', border: '1px solid #999', borderBottom: 'none' }}>
                <span style={{ color: 'red', fontWeight: 700, fontSize: 11 }}>Amount in Words:</span>
              </td>
            </tr>
            <tr>
              <td style={{ padding: '4px 12px 10px', textAlign: 'center', fontWeight: 700, fontSize: 13, border: '1px solid #999' }}>
                {amountInWords}
              </td>
            </tr>
          </tbody>
        </table>

        <div style={{ padding: '8px 12px', border: '1px solid #999', marginTop: -1, background: '#fff' }}>
          <div style={{ color: 'red', fontWeight: 700, fontSize: 12, marginBottom: 4 }}>NOTE:</div>
          {NOTES.map((note, i) => (
            <div key={i} style={{ fontSize: 10, marginBottom: 2 }}>{i + 1}. {note}</div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useRef, useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, Copy, Loader2 } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);

  useEffect(() => {
    if (!document.getElementById('html2canvas-script') && !(window as any).html2canvas) {
      const script = document.createElement('script');
      script.id = 'html2canvas-script';
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  const activeRecords = useMemo(() => {
    const excludedStatuses = ['Cancelled', 'Returned Item'];
    return records
      .filter(r => !excludedStatuses.includes(r.status || ''))
      .sort((a, b) => {
        const dateA = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
        const dateB = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
        return dateA - dateB;
      });
  }, [records]);

  const baseRecord = activeRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleCopyImage = async () => {
    if (activeRecords.length === 0 || !printRef.current) return;

    const html2canvas = (window as any).html2canvas;
    if (!html2canvas) {
      toast.error('The image tool is still loading. Please try again in a few seconds.');
      return;
    }

    setIsCopying(true);
    toast.info('Generating image, please wait...');

    try {
      const makeImagePromise = async (): Promise<Blob> => {
        const canvas = await html2canvas(printRef.current!, {
          scale: 2, 
          useCORS: true, 
          backgroundColor: '#ffffff',
          scrollY: 0,
          windowHeight: printRef.current?.scrollHeight || window.innerHeight
        });
        return new Promise<Blob>((resolve, reject) => {
          canvas.toBlob((blob: Blob | null) => {
            if (blob) resolve(blob);
            else reject(new Error('Failed to generate image blob'));
          }, 'image/png');
        });
      };

      await navigator.clipboard.write([
        new ClipboardItem({
          'image/png': makeImagePromise()
        })
      ]);
      toast.success('Invoice image copied! You can now paste it into Meta Business Suite.');
    } catch (error: any) {
      console.error(error);
      if (error.name === 'NotAllowedError') {
         toast.error('Clipboard permission denied. Please allow clipboard access in your browser settings.');
      } else {
         toast.error('Failed to copy image. Try again.');
      }
    } finally {
      setIsCopying(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0" aria-describedby={undefined}>
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex items-center justify-between gap-4">
            <DialogTitle className="text-base font-bold text-foreground">
              Statement of Account (Active)
            </DialogTitle>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger className="h-8 w-24 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CURRENCIES.map(c => (
                      <SelectItem key={c} value={c}>{c}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <Button
                onClick={handleCopyImage}
                size="sm"
                variant="outline"
                className="h-8 border-blue-600 text-blue-700 hover:bg-blue-50"
                disabled={activeRecords.length === 0 || isCopying}
              >
                {isCopying ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Copy className="h-3.5 w-3.5 mr-1.5" />}
                {isCopying ? 'Copying...' : 'Copy Image'}
              </Button>

              <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={activeRecords.length === 0}>
                <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
              </Button>
            </div>
          </div>
        </DialogHeader>

        {activeRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Active Items</p>
            <p className="text-xs">This client's items have all been Delivered, Dispatched, or Cancelled.</p>
          </div>
        )}

        {activeRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4 bg-white">
              <InvoicePrintContent records={activeRecords} currency={currency} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect, useRef, memo } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { AlertCircle, Loader2, Pencil } from 'lucide-react';
import EditItemDialog from '@/components/admin/EditItemDialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Checkbox } from '@/components/ui/checkbox';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { DatabaseRowType } from '@/types';
import { isOverdue, isFreeSf, getQty } from '@/lib/calculations';
import { MOP_OPTIONS, REGION_OPTIONS, getLocationFromRegion, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import { generateInvoiceNumber } from 'zite-endpoints-sdk';
import { parseDateRobust } from '@/lib/calculations';

interface Props {
  record: DatabaseRowType;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  onGroupUpdate: (fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
}

const TOG_OPTIONS = ['18K', 'VCA', '21K', '24K', 'S-925'];

function isInStore(record: DatabaseRowType): boolean {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  return mos === 'in-store' || mos === 'walk-in' || mos === 'walk in';
}

function detectAutoFill(remarks: string): Partial<DatabaseRowType> | null {
  const r = (remarks || '').toLowerCase();
  if (r.includes('tabby approved')) return { modeOfPayment: 'Tabby', freeSf: 'TRUE' };
  if (r.includes('tamara approved')) return { modeOfPayment: 'Tamara', freeSf: 'TRUE' };
  if (/\bcod\b/.test(r)) return { modeOfPayment: 'COD' };
  if (/\bcc\b/.test(r) || r.includes('credit card')) return { modeOfPayment: 'Credit Card' };
  return null;
}

/** Returns MMDDYY prefix from the record's dateOfLive (falls back to today) */
function getDatePrefix(dateOfLive?: string): string {
  const d = dateOfLive ? parseDateRobust(dateOfLive) : null;
  const date = d || new Date();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const yy = String(date.getFullYear()).slice(-2);
  return `${mm}${dd}${yy}`;
}

function AdminItemRow({ record, onUpdate, onGroupUpdate, userEmail }: Props) {
  const [showCancel, setShowCancel] = useState(false);
  const [showEdit, setShowEdit] = useState(false);
  const [remarks, setRemarks] = useState(record.liverAdminRemarks || '');
  const [invoiceNum, setInvoiceNum] = useState(record.pureWeight || '');
  const [resetKey, setResetKey] = useState(Date.now());
  const [hasDownpayment, setHasDownpayment] = useState(!!record.downpayment);
  const [downpayment, setDownpayment] = useState(record.downpayment || '');
  const [generating, setGenerating] = useState(false);
  const generatingRef = useRef(false);
  const overdue = isOverdue(record);
  const inStore = isInStore(record);

  // Sync if record.pureWeight changes externally
  useEffect(() => {
    if (record.pureWeight) setInvoiceNum(record.pureWeight);
  }, [record.pureWeight]);

  useEffect(() => {
    if (!record.modeOfPayment && record.liverAdminRemarks) {
      const auto = detectAutoFill(record.liverAdminRemarks);
      if (auto) onGroupUpdate(auto);
    }
  }, [record.modeOfPayment, record.liverAdminRemarks, onGroupUpdate]);

  const debouncedDownpayment = useDebouncedCallback(async (val: string) => {
    await onUpdate(record.id, { downpayment: val });
  }, 700);

  const debouncedRemarks = useDebouncedCallback(async (val: string) => {
    const autoFill = detectAutoFill(val);
    await onUpdate(record.id, { liverAdminRemarks: val });
    if (autoFill) {
      await onGroupUpdate(autoFill);
      toast.success('Auto-filled MOP from remarks');
    }
  }, 700);

  const handleMopChange = async (mop: string) => {
    const fields: Partial<DatabaseRowType> = { modeOfPayment: mop };
    if (mop === 'Pick Up Shop' || mop === 'Meet Up') fields.regions = 'Dubai';
    if (mop === 'Tabby' || mop === 'Tamara') fields.freeSf = 'TRUE';
    await onGroupUpdate(fields);
  };

  const handleRegionChange = async (region: string) => {
    const newLocation = getLocationFromRegion(region);
    await onGroupUpdate({ regions: region, locationOfMiner: newLocation });
  };

  const handleTogChange = async (tog: string) => {
    await onUpdate(record.id, { tog });
  };

  const isWaitingForDP = record.status === 'Waiting for Downpayment';
  const hasDPAmount = hasDownpayment && !!downpayment && parseFloat(downpayment) > 0;
  const dpLocked = isWaitingForDP && !hasDPAmount;

  const handleStatusChange = async (newStatus: string) => {
    setResetKey(Date.now());
    if (newStatus === 'Cancelled') { setShowCancel(true); return; }
    if (dpLocked) {
      toast.error('Enter a downpayment amount to enable other status options');
      return;
    }
    if (newStatus === 'For Pullout') {
      if (!record.modeOfPayment) { toast.error('Mode of Payment is required'); return; }
      if (record.locationOfMiner === 'Local' && !record.regions) { toast.error('Region required for Local miners'); return; }
    }
    const fields: Partial<DatabaseRowType> = { status: newStatus };
    if (userEmail) {
      const timestamp = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
      const newEntry = `[${newStatus} by ${userEmail.split('@')[0]} on ${timestamp}]`;
      fields.auditTrail = record.auditTrail ? `${record.auditTrail} ${newEntry}` : newEntry;
    }
    await onUpdate(record.id, fields);
    toast.success(`Status set to ${newStatus}`);
  };

  return (
    <div className={`rounded-lg border p-3 mb-2 ${overdue ? 'border-destructive bg-destructive/5' : 'border-border bg-secondary/30'}`}>
      <div className="flex items-start justify-between mb-2">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-1.5">
            <p className="text-sm font-medium truncate">{record.itemDescription || '—'}</p>
            <button onClick={() => setShowEdit(true)} className="shrink-0 text-muted-foreground hover:text-primary transition-colors" title="Edit item details">
              <Pencil className="h-3 w-3" />
            </button>
          </div>
          <div className="flex flex-wrap gap-1 mt-1">
            <StatusBadge status={record.status} />
            {overdue && (
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded border text-xs font-bold bg-destructive/20 text-destructive border-destructive/40">
                <AlertCircle className="h-3 w-3" /> NEEDS ATTENTION
              </span>
            )}
          </div>
        </div>
        <div className="text-right ml-2 shrink-0">
          <p className="text-xs text-muted-foreground">{record.category}</p>
          <p className="text-xs text-muted-foreground">
            {(record.category || '').toLowerCase().includes('screw type')
              ? `${getQty(record)} PCS`
              : (record.grams ? `${record.grams}g` : 'PC')}
          </p>
          <p className="text-xs text-muted-foreground">{record.currency}</p>
        </div>
      </div>
      <p className="text-xs text-muted-foreground mb-3">Live: {formatDate(record.dateOfLive)} · {record.locationOfMiner}</p>

      <div className="space-y-2">
        <div>
          <Label className="text-xs text-muted-foreground">Mode of Payment <span className="text-primary/60">(applies to all items)</span></Label>
          <Select value={record.modeOfPayment || ''} onValueChange={handleMopChange}>
            <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
              <SelectValue placeholder="Select MOP..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {MOP_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
            </SelectContent>
          </Select>
        </div>

        {!inStore && (
          <div>
            <Label className="text-xs text-muted-foreground">Region <span className="text-primary/60">(applies to all items)</span></Label>
            <Select value={record.regions || ''} onValueChange={handleRegionChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select region..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {REGION_OPTIONS.map(r => <SelectItem key={r} value={r} className="text-xs">{r}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
        )}

        <div className="grid grid-cols-3 gap-2">
          <div>
            <Label className="text-xs text-muted-foreground">T.O.G</Label>
            <Select value={record.tog || ''} onValueChange={handleTogChange}>
              <SelectTrigger className="h-8 text-xs bg-background border-border mt-0.5">
                <SelectValue placeholder="Select..." />
              </SelectTrigger>
              <SelectContent className="bg-popover border-border">
                {TOG_OPTIONS.map(opt => <SelectItem key={opt} value={opt} className="text-xs">{opt}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          <div>
            <Label className="text-xs text-primary/80 font-semibold">Invoice #</Label>
            <div className="flex gap-1 mt-0.5">
              <Input
                type="text"
                value={invoiceNum || ''}
                readOnly
                className="h-8 text-xs bg-muted/40 border-border cursor-not-allowed font-mono flex-1 min-w-0"
                placeholder="—"
              />
              <Button
                size="sm"
                variant="outline"
                className="h-8 text-xs px-2 border-border shrink-0"
                disabled={generating}
                onClick={async () => {
                  if (generatingRef.current) return;
                  generatingRef.current = true;
                  setGenerating(true);
                  try {
                    const prefix = getDatePrefix(record.dateOfLive);
                    const { invoiceNumber } = await generateInvoiceNumber({ prefix, recordId: record.id, dateOfLive: record.dateOfLive || '', minerName: record.minerName || '' });
                    setInvoiceNum(invoiceNumber);
                    await onUpdate(record.id, { pureWeight: invoiceNumber });
                    toast.success('Invoice # generated');
                  } catch {
                    toast.error('Failed to generate invoice #');
                  } finally {
                    generatingRef.current = false;
                    setGenerating(false);
                  }
                }}
              >
                {generating ? <Loader2 className="h-3 w-3 animate-spin" /> : 'Gen'}
              </Button>
            </div>
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">Qty</Label>
            <Input
              type="number"
              defaultValue={getQty(record)}
              onChange={e => onUpdate(record.id, { qty: Number(e.target.value) })}
              className="h-8 text-xs bg-background border-border mt-0.5"
              placeholder="1"
            />
          </div>
        </div>

        <div>
          <Label className="text-xs text-muted-foreground">Liver/Admin Remarks</Label>
          <Textarea value={remarks} onChange={e => { setRemarks(e.target.value); debouncedRemarks(e.target.value); }} className="h-14 text-xs bg-background border-border mt-0.5 resize-none" placeholder="e.g. TABBY APPROVED, COD..." />
        </div>

        {/* Downpayment */}
        <div className="space-y-1.5">
          <div className="flex items-center gap-2">
            <Checkbox
              id={`dp-${record.id}`}
              checked={hasDownpayment}
              onCheckedChange={(checked) => {
                const on = !!checked;
                setHasDownpayment(on);
                if (!on) {
                  setDownpayment('');
                  onUpdate(record.id, { downpayment: '' });
                }
              }}
            />
            <Label htmlFor={`dp-${record.id}`} className="text-xs cursor-pointer">Downpayment</Label>
            {hasDownpayment && downpayment && (
              <span className="text-xs text-primary font-medium ml-1">{record.currency || 'AED'} {downpayment}</span>
            )}
          </div>
          {hasDownpayment && (
            <Input
              type="number"
              value={downpayment}
              onChange={e => {
                setDownpayment(e.target.value);
                debouncedDownpayment(e.target.value);
              }}
              className="h-8 text-xs bg-background border-border"
              placeholder="Enter downpayment amount..."
            />
          )}
        </div>

        <div className="flex items-center justify-between">
          {!inStore ? (
            <div className="flex items-center gap-2">
              <Switch checked={isFreeSf(record)} onCheckedChange={v => onGroupUpdate({ freeSf: v ? 'TRUE' : '' })} className="scale-90" />
              <Label className="text-xs">FREE SF</Label>
            </div>
          ) : <div />}

          <Select key={resetKey} onValueChange={handleStatusChange}>
            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="Change status..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {inStore ? (
                <>
                  <SelectItem value="Delivered" className="text-xs">Delivered</SelectItem>
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              ) : (
                <>
                  <SelectItem value="Waiting for Downpayment" className="text-xs text-amber-400">Waiting for Downpayment</SelectItem>
                  <SelectItem value="Paid/DP but Item Hold" className="text-xs text-blue-400">Paid/DP but Item Hold</SelectItem>
                  <SelectItem value="Payment for Verification" className="text-xs text-cyan-400">Payment for Verification</SelectItem>
                  <SelectItem value="For Pullout" disabled={dpLocked} className={`text-xs ${dpLocked ? 'opacity-40' : ''}`}>For Pullout</SelectItem>
                  <SelectItem value="Reseller" disabled={dpLocked} className={`text-xs ${dpLocked ? 'opacity-40' : ''}`}>Reseller</SelectItem>
                  <SelectItem value="Cancelled" className="text-xs text-destructive">Cancelled</SelectItem>
                </>
              )}
            </SelectContent>
          </Select>
        </div>
      </div>

      {showEdit && (
        <EditItemDialog
          record={record}
          onSave={fields => onUpdate(record.id, fields)}
          onClose={() => setShowEdit(false)}
        />
      )}

      <AlertDialog open={showCancel} onOpenChange={setShowCancel}>
        <AlertDialogContent className="bg-card border-border">
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this item?</AlertDialogTitle>
            <AlertDialogDescription>This cannot be undone from the app.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground" onClick={async () => { await onUpdate(record.id, { status: 'Cancelled' }); toast.success('Item cancelled'); }}>
              Cancel Item
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

export default memo(AdminItemRow, (prevProps, nextProps) => {
  return prevProps.record === nextProps.record && prevProps.userEmail === nextProps.userEmail;
});

import { useState, memo, useMemo } from 'react';
import { ChevronDown, FileText, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { calcRemainingBalance, calcShippingFee, calcCCFee, calcItemPrice, calcDueDate, getQty } from '@/lib/calculations';
import { formatDateObj, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import FinancialsForm from './FinancialsForm';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function AccountsClientCard({ minerName, records, allRecords, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [expandedItem, setExpandedItem] = useState<number | null>(null);

  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));
  const totalRemaining = records.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

  // Group records by Date → Liver → Status
  const grouped = useMemo(() => {
    const byDate: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'No Date';
      const liver = r.liverName || 'Unknown Liver';
      const status = r.status || 'No Status';
      if (!byDate[date]) byDate[date] = {};
      if (!byDate[date][liver]) byDate[date][liver] = {};
      if (!byDate[date][liver][status]) byDate[date][liver][status] = [];
      byDate[date][liver][status].push(r);
    }
    return byDate;
  }, [records]);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button className="w-full text-left px-4 py-3 flex items-center justify-between" onClick={() => setExpanded(e => !e)}>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-cinzel text-sm text-primary">{minerName}</span>
            {first?.customerId && (
              <button
                className="text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Due: {dueDate}</span>
          </div>
          {totalRemaining > 0 && (
            <span className="text-xs font-medium text-destructive">Balance: AED {totalRemaining.toFixed(2)}</span>
          )}
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {/* Generate Invoice at the TOP */}
          <Button
            variant="outline"
            size="sm"
            className="w-full mb-3 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>

          {/* Grouped by Date → Liver → Status */}
          {Object.entries(grouped).sort().map(([date, livers]) => (
            <div key={date} className="mb-3">
              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2 px-1">
                📅 {formatDate(date)}
              </div>
              {Object.entries(livers).map(([liver, statuses]) => (
                <div key={liver} className="mb-2 ml-2">
                  <div className="text-xs font-medium text-primary/80 mb-1 px-1">🧑 {liver}</div>
                  {Object.entries(statuses).map(([status, items]) => (
                    <div key={status} className="mb-2 ml-2">
                      <div className="text-xs text-muted-foreground mb-1 px-1 flex items-center gap-1">
                        <StatusBadge status={status} /> <span className="ml-1">({items.length})</span>
                      </div>
                      {items.map(record => (
                        <div key={record.id} className="mb-2 rounded-lg border border-border/50 bg-secondary/20 overflow-hidden">
                          <button
                            className="w-full text-left p-3 flex items-start justify-between"
                            onClick={() => setExpandedItem(expandedItem === record.id ? null : record.id)}
                          >
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-medium truncate mb-1">{record.itemDescription}</p>
                              <div className="text-xs text-muted-foreground">
                                {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')} · {record.modeOfPayment}
                              </div>
                              <div className="flex gap-3 text-xs mt-1">
                                <span className="text-muted-foreground">Price: <span className="text-foreground">{record.currency || 'AED'} {calcItemPrice(record).toFixed(2)}</span></span>
                                <span className="text-muted-foreground">SF: <span className="text-foreground">AED {calcShippingFee(record).toFixed(2)}</span></span>
                                {calcCCFee(record) > 0 && <span className="text-muted-foreground">CC: <span className="text-foreground">AED {calcCCFee(record).toFixed(2)}</span></span>}
                              </div>
                              <div className="text-xs mt-0.5">
                                <span className={`font-medium ${calcRemainingBalance(record) > 0 ? 'text-destructive' : 'text-green-400'}`}>
                                  Balance: AED {calcRemainingBalance(record).toFixed(2)}
                                </span>
                              </div>
                            </div>
                            <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground shrink-0 ml-2 mt-1 transition-transform ${expandedItem === record.id ? 'rotate-180' : ''}`} />
                          </button>

                          {expandedItem === record.id && (
                            <div className="px-3 pb-3 animate-in fade-in slide-in-from-top-2 duration-200">
                              <FinancialsForm record={record} onUpdate={onUpdate} />
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          ))}
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

export default memo(AccountsClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { TabProps, DatabaseRowType } from '@/types';
import {
  calcProfitAED,
  calcRemainingBalance,
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [selectedPrintStatuses, setSelectedPrintStatuses] = useState<Set<string>>(new Set());

  const [historyCustomer, setHistoryCustomer] = useState<{ id: string, name: string } | null>(null);

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    const base = records;
    if (range === 'all') return base;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return base.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      const itemTime = d.getTime();
      if (itemTime < from.getTime()) return false;
      if (to) {
        const endOfToDay = new Date(to);
        endOfToDay.setHours(23, 59, 59, 999);
        if (itemTime > endOfToDay.getTime()) return false;
      }
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    // FIX: Exclude both Cancelled and Returned Item from active calculations
    const activeRecords = filtered.filter(r => r.status !== 'Cancelled' && r.status !== 'Returned Item');
    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    const totalGrams = activeRecords.reduce((sum, r) => {
      const cat = (r.category || '').toLowerCase();
      if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
      return sum + (Number(r.grams) || 0);
    }, 0);
    return { totalProfit, totalSold, outstanding, activeCount: activeRecords.length, totalGrams };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const toggleStatus = (status: string) => {
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));
  };

  const RANGES: { key: DateRange; label: string }[] = [
    { key: 'all', label: 'All Time' },
    { key: 'week', label: 'This Week' },
    { key: 'month', label: 'This Month' },
    { key: '3months', label: '3 Months' },
    { key: 'custom', label: 'Custom' },
  ];

  const openPrintDialog = () => {
    setSelectedPrintStatuses(new Set(statusGroups.keys()));
    setShowPrintDialog(true);
  };

  const togglePrintStatus = (status: string) => {
    setSelectedPrintStatuses(prev => {
      const next = new Set(prev);
      if (next.has(status)) next.delete(status);
      else next.add(status);
      return next;
    });
  };

  const handlePrintReport = () => {
    setShowPrintDialog(false);
    const win = window.open('', '_blank');
    if (!win) return;

    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin-bottom: 4px; font-size: 24px; color: #111; }
        .summary { margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-radius: 8px; border: 1px solid #ddd; }
        .summary p { margin: 6px 0; font-size: 14px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
        th { background: #111; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
        th.r, td.r { text-align: right; }
        td { padding: 8px; border-bottom: 1px solid #ddd; }
        .status-header { font-size: 16px; margin-top: 24px; margin-bottom: 8px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px;}
        .page-header { font-size: 13px; font-weight: bold; margin-top: 14px; margin-bottom: 4px; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; }
        .date-header { font-size: 11px; font-weight: bold; margin-top: 8px; margin-bottom: 2px; color: #555; padding: 3px 8px; background: #f0f0f0; border-left: 3px solid #C9A84C; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
      </style></head><body>

      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>

      <div class="summary">
        <p>Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></p>
        <p>Total Items Sold: ${kpis.totalSold}</p>
        <p>Outstanding Receivables: AED ${kpis.outstanding.toFixed(2)}</p>
        <p style="font-size: 11px; color: #666; font-weight: normal; margin-top: 12px;">Date Range: ${dateRangeLabel} | Generated: ${new Date().toLocaleString()}</p>
      </div>
    `;

    Array.from(statusGroups.entries())
      .filter(([status]) => selectedPrintStatuses.has(status))
      .sort((a, b) => {
        if (a[0] === 'Cancelled' || a[0] === 'Returned Item') return 1;
        if (b[0] === 'Cancelled' || b[0] === 'Returned Item') return -1;
        return a[0].localeCompare(b[0]);
      }).forEach(([status, items]) => {
        const isDeadStatus = status === 'Cancelled' || status === 'Returned Item';
        const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
        const profitText = isDeadStatus ? '' : ` | Profit: AED ${statusProfit.toFixed(2)}`;
        html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} (${items.length} items${profitText})</h2>`;

        const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
        for (const r of items) {
          let pageKey = (r.page || 'Other').trim();
          if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
          else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
          const date = formatDate(r.dateOfLive);
          if (!byPage.has(pageKey)) byPage.set(pageKey, new Map());
          const byDate = byPage.get(pageKey)!;
          if (!byDate.has(date)) byDate.set(date, []);
          byDate.get(date)!.push(r);
        }

        const profitHeader = isDeadStatus ? '' : `<th class="r">Profit (AED)</th>`;

        Array.from(byPage.entries()).sort((a, b) => {
          if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
          if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
          return a[0].localeCompare(b[0]);
        }).forEach(([page, dateMap]) => {
          html += `<div class="page-header">📄 ${page}</div>`;

          Array.from(dateMap.entries()).sort((a, b) => b[0].localeCompare(a[0])).forEach(([date, rows]) => {
            const dateProfit = rows.reduce((s, r) => s + calcProfitAED(r), 0);
            const dateProfitText = isDeadStatus ? '' : ` — Profit: AED ${dateProfit.toFixed(2)}`;
            html += `<div class="date-header">📅 ${date}${dateProfitText}</div>`;
            html += `<table><thead><tr>
              <th>Client</th><th>Item</th>
              <th class="r">Price (AED)</th><th class="r">Cost (AED)</th>
              ${profitHeader}
            </tr></thead><tbody>`;

            html += rows.map(r => {
              const profit = calcProfitAED(r);
              const profitClass = profit >= 0 ? 'profit-pos' : 'profit-neg';
              const profitCell = isDeadStatus ? '' : `<td class="r"><strong class="${profitClass}">${profit.toFixed(2)}</strong></td>`;
              return `<tr>
                <td><strong>${r.minerName || '—'}</strong></td>
                <td>${r.itemDescription || '—'}</td>
                <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
                <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
                ${profitCell}
              </tr>`;
            }).join('');

            html += `</tbody></table>`;
          });
        });
      });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <div className="flex gap-1.5 flex-wrap mb-4">
          {RANGES.map(r => (
            <Button
              key={r.key}
              size="sm"
              variant={range === r.key ? 'default' : 'outline'}
              className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
              onClick={() => setRange(r.key)}
            >
              {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
              {r.label}
            </Button>
          ))}
        </div>

        <div className="mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-44 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="grid grid-cols-1 gap-3 mb-6">
          <KpiCard title="Total Expected Profit" value={`AED ${kpis.totalProfit.toFixed(2)}`} subtitle={`${kpis.activeCount} active records (excl. Cancelled/Returned)`} highlight />
          <KpiCard title="Total Items Sold" value={kpis.totalSold.toString()} subtitle="Delivered/Given to Shop (excl. Cancelled/Returned)" />
          <KpiCard title="Total Grams Sold" value={`${kpis.totalGrams.toFixed(2)}g`} subtitle="Excl. Per PC / Screw Type / Diamond" />
          <KpiCard title="Outstanding Receivables" value={`AED ${kpis.outstanding.toFixed(2)}`} subtitle="Sum of remaining balances (excl. Cancelled/Returned)" />
        </div>

        <div className="flex items-center justify-between mb-4">
          <h2 className="font-cinzel text-lg text-primary">Detailed Breakdown</h2>
          <Button variant="outline" size="sm" className="h-8 text-xs border-primary/40 text-primary" onClick={openPrintDialog}>
            <Printer className="h-3.5 w-3.5 mr-1.5" /> Print Report
          </Button>
        </div>

        <div className="space-y-3">
          {Array.from(statusGroups.entries()).sort((a, b) => {
            if (a[0] === 'Cancelled' || a[0] === 'Returned Item') return 1;
            if (b[0] === 'Cancelled' || b[0] === 'Returned Item') return -1;
            return a[0].localeCompare(b[0]);
          }).map(([status, items]) => {
            const isDeadStatus = status === 'Cancelled' || status === 'Returned Item';
            const totalProfit = items.reduce((sum, r) => sum + calcProfitAED(r), 0);
            const groupGrams = items.reduce((sum, r) => {
              const cat = (r.category || '').toLowerCase();
              if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
              return sum + (Number(r.grams) || 0);
            }, 0);
            const isExpanded = expandedStatuses[status];

            return (
              <div key={status} className="rounded-xl border border-border bg-card overflow-hidden">
                <button
                  onClick={() => toggleStatus(status)}
                  className="w-full flex items-center justify-between p-4 text-left focus:outline-none"
                >
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <StatusBadge status={status} />
                      <span className="text-xs text-muted-foreground">{items.length} items</span>
                    </div>
                    <div className="flex flex-wrap gap-x-3 gap-y-0.5">
                      {!isDeadStatus && (
                        <p className="text-xs font-medium">
                          Profit: <span className={totalProfit >= 0 ? 'text-green-400' : 'text-destructive'}>AED {totalProfit.toFixed(2)}</span>
                        </p>
                      )}
                      {groupGrams > 0 && (
                        <p className="text-xs font-medium text-muted-foreground">
                          Grams: <span className="text-foreground">{groupGrams.toFixed(2)}g</span>
                        </p>
                      )}
                    </div>
                  </div>
                  <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {isExpanded && (() => {
                  const statusLiver = statusLiverFilters[status] || 'all';
                  const statusLiverNames = [...new Set(items.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean) as string[])].sort();
                  const visibleItems = statusLiver === 'all' ? items : items.filter(r => r.liverName?.trim().toUpperCase() === statusLiver);

                  const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
                  for (const r of visibleItems) {
                    let pageKey = (r.page || 'Other').trim();
                    if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
                    else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
                    const d = r.dateOfLive || 'Unknown Date';
                    if (!byPage.has(pageKey)) byPage.set(pageKey, new Map());
                    const byDate = byPage.get(pageKey)!;
                    if (!byDate.has(d)) byDate.set(d, []);
                    byDate.get(d)!.push(r);
                  }

                  const sortedPages = [...byPage.entries()].sort((a, b) => {
                    if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
                    if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
                    return a[0].localeCompare(b[0]);
                  });

                  return (
                    <div className="px-4 pb-4 border-t border-border pt-3 animate-in fade-in slide-in-from-top-2 duration-200">
                      {statusLiverNames.length > 1 && (
                        <div className="mb-3">
                          <Select value={statusLiver} onValueChange={v => setStatusLiverFilters(prev => ({ ...prev, [status]: v }))}>
                            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
                              <SelectValue placeholder="All Livers" />
                            </SelectTrigger>
                            <SelectContent className="bg-popover border-border">
                              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
                              {statusLiverNames.map(name => (
                                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                      <div className="space-y-4">
                        {sortedPages.map(([page, dateMap]) => {
                          const sortedDates = [...dateMap.entries()].sort((a, b) => b[0].localeCompare(a[0]));
                          return (
                            <div key={page}>
                              <div className="flex items-center gap-2 mb-2">
                                <span className="text-[10px] font-bold text-primary/70 uppercase tracking-widest">📄 {page}</span>
                                <div className="h-px flex-1 bg-border/50" />
                                <span className="text-[10px] text-muted-foreground">{Array.from(dateMap.values()).reduce((s, v) => s + v.length, 0)}</span>
                              </div>
                              <div className="space-y-3 ml-2">
                                {sortedDates.map(([date, dateItems]) => (
                                  <div key={date}>
                                    <div className="flex items-center gap-1.5 mb-1.5">
                                      <span className="text-[9px] font-semibold text-muted-foreground uppercase tracking-widest">📅 {formatDate(date)}</span>
                                      <div className="h-px flex-1 bg-border/30" />
                                      <span className="text-[9px] text-muted-foreground">{dateItems.length} · {dateItems.reduce((s, r) => { const c = (r.category||'').toLowerCase(); return c.includes('per pc')||c.includes('screw type')||c.includes('diamond') ? s : s+(Number(r.grams)||0); }, 0).toFixed(2)}g</span>
                                    </div>
                                    <div className="space-y-2 ml-2">
                                      {dateItems.map(record => {
                                        const profit = calcProfitAED(record);
                                        const cat = (record.category || '').toLowerCase();
                                        const isPc = cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond');
                                        const gramsDisplay = isPc ? 'PC' : (record.grams ? `${Number(record.grams).toFixed(2)}g` : '—');
                                        return (
                                          <div key={record.id} className="flex justify-between items-start border-b border-border/40 pb-2 last:border-0 last:pb-0">
                                            <div className="flex-1 pr-2">
                                              <div className="flex items-center gap-1.5">
                                                <p className="text-sm font-medium">{record.minerName || 'Unknown'}</p>
                                                {record.customerId && (
                                                  <button
                                                    onClick={(e) => {
                                                      e.stopPropagation();
                                                      setHistoryCustomer({ id: record.customerId!, name: record.minerName || '' });
                                                    }}
                                                    className="text-muted-foreground hover:text-primary transition-colors mt-0.5"
                                                    title="View Lifetime History"
                                                  >
                                                    <History className="h-3.5 w-3.5" />
                                                  </button>
                                                )}
                                              </div>
                                              <p className="text-xs text-muted-foreground mt-0.5 truncate">{record.itemDescription}</p>
                                            </div>
                                            <div className="text-right shrink-0 space-y-0.5">
                                              <p className="text-[10px] font-semibold text-muted-foreground">{gramsDisplay}</p>
                                              {!isDeadStatus && (
                                                <>
                                                  <p className={`text-sm font-medium ${profit >= 0 ? 'text-foreground' : 'text-destructive'}`}>AED {profit.toFixed(2)}</p>
                                                  <p className="text-[10px] text-muted-foreground">Profit</p>
                                                </>
                                              )}
                                            </div>
                                          </div>
                                        );
                                      })}
                                    </div>
                                  </div>
                                ))}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })()}
              </div>
            );
          })}

          {statusGroups.size === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No records found for this period.</p>
            </div>
          )}
        </div>
      </div>

      <Dialog open={showPrintDialog} onOpenChange={setShowPrintDialog}>
        <DialogContent className="bg-card border-border max-w-sm">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary text-base">Select Statuses to Print</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="flex gap-2 mb-2">
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set(statusGroups.keys()))}>Select All</Button>
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set())}>Clear All</Button>
            </div>
            {Array.from(statusGroups.entries()).sort((a, b) => {
              if (a[0] === 'Cancelled' || a[0] === 'Returned Item') return 1;
              if (b[0] === 'Cancelled' || b[0] === 'Returned Item') return -1;
              return a[0].localeCompare(b[0]);
            }).map(([status, items]) => (
              <div key={status} className="flex items-center gap-3">
                <Checkbox
                  id={`print-${status}`}
                  checked={selectedPrintStatuses.has(status)}
                  onCheckedChange={() => togglePrintStatus(status)}
                />
                <Label htmlFor={`print-${status}`} className="text-sm cursor-pointer flex-1">
                  {status}
                  <span className="text-xs text-muted-foreground ml-2">({items.length} items)</span>
                </Label>
              </div>
            ))}
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" className="text-xs border-border" onClick={() => setShowPrintDialog(false)}>Cancel</Button>
            <Button
              size="sm"
              className="text-xs bg-primary text-primary-foreground"
              disabled={selectedPrintStatuses.size === 0}
              onClick={handlePrintReport}
            >
              <Printer className="h-3.5 w-3.5 mr-1.5" /> Print
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {historyCustomer && (
        <CustomerHistoryModal
          customerId={historyCustomer.id}
          minerName={historyCustomer.name}
          allRecords={records}
          onClose={() => setHistoryCustomer(null)}
        />
      )}
    </div>
  );
}

