import { useState, useEffect } from 'react';
import { useDebouncedCallback } from 'use-debounce';
import { Checkbox } from '@/components/ui/checkbox';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { DatabaseRowType } from '@/types';

interface Props {
  items: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

/** Returns the AED currency label based on the group's MOP */
function dpCurrencyFromMOP(mop?: string): string {
  const m = (mop || '').toUpperCase();
  if (m.includes('AED')) return 'AED';
  if (m.includes('PHP')) return 'PHP';
  if (m.includes('USD')) return 'USD';
  return 'AED';
}

/** Finds the primary DP amount (non-acknowledged numeric value) across the group */
function getPrimaryDP(items: DatabaseRowType[]): { item: DatabaseRowType | null; amount: string } {
  for (const r of items) {
    const v = String(r.downpayment || '').trim();
    if (v && v !== 'acknowledged' && !isNaN(parseFloat(v))) {
      return { item: r, amount: v };
    }
  }
  return { item: null, amount: '' };
}

export default function GroupDownpaymentSection({ items, onUpdate }: Props) {
  const { item: primaryItem, amount: initialAmount } = getPrimaryDP(items);
  const groupIsChecked = items.some(r => {
    const v = String(r.downpayment || '').trim();
    return v !== '';
  });

  const [checked, setChecked] = useState(groupIsChecked);
  const [amount, setAmount] = useState(initialAmount);
  const [saving, setSaving] = useState(false);

  // Keep in sync if records update externally
  useEffect(() => {
    const { amount: ext } = getPrimaryDP(items);
    if (ext) setAmount(ext);
    setChecked(items.some(r => String(r.downpayment || '').trim() !== ''));
  }, [items]);

  const dpCurrency = dpCurrencyFromMOP(items[0]?.modeOfPayment);

  const saveGroupDP = useDebouncedCallback(async (val: string) => {
    // Save actual amount to first item, mark rest as acknowledged
    for (let i = 0; i < items.length; i++) {
      const dpVal = i === 0 ? val : 'acknowledged';
      await onUpdate(items[i].id, { downpayment: dpVal });
      await new Promise(res => setTimeout(res, 80));
    }
  }, 600);

  const handleCheck = async (on: boolean) => {
    setChecked(on);
    setSaving(true);
    if (!on) {
      setAmount('');
      for (const r of items) {
        await onUpdate(r.id, { downpayment: '' });
