          id={`group-dp-${items[0]?.id}`}
          checked={checked}
          disabled={saving}
          onCheckedChange={(v) => handleCheck(!!v)}
        />
        <Label htmlFor={`group-dp-${items[0]?.id}`} className="text-xs cursor-pointer font-semibold">
          Downpayment
          <span className="text-muted-foreground font-normal ml-1">
            (applies to all {items.length} item{items.length !== 1 ? 's' : ''}{invoiceNo ? ` · Invoice ${invoiceNo}` : ''})
          </span>
        </Label>
        {checked && amount && (
          <span className="text-xs text-primary font-bold ml-auto">{dpCurrency} {parseFloat(amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
        )}
      </div>
      {checked && (
        <Input
          type="number"
          value={amount}
          onChange={e => handleAmount(e.target.value)}
          className="h-8 text-xs bg-background border-border mt-2"
          placeholder={`Enter ${dpCurrency} downpayment for this group...`}
          disabled={saving}
        />
      )}
    </div>
  );
}

