// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [;
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, MapPin, Store, ChevronDown, PauseCircle, Users, Layout, Crown, BookOpen, XCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(false);
  const [showHold, setShowHold] = useState(false);
  const [showReseller, setShowReseller] = useState(false);
  const [showDispatched, setShowDispatched] = useState(false);
  const [showCancelled, setShowCancelled] = useState(false);

  const { forPullout, onHold, reseller, dispatched, cancelled } = useMemo(() => {
    const filtered = records.filter(r => {
      const s = r.status || '';
      if (!['For Pullout', 'Dispatch', 'Dispatched', 'Delivered', 'Given to Shop', 'Paid/DP but Item Hold', 'Payment for Verification', 'Reseller', 'Cancelled'].includes(s)) return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      return true;
    });
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByPageDateMiner(searched.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch')),
      onHold: groupByPageDateMiner(searched.filter(r => r.status === 'Paid/DP but Item Hold' || r.status === 'Payment for Verification')),
      reseller: groupByPageDateMiner(searched.filter(r => r.status === 'Reseller')),
      dispatched: groupByPageDateMiner(searched.filter(r => r.status === 'Dispatched' || r.status === 'Delivered' || r.status === 'Given to Shop')),
      cancelled: groupByPageDateMiner(searched.filter(r => r.status === 'Cancelled')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch').length, [records]);

  const getPageIcon = (page: string) => {
    if (page === 'MYK') return <Crown className="h-4 w-4 text-yellow-500" />;
    if (page === 'Empire Gold By ETG') return <BookOpen className="h-4 w-4 text-primary" />;
    return <Layout className="h-4 w-4 text-muted-foreground" />;
  };

  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }
    return Array.from(groupedData.entries()).map(([page, dateMap]) => {
      const totalItems = Array.from(dateMap.values()).reduce((s, m) => s + Array.from(m.values()).reduce((ss, v) => ss + v.length, 0), 0);
      return (
        <div key={page} className="mb-6">
          <div className="flex items-center gap-2 mb-3 py-2 px-3 bg-secondary/40 rounded-lg border border-primary/10">
            {getPageIcon(page)}
            <h3 className="font-cinzel text-sm text-primary tracking-wide uppercase">{page}</h3>
            <div className="h-px flex-1 bg-primary/10" />
            <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
          </div>
          <div className="pl-2 sm:pl-4 space-y-2">
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
                {Array.from(minerMap.entries()).map(([miner, items]) => (
                  <DispatchClientCard 
                    key={miner} 
                    minerName={miner} 
                    records={items} 
                    allRecords={records} 
                    onUpdate={onUpdate} 
                    userEmail={userEmail} 
                  />
                ))}
              </CollapsibleGroup>
            ))}
          </div>
        </div>
      );
    });
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">

        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPullout(!showPullout)}>
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>
        {showPullout && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(forPullout)}</div>}

        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowReseller(!showReseller)}>
          <Users className="h-4 w-4 text-teal-400" />
          <span className="font-cinzel text-xs text-teal-400 font-bold">RESELLER</span>
          <div className="h-px flex-1 bg-teal-400/30" />
          <ChevronDown className={`h-4 w-4 text-teal-400 transition-transform ${showReseller ? 'rotate-180' : ''}`} />
        </button>
        {showReseller && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(reseller)}</div>}

        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowHold(!showHold)}>
          <PauseCircle className="h-4 w-4 text-indigo-400" />
          <span className="font-cinzel text-xs text-indigo-400 font-bold">PAID/DP BUT ON HOLD</span>
          <div className="h-px flex-1 bg-indigo-400/30" />
          <ChevronDown className={`h-4 w-4 text-indigo-400 transition-transform ${showHold ? 'rotate-180' : ''}`} />
        </button>
        {showHold && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(onHold)}</div>}

        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDispatched(!showDispatched)}>
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED / DELIVERED</span>
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>
        {showDispatched && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(dispatched)}</div>}

        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowCancelled(!showCancelled)}>
          <XCircle className="h-4 w-4 text-destructive" />
          <span className="font-cinzel text-xs text-destructive font-bold">CANCELLED</span>
          <div className="h-px flex-1 bg-destructive/30" />
          <ChevronDown className={`h-4 w-4 text-destructive transition-transform ${showCancelled ? 'rotate-180' : ''}`} />
        </button>
        {showCancelled && <div className="animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(cancelled)}</div>}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import { calcRemainingBalance, parseDateRobust } from '@/lib/calculations';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus, Calendar } from 'lucide-react';
import AddClientModal from './AddClientModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' },
  { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [deliveredExpanded, setDeliveredExpanded] = useState(false);
  const [otherExpanded, setOtherExpanded] = useState(false);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    let base = records;

    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }

    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;

      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) {
          const end = new Date(to); end.setHours(23, 59, 59, 999);
          if (d.getTime() > end.getTime()) return false;
        }
        return true;
      });
    }

    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  const { deliveredGroups, otherActiveGroups, clearedGroups } = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);

    // FIX: EXCLUSION FILTER - This forces all Active, Walk-ins, and Pending to show!
    const deadStatuses = ['Cancelled', 'Returned Item'];
    const aliveRecords = searched.filter(r => !deadStatuses.includes((r.status || '').trim()));

    const active: DatabaseRowType[] = [];
    const cleared: DatabaseRowType[] = [];

    aliveRecords.forEach(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase();
      const isCleared = remStatus.includes('secured') || remStatus.includes('received') || calcRemainingBalance(r) <= 0;

      if (isCleared) {
        cleared.push(r);
      } else {
        active.push(r);
      }
    });

    const delivered = active.filter(r => r.status === 'Delivered');
    const others = active.filter(r => r.status !== 'Delivered');

    return {
      deliveredGroups: groupByPageDateMiner(delivered),
      otherActiveGroups: groupByPageDateMiner(others),
      clearedGroups: groupByPageDateMiner(cleared),
    };
  }, [filteredRecords, searchQuery]);

  const renderGroups = (groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => (
    groups.size === 0 ? (
      <div className="text-center py-10 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      <div>
        {Array.from(groups.entries()).map(([page, dateMap]) => (
          <CollapsibleGroup key={page} label={page} colorClass="text-primary/70" lineClass="bg-primary/10" defaultOpen={false}>
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
                <div className="space-y-3">
                  {Array.from(minerMap.entries()).map(([minerName, items]) => (
                    <AccountsClientCard key={minerName} minerName={minerName} records={items} allRecords={records} onUpdate={onUpdate} />
                  ))}
                </div>
              </CollapsibleGroup>
            ))}
          </CollapsibleGroup>
        ))}
      </div>
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${deliveredGroups.size + otherActiveGroups.size} active clients`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        <div className="flex flex-wrap gap-2 mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button
            onClick={() => setShowAddModal(true)}
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" />
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Active ({deliveredGroups.size + otherActiveGroups.size})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            <div className="mb-6">
              <button className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none" onClick={() => setDeliveredExpanded(!deliveredExpanded)}>
                <span className="font-cinzel text-sm font-bold text-green-500 whitespace-nowrap tracking-wide">DELIVERED</span>
                <span className="text-xs bg-green-500/10 text-green-500 px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-green-500/20">{deliveredGroups.size} pages</span>
                <div className="h-px flex-1 bg-green-500/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>
              {deliveredExpanded && <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroups(deliveredGroups)}</div>}
            </div>

            <div className="mb-4">
              <button className="flex w-full items-center gap-3 mb-3 text-left focus:outline-none" onClick={() => setOtherExpanded(!otherExpanded)}>
                <span className="font-cinzel text-sm font-bold text-primary whitespace-nowrap tracking-wide">OTHER ACTIVE (LAYAWAY/SHOP)</span>
                <span className="text-xs bg-primary/10 text-primary px-2.5 py-0.5 rounded-full font-bold whitespace-nowrap border border-primary/20">{otherActiveGroups.size} pages</span>
                <div className="h-px flex-1 bg-primary/20" />
                <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${otherExpanded ? 'rotate-180' : ''}`} />
              </button>
              {otherExpanded && <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroups(otherActiveGroups)}</div>}
            </div>
          </TabsContent>

          <TabsContent value="cleared">
            <div className="space-y-3">{renderGroups(clearedGroups)}</div>
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} existingRecords={records} />}
    </div>
  );
}

import { useState, memo, useMemo } from 'react';
import { ChevronDown, FileText, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { calcRemainingBalance, calcShippingFee, calcCCFee, calcItemPrice, calcDueDate, getQty } from '@/lib/calculations';
import { formatDateObj, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import FinancialsForm from './FinancialsForm';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function AccountsClientCard({ minerName, records, allRecords, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [expandedItem, setExpandedItem] = useState<number | null>(null);

  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));
  const totalRemaining = records.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

  // Group records by Date → Liver → Status
  const grouped = useMemo(() => {
    const byDate: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'No Date';
      const liver = r.liverName || 'Unknown Liver';
      const status = r.status || 'No Status';
      if (!byDate[date]) byDate[date] = {};
      if (!byDate[date][liver]) byDate[date][liver] = {};
      if (!byDate[date][liver][status]) byDate[date][liver][status] = [];
      byDate[date][liver][status].push(r);
    }
    return byDate;
  }, [records]);

  return (
