// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, MapPin, Users, Layout, Crown, BookOpen, XCircle, PauseCircle, ShieldCheck, CheckCircle2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';
import { ChevronDown } from 'lucide-react';

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(false);
  const [showHold, setShowHold] = useState(false);
  const [showPaymentVerif, setShowPaymentVerif] = useState(false);
  const [showReseller, setShowReseller] = useState(false);
  const [showDispatched, setShowDispatched] = useState(false);
  const [showDelivered, setShowDelivered] = useState(false);
  const [showCancelled, setShowCancelled] = useState(false);

  const { forPullout, onHold, paymentVerif, reseller, dispatched, delivered, cancelled } = useMemo(() => {
    const filtered = records.filter(r => {
      const s = r.status || '';
      if (!['For Pullout', 'Dispatch', 'Dispatched', 'Delivered', 'Given to Shop', 'Paid/DP but Item Hold', 'Payment for Verification', 'Reseller', 'Cancelled'].includes(s)) return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      return true;
    });
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByPageDateMiner(searched.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch')),
      onHold: groupByPageDateMiner(searched.filter(r => r.status === 'Paid/DP but Item Hold')),
      paymentVerif: groupByPageDateMiner(searched.filter(r => r.status === 'Payment for Verification')),
      reseller: groupByPageDateMiner(searched.filter(r => r.status === 'Reseller')),
      dispatched: groupByPageDateMiner(searched.filter(r => r.status === 'Dispatched')),
      delivered: groupByPageDateMiner(searched.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop')),
      cancelled: groupByPageDateMiner(searched.filter(r => r.status === 'Cancelled')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch').length, [records]);

  const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
    Array.from(g.values()).reduce((s, dm) =>
      s + Array.from(dm.values()).reduce((ss, mm) =>
        ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

  const getPageIcon = (page: string) => {
    if (page === 'MYK') return <Crown className="h-4 w-4 text-yellow-500" />;
    if (page === 'Empire Gold By ETG') return <BookOpen className="h-4 w-4 text-primary" />;
    return <Layout className="h-4 w-4 text-muted-foreground" />;
  };

  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }
    return Array.from(groupedData.entries()).map(([page, dateMap]) => {
      const totalItems = Array.from(dateMap.values()).reduce((s, m) => s + Array.from(m.values()).reduce((ss, v) => ss + v.length, 0), 0);
      return (
        <div key={page} className="mb-6">
          <div className="flex items-center gap-2 mb-3 py-2 px-3 bg-secondary/40 rounded-lg border border-primary/10">
            {getPageIcon(page)}
            <h3 className="font-cinzel text-sm text-primary tracking-wide uppercase">{page}</h3>
            <div className="h-px flex-1 bg-primary/10" />
            <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
          </div>
          <div className="pl-2 sm:pl-4 space-y-2">
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
                {Array.from(minerMap.entries()).map(([miner, items]) => (
                  <DispatchClientCard
                    key={miner}
                    minerName={miner}
                    records={items}
                    allRecords={records}
                    onUpdate={onUpdate}
                    userEmail={userEmail}
                  />
                ))}
              </CollapsibleGroup>
            ))}
          </div>
        </div>
      );
    });
  };

  const SectionHeader = ({
    icon, label, color, count, expanded, onToggle,
  }: {
    icon: React.ReactNode; label: string; color: string; count: number; expanded: boolean; onToggle: () => void;
  }) => (
    <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={onToggle}>
      {icon}
      <span className={`font-cinzel text-xs font-bold ${color}`}>{label}</span>
      {count > 0 && (
        <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-current/10 ${color} opacity-80`}>{count}</span>
      )}
      <div className={`h-px flex-1 opacity-30`} style={{ backgroundColor: 'currentColor' }} />
      <ChevronDown className={`h-4 w-4 ${color} transition-transform ${expanded ? 'rotate-180' : ''}`} />
    </button>
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">

        {/* FOR PULLOUT */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPullout(!showPullout)}>
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          {countItems(forPullout) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-purple-400/10 text-purple-400">{countItems(forPullout)}</span>}
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>
        {showPullout && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(forPullout)}</div>}

        {/* RESELLER */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowReseller(!showReseller)}>
          <Users className="h-4 w-4 text-teal-400" />
          <span className="font-cinzel text-xs text-teal-400 font-bold">RESELLER</span>
          {countItems(reseller) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-teal-400/10 text-teal-400">{countItems(reseller)}</span>}
          <div className="h-px flex-1 bg-teal-400/30" />
          <ChevronDown className={`h-4 w-4 text-teal-400 transition-transform ${showReseller ? 'rotate-180' : ''}`} />
        </button>
        {showReseller && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(reseller)}</div>}

        {/* PAID/DP BUT ON HOLD */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowHold(!showHold)}>
          <PauseCircle className="h-4 w-4 text-indigo-400" />
          <span className="font-cinzel text-xs text-indigo-400 font-bold">PAID/DP BUT ON HOLD</span>
          {countItems(onHold) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-indigo-400/10 text-indigo-400">{countItems(onHold)}</span>}
          <div className="h-px flex-1 bg-indigo-400/30" />
          <ChevronDown className={`h-4 w-4 text-indigo-400 transition-transform ${showHold ? 'rotate-180' : ''}`} />
        </button>
        {showHold && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(onHold)}</div>}

        {/* PAYMENT FOR VERIFICATION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPaymentVerif(!showPaymentVerif)}>
          <ShieldCheck className="h-4 w-4 text-amber-400" />
          <span className="font-cinzel text-xs text-amber-400 font-bold">PAYMENT FOR VERIFICATION</span>
          {countItems(paymentVerif) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-amber-400/10 text-amber-400">{countItems(paymentVerif)}</span>}
          <div className="h-px flex-1 bg-amber-400/30" />
          <ChevronDown className={`h-4 w-4 text-amber-400 transition-transform ${showPaymentVerif ? 'rotate-180' : ''}`} />
        </button>
        {showPaymentVerif && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(paymentVerif)}</div>}

        {/* DISPATCHED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDispatched(!showDispatched)}>
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED</span>
          {countItems(dispatched) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-orange-400/10 text-orange-400">{countItems(dispatched)}</span>}
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>
        {showDispatched && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(dispatched)}</div>}

        {/* DELIVERED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDelivered(!showDelivered)}>
          <CheckCircle2 className="h-4 w-4 text-green-400" />
          <span className="font-cinzel text-xs text-green-400 font-bold">DELIVERED</span>
          {countItems(delivered) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-green-400/10 text-green-400">{countItems(delivered)}</span>}
          <div className="h-px flex-1 bg-green-400/30" />
          <ChevronDown className={`h-4 w-4 text-green-400 transition-transform ${showDelivered ? 'rotate-180' : ''}`} />
        </button>
        {showDelivered && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(delivered)}</div>}

        {/* CANCELLED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowCancelled(!showCancelled)}>
          <XCircle className="h-4 w-4 text-destructive" />
          <span className="font-cinzel text-xs text-destructive font-bold">CANCELLED</span>
          {countItems(cancelled) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-destructive/10 text-destructive">{countItems(cancelled)}</span>}
          <div className="h-px flex-1 bg-destructive/30" />
          <ChevronDown className={`h-4 w-4 text-destructive transition-transform ${showCancelled ? 'rotate-180' : ''}`} />
        </button>
        {showCancelled && <div className="animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(cancelled)}</div>}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

