                              <Calendar className="h-3.5 w-3.5 text-orange-400" />
                              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-orange-400/20" />
                              <span className="text-[10px] font-bold bg-orange-400/20 text-orange-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {paymentVerifByDate.size > 0 && (() => {
              const isVerifExpanded = expandedDates[`verif__${pageName}`] === true;
              const totalVerif = paymentVerifItems.length;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-3 cursor-pointer"
                    onClick={() => toggleDate(`verif__${pageName}`)}
                  >
                    <ShieldCheck className="h-3.5 w-3.5 text-cyan-400" />
                    <span className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.2em] pl-1">Payment for Verification</span>
                    <div className="h-px flex-1 bg-cyan-400/20" />
                    <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalVerif}</span>
                    <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isVerifExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isVerifExpanded && (
                    <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                      {Array.from(paymentVerifByDate.entries()).map(([date, minerMap]) => {
                        const dateKey = `verif__${pageName}__${date}`;
                        const isDateExpanded = expandedDates[dateKey] === true;
                        const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                        return (
                          <div key={date} className="mb-3">
                            <div
                              className="flex items-center gap-2 py-2 px-3 bg-cyan-400/10 rounded-lg cursor-pointer mb-2 border border-cyan-400/20 hover:bg-cyan-400/15 transition-colors"
                              onClick={() => toggleDate(dateKey)}
                            >
                              <Calendar className="h-3.5 w-3.5 text-cyan-400" />
                              <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-cyan-400/20" />
                              <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {resellerGrouped.size > 0 && (() => {
              const isResellerExpanded = expandedResellers[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedResellers(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                    <div className="h-px flex-1 bg-teal-500/20" />
                    <span className="text-[10px] font-bold bg-teal-500/20 text-teal-500 px-2 py-0.5 rounded-md">{resellerGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-500 transition-transform duration-200 ${isResellerExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isResellerExpanded && Array.from(resellerGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {reviewChasingGroups.size > 0 && (() => {
              const isReviewExpanded = expandedReviewChasing[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedReviewChasing(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-yellow-400 uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                    <div className="h-px flex-1 bg-yellow-400/20" />
                    <span className="text-[10px] font-bold bg-yellow-400/20 text-yellow-400 px-2 py-0.5 rounded-md">{reviewChasingGroups.size}</span>
                    <ChevronDown className={`h-4 w-4 text-yellow-400 transition-transform duration-200 ${isReviewExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isReviewExpanded && (
                    <div className="grid grid-cols-1 gap-3">
                      {Array.from(reviewChasingGroups.entries()).map(([name, items]) => (
                        <ReviewChasingCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} />
                      ))}
                    </div>
                  )}
                </div>
              );
            })()}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Admin Pipeline" subtitle="Active Tasks & Pipeline" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <DailyRatesEditor date={new Date().toISOString().split('T')[0]} />

        {/* Pipeline Summary Strip */}
        {pipelineSummary.total > 0 && (
          <div className="flex items-center gap-1.5 flex-wrap mb-4 p-3 rounded-xl bg-secondary/30 border border-border">
            <BarChart2 className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
            <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-wide mr-1">Pipeline:</span>
            {pipelineSummary.pending > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-primary/15 text-primary border border-primary/20">
                Pending {pipelineSummary.pending}
              </span>
            )}
            {pipelineSummary.wfdp > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-400/15 text-orange-400 border border-orange-400/20">
                WFDP {pipelineSummary.wfdp}
              </span>
            )}
            {pipelineSummary.verif > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-400/15 text-cyan-400 border border-cyan-400/20">
                Verif {pipelineSummary.verif}
              </span>
            )}
            {pipelineSummary.reseller > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-teal-400/15 text-teal-400 border border-teal-400/20">
                Reseller {pipelineSummary.reseller}
              </span>
            )}
            {pipelineSummary.reviewChasing > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-yellow-400/15 text-yellow-400 border border-yellow-400/20">
                Review {pipelineSummary.reviewChasing}
              </span>
            )}
            <div className="h-px flex-1" />
            <span className="text-[10px] font-bold text-muted-foreground">{pipelineSummary.total} total</span>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>
      </div>
      <div className="px-4">
        {Object.keys(pageGroups).length > 0
          ? Object.keys(pageGroups).map(page => renderPageSection(page, pageGroups[page]))
          : (
            <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
              <p className="text-sm text-muted-foreground font-medium">No records found matching your search.</p>
            </div>
          )}
      </div>
      {showAddModal && <AddClientModal onClose={() => setShowAddModal(false)} userFirstName={userFirstName} userEmail={userEmail} onRefresh={onRefresh} existingRecords={records} />}
    </div>
  );
}

