import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import { calcRemainingBalance, parseDateRobust } from '@/lib/calculations';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus, Calendar, TrendingDown, Package, Users, ShieldCheck, CheckCircle2 } from 'lucide-react';
import AddClientModal from './AddClientModal';

// ─── ACCOUNTS SCOPE ───────────────────────────────────────────────────────────
// Accounts ONLY handles records that have cleared the dispatch pipeline.
// Pre-dispatch statuses (Pending, WFDP, For Pullout, Dispatched, Hold) are
// dispatch/admin concerns — the accounts team must NOT see them here.
const ACCOUNTS_STATUSES = ['Delivered', 'Given to Shop', 'Payment for Verification'];

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' },
  { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [verifExpanded, setVerifExpanded] = useState(true);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(
      records
        .filter(r => ACCOUNTS_STATUSES.includes(r.status || ''))
        .map(r => r.liverName?.trim().toUpperCase())
        .filter(Boolean)
    )) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    // Only accounts-relevant records
    let base = records.filter(r => ACCOUNTS_STATUSES.includes(r.status || ''));

    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }

    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;
      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) {
          const end = new Date(to); end.setHours(23, 59, 59, 999);
          if (d.getTime() > end.getTime()) return false;
        }
        return true;
      });
    }

    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  const { verifGroups, deliveredGroups, clearedGroups, activeRecords } = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);

    const active: DatabaseRowType[] = [];
    const cleared: DatabaseRowType[] = [];

    searched.forEach(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase().trim();
      const remittanceConfirmed = remStatus.includes('secured') || remStatus.includes('received');
      const balanceZero = calcRemainingBalance(r) <= 0;
      const isPendingRemittance = remStatus === '' || remStatus === 'pending' || remStatus === 'n/a';
      // Only clear if remittance explicitly confirmed, OR zero balance with a non-pending remittance status
      const isCleared = remittanceConfirmed || (balanceZero && !isPendingRemittance);
      if (isCleared) cleared.push(r);
      else active.push(r);
    });

    // Payment for Verification — urgent: needs accounts to check
    const verif = active.filter(r => r.status === 'Payment for Verification');
    // Delivered / Given to Shop — main accounts work
    const delivered = active.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    return {
      verifGroups: groupByPageDateMiner(verif),
      deliveredGroups: groupByPageDateMiner(delivered),
      clearedGroups: groupByPageDateMiner(cleared),
      activeRecords: active,
    };
  }, [filteredRecords, searchQuery]);

  const totalOutstanding = useMemo(() =>
    activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0),
    [activeRecords]
  );

  const activeClientCount = useMemo(() => {
    const names = new Set(activeRecords.map(r => r.minerName || '').filter(Boolean));
    return names.size;
  }, [activeRecords]);

  const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
    Array.from(g.values()).reduce((s, dm) =>
      s + Array.from(dm.values()).reduce((ss, mm) =>
        ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

  const renderGroups = (groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => (
    groups.size === 0 ? (
      <div className="text-center py-8 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      <div>
        {Array.from(groups.entries()).map(([page, dateMap]) => (
          <CollapsibleGroup key={page} label={page} colorClass="text-primary/70" lineClass="bg-primary/10" defaultOpen={false}>
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
                <div className="space-y-3">
                  {Array.from(minerMap.entries()).map(([minerName, items]) => (
                    <AccountsClientCard key={minerName} minerName={minerName} records={items} allRecords={records} onUpdate={onUpdate} />
                  ))}
                </div>
              </CollapsibleGroup>
            ))}
          </CollapsibleGroup>
        ))}
      </div>
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeClientCount} clients with outstanding balance`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* Filters */}
        <div className="flex flex-wrap gap-2 mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button
            onClick={() => setShowAddModal(true)}
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" />
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Outstanding ({activeRecords.length})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* Summary Strip */}
            <div className="grid grid-cols-3 gap-2 mb-5">
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Users className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Clients</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeClientCount}</span>
              </div>
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Package className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Items</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeRecords.length}</span>
              </div>
              <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-destructive/70">
                  <TrendingDown className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Due</span>
                </div>
                <span className="text-sm font-bold text-destructive font-cinzel leading-tight">
                  {totalOutstanding > 0 ? `AED ${totalOutstanding.toFixed(0)}` : 'AED 0'}
                </span>
              </div>
            </div>

            {/* PAYMENT FOR VERIFICATION — urgent action section */}
            {verifGroups.size > 0 && (
              <div className="mb-5">
                <button
                  className="flex w-full items-center gap-2 mb-3 p-3 rounded-lg bg-amber-500/8 border border-amber-500/30 text-left focus:outline-none hover:bg-amber-500/12 transition-colors"
                  onClick={() => setVerifExpanded(!verifExpanded)}
                >
                  <ShieldCheck className="h-4 w-4 text-amber-400 shrink-0" />
                  <span className="font-cinzel text-sm font-bold text-amber-400 tracking-wide">PAYMENT FOR VERIFICATION</span>
                  <span className="text-[11px] bg-amber-400/15 text-amber-400 px-2 py-0.5 rounded-full font-bold border border-amber-400/20">
                    {countItems(verifGroups)} items
                  </span>
                  <div className="h-px flex-1 bg-amber-400/20" />
                  <ChevronDown className={`h-4 w-4 text-amber-400/70 transition-transform shrink-0 ${verifExpanded ? 'rotate-180' : ''}`} />
                </button>
                {verifExpanded && (
                  <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                    {renderGroups(verifGroups)}
                  </div>
                )}
              </div>
            )}

            {/* DELIVERED / GIVEN TO SHOP — main accounts work */}
            <div className="mb-4">
              <button
                className="flex w-full items-center gap-2 mb-3 p-3 rounded-lg bg-green-500/5 border border-green-500/20 text-left focus:outline-none hover:bg-green-500/10 transition-colors"
                onClick={() => setDeliveredExpanded(!deliveredExpanded)}
              >
                <CheckCircle2 className="h-4 w-4 text-green-500 shrink-0" />
                <span className="font-cinzel text-sm font-bold text-green-500 tracking-wide">DELIVERED / GIVEN TO SHOP</span>
                <span className="text-[11px] bg-green-500/15 text-green-500 px-2 py-0.5 rounded-full font-bold border border-green-500/20">
                  {deliveredGroups.size} pages · {countItems(deliveredGroups)} items
                </span>
                <div className="h-px flex-1 bg-green-500/15" />
                <ChevronDown className={`h-4 w-4 text-green-500/70 transition-transform shrink-0 ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>
              {deliveredExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(deliveredGroups)}
                </div>
              )}
            </div>

            {activeRecords.length === 0 && (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <CheckCircle2 className="h-8 w-8 text-green-500/40 mx-auto mb-2" />
                <p className="text-sm text-muted-foreground font-medium">All clear! No outstanding balances.</p>
              </div>
            )}
          </TabsContent>

          <TabsContent value="cleared">
            {clearedGroups.size === 0 ? (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No cleared records yet.</p>
              </div>
            ) : (
              <div className="space-y-3">{renderGroups(clearedGroups)}</div>
            )}
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && (
        <AddClientModal
          onClose={() => setShowAddModal(false)}
          userFirstName={userFirstName}
          userEmail={userEmail}
          onRefresh={onRefresh}
          existingRecords={records}
        />
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer, History, TrendingUp } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { TabProps, DatabaseRowType } from '@/types';
import {
  calcProfitAED,
  calcRemainingBalance,
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

// Status display order: most business-important first
const STATUS_SORT: Record<string, number> = {
  'Delivered': 1,
  'Given to Shop': 2,
  'Dispatched': 3,
  'Payment for Verification': 4,
  'Paid/DP but Item Hold': 5,
  'For Pullout': 6,
  'Dispatch': 7,
  'Reseller': 8,
  'Pending': 9,
  'Waiting for Details': 10,
  'Waiting for Downpayment': 11,
  'Returned Item': 12,
  'Cancelled': 13,
};

const DEAD_STATUSES = new Set(['Cancelled', 'Returned Item']);

const RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All Time' },
  { key: 'week', label: 'This Week' },
  { key: 'month', label: 'This Month' },
  { key: '3months', label: '3 Months' },
  { key: 'custom', label: 'Custom' },
];

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [selectedPrintStatuses, setSelectedPrintStatuses] = useState<Set<string>>(new Set());
  const [historyCustomer, setHistoryCustomer] = useState<{ id: string, name: string } | null>(null);

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    if (range === 'all') return records;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return records.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      const t = d.getTime();
      if (t < from.getTime()) return false;
      if (to) {
        const end = new Date(to); end.setHours(23, 59, 59, 999);
        if (t > end.getTime()) return false;
      }
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    const activeRecords = filtered.filter(r => !DEAD_STATUSES.has(r.status || ''));
    const deliveredRecords = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');
    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const confirmedProfit = deliveredRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = deliveredRecords.length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    const totalGrams = activeRecords.reduce((sum, r) => {
      const cat = (r.category || '').toLowerCase();
      if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
      return sum + (Number(r.grams) || 0);
    }, 0);
    return { totalProfit, confirmedProfit, totalSold, outstanding, activeCount: activeRecords.length, totalGrams };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const sortedStatusEntries = useMemo(() =>
    [...statusGroups.entries()].sort((a, b) => {
      const ao = STATUS_SORT[a[0]] ?? 99;
      const bo = STATUS_SORT[b[0]] ?? 99;
      return ao - bo;
    }),
    [statusGroups]
  );

  const toggleStatus = (status: string) =>
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));

  const toggleDate = (key: string) =>
    setCollapsedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const openPrintDialog = () => {
    setSelectedPrintStatuses(new Set(statusGroups.keys()));
    setShowPrintDialog(true);
  };

  const togglePrintStatus = (status: string) => {
    setSelectedPrintStatuses(prev => {
      const next = new Set(prev);
      if (next.has(status)) next.delete(status); else next.add(status);
      return next;
    });
  };

  const handlePrintReport = () => {
    setShowPrintDialog(false);
    const win = window.open('', '_blank');
    if (!win) return;
    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';
    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        body { font-family: sans-serif; color: #111; background: #fff; margin: 0; padding: 24px; font-size: 12px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin-bottom: 4px; font-size: 24px; color: #111; }
        .summary { margin-bottom: 24px; padding: 16px; background: #f9f9f9; border-radius: 8px; border: 1px solid #ddd; }
        .summary p { margin: 6px 0; font-size: 14px; font-weight: bold; }
        table { width: 100%; border-collapse: collapse; margin-bottom: 32px; }
        th { background: #111; color: #fff; padding: 8px; text-align: left; font-size: 11px; }
        th.r, td.r { text-align: right; }
        td { padding: 8px; border-bottom: 1px solid #ddd; }
        .status-header { font-size: 16px; margin-top: 24px; margin-bottom: 8px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px;}
        .page-header { font-size: 13px; font-weight: bold; margin-top: 14px; margin-bottom: 4px; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; }
        .date-header { font-size: 11px; font-weight: bold; margin-top: 8px; margin-bottom: 2px; color: #555; padding: 3px 8px; background: #f0f0f0; border-left: 3px solid #C9A84C; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
      </style></head><body>
      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>
      <div class="summary">
        <p>Confirmed Delivered Profit: <span class="profit-pos">AED ${kpis.confirmedProfit.toFixed(2)}</span></p>
        <p>Total Expected Profit (All Active): <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></p>
        <p>Total Items Delivered: ${kpis.totalSold}</p>
        <p>Outstanding Receivables: AED ${kpis.outstanding.toFixed(2)}</p>
        <p style="font-size: 11px; color: #666; font-weight: normal; margin-top: 12px;">Date Range: ${dateRangeLabel} | Generated: ${new Date().toLocaleString()}</p>
      </div>
    `;
    [...statusGroups.entries()]
      .filter(([status]) => selectedPrintStatuses.has(status))
      .sort((a, b) => (STATUS_SORT[a[0]] ?? 99) - (STATUS_SORT[b[0]] ?? 99))
      .forEach(([status, items]) => {
        const isDead = DEAD_STATUSES.has(status);
        const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);
        const profitText = isDead ? '' : ` | Profit: AED ${statusProfit.toFixed(2)}`;
        html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} (${items.length} items${profitText})</h2>`;
        const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
        for (const r of items) {
          let pk = (r.page || 'Other').trim();
          if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
          else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
          const date = formatDate(r.dateOfLive);
          if (!byPage.has(pk)) byPage.set(pk, new Map());
          const bd = byPage.get(pk)!;
          if (!bd.has(date)) bd.set(date, []);
          bd.get(date)!.push(r);
        }
        const profitHeader = isDead ? '' : `<th class="r">Profit (AED)</th>`;
        [...byPage.entries()].sort((a, b) => {
          if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
          if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
          return a[0].localeCompare(b[0]);
        }).forEach(([page, dateMap]) => {
          html += `<div class="page-header">📄 ${page}</div>`;
          [...dateMap.entries()].sort((a, b) => b[0].localeCompare(a[0])).forEach(([date, rows]) => {
            const dp = rows.reduce((s, r) => s + calcProfitAED(r), 0);
            const dpt = isDead ? '' : ` — Profit: AED ${dp.toFixed(2)}`;
            html += `<div class="date-header">📅 ${date}${dpt}</div>`;
            html += `<table><thead><tr><th>Client</th><th>Item</th><th class="r">Price (AED)</th><th class="r">Cost (AED)</th>${profitHeader}</tr></thead><tbody>`;
            html += rows.map(r => {
              const pr = calcProfitAED(r);
              const pc = pr >= 0 ? 'profit-pos' : 'profit-neg';
              const pCell = isDead ? '' : `<td class="r"><strong class="${pc}">${pr.toFixed(2)}</strong></td>`;
              return `<tr><td><strong>${r.minerName || '—'}</strong></td><td>${r.itemDescription || '—'}</td><td class="r">${calcItemPriceAED(r).toFixed(2)}</td><td class="r">${calcItemCostAED(r).toFixed(2)}</td>${pCell}</tr>`;
            }).join('');
            html += `</tbody></table>`;
          });
        });
      });
    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">

        {/* Filters Row */}
        <div className="flex flex-wrap items-center gap-2 mb-4">
          <div className="flex gap-1 flex-wrap flex-1">
            {RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={range === r.key ? 'default' : 'outline'}
                className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-7 text-xs w-36 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        {/* KPI Grid */}
        <div className="grid grid-cols-2 gap-3 mb-6">
          {/* Confirmed Delivered Profit — most important KPI */}
          <div className="col-span-2 rounded-xl border border-primary/40 bg-primary/5 p-4 flex flex-col gap-1">
            <div className="flex items-center gap-1.5">
              <TrendingUp className="h-3.5 w-3.5 text-primary" />
              <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Confirmed Profit (Delivered)</p>
            </div>
            <p className="text-2xl font-bold font-cinzel text-primary leading-none">AED {kpis.confirmedProfit.toFixed(2)}</p>
            <p className="text-[10px] text-muted-foreground">{kpis.totalSold} items delivered · All-active: AED {kpis.totalProfit.toFixed(2)}</p>
          </div>
          <KpiCard title="Total Grams" value={`${kpis.totalGrams.toFixed(2)}g`} subtitle="Excl. PC / Screw / Diamond" />
          <KpiCard title="Outstanding" value={`AED ${kpis.outstanding.toFixed(0)}`} subtitle="Remaining receivables" />
        </div>

        {/* Detailed Breakdown header */}
        <div className="flex items-center justify-between mb-3">
          <h2 className="font-cinzel text-base text-primary">Breakdown by Status</h2>
          <Button variant="outline" size="sm" className="h-8 text-xs border-primary/40 text-primary" onClick={openPrintDialog}>
            <Printer className="h-3.5 w-3.5 mr-1.5" /> Print Report
          </Button>
        </div>

        <div className="space-y-2">
          {sortedStatusEntries.map(([status, items]) => {
            const isDead = DEAD_STATUSES.has(status);
            const totalProfit = items.reduce((sum, r) => sum + calcProfitAED(r), 0);
            const groupGrams = items.reduce((sum, r) => {
              const cat = (r.category || '').toLowerCase();
              if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
              return sum + (Number(r.grams) || 0);
            }, 0);
            const isExpanded = expandedStatuses[status];

            return (
              <div key={status} className="rounded-xl border border-border bg-card overflow-hidden">
                <button
                  onClick={() => toggleStatus(status)}
                  className="w-full flex items-center justify-between px-4 py-3 text-left focus:outline-none"
                >
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <StatusBadge status={status} />
                    <span className="text-xs text-muted-foreground shrink-0">{items.length} items</span>
                    {!isDead && (
                      <span className={`text-xs font-semibold ${totalProfit >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                        AED {totalProfit.toFixed(2)}
                      </span>
                    )}
                    {groupGrams > 0 && (
                      <span className="text-xs text-muted-foreground hidden sm:inline">{groupGrams.toFixed(2)}g</span>
                    )}
                  </div>
                  <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform shrink-0 ml-2 ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {isExpanded && (() => {
                  const statusLiver = statusLiverFilters[status] || 'all';
                  const statusLiverNames = [...new Set(items.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean) as string[])].sort();
                  const visibleItems = statusLiver === 'all' ? items : items.filter(r => r.liverName?.trim().toUpperCase() === statusLiver);

                  const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
                  for (const r of visibleItems) {
                    let pk = (r.page || 'Other').trim();
                    if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
                    else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
                    const d = r.dateOfLive || 'Unknown Date';
                    if (!byPage.has(pk)) byPage.set(pk, new Map());
                    const bd = byPage.get(pk)!;
                    if (!bd.has(d)) bd.set(d, []);
                    bd.get(d)!.push(r);
                  }
                  const sortedPages = [...byPage.entries()].sort((a, b) => {
                    if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
                    if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
                    return a[0].localeCompare(b[0]);
                  });

                  return (
                    <div className="px-4 pb-4 border-t border-border pt-3 animate-in fade-in slide-in-from-top-2 duration-200">
                      {statusLiverNames.length > 1 && (
                        <div className="mb-3">
                          <Select value={statusLiver} onValueChange={v => setStatusLiverFilters(prev => ({ ...prev, [status]: v }))}>
                            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
                              <SelectValue placeholder="All Livers" />
                            </SelectTrigger>
                            <SelectContent className="bg-popover border-border">
                              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
                              {statusLiverNames.map(name => (
                                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                      <div className="space-y-4">
                        {sortedPages.map(([page, dateMap]) => {
                          const sortedDates = [...dateMap.entries()].sort((a, b) => b[0].localeCompare(a[0]));
                          return (
                            <div key={page}>
                              <div className="flex items-center gap-2 mb-2">
                                <span className="text-[10px] font-bold text-primary/70 uppercase tracking-widest">📄 {page}</span>
                                <div className="h-px flex-1 bg-border/50" />
                                <span className="text-[10px] text-muted-foreground">{Array.from(dateMap.values()).reduce((s, v) => s + v.length, 0)}</span>
                              </div>
                              <div className="space-y-2 ml-2">
                                {sortedDates.map(([date, dateItems]) => {
                                  const dateKey = `${status}__${page}__${date}`;
                                  const isDateCollapsed = collapsedDates[dateKey];
                                  const dg = dateItems.reduce((s, r) => {
                                    const c = (r.category || '').toLowerCase();
                                    return c.includes('per pc') || c.includes('screw type') || c.includes('diamond') ? s : s + (Number(r.grams) || 0);
                                  }, 0);
                                  const dp = dateItems.reduce((s, r) => s + calcProfitAED(r), 0);

                                  return (
                                    <div key={date} className="rounded-lg border border-border/50 overflow-hidden">
                                      <button
                                        onClick={() => toggleDate(dateKey)}
                                        className="w-full flex items-center justify-between px-3 py-2 bg-muted/40 hover:bg-muted/60 transition-colors text-left focus:outline-none"
                                      >
                                        <div className="flex items-center gap-2">
                                          <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">📅 {formatDate(date)}</span>
                                          <span className="text-[9px] text-muted-foreground bg-border/50 px-1.5 py-0.5 rounded-full">
                                            {dateItems.length} item{dateItems.length !== 1 ? 's' : ''}{dg > 0 ? ` · ${dg.toFixed(2)}g` : ''}
                                          </span>
                                          {!isDead && (
                                            <span className={`text-[9px] font-semibold ${dp >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                                              AED {dp.toFixed(2)}
                                            </span>
                                          )}
                                        </div>
                                        <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${isDateCollapsed ? '' : 'rotate-180'}`} />
                                      </button>

                                      {!isDateCollapsed && (
                                        <div className="px-3 py-2 space-y-2">
                                          {dateItems.map(record => {
                                            const profit = calcProfitAED(record);
                                            const cat = (record.category || '').toLowerCase();
                                            const isPc = cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond');
                                            const gramsDisplay = isPc ? 'PC' : (record.grams ? `${Number(record.grams).toFixed(2)}g` : '—');
                                            return (
                                              <div key={record.id} className="flex justify-between items-start border-b border-border/40 pb-2 last:border-0 last:pb-0">
                                                <div className="flex-1 pr-2">
                                                  <div className="flex items-center gap-1.5">
                                                    <p className="text-sm font-medium">{record.minerName || 'Unknown'}</p>
                                                    {record.customerId && (
                                                      <button
                                                        onClick={e => { e.stopPropagation(); setHistoryCustomer({ id: record.customerId!, name: record.minerName || '' }); }}
                                                        className="text-muted-foreground hover:text-primary transition-colors"
                                                        title="View Lifetime History"
                                                      >
                                                        <History className="h-3.5 w-3.5" />
                                                      </button>
                                                    )}
                                                  </div>
                                                  <p className="text-xs text-muted-foreground mt-0.5 truncate">{record.itemDescription}</p>
                                                </div>
                                                <div className="text-right shrink-0 space-y-0.5">
                                                  <p className="text-[10px] font-semibold text-muted-foreground">{gramsDisplay}</p>
                                                  {!isDead && (
                                                    <>
                                                      <p className={`text-sm font-medium ${profit >= 0 ? 'text-foreground' : 'text-destructive'}`}>AED {profit.toFixed(2)}</p>
                                                      <p className="text-[10px] text-muted-foreground">Profit</p>
                                                    </>
                                                  )}
                                                </div>
                                              </div>
                                            );
                                          })}
                                        </div>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })()}
              </div>
            );
          })}

          {statusGroups.size === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No records found for this period.</p>
            </div>
          )}
        </div>
      </div>

      {/* Print Dialog */}
      <Dialog open={showPrintDialog} onOpenChange={setShowPrintDialog}>
        <DialogContent className="bg-card border-border max-w-sm">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary text-base">Select Statuses to Print</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="flex gap-2 mb-2">
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set(statusGroups.keys()))}>Select All</Button>
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set())}>Clear All</Button>
            </div>
            {sortedStatusEntries.map(([status, items]) => (
              <div key={status} className="flex items-center gap-3">
                <Checkbox id={`print-${status}`} checked={selectedPrintStatuses.has(status)} onCheckedChange={() => togglePrintStatus(status)} />
                <Label htmlFor={`print-${status}`} className="text-sm cursor-pointer flex-1">
                  {status}
                  <span className="text-xs text-muted-foreground ml-2">({items.length} items)</span>
                </Label>
              </div>
            ))}
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" className="text-xs border-border" onClick={() => setShowPrintDialog(false)}>Cancel</Button>
            <Button size="sm" className="text-xs bg-primary text-primary-foreground" disabled={selectedPrintStatuses.size === 0} onClick={handlePrintReport}>
              <Printer className="h-3.5 w-3.5 mr-1.5" /> Print
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {historyCustomer && (
        <CustomerHistoryModal
          customerId={historyCustomer.id}
          minerName={historyCustomer.name}
          allRecords={records}
          onClose={() => setHistoryCustomer(null)}
        />
      )}
    </div>
  );
}

