import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import { calcRemainingBalance, parseDateRobust } from '@/lib/calculations';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import { ChevronDown, Plus, Calendar, TrendingDown, Package, Users, ShieldCheck, CheckCircle2, Clock } from 'lucide-react';
import AddClientModal from './AddClientModal';

// ─── ACCOUNTS SCOPE ───────────────────────────────────────────────────────────
// Accounts tracks all records where money is owed or being collected:
//   • Delivered / Given to Shop  — item delivered, chase payment & remittance
//   • Paid/DP but Item Hold      — DP collected, tracking installment/layaway
//   • Dispatched                 — in transit; layaway balances still outstanding
//   • Payment for Verification   — screenshot received, needs accounts to verify
// Excluded: pre-delivery admin/dispatch stages (Pending, WFDP, For Pullout, etc.)
const ACCOUNTS_STATUSES = [
  'Delivered',
  'Given to Shop',
  'Paid/DP but Item Hold',
  'Dispatched',
  'Payment for Verification',
];

// A record qualifies for accounts if its status is in scope, OR if it's a
// layaway order (modeOfPayment === 'Layaway') that has any payment recorded —
// because layaway payments must be tracked regardless of dispatch status.
function isAccountsRelevant(r: DatabaseRowType): boolean {
  const status = r.status || '';
  if (status === 'Cancelled' || status === 'Returned Item') return false;
  if (ACCOUNTS_STATUSES.includes(status)) return true;
  // Include layaway records that have at least one payment recorded
  const mop = (r.modeOfPayment || '').toLowerCase();
  if (mop === 'layaway') {
    const hasPayment =
      Number(r.downpayment) > 0 ||
      Number(r.la1MonthPayment) > 0 ||
      Number(r.la2MonthPayment) > 0 ||
      Number(r.la3MonthPayment) > 0 ||
      Number(r.la4MonthPayment) > 0 ||
      Number(r.amountReceived) > 0;
    return hasPayment;
  }
  return false;
}

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' },
  { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' },
  { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [verifExpanded, setVerifExpanded] = useState(true);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [layawayExpanded, setLayawayExpanded] = useState(true);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(
      records.filter(isAccountsRelevant).map(r => r.liverName?.trim().toUpperCase()).filter(Boolean)
    )) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    let base = records.filter(isAccountsRelevant);

    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }

    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;
      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) {
          const end = new Date(to); end.setHours(23, 59, 59, 999);
          if (d.getTime() > end.getTime()) return false;
        }
        return true;
      });
    }

    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  const { verifGroups, deliveredGroups, layawayGroups, clearedGroups, activeRecords } = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);

    const active: DatabaseRowType[] = [];
    const cleared: DatabaseRowType[] = [];

    searched.forEach(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase().trim();
      const remittanceConfirmed = remStatus.includes('secured') || remStatus.includes('received');
      const balanceZero = calcRemainingBalance(r) <= 0;
      const isPendingRemittance = remStatus === '' || remStatus === 'pending' || remStatus === 'n/a';
      const isCleared = remittanceConfirmed || (balanceZero && !isPendingRemittance);
      if (isCleared) cleared.push(r);
      else active.push(r);
    });

    // Payment for Verification — needs immediate accounts action
    const verif = active.filter(r => r.status === 'Payment for Verification');

    // Delivered / Given to Shop — main remittance tracking
    const delivered = active.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    // Layaway / On Hold / Dispatched — installment payment tracking
    const layaway = active.filter(r =>
      r.status === 'Paid/DP but Item Hold' ||
      r.status === 'Dispatched' ||
      (r.modeOfPayment || '').toLowerCase() === 'layaway' && r.status !== 'Delivered' && r.status !== 'Given to Shop' && r.status !== 'Payment for Verification'
    );

    return {
      verifGroups: groupByPageDateMiner(verif),
      deliveredGroups: groupByPageDateMiner(delivered),
      layawayGroups: groupByPageDateMiner(layaway),
      clearedGroups: groupByPageDateMiner(cleared),
      activeRecords: active,
    };
  }, [filteredRecords, searchQuery]);

  const totalOutstanding = useMemo(() =>
    activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0),
    [activeRecords]
  );

  const activeClientCount = useMemo(() => {
    const names = new Set(activeRecords.map(r => r.minerName || '').filter(Boolean));
    return names.size;
  }, [activeRecords]);

  const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
    Array.from(g.values()).reduce((s, dm) =>
      s + Array.from(dm.values()).reduce((ss, mm) =>
        ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

  const renderGroups = (groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) => (
    groups.size === 0 ? (
      <div className="text-center py-8 text-muted-foreground text-sm border border-dashed border-border rounded-lg mt-2">
        No records found in this section.
      </div>
    ) : (
      <div>
        {Array.from(groups.entries()).map(([page, dateMap]) => (
          <CollapsibleGroup key={page} label={page} colorClass="text-primary/70" lineClass="bg-primary/10" defaultOpen={false}>
            {Array.from(dateMap.entries()).map(([date, minerMap]) => (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
                <div className="space-y-3">
                  {Array.from(minerMap.entries()).map(([minerName, items]) => (
                    <AccountsClientCard key={minerName} minerName={minerName} records={items} allRecords={records} onUpdate={onUpdate} />
                  ))}
                </div>
              </CollapsibleGroup>
            ))}
          </CollapsibleGroup>
        ))}
      </div>
    )
  );

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeClientCount} clients with outstanding balance`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* Filters */}
        <div className="flex flex-wrap gap-2 mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button
            onClick={() => setShowAddModal(true)}
            className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm"
          >
            <Plus className="h-4 w-4 mr-1.5" />
            Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Outstanding ({activeRecords.length})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* Summary Strip */}
            <div className="grid grid-cols-3 gap-2 mb-5">
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Users className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Clients</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeClientCount}</span>
              </div>
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Package className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Items</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeRecords.length}</span>
              </div>
              <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-destructive/70">
                  <TrendingDown className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Due</span>
                </div>
                <span className="text-sm font-bold text-destructive font-cinzel leading-tight">
                  {totalOutstanding > 0 ? `AED ${totalOutstanding.toFixed(0)}` : 'AED 0'}
                </span>
              </div>
            </div>

            {/* 1. PAYMENT FOR VERIFICATION — urgent, act now */}
            {verifGroups.size > 0 && (
              <div className="mb-4">
                <button
                  className="flex w-full items-center gap-2 mb-3 p-3 rounded-lg border border-amber-500/30 bg-amber-500/5 text-left focus:outline-none hover:bg-amber-500/10 transition-colors"
                  onClick={() => setVerifExpanded(!verifExpanded)}
                >
                  <ShieldCheck className="h-4 w-4 text-amber-400 shrink-0" />
                  <span className="font-cinzel text-sm font-bold text-amber-400 tracking-wide">PAYMENT FOR VERIFICATION</span>
                  <span className="text-[11px] bg-amber-400/15 text-amber-400 px-2 py-0.5 rounded-full font-bold border border-amber-400/20">
                    {countItems(verifGroups)} items
                  </span>
                  <div className="h-px flex-1 bg-amber-400/20" />
                  <ChevronDown className={`h-4 w-4 text-amber-400/70 transition-transform shrink-0 ${verifExpanded ? 'rotate-180' : ''}`} />
                </button>
                {verifExpanded && (
                  <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                    {renderGroups(verifGroups)}
                  </div>
                )}
              </div>
            )}

            {/* 2. LAYAWAY / ON HOLD — installment tracking */}
            {layawayGroups.size > 0 && (
              <div className="mb-4">
                <button
                  className="flex w-full items-center gap-2 mb-3 p-3 rounded-lg border border-indigo-400/30 bg-indigo-400/5 text-left focus:outline-none hover:bg-indigo-400/10 transition-colors"
                  onClick={() => setLayawayExpanded(!layawayExpanded)}
                >
                  <Clock className="h-4 w-4 text-indigo-400 shrink-0" />
                  <span className="font-cinzel text-sm font-bold text-indigo-400 tracking-wide">LAYAWAY / ON HOLD</span>
                  <span className="text-[11px] bg-indigo-400/15 text-indigo-400 px-2 py-0.5 rounded-full font-bold border border-indigo-400/20">
                    {layawayGroups.size} pages · {countItems(layawayGroups)} items
                  </span>
                  <div className="h-px flex-1 bg-indigo-400/20" />
                  <ChevronDown className={`h-4 w-4 text-indigo-400/70 transition-transform shrink-0 ${layawayExpanded ? 'rotate-180' : ''}`} />
                </button>
                {layawayExpanded && (
                  <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                    {renderGroups(layawayGroups)}
                  </div>
                )}
              </div>
            )}

            {/* 3. DELIVERED / GIVEN TO SHOP — main remittance work */}
            <div className="mb-4">
              <button
                className="flex w-full items-center gap-2 mb-3 p-3 rounded-lg border border-green-500/20 bg-green-500/5 text-left focus:outline-none hover:bg-green-500/10 transition-colors"
                onClick={() => setDeliveredExpanded(!deliveredExpanded)}
              >
                <CheckCircle2 className="h-4 w-4 text-green-500 shrink-0" />
                <span className="font-cinzel text-sm font-bold text-green-500 tracking-wide">DELIVERED / GIVEN TO SHOP</span>
                <span className="text-[11px] bg-green-500/15 text-green-500 px-2 py-0.5 rounded-full font-bold border border-green-500/20">
                  {deliveredGroups.size} pages · {countItems(deliveredGroups)} items
                </span>
                <div className="h-px flex-1 bg-green-500/15" />
                <ChevronDown className={`h-4 w-4 text-green-500/70 transition-transform shrink-0 ${deliveredExpanded ? 'rotate-180' : ''}`} />
              </button>
              {deliveredExpanded && (
                <div className="space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">
                  {renderGroups(deliveredGroups)}
                </div>
              )}
            </div>

            {activeRecords.length === 0 && (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <CheckCircle2 className="h-8 w-8 text-green-500/40 mx-auto mb-2" />
                <p className="text-sm text-muted-foreground font-medium">All clear! No outstanding balances.</p>
              </div>
            )}
          </TabsContent>

          <TabsContent value="cleared">
            {clearedGroups.size === 0 ? (
              <div className="text-center py-16 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No cleared records yet.</p>
              </div>
            ) : (
              <div className="space-y-3">{renderGroups(clearedGroups)}</div>
            )}
          </TabsContent>
        </Tabs>
      </div>

      {showAddModal && (
        <AddClientModal
          onClose={() => setShowAddModal(false)}
          userFirstName={userFirstName}
          userEmail={userEmail}
          onRefresh={onRefresh}
          existingRecords={records}
        />
      )}
    </div>
  );
}

/**
 * Historical Rate Locking Store
 *
 * All dates are normalized to YYYY-MM-DD before being used as localStorage keys.
 * This ensures that "02/27/2026", "February 27, 2026", "Feb 27, 2026", and "2026-02-27"
 * all map to the same key: rates_2026-02-27.
 */

export interface RateSnapshot {
  phpRate: number;
  silverSellRate: number;
  silverCostRate: number;
  silverBrandedSellRate: number;
  silverBrandedCostRate: number;
}

export const DEFAULT_RATES: RateSnapshot = {
  phpRate: 16.7,
  silverSellRate: 45,
  silverCostRate: 15,
  silverBrandedSellRate: 60,
  silverBrandedCostRate: 32,
};

// ── Date Normalization ────────────────────────────────────────────────────────
// Converts any date string to YYYY-MM-DD so all formats hit the same key.
function normalizeDate(date: string): string {
  if (!date) return '';

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(date.trim())) return date.trim();

  // MM/DD/YYYY or M/D/YYYY
  const mdyMatch = date.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (mdyMatch) {
    return `${mdyMatch[3]}-${mdyMatch[1].padStart(2, '0')}-${mdyMatch[2].padStart(2, '0')}`;
  }

  // "February 27, 2026" or "Feb 27, 2026" etc. — let Date parse it
  try {
    const d = new Date(date);
    if (!isNaN(d.getTime())) {
      // Use UTC to avoid off-by-one from timezone shifts
      const utc = new Date(d.getTime() + d.getTimezoneOffset() * 60000);
      const yyyy = utc.getFullYear();
      const mm = String(utc.getMonth() + 1).padStart(2, '0');
      const dd = String(utc.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    }
  } catch { /* fall through */ }

  return date.trim(); // last resort — return as-is
}

const KEY = (date: string) => `rates_${normalizeDate(date)}`;
const LOCK_KEY = (date: string) => `rates_lock_${normalizeDate(date)}`;

/** Save a full rate snapshot for a specific date (any date format accepted). */
export function saveRatesForDate(date: string, rates: RateSnapshot): void {
  if (!date) return;
  try {
    localStorage.setItem(KEY(date), JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save', e);
  }
}

/** Retrieve the rate snapshot for a date (any format). Falls back to DEFAULT_RATES. */
export function getRatesForDate(date: string): RateSnapshot {
  if (!date) return { ...DEFAULT_RATES };
  try {
    const raw = localStorage.getItem(KEY(date));
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
      return {
        phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
        silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
        silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
        silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
        silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
      };
    }
  } catch (e) {
    console.error('ratesStore: failed to read', e);
  }
  return { ...DEFAULT_RATES };
}

/** Returns true only if a snapshot was explicitly saved for this date (not just defaults). */
export function hasRatesSnapshotForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(KEY(date)) !== null;
}

// ── Rate Lock / Unlock ────────────────────────────────────────────────────────

export function isRateLockedForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(LOCK_KEY(date)) === 'true';
}

export function lockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.setItem(LOCK_KEY(date), 'true');
}

export function unlockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.removeItem(LOCK_KEY(date));
}

// ── Convenience getters ───────────────────────────────────────────────────────

export const DEFAULT_PHP_RATE = DEFAULT_RATES.phpRate;
export const DEFAULT_SILVER_SELL_RATE = DEFAULT_RATES.silverSellRate;
export const DEFAULT_SILVER_BRANDED_SELL_RATE = DEFAULT_RATES.silverBrandedSellRate;
export const DEFAULT_SILVER_COST_RATE = DEFAULT_RATES.silverCostRate;
export const DEFAULT_SILVER_BRANDED_COST_RATE = DEFAULT_RATES.silverBrandedCostRate;

export function getPhpRate(date: string): number { return getRatesForDate(date).phpRate; }
export function getSilverSellRate(date: string): number { return getRatesForDate(date).silverSellRate; }
export function getSilverBrandedSellRate(date: string): number { return getRatesForDate(date).silverBrandedSellRate; }
export function getSilverCostRate(date: string): number { return getRatesForDate(date).silverCostRate; }
export function getSilverBrandedCostRate(date: string): number { return getRatesForDate(date).silverBrandedCostRate; }

// Individual setters
function patchDate(date: string, patch: Partial<RateSnapshot>) {
  saveRatesForDate(date, { ...getRatesForDate(date), ...patch });
}
export function setPhpRate(date: string, rate: number) { patchDate(date, { phpRate: rate }); }
export function setSilverSellRate(date: string, rate: number) { patchDate(date, { silverSellRate: rate }); }
export function setSilverBrandedSellRate(date: string, rate: number) { patchDate(date, { silverBrandedSellRate: rate }); }
export function setSilverCostRate(date: string, rate: number) { patchDate(date, { silverCostRate: rate }); }
export function setSilverBrandedCostRate(date: string, rate: number) { patchDate(date, { silverBrandedCostRate: rate }); }

// Legacy aliases
/** @deprecated Use getRatesForDate(date).silverSellRate */
export function getSilverRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverSellRate */
export function setSilverRate(date: string, rate: number) { setSilverSellRate(date, rate); }
/** @deprecated Use getRatesForDate(date).silverBrandedSellRate */
export function getSilverBrandedRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverBrandedSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverBrandedSellRate */
export function setSilverBrandedRate(date: string, rate: number) { setSilverBrandedSellRate(date, rate); }
export function hasPhpRate(date: string): boolean { return localStorage.getItem(KEY(date)) !== null; }

import { useState, memo, useMemo } from 'react';
import { ChevronDown, FileText, History } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { DatabaseRowType } from '@/types';
import { calcRemainingBalance, calcShippingFee, calcCCFee, calcItemPrice, calcDueDate, getQty } from '@/lib/calculations';
import { formatDateObj, formatDate } from '@/lib/formatters';
import StatusBadge from '@/components/StatusBadge';
import InvoiceModal from '@/components/InvoiceModal';
import FinancialsForm from './FinancialsForm';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

interface Props {
  minerName: string;
  records: DatabaseRowType[];
  allRecords: DatabaseRowType[];
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
}

function AccountsClientCard({ minerName, records, allRecords, onUpdate }: Props) {
  const [expanded, setExpanded] = useState(false);
  const [showInvoice, setShowInvoice] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [expandedItem, setExpandedItem] = useState<number | null>(null);

  const first = records[0];
  const dueDate = formatDateObj(calcDueDate(first?.dateOfLive));
  const totalRemaining = records.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);

  // Group records by Date → Liver → Status
  const grouped = useMemo(() => {
    const byDate: Record<string, Record<string, Record<string, DatabaseRowType[]>>> = {};
    for (const r of records) {
      const date = r.dateOfLive || 'No Date';
      const liver = r.liverName || 'Unknown Liver';
      const status = r.status || 'No Status';
      if (!byDate[date]) byDate[date] = {};
      if (!byDate[date][liver]) byDate[date][liver] = {};
      if (!byDate[date][liver][status]) byDate[date][liver][status] = [];
      byDate[date][liver][status].push(r);
    }
    return byDate;
  }, [records]);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button className="w-full text-left px-4 py-3 flex items-center justify-between" onClick={() => setExpanded(e => !e)}>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className="font-cinzel text-sm text-primary">{minerName}</span>
            {first?.customerId && (
              <button
                className="text-muted-foreground hover:text-primary transition-colors"
                title="View Lifetime History"
                onClick={e => { e.stopPropagation(); setShowHistory(true); }}
              >
                <History className="h-3.5 w-3.5" />
              </button>
            )}
          </div>
          <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
            <span>{records.length} item{records.length !== 1 ? 's' : ''}</span>
            <span>Due: {dueDate}</span>
          </div>
          {totalRemaining > 0 && (
            <span className="text-xs font-medium text-destructive">Balance: AED {totalRemaining.toFixed(2)}</span>
          )}
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground shrink-0 ml-2 transition-transform ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 border-t border-border pt-3">
          {/* Generate Invoice at the TOP */}
          <Button
            variant="outline"
            size="sm"
            className="w-full mb-3 border-primary/40 text-primary text-xs"
            onClick={() => setShowInvoice(true)}
          >
            <FileText className="h-3.5 w-3.5 mr-1.5" /> Generate Invoice
          </Button>

          {/* Grouped by Date → Liver → Status */}
          {Object.entries(grouped).sort().map(([date, livers]) => (
            <div key={date} className="mb-3">
              <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2 px-1">
                📅 {formatDate(date)}
              </div>
              {Object.entries(livers).map(([liver, statuses]) => (
                <div key={liver} className="mb-2 ml-2">
                  <div className="text-xs font-medium text-primary/80 mb-1 px-1">🧑 {liver}</div>
                  {Object.entries(statuses).map(([status, items]) => (
                    <div key={status} className="mb-2 ml-2">
                      <div className="text-xs text-muted-foreground mb-1 px-1 flex items-center gap-1">
                        <StatusBadge status={status} /> <span className="ml-1">({items.length})</span>
                      </div>
                      {items.map(record => (
                        <div key={record.id} className="mb-2 rounded-lg border border-border/50 bg-secondary/20 overflow-hidden">
                          <button
                            className="w-full text-left p-3 flex items-start justify-between"
                            onClick={() => setExpandedItem(expandedItem === record.id ? null : record.id)}
                          >
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-medium truncate mb-1">{record.itemDescription}</p>
                              <div className="text-xs text-muted-foreground">
                                {record.category} · {(record.category || '').toLowerCase().includes('screw type') ? `${getQty(record)} PCS` : (record.grams ? `${record.grams}g` : 'PC')} · {record.modeOfPayment}
                              </div>
                              <div className="flex gap-3 text-xs mt-1">
                                <span className="text-muted-foreground">Price: <span className="text-foreground">{record.currency || 'AED'} {calcItemPrice(record).toFixed(2)}</span></span>
                                <span className="text-muted-foreground">SF: <span className="text-foreground">AED {calcShippingFee(record).toFixed(2)}</span></span>
                                {calcCCFee(record) > 0 && <span className="text-muted-foreground">CC: <span className="text-foreground">AED {calcCCFee(record).toFixed(2)}</span></span>}
                              </div>
                              <div className="text-xs mt-0.5">
                                <span className={`font-medium ${calcRemainingBalance(record) > 0 ? 'text-destructive' : 'text-green-400'}`}>
                                  Balance: AED {calcRemainingBalance(record).toFixed(2)}
                                </span>
                              </div>
                            </div>
                            <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground shrink-0 ml-2 mt-1 transition-transform ${expandedItem === record.id ? 'rotate-180' : ''}`} />
                          </button>

                          {expandedItem === record.id && (
                            <div className="px-3 pb-3 animate-in fade-in slide-in-from-top-2 duration-200">
                              <FinancialsForm record={record} onUpdate={onUpdate} />
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  ))}
                </div>
              ))}
            </div>
          ))}
        </div>
      )}

      {showInvoice && <InvoiceModal records={records} onClose={() => setShowInvoice(false)} />}
      {showHistory && first?.customerId && (
        <CustomerHistoryModal
          customerId={first.customerId}
          minerName={minerName}
          allRecords={allRecords}
          onClose={() => setShowHistory(false)}
        />
      )}
    </div>
  );
}

export default memo(AccountsClientCard, (prev, next) => {
  if (prev.minerName !== next.minerName) return false;
  if (prev.records.length !== next.records.length) return false;
  for (let i = 0; i < prev.records.length; i++) {
    if (prev.records[i] !== next.records[i]) return false;
  }
  if (prev.allRecords !== next.allRecords) return false;
  return true;
});

import { DatabaseRowType } from '@/types';
import { parseISO, isValid, parse } from 'date-fns';
import { getRatesForDate } from '@/lib/ratesStore';

const n = (v: unknown): number => {
  if (typeof v === 'number') return v;
  if (!v) return 0;
  const s = String(v).replace(/,/g, '').trim();
  const parsed = Number(s);
  return isNaN(parsed) ? 0 : parsed;
};

export function roundPrice(v: number): number { return Math.round(v); }

export function parseDateRobust(dateStr?: string): Date | null {
  if (!dateStr) return null;

  // FORCE DUBAI TIMEZONE (UTC+4)
  let safeDateStr = dateStr;
  if (!dateStr.includes('T') && !dateStr.includes('+') && !dateStr.includes('Z')) {
    safeDateStr = `${dateStr} 12:00:00 +0400`;
  }

  const iso = parseISO(safeDateStr);
  if (isValid(iso)) return iso;

  const native = new Date(safeDateStr);
  if (!isNaN(native.getTime())) return native;

  const formats = ['MMMM dd,yyyy', 'MMMM d,yyyy', 'MM/dd/yyyy', 'M/d/yyyy', 'dd/MM/yyyy'];
  for (const fmt of formats) {
    try {
      const d = parse(safeDateStr, fmt, new Date());
      if (isValid(d)) return d;
    } catch { /* continue */ }
  }
  return null;
}

export function getQty(record: DatabaseRowType): number {
  return record.qty != null && Number(record.qty) > 0 ? Number(record.qty) : 1;
}

export function isPcItem(record: DatabaseRowType): boolean {
  const grams = n(record.grams);
  return !grams || isNaN(grams) || grams <= 0;
}

export function isFreeSf(record: DatabaseRowType): boolean {
  return String(record.freeSf).toLowerCase() === 'true';
}

function normCurrency(currency?: string): string {
  return (currency || '').toUpperCase().trim();
}

export function getEffectiveCurrency(record: DatabaseRowType): string {
  const curr = normCurrency(record.currency);
  if (!curr && normCurrency(record.locationOfMiner) === 'PINAS') return 'PHP';
  return curr || 'AED';
}

// ── Default anchor rates (used when no snapshot is stored for a date) ──
export const SILVER_RATE = 45;
export const SILVER_BRANDED_RATE = 60;

/** Return the daily silver anchor for this record's date and category, or null if not silver. */
export function getSilverRate(category: string, record?: DatabaseRowType): number | null {
  const cat = (category || '').toLowerCase();
  if (record?.dateOfLive) {
    const snap = getRatesForDate(record.dateOfLive);
    if (cat.includes('silver branded')) return snap.silverBrandedSellRate;
    if (cat.includes('silver')) return snap.silverSellRate;
  }
  if (cat.includes('silver branded')) return SILVER_BRANDED_RATE;
  if (cat.includes('silver')) return SILVER_RATE;
  return null;
}

// ── MASTER ANCHOR: toAED ─────────────────────────────────────────────────────
// Converts any currency value to AED.
//
// CRITICAL RULE: Smart Snap only applies when converting FROM a foreign currency
// (USD or PHP) to AED. It must NEVER fire when the price is already in AED,
// because the AED value entered by the user IS the correct anchor.
//
// Why: if the Admin sets 35 AED and no daily snapshot is saved (default = 45),
// then |35 - 45| = 10 which would wrongly snap 35 → 45.
export function toAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';

  // If already AED — return as-is. No snap. The entered value is the truth.
  if (curr === 'AED') return value;

  let rawAED: number;
  if (curr === 'USD') {
    rawAED = value * 3.67;
  } else if (curr === 'PHP') {
    const phpRate = record?.dateOfLive
      ? getRatesForDate(record.dateOfLive).phpRate
      : 16.7;
    rawAED = value / phpRate;
  } else {
    return value; // unknown currency — pass through
  }

  // Smart Snap: only for silver items converting from foreign currency (USD/PHP → AED).
  // Always fires — even if no explicit snapshot was saved — so that raw USD math
  // (e.g. 12 USD = 44.04) snaps to the correct silver anchor (45 by default).
  // Rule: AED currencies are returned early above, so this never fires for AED inputs.
  if (record?.dateOfLive) {
    const category = (record.category || '').toLowerCase();
    const snap = getRatesForDate(record.dateOfLive); // uses defaults if no snapshot

    if (category.includes('silver branded')) {
      if (Math.abs(rawAED - snap.silverBrandedSellRate) <= 10) return snap.silverBrandedSellRate;
    } else if (category.includes('silver')) {
      if (Math.abs(rawAED - snap.silverSellRate) <= 10) return snap.silverSellRate;
    }
  }

  return rawAED;
}

// ── fromAED: convert AED → native currency ──────────────────────────────────
// Uses the daily phpRate snapshot so PHP display is always in sync with Admin settings.
export function fromAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value / 3.67;
  if (curr === 'PHP') {
    const phpRate = record?.dateOfLive
      ? getRatesForDate(record.dateOfLive).phpRate
      : 16.7;
    return value * phpRate;
  }
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const rate = n(record.clientRate);
  const curr = getEffectiveCurrency(record);

  // If already in AED, return directly — no snap, no conversion
  if (curr === 'AED') return rate;

  // For foreign currencies, toAED handles the Smart Snap
  return toAED(rate, record);
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (clientRate > 0) return roundPrice(n(record.grams) * clientRate);
    return roundPrice(fromAED(n(record.grams) * silverRate, record));
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(clientRate * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRate);
  const price = roundPrice(n(record.grams) * clientRate);
  return price > 0 ? price : (clientRate > 0 ? roundPrice(clientRate) : 0);
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const rateAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (n(record.clientRate) > 0) return roundPrice(n(record.grams) * rateAED);
    return roundPrice(n(record.grams) * silverRate);
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(rateAED * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(rateAED);
  const price = roundPrice(n(record.grams) * rateAED);
  return price > 0 ? price : (rateAED > 0 ? roundPrice(rateAED) : 0);
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);

  if (category.includes('diamond')) return roundPrice(supplierRate * getQty(record));

  if (category.includes('per pc') || category.includes('screw type')) {
    let rate = supplierRate > 0 ? supplierRate : goldRate > 0 ? goldRate : 115;
    if (rate === 115 && (desc.includes('buy 1 take 1') || desc.includes('b1t1'))) rate *= 2;
    return roundPrice(rate * getQty(record));
  }

  if (category.includes('silver branded')) return roundPrice(32 * grams);
  if (category.includes('silver')) return roundPrice(15 * grams);

  if (goldRate > 0) {
    const effectiveMc = mc > 0 ? mc : category.includes('special price ef') ? 25 : category.includes('special price') ? 21 : 16;
    if (isPcItem(record)) return roundPrice(goldRate + effectiveMc);
    return roundPrice((goldRate + effectiveMc) * grams);
  }

  if (supplierRate > 0) {
    if (isPcItem(record)) return roundPrice(supplierRate);
    return roundPrice(supplierRate * grams);
  }

  return 0;
}

export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const grams = n(record.grams);
  const isSilver = getSilverRate(category, record) !== null;
  const isPerPcType = category.includes('per pc') || category.includes('screw type') || category.includes('diamond');

  if (!isSilver && !isPerPcType && grams > 0) {
    const goldRate = n(record.goldRate);
    const supplierRate = n(record.supplierRate);
    if (goldRate === 0 && supplierRate === 0) return 0;
  }

  const totalSales = calcItemPriceAED(record);
  const totalCost = calcItemCostAED(record);
  return roundPrice(totalSales - totalCost);
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  const loc = normCurrency(record.locationOfMiner);
  if (loc === 'LOCAL') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30;
    return 30;
  }

  if (loc === 'INTERNATIONAL' || loc === 'PINAS') return 299;
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  if (record.modeOfPayment !== 'Credit Card') return 0;
  const basePrice = calcItemPriceAED(record);
  return roundPrice(basePrice * 0.05);
}

export function calcTotalPaid(record: DatabaseRowType): number {
  // downpayment is always entered/stored in AED (entered in the MOP's currency = AED)
  // so we treat it as AED directly — no toAED conversion.
  // "acknowledged" marker on sibling items = 0 (n() returns 0 for non-numeric strings).
  const dpAED = n(record.downpayment);

  // Layaway payments and amountReceived are in the record's native currency — convert to AED.
  const otherRaw = n(record.la1MonthPayment) + n(record.la2MonthPayment) + n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
  return dpAED + toAED(otherRaw, record);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = calcItemPriceAED(record);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return roundPrice((itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid);
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details' && record.status !== 'Waiting for Downpayment') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

/**
 * calcItemPricePHP — returns the final item price in Philippine Pesos.
 * Uses the Smart-Snapped AED value × the daily phpRate snapshot.
 *
 * CRITICAL: Smart Snap only fires for USD/PHP → AED conversions.
 * If the price is already in AED, it is passed through as-is.
 * e.g. 35 AED silver × 16.7 = 584.5 → 585 PHP ✓
 * e.g. 10 USD silver → 36.7 raw → snaps to 35 → 35 × 16.7 = 584.5 → 585 PHP ✓
 */
export function calcItemPricePHP(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (clientRate === 0) return 0;

  const currency = String(record.currency || 'AED').toUpperCase();
  const category = String(record.category || '').toLowerCase();
  const dateOfLive = record.dateOfLive || new Date().toISOString().split('T')[0];
  const rates = getRatesForDate(dateOfLive);

  // Step 1: Convert to AED
  let snappedAED = clientRate;
  if (currency === 'AED') {
    // Already AED — trust the value, no snap
    snappedAED = clientRate;
  } else if (currency === 'USD') {
    let rawAED = clientRate * 3.67;
    // Always snap — uses saved snapshot if available, otherwise defaults
    if (category.includes('silver branded')) {
      if (Math.abs(rawAED - rates.silverBrandedSellRate) <= 10) rawAED = rates.silverBrandedSellRate;
    } else if (category.includes('silver')) {
      if (Math.abs(rawAED - rates.silverSellRate) <= 10) rawAED = rates.silverSellRate;
    }
    snappedAED = rawAED;
  } else if (currency === 'PHP') {
    let rawAED = clientRate / rates.phpRate;
    if (category.includes('silver branded')) {
      if (Math.abs(rawAED - rates.silverBrandedSellRate) <= 10) rawAED = rates.silverBrandedSellRate;
    } else if (category.includes('silver')) {
      if (Math.abs(rawAED - rates.silverSellRate) <= 10) rawAED = rates.silverSellRate;
    }
    snappedAED = rawAED;
  }

  // Step 2: Multiply snapped AED by daily PHP rate
  return snappedAED * rates.phpRate;
}

