      .status-header { font-size: 15px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px; margin: 0 0 10px; }
      .status-totals { font-size: 11px; color: #555; margin-bottom: 10px; }

      /* Brand section */
      .brand-block { margin-bottom: 16px; }
      .brand-header { font-size: 12px; font-weight: bold; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; margin-bottom: 4px; }

      /* Table */
      table { width: 100%; border-collapse: collapse; margin-bottom: 0; page-break-inside: auto; }
      thead tr { background: #444; color: #fff; }
      th { padding: 6px 8px; text-align: left; font-size: 10px; font-weight: bold; white-space: nowrap; }
      td { padding: 5px 8px; vertical-align: top; font-size: 10px; }
      tbody tr:nth-child(even) { background: #f5f5f5; }
      tbody tr:nth-child(odd) { background: #fff; }
      tr.subtotal-row { background: #e8e8e8 !important; border-top: 2px solid #111; font-weight: bold; }
      .r { text-align: right; }
      .client-name { font-weight: bold; }
      .order-id { font-family: monospace; font-size: 9px; color: #777; }
      .grams { color: #555; }
    </style></head><body>
    <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>
    <p class="meta">Date Range: ${dateRangeLabel} &nbsp;|&nbsp; Generated: ${new Date().toLocaleString()}</p>
    <div class="summary">
      <div class="summary-item">Confirmed Profit (Delivered): <span class="profit-pos">AED ${kpis.confirmedProfit.toFixed(2)}</span></div>
      <div class="summary-item">Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></div>
      <div class="summary-item">Items Delivered: <span>${kpis.totalSold}</span></div>
      <div class="summary-item">Outstanding: <span>AED ${kpis.outstanding.toFixed(2)}</span></div>
      <div class="summary-item">Total Grams: <span>${kpis.totalGrams.toFixed(2)}g</span></div>
    </div>`;

  [...statusGroups.entries()]
    .filter(([status]) => selectedPrintStatuses.has(status))
    .sort((a, b) => (STATUS_SORT[a[0]] ?? 99) - (STATUS_SORT[b[0]] ?? 99))
    .forEach(([status, items]) => {
      const isDead = DEAD_STATUSES.has(status);
      const statusPrice = items.reduce((s, r) => s + calcItemPriceAED(r), 0);
      const statusCost = items.reduce((s, r) => s + calcItemCostAED(r), 0);
      const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);

      // Group by brand only
      const byBrand = new Map<string, DatabaseRowType[]>();
      for (const r of items) {
        let pk = (r.page || 'Other').trim();
        if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
        else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
        if (!byBrand.has(pk)) byBrand.set(pk, []);
        byBrand.get(pk)!.push(r);
      }
      const sortedBrands = [...byBrand.entries()].sort((a, b) => {
        if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
        if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
        return a[0].localeCompare(b[0]);
      });

      html += `<div class="status-section">`;
      html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} &nbsp; <small style="font-size:12px;font-weight:normal;">(${items.length} items)</small></h2>`;
      if (!isDead) {
        html += `<p class="status-totals">Price: AED ${statusPrice.toFixed(2)} &nbsp;|&nbsp; Cost: AED ${statusCost.toFixed(2)} &nbsp;|&nbsp; <strong class="${statusProfit >= 0 ? 'profit-pos' : 'profit-neg'}">Profit: AED ${statusProfit.toFixed(2)}</strong></p>`;
      }

      const profitTh = isDead ? '' : `<th class="r">Profit</th>`;

      sortedBrands.forEach(([brand, brandRows]) => {
        const brandSorted = [...brandRows].sort((a, b) => (b.dateOfLive || '').localeCompare(a.dateOfLive || ''));
        const bPrice = brandRows.reduce((s, r) => s + calcItemPriceAED(r), 0);
        const bCost = brandRows.reduce((s, r) => s + calcItemCostAED(r), 0);
        const bProfit = brandRows.reduce((s, r) => s + calcProfitAED(r), 0);
        const bGrams = brandRows.reduce((s, r) => {
          const c = (r.category || '').toLowerCase();
          return c.includes('per pc') || c.includes('screw type') || c.includes('diamond') ? s : s + (Number(r.grams) || 0);
        }, 0);

        html += `<div class="brand-block">`;
        html += `<div class="brand-header">📄 ${brand} &nbsp; <span style="font-weight:normal;font-size:10px;">${brandRows.length} items · ${bGrams.toFixed(2)}g</span></div>`;
        html += `<table><thead><tr><th>Date</th><th>Order ID</th><th class="client-name">Client</th><th>Item</th><th class="r">Grams</th><th class="r">Price (AED)</th><th class="r">Cost (AED)</th>${profitTh}</tr></thead><tbody>`;

        brandSorted.forEach(r => {
          const cat = (r.category || '').toLowerCase();
          const isPc = cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond');
          const gramsStr = isPc ? 'PC' : (r.grams ? `${Number(r.grams).toFixed(2)}g` : '—');
          const pr = calcProfitAED(r);
          const pCell = isDead ? '' : `<td class="r ${pr >= 0 ? 'profit-pos' : 'profit-neg'}"><strong>${pr.toFixed(2)}</strong></td>`;
          const orderId = r.orderId || `#${r.id}`;
          html += `<tr>
            <td style="white-space:nowrap">${formatDate(r.dateOfLive)}</td>
            <td class="order-id">${orderId}</td>
            <td class="client-name">${r.minerName || '—'}</td>
            <td>${r.itemDescription || '—'}</td>
            <td class="r grams">${gramsStr}</td>
            <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
            <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
            ${pCell}
          </tr>`;
        });

        // Subtotal row
        const subProfitCell = isDead ? '' : `<td class="r ${bProfit >= 0 ? 'profit-pos' : 'profit-neg'}">${bProfit.toFixed(2)}</td>`;
        html += `<tr class="subtotal-row">
          <td colspan="4">${brand} SUBTOTAL (${brandRows.length} items · ${bGrams.toFixed(2)}g)</td>
          <td class="r"></td>
          <td class="r">${bPrice.toFixed(2)}</td>
          <td class="r">${bCost.toFixed(2)}</td>
          ${subProfitCell}
        </tr>`;

        html += `</tbody></table></div>`;
      });
      html += `</div>`;
    });

  html += `</body></html>`;
  win.document.write(html);
  win.document.close();
  win.print();
};

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [;
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

