import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen, Plus, Calendar, Clock, PauseCircle, ShieldCheck, BarChart2, Merge } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMiner, groupByMinerName, formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';
import AddClientModal from '@/components/accounts/AddClientModal';
import DailyRatesEditor from '@/components/admin/DailyRatesEditor';
import MergeClientsModal from '@/components/admin/MergeClientsModal';
import { Button } from '@/components/ui/button';

import { z } from 'zod';
import { createEndpoint, Database } from 'zite-integrations-backend-sdk';

export default createEndpoint({
  description: 'Merges all records from a duplicate customer ID into a master customer ID. Updates minerName to match the master profile name.',
  inputSchema: z.object({
    duplicateCustomerId: z.string(),
    masterCustomerId: z.string(),
    masterMinerName: z.string(),
  }),
  outputSchema: z.object({
    updatedCount: z.number(),
    success: z.boolean(),
    message: z.string(),
  }),
  execute: async ({ input }) => {
    const { duplicateCustomerId, masterCustomerId, masterMinerName } = input;

    if (duplicateCustomerId === masterCustomerId) {
      return { updatedCount: 0, success: false, message: 'Duplicate and master cannot be the same profile.' };
    }

    // Find all records with the duplicate customer ID
    const allRecords = await Database.findAll({ limit: 50000 });
    const targets = (allRecords ?? []).filter(r => r.customerId === duplicateCustomerId);

    if (targets.length === 0) {
      return { updatedCount: 0, success: false, message: `No records found for Customer ID: ${duplicateCustomerId}` };
    }

    // Update each record: overwrite customerId and normalize minerName to master
    let updatedCount = 0;
    for (const record of targets) {
      await Database.update({
        rowId: record.id,
        row: {
          customerId: masterCustomerId,
          minerName: masterMinerName,
        },
      });
      updatedCount++;
    }

    return {
      updatedCount,
      success: true,
      message: `Successfully merged ${updatedCount} record(s) from ${duplicateCustomerId} → ${masterCustomerId}`,
    };
  },
});

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {;
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

