import { useRef, useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, Copy, Loader2 } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);

  useEffect(() => {
    if (!document.getElementById('html2canvas-script') && !(window as any).html2canvas) {
      const script = document.createElement('script');
      script.id = 'html2canvas-script';
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  const activeRecords = useMemo(() => {
    const excludedStatuses = ['Cancelled', 'Returned Item'];
    return records
      .filter(r => !excludedStatuses.includes(r.status || ''))
      .sort((a, b) => {
        const dateA = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
        const dateB = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
        return dateA - dateB;
      });
  }, [records]);

  const baseRecord = activeRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleCopyImage = async () => {
    if (activeRecords.length === 0 || !printRef.current) return;

    const html2canvas = (window as any).html2canvas;
    if (!html2canvas) {
      toast.error('The image tool is still loading. Please try again in a few seconds.');
      return;
    }

    setIsCopying(true);
    toast.info('Generating image, please wait...');

    try {
      const makeImagePromise = async (): Promise<Blob> => {
        const canvas = await html2canvas(printRef.current!, {
          scale: 2, 
          useCORS: true, 
          backgroundColor: '#ffffff',
          scrollY: 0,
          windowHeight: printRef.current?.scrollHeight || window.innerHeight
        });
        return new Promise<Blob>((resolve, reject) => {
          canvas.toBlob((blob: Blob | null) => {
            if (blob) resolve(blob);
            else reject(new Error('Failed to generate image blob'));
          }, 'image/png');
        });
      };

      await navigator.clipboard.write([
        new ClipboardItem({
          'image/png': makeImagePromise()
        })
      ]);
      toast.success('Invoice image copied! You can now paste it into Meta Business Suite.');
    } catch (error: any) {
      console.error(error);
      if (error.name === 'NotAllowedError') {
         toast.error('Clipboard permission denied. Please allow clipboard access in your browser settings.');
      } else {
         toast.error('Failed to copy image. Try again.');
      }
    } finally {
      setIsCopying(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0" aria-describedby={undefined}>
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex items-center justify-between gap-4">
            <DialogTitle className="text-base font-bold text-foreground">
              Statement of Account (Active)
            </DialogTitle>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger className="h-8 w-24 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CURRENCIES.map(c => (
                      <SelectItem key={c} value={c}>{c}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <Button
                onClick={handleCopyImage}
                size="sm"
                variant="outline"
                className="h-8 border-blue-600 text-blue-700 hover:bg-blue-50"
                disabled={activeRecords.length === 0 || isCopying}
              >
                {isCopying ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Copy className="h-3.5 w-3.5 mr-1.5" />}
                {isCopying ? 'Copying...' : 'Copy Image'}
              </Button>

              <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={activeRecords.length === 0}>
                <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
              </Button>
            </div>
          </div>
        </DialogHeader>

        {activeRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Active Items</p>
            <p className="text-xs">This client's items have all been Delivered, Dispatched, or Cancelled.</p>
          </div>
        )}

        {activeRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4 bg-white">
              <InvoicePrintContent records={activeRecords} currency={currency} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { DatabaseRowType } from '@/types';
import { calcItemPriceAED, calcTotalPaid, parseDateRobust } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { Copy, CheckCircle2 } from 'lucide-react';
import { toast } from 'sonner';

interface Props {
  customerId: string;
  minerName: string;
  allRecords: DatabaseRowType[];
  onClose: () => void;
}

export default function CustomerHistoryModal({ customerId, minerName, allRecords, onClose }: Props) {
  const customerRecords = useMemo(() => {
    return allRecords
      .filter(r => r.customerId === customerId)
      .sort((a, b) => {
        const dateA = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
        const dateB = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
        return dateB - dateA;
      });
  }, [allRecords, customerId]);

  const summary = useMemo(() => {
    const totalItems = customerRecords.length;
    const activeItems = customerRecords.filter(r => r.status !== 'Cancelled' && r.status !== 'Returned Item');
    const totalSpent = activeItems.reduce((sum, r) => sum + calcItemPriceAED(r), 0);
    const totalPaid = activeItems.reduce((sum, r) => sum + calcTotalPaid(r), 0);
    const balance = Math.max(0, totalSpent - totalPaid);
    return { totalItems, activeCount: activeItems.length, totalSpent, balance };
  }, [customerRecords]);

  const handleCopyId = () => {
    navigator.clipboard.writeText(customerId);
    toast.success('Customer ID copied to clipboard!');
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto bg-card border-border">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary flex items-center justify-between pr-6">
            <span>Client Ledger: {minerName.toUpperCase()}</span>
            <button 
              onClick={handleCopyId}
              className="group flex items-center gap-1.5 px-2.5 py-1 rounded bg-secondary/50 hover:bg-primary/10 transition-colors border border-border hover:border-primary/30"
              title="Copy Customer ID"
            >
              <span className="text-xs font-mono text-muted-foreground group-hover:text-primary transition-colors">{customerId}</span>
              <Copy className="h-3 w-3 text-muted-foreground group-hover:text-primary transition-colors" />
            </button>
          </DialogTitle>
        </DialogHeader>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 my-4">
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Total Items</p>
            <p className="text-lg font-bold">{summary.totalItems}</p>
          </div>
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Active Items</p>
            <p className="text-lg font-bold">{summary.activeCount}</p>
          </div>
          <div className="bg-secondary/30 border border-border rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-muted-foreground mb-1">Total Value</p>
            <p className="text-lg font-bold text-foreground">AED {summary.totalSpent.toFixed(2)}</p>
          </div>
          <div className="bg-primary/5 border border-primary/20 rounded-lg p-3 text-center">
            <p className="text-[10px] uppercase tracking-wider text-primary/80 mb-1">Outstanding</p>
            <p className={`text-lg font-bold ${summary.balance > 0 ? 'text-destructive' : 'text-green-500'}`}>
              AED {summary.balance.toFixed(2)}
            </p>
          </div>
        </div>

        <div className="space-y-3">
          {customerRecords.map(record => {
            const price = calcItemPriceAED(record);
            const paid = calcTotalPaid(record);
            const balance = Math.max(0, price - paid);
            const isDead = record.status === 'Cancelled' || record.status === 'Returned Item';

            return (
              <div key={record.id} className={`p-4 rounded-xl border ${isDead ? 'border-border/50 bg-background/50 opacity-70' : 'border-border bg-card'}`}>
                <div className="flex flex-col md:flex-row justify-between gap-4">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-semibold px-2 py-0.5 rounded-full bg-secondary text-secondary-foreground border border-border">
                        {record.status || 'Unknown'}
                      </span>
                      <span className="text-xs text-muted-foreground">{formatDate(record.dateOfLive)}</span>
                    </div>
                    <p className="text-sm font-medium mt-1">{record.itemDescription}</p>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      {record.orderId && <span>ID: <span className="font-mono">{record.orderId}</span></span>}
                      <span>{record.category || 'N/A'}</span>
                      {record.grams && <span>{Number(record.grams).toFixed(2)}g</span>}
                    </div>
                  </div>

                  <div className="flex flex-col items-end justify-center min-w-[120px] shrink-0">
                    {!isDead && (
                      <>
                        <div className="text-right w-full flex justify-between gap-4 mb-0.5">
