type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

// Status display order: most business-important first
const STATUS_SORT: Record<string, number> = {
  'Delivered': 1,
  'Given to Shop': 2,
  'Dispatched': 3,
  'Payment for Verification': 4,
  'Paid/DP but Item Hold': 5,
