/**
 * Historical Rate Locking Store
 *
 * All dates are normalized to YYYY-MM-DD before being used as localStorage keys.
 * This ensures that "02/27/2026", "February 27, 2026", "Feb 27, 2026", and "2026-02-27"
 * all map to the same key: rates_2026-02-27.
 */

export interface RateSnapshot {
  phpRate: number;
  silverSellRate: number;
  silverCostRate: number;
  silverBrandedSellRate: number;
  silverBrandedCostRate: number;
}

export const DEFAULT_RATES: RateSnapshot = {
  phpRate: 16.7,
  silverSellRate: 45,
  silverCostRate: 15,
  silverBrandedSellRate: 60,
  silverBrandedCostRate: 32,
};

// ── Date Normalization ────────────────────────────────────────────────────────
// Converts any date string to YYYY-MM-DD so all formats hit the same key.
function normalizeDate(date: string): string {
  if (!date) return '';

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(date.trim())) return date.trim();

  // MM/DD/YYYY or M/D/YYYY
  const mdyMatch = date.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (mdyMatch) {
    return `${mdyMatch[3]}-${mdyMatch[1].padStart(2, '0')}-${mdyMatch[2].padStart(2, '0')}`;
  }

  // "February 27, 2026" or "Feb 27, 2026" etc. — let Date parse it
  try {
    const d = new Date(date);
    if (!isNaN(d.getTime())) {
      // Use UTC to avoid off-by-one from timezone shifts
      const utc = new Date(d.getTime() + d.getTimezoneOffset() * 60000);
      const yyyy = utc.getFullYear();
      const mm = String(utc.getMonth() + 1).padStart(2, '0');
      const dd = String(utc.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    }
  } catch { /* fall through */ }

  return date.trim(); // last resort — return as-is
}

const KEY = (date: string) => `rates_${normalizeDate(date)}`;
const LOCK_KEY = (date: string) => `rates_lock_${normalizeDate(date)}`;

/** Save a full rate snapshot for a specific date (any date format accepted). */
export function saveRatesForDate(date: string, rates: RateSnapshot): void {
  if (!date) return;
  try {
    localStorage.setItem(KEY(date), JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save', e);
  }
}

/** Retrieve the rate snapshot for a date (any format). Falls back to DEFAULT_RATES. */
export function getRatesForDate(date: string): RateSnapshot {
  if (!date) return { ...DEFAULT_RATES };
  try {
    const raw = localStorage.getItem(KEY(date));
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
      return {
        phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
        silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
        silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
        silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
        silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
      };
    }
  } catch (e) {
    console.error('ratesStore: failed to read', e);
  }
  return { ...DEFAULT_RATES };
}

/** Returns true only if a snapshot was explicitly saved for this date (not just defaults). */
export function hasRatesSnapshotForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(KEY(date)) !== null;
}

// ── Rate Lock / Unlock ────────────────────────────────────────────────────────

export function isRateLockedForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(LOCK_KEY(date)) === 'true';
}

export function lockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.setItem(LOCK_KEY(date), 'true');
}

export function unlockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.removeItem(LOCK_KEY(date));
}

// ── Convenience getters ───────────────────────────────────────────────────────

export const DEFAULT_PHP_RATE = DEFAULT_RATES.phpRate;
export const DEFAULT_SILVER_SELL_RATE = DEFAULT_RATES.silverSellRate;
export const DEFAULT_SILVER_BRANDED_SELL_RATE = DEFAULT_RATES.silverBrandedSellRate;
export const DEFAULT_SILVER_COST_RATE = DEFAULT_RATES.silverCostRate;
export const DEFAULT_SILVER_BRANDED_COST_RATE = DEFAULT_RATES.silverBrandedCostRate;

export function getPhpRate(date: string): number { return getRatesForDate(date).phpRate; }
export function getSilverSellRate(date: string): number { return getRatesForDate(date).silverSellRate; }
export function getSilverBrandedSellRate(date: string): number { return getRatesForDate(date).silverBrandedSellRate; }
export function getSilverCostRate(date: string): number { return getRatesForDate(date).silverCostRate; }
export function getSilverBrandedCostRate(date: string): number { return getRatesForDate(date).silverBrandedCostRate; }

// Individual setters
function patchDate(date: string, patch: Partial<RateSnapshot>) {
  saveRatesForDate(date, { ...getRatesForDate(date), ...patch });
}
export function setPhpRate(date: string, rate: number) { patchDate(date, { phpRate: rate }); }
export function setSilverSellRate(date: string, rate: number) { patchDate(date, { silverSellRate: rate }); }
export function setSilverBrandedSellRate(date: string, rate: number) { patchDate(date, { silverBrandedSellRate: rate }); }
export function setSilverCostRate(date: string, rate: number) { patchDate(date, { silverCostRate: rate }); }
export function setSilverBrandedCostRate(date: string, rate: number) { patchDate(date, { silverBrandedCostRate: rate }); }

// Legacy aliases
/** @deprecated Use getRatesForDate(date).silverSellRate */
export function getSilverRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverSellRate */
export function setSilverRate(date: string, rate: number) { setSilverSellRate(date, rate); }
/** @deprecated Use getRatesForDate(date).silverBrandedSellRate */
export function getSilverBrandedRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverBrandedSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverBrandedSellRate */
export function setSilverBrandedRate(date: string, rate: number) { setSilverBrandedSellRate(date, rate); }
export function hasPhpRate(date: string): boolean { return localStorage.getItem(KEY(date)) !== null; }

import { useMemo, useState } from 'react';
import { Calendar, ChevronDown, Printer, History, TrendingUp } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Checkbox } from '@/components/ui/checkbox';
import { Label } from '@/components/ui/label';
import { TabProps, DatabaseRowType } from '@/types';
import {
  calcProfitAED,
  calcProfitNative,
  calcRemainingBalance,
  parseDateRobust,
  calcItemPriceAED,
  calcItemCostAED,
  getEffectiveCurrency,
} from '@/lib/calculations';
import { formatDate, applySearch } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import KpiCard from './KpiCard';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import CustomerHistoryModal from '@/components/CustomerHistoryModal';

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';

// Status display order: most business-important first
const STATUS_SORT: Record<string, number> = {
  'Delivered': 1,
  'Given to Shop': 2,
  'Dispatched': 3,
  'Payment for Verification': 4,
  'Paid/DP but Item Hold': 5,
  'For Pullout': 6,
  'Dispatch': 7,
  'Reseller': 8,
  'Pending': 9,
  'Waiting for Details': 10,
  'Waiting for Downpayment': 11,
  'Returned Item': 12,
  'Cancelled': 13,
};

const DEAD_STATUSES = new Set(['Cancelled', 'Returned Item']);

const RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All Time' },
  { key: 'week', label: 'This Week' },
  { key: 'month', label: 'This Month' },
  { key: '3months', label: '3 Months' },
  { key: 'custom', label: 'Custom' },
];

export default function BossingDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [range, setRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();
  const [pickerOpen, setPickerOpen] = useState(false);
  const [expandedStatuses, setExpandedStatuses] = useState<Record<string, boolean>>({});
  const [collapsedDates, setCollapsedDates] = useState<Record<string, boolean>>({});
  const [liverFilter, setLiverFilter] = useState('all');
  const [statusLiverFilters, setStatusLiverFilters] = useState<Record<string, string>>({});
  const [showPrintDialog, setShowPrintDialog] = useState(false);
  const [selectedPrintStatuses, setSelectedPrintStatuses] = useState<Set<string>>(new Set());
  const [historyCustomer, setHistoryCustomer] = useState<{ id: string, name: string } | null>(null);

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(records.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean))) as string[];
    return names.sort();
  }, [records]);

  const dateFiltered = useMemo(() => {
    if (range === 'all') return records;
    const now = new Date();
    let from: Date;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else if (range === '3months') from = subMonths(now, 3);
    else from = customFrom || new Date(0);
    const to = range === 'custom' ? customTo : undefined;
    return records.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      const t = d.getTime();
      if (t < from.getTime()) return false;
      if (to) {
        const end = new Date(to); end.setHours(23, 59, 59, 999);
        if (t > end.getTime()) return false;
      }
      return true;
    });
  }, [records, range, customFrom, customTo]);

  const filtered = useMemo(() => {
    let base = applySearch(dateFiltered, searchQuery);
    if (liverFilter !== 'all') {
      base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    }
    return base;
  }, [dateFiltered, searchQuery, liverFilter]);

  const kpis = useMemo(() => {
    const activeRecords = filtered.filter(r => !DEAD_STATUSES.has(r.status || ''));
    const deliveredRecords = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    // AED-based totals (for overall summary & legacy)
    const totalProfit = activeRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const confirmedProfit = deliveredRecords.reduce((sum, r) => sum + calcProfitAED(r), 0);
    const totalSold = deliveredRecords.length;
    const outstanding = activeRecords.reduce((sum, r) => sum + Math.max(0, calcRemainingBalance(r)), 0);
    const totalGrams = activeRecords.reduce((sum, r) => {
      const cat = (r.category || '').toLowerCase();
      if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
      return sum + (Number(r.grams) || 0);
    }, 0);

    // Native currency profit split (Active records)
    const nativeProfitAED = activeRecords.filter(r => getEffectiveCurrency(r) === 'AED').reduce((sum, r) => sum + calcProfitNative(r), 0);
    const nativeProfitPHP = activeRecords.filter(r => getEffectiveCurrency(r) === 'PHP').reduce((sum, r) => sum + calcProfitNative(r), 0);
    const nativeProfitUSD = activeRecords.filter(r => getEffectiveCurrency(r) === 'USD').reduce((sum, r) => sum + calcProfitNative(r), 0);

    // Native currency profit split (Delivered/Confirmed)
    const confirmedNativeProfitAED = deliveredRecords.filter(r => getEffectiveCurrency(r) === 'AED').reduce((sum, r) => sum + calcProfitNative(r), 0);
    const confirmedNativeProfitPHP = deliveredRecords.filter(r => getEffectiveCurrency(r) === 'PHP').reduce((sum, r) => sum + calcProfitNative(r), 0);
    const confirmedNativeProfitUSD = deliveredRecords.filter(r => getEffectiveCurrency(r) === 'USD').reduce((sum, r) => sum + calcProfitNative(r), 0);

    return {
      totalProfit, confirmedProfit, totalSold, outstanding, activeCount: activeRecords.length, totalGrams,
      nativeProfitAED, nativeProfitPHP, nativeProfitUSD,
      confirmedNativeProfitAED, confirmedNativeProfitPHP, confirmedNativeProfitUSD,
    };
  }, [filtered]);

  const statusGroups = useMemo(() => {
    const grouped = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const status = r.status || 'Unknown';
      if (!grouped.has(status)) grouped.set(status, []);
      grouped.get(status)!.push(r);
    }
    return grouped;
  }, [filtered]);

  const sortedStatusEntries = useMemo(() =>
    [...statusGroups.entries()].sort((a, b) => {
      const ao = STATUS_SORT[a[0]] ?? 99;
      const bo = STATUS_SORT[b[0]] ?? 99;
      return ao - bo;
    }),
    [statusGroups]
  );

  const toggleStatus = (status: string) =>
    setExpandedStatuses(prev => ({ ...prev, [status]: !prev[status] }));

  const toggleDate = (key: string) =>
    setCollapsedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const openPrintDialog = () => {
    setSelectedPrintStatuses(new Set(statusGroups.keys()));
    setShowPrintDialog(true);
  };

  const togglePrintStatus = (status: string) => {
    setSelectedPrintStatuses(prev => {
      const next = new Set(prev);
      if (next.has(status)) next.delete(status); else next.add(status);
      return next;
    });
  };

  const handlePrintReport = () => {
    setShowPrintDialog(false);
    const win = window.open('', '_blank');
    if (!win) return;
    const dateRangeLabel = RANGES.find(r => r.key === range)?.label || 'Custom';

    let html = `<html><head><title>Executive Report</title>
      <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@700&display=swap" rel="stylesheet">
      <style>
        * { box-sizing: border-box; }
        body { font-family: Arial, sans-serif; color: #111; background: #fff; margin: 0; padding: 20px; font-size: 11px; }
        .font-cinzel { font-family: 'Cinzel', serif; font-weight: 700; }
        h1 { margin: 0 0 4px; font-size: 22px; }
        .summary { margin-bottom: 20px; padding: 12px 16px; background: #f9f9f9; border-radius: 6px; border: 1px solid #ddd; display: flex; flex-wrap: wrap; gap: 12px 32px; }
        .summary-item { font-size: 12px; }
        .summary-item span { font-weight: bold; }
        .profit-pos { color: #16a34a; }
        .profit-neg { color: #dc2626; }
        .meta { font-size: 10px; color: #888; margin-bottom: 20px; }

        /* Status section */
        .status-section { margin-bottom: 28px; break-inside: avoid; }
        .status-header { font-size: 15px; color: #C9A84C; border-bottom: 2px solid #C9A84C; padding-bottom: 4px; margin: 0 0 10px; }
        .status-totals { font-size: 11px; color: #555; margin-bottom: 10px; }

        /* Brand section */
        .brand-block { margin-bottom: 16px; }
        .brand-header { font-size: 12px; font-weight: bold; background: #222; color: #fff; padding: 5px 10px; border-radius: 4px; margin-bottom: 6px; }
        .client-header { background: #444; color: #fff; padding: 5px 10px; font-size: 11px; font-weight: bold; display: flex; justify-content: space-between; align-items: center; }
        .client-meta { font-size: 9px; font-weight: normal; color: #ccc; }

        /* Table */
        table { width: 100%; border-collapse: collapse; margin-bottom: 0; page-break-inside: auto; }
        thead tr { background: #444; color: #fff; }
        th { padding: 6px 8px; text-align: left; font-size: 10px; font-weight: bold; white-space: nowrap; }
        td { padding: 5px 8px; vertical-align: top; font-size: 10px; }
        tbody tr:nth-child(even) { background: #f5f5f5; }
        tbody tr:nth-child(odd) { background: #fff; }
        tr.subtotal-row { background: #e8e8e8 !important; border-top: 2px solid #111; font-weight: bold; }
        .r { text-align: right; }
        .client-name { font-weight: bold; }
        .order-id { font-family: monospace; font-size: 9px; color: #777; }
        .grams { color: #555; }
      </style></head><body>
      <h1 class="font-cinzel">EXECUTIVE SUMMARY REPORT</h1>
      <p class="meta">Date Range: ${dateRangeLabel} &nbsp;|&nbsp; Generated: ${new Date().toLocaleString()}</p>
      <div class="summary">
        <div class="summary-item">Confirmed Profit (Delivered): <span class="profit-pos">AED ${kpis.confirmedProfit.toFixed(2)}</span></div>
        <div class="summary-item">Total Expected Profit: <span class="profit-pos">AED ${kpis.totalProfit.toFixed(2)}</span></div>
        <div class="summary-item">Items Delivered: <span>${kpis.totalSold}</span></div>
        <div class="summary-item">Outstanding: <span>AED ${kpis.outstanding.toFixed(2)}</span></div>
        <div class="summary-item">Total Grams: <span>${kpis.totalGrams.toFixed(2)}g</span></div>
      </div>
      <div class="summary" style="margin-top:8px;">
        <strong style="font-size:12px;width:100%;display:block;margin-bottom:6px;">Confirmed Profit by Native Currency</strong>
        <div class="summary-item">Local (AED): <span class="${kpis.confirmedNativeProfitAED >= 0 ? 'profit-pos' : 'profit-neg'}">AED ${kpis.confirmedNativeProfitAED.toFixed(2)}</span></div>
        <div class="summary-item">Pinas (PHP): <span class="${kpis.confirmedNativeProfitPHP >= 0 ? 'profit-pos' : 'profit-neg'}">PHP ${kpis.confirmedNativeProfitPHP.toFixed(0)}</span></div>
        <div class="summary-item">Intl (USD): <span class="${kpis.confirmedNativeProfitUSD >= 0 ? 'profit-pos' : 'profit-neg'}">USD ${kpis.confirmedNativeProfitUSD.toFixed(2)}</span></div>
      </div>`;

    [...statusGroups.entries()]
      .filter(([status]) => selectedPrintStatuses.has(status))
      .sort((a, b) => (STATUS_SORT[a[0]] ?? 99) - (STATUS_SORT[b[0]] ?? 99))
      .forEach(([status, items]) => {
        const isDead = DEAD_STATUSES.has(status);
        const statusPrice = items.reduce((s, r) => s + calcItemPriceAED(r), 0);
        const statusCost = items.reduce((s, r) => s + calcItemCostAED(r), 0);
        const statusProfit = items.reduce((s, r) => s + calcProfitAED(r), 0);

        // Group by brand only
        const byBrand = new Map<string, DatabaseRowType[]>();
        for (const r of items) {
          let pk = (r.page || 'Other').trim();
          if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
          else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
          if (!byBrand.has(pk)) byBrand.set(pk, []);
          byBrand.get(pk)!.push(r);
        }
        const sortedBrands = [...byBrand.entries()].sort((a, b) => {
          if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
          if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
          return a[0].localeCompare(b[0]);
        });

        html += `<div class="status-section">`;
        html += `<h2 class="font-cinzel status-header">${status.toUpperCase()} &nbsp; <small style="font-size:12px;font-weight:normal;">(${items.length} items)</small></h2>`;
        if (!isDead) {
          html += `<p class="status-totals">Price: AED ${statusPrice.toFixed(2)} &nbsp;|&nbsp; Cost: AED ${statusCost.toFixed(2)} &nbsp;|&nbsp; <strong class="${statusProfit >= 0 ? 'profit-pos' : 'profit-neg'}">Profit: AED ${statusProfit.toFixed(2)}</strong></p>`;
        }

        const profitTh = isDead ? '' : `<th class="r">Profit</th>`;

        sortedBrands.forEach(([brand, brandRows]) => {
          const bPrice = brandRows.reduce((s, r) => s + calcItemPriceAED(r), 0);
          const bCost = brandRows.reduce((s, r) => s + calcItemCostAED(r), 0);
          const bProfit = brandRows.reduce((s, r) => s + calcProfitAED(r), 0);
          const bGrams = brandRows.reduce((s, r) => {
            const c = (r.category || '').toLowerCase();
            return c.includes('per pc') || c.includes('screw type') || c.includes('diamond') ? s : s + (Number(r.grams) || 0);
          }, 0);

          // Group by client within this brand, sorted by date desc
          const byClient = new Map<string, DatabaseRowType[]>();
          for (const r of [...brandRows].sort((a, b) => (b.dateOfLive || '').localeCompare(a.dateOfLive || ''))) {
            const key = `${r.minerName || 'Unknown'}__${r.dateOfLive || ''}`;
            if (!byClient.has(key)) byClient.set(key, []);
            byClient.get(key)!.push(r);
          }

          html += `<div class="brand-block">`;
          html += `<div class="brand-header">📄 ${brand} &nbsp; <span style="font-weight:normal;font-size:10px;">${brandRows.length} items · ${bGrams.toFixed(2)}g</span></div>`;

          byClient.forEach((clientRows, key) => {
            const [clientName] = key.split('__');
            const cDate = clientRows[0]?.dateOfLive;
            const cPrice = clientRows.reduce((s, r) => s + calcItemPriceAED(r), 0);
            const cCost = clientRows.reduce((s, r) => s + calcItemCostAED(r), 0);
            const cProfit = clientRows.reduce((s, r) => s + calcProfitAED(r), 0);
            const cGrams = clientRows.reduce((s, r) => {
              const c = (r.category || '').toLowerCase();
              return c.includes('per pc') || c.includes('screw type') || c.includes('diamond') ? s : s + (Number(r.grams) || 0);
            }, 0);

            html += `<div style="margin-bottom:10px;">
              <div class="client-header">
                <span>${clientName}</span>
                <span class="client-meta">${formatDate(cDate)} &nbsp;·&nbsp; ${clientRows.length} item${clientRows.length !== 1 ? 's' : ''} &nbsp;·&nbsp; ${cGrams.toFixed(2)}g</span>
              </div>
              <table><thead><tr>
                <th>Order ID</th><th>Item</th><th class="r">Grams</th>
                <th class="r">Price</th><th class="r">Cost</th>${profitTh}
              </tr></thead><tbody>`;

            clientRows.forEach(r => {
              const cat = (r.category || '').toLowerCase();
              const isPc = cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond');
              const gramsStr = isPc ? `${r.grams ? Number(r.grams).toFixed(2) : ''}PC` : (r.grams ? `${Number(r.grams).toFixed(2)}g` : '—');
              const pr = calcProfitAED(r);
              const pCell = isDead ? '' : `<td class="r ${pr >= 0 ? 'profit-pos' : 'profit-neg'}">${pr.toFixed(2)}</td>`;
              html += `<tr>
                <td class="order-id">${r.orderId || `#${r.id}`}</td>
                <td>${r.itemDescription || '—'}</td>
                <td class="r">${gramsStr}</td>
                <td class="r">${calcItemPriceAED(r).toFixed(2)}</td>
                <td class="r">${calcItemCostAED(r).toFixed(2)}</td>
                ${pCell}
              </tr>`;
            });

            const subProfitCell = isDead ? '' : `<td class="r ${cProfit >= 0 ? 'profit-pos' : 'profit-neg'}">${cProfit.toFixed(2)}</td>`;
            html += `<tr class="subtotal-row">
              <td colspan="2">Subtotal</td><td class="r"></td>
              <td class="r">${cPrice.toFixed(2)}</td><td class="r">${cCost.toFixed(2)}</td>${subProfitCell}
            </tr></tbody></table></div>`;
          });

          // Brand total
          const brandProfitCell = isDead ? '' : `<td class="r ${bProfit >= 0 ? 'profit-pos' : 'profit-neg'}">${bProfit.toFixed(2)}</td>`;
          html += `<table style="margin-top:4px;"><tbody><tr class="subtotal-row" style="background:#d0d0d0!important;">
            <td colspan="2"><strong>${brand} TOTAL — ${brandRows.length} items · ${bGrams.toFixed(2)}g</strong></td>
            <td class="r"></td><td class="r">${bPrice.toFixed(2)}</td><td class="r">${bCost.toFixed(2)}</td>${brandProfitCell}
          </tr></tbody></table>`;

          html += `</div>`;
        });
        html += `</div>`;
      });

    html += `</body></html>`;
    win.document.write(html);
    win.document.close();
    win.print();
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Bossing Dashboard" subtitle="Executive summary — AED" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">

        {/* Filters Row */}
        <div className="flex flex-wrap items-center gap-2 mb-4">
          <div className="flex gap-1 flex-wrap flex-1">
            {RANGES.map(r => (
              <Button
                key={r.key}
                size="sm"
                variant={range === r.key ? 'default' : 'outline'}
                className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-7 text-xs w-36 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {range === 'custom' && (
          <div className="flex gap-2 mb-4">
            <Popover open={pickerOpen} onOpenChange={setPickerOpen}>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={d => { setCustomFrom(d); setPickerOpen(false); }} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={d => setCustomTo(d)} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        {/* KPI Grid */}
        <div className="grid grid-cols-2 gap-3 mb-6">
          {/* Confirmed Delivered Profit — most important KPI */}
          <div className="col-span-2 rounded-xl border border-primary/40 bg-primary/5 p-4 flex flex-col gap-1.5">
            <div className="flex items-center gap-1.5">
              <TrendingUp className="h-3.5 w-3.5 text-primary" />
              <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">Confirmed Profit (Delivered)</p>
            </div>
            <p className="text-2xl font-bold font-cinzel text-primary leading-none">AED {kpis.confirmedProfit.toFixed(2)}</p>
            <p className="text-[10px] text-muted-foreground">{kpis.totalSold} items delivered · All-active: AED {kpis.totalProfit.toFixed(2)}</p>
          </div>

          {/* Native Currency Profit Split — Confirmed (Delivered) */}
          <div className="col-span-2 rounded-xl border border-border bg-card p-3">
            <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-2">Confirmed Profit by Currency</p>
            <div className="grid grid-cols-3 gap-2">
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Local (AED)</p>
                <p className={`text-sm font-bold ${kpis.confirmedNativeProfitAED >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                  AED {kpis.confirmedNativeProfitAED.toFixed(0)}
                </p>
              </div>
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Pinas (PHP)</p>
                <p className={`text-sm font-bold ${kpis.confirmedNativeProfitPHP >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                  PHP {kpis.confirmedNativeProfitPHP.toFixed(0)}
                </p>
              </div>
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Intl (USD)</p>
                <p className={`text-sm font-bold ${kpis.confirmedNativeProfitUSD >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                  USD {kpis.confirmedNativeProfitUSD.toFixed(2)}
                </p>
              </div>
            </div>
          </div>

          {/* Native Currency Profit Split — All Active */}
          <div className="col-span-2 rounded-xl border border-border bg-card p-3">
            <p className="text-[10px] font-semibold uppercase tracking-widest text-muted-foreground mb-2">Expected Profit by Currency (All Active)</p>
            <div className="grid grid-cols-3 gap-2">
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Local (AED)</p>
                <p className={`text-sm font-bold ${kpis.nativeProfitAED >= 0 ? 'text-foreground' : 'text-destructive'}`}>
                  AED {kpis.nativeProfitAED.toFixed(0)}
                </p>
              </div>
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Pinas (PHP)</p>
                <p className={`text-sm font-bold ${kpis.nativeProfitPHP >= 0 ? 'text-foreground' : 'text-destructive'}`}>
                  PHP {kpis.nativeProfitPHP.toFixed(0)}
                </p>
              </div>
              <div className="rounded-lg bg-muted/40 p-2 text-center">
                <p className="text-[9px] uppercase tracking-widest text-muted-foreground mb-0.5">Intl (USD)</p>
                <p className={`text-sm font-bold ${kpis.nativeProfitUSD >= 0 ? 'text-foreground' : 'text-destructive'}`}>
                  USD {kpis.nativeProfitUSD.toFixed(2)}
                </p>
              </div>
            </div>
          </div>

          <KpiCard title="Total Grams" value={`${kpis.totalGrams.toFixed(2)}g`} subtitle="Excl. PC / Screw / Diamond" />
          <KpiCard title="Outstanding" value={`AED ${kpis.outstanding.toFixed(0)}`} subtitle="Remaining receivables" />
        </div>

        {/* Detailed Breakdown header */}
        <div className="flex items-center justify-between mb-3">
          <h2 className="font-cinzel text-base text-primary">Breakdown by Status</h2>
          <Button variant="outline" size="sm" className="h-8 text-xs border-primary/40 text-primary" onClick={openPrintDialog}>
            <Printer className="h-3.5 w-3.5 mr-1.5" /> Print Report
          </Button>
        </div>

        <div className="space-y-2">
          {sortedStatusEntries.map(([status, items]) => {
            const isDead = DEAD_STATUSES.has(status);
            const totalProfit = items.reduce((sum, r) => sum + calcProfitAED(r), 0); // AED for group header
            const groupGrams = items.reduce((sum, r) => {
              const cat = (r.category || '').toLowerCase();
              if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return sum;
              return sum + (Number(r.grams) || 0);
            }, 0);
            const isExpanded = expandedStatuses[status];

            return (
              <div key={status} className="rounded-xl border border-border bg-card overflow-hidden">
                <button
                  onClick={() => toggleStatus(status)}
                  className="w-full flex items-center justify-between px-4 py-3 text-left focus:outline-none"
                >
                  <div className="flex items-center gap-3 flex-1 min-w-0">
                    <StatusBadge status={status} />
                    <span className="text-xs text-muted-foreground shrink-0">{items.length} items</span>
                    {!isDead && (
                      <span className={`text-xs font-semibold ${totalProfit >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                        AED {totalProfit.toFixed(2)}
                      </span>
                    )}
                    {groupGrams > 0 && (
                      <span className="text-xs text-muted-foreground hidden sm:inline">{groupGrams.toFixed(2)}g</span>
                    )}
                  </div>
                  <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform shrink-0 ml-2 ${isExpanded ? 'rotate-180' : ''}`} />
                </button>

                {isExpanded && (() => {
                  const statusLiver = statusLiverFilters[status] || 'all';
                  const statusLiverNames = [...new Set(items.map(r => r.liverName?.trim().toUpperCase()).filter(Boolean) as string[])].sort();
                  const visibleItems = statusLiver === 'all' ? items : items.filter(r => r.liverName?.trim().toUpperCase() === statusLiver);

                  const byPage = new Map<string, Map<string, DatabaseRowType[]>>();
                  for (const r of visibleItems) {
                    let pk = (r.page || 'Other').trim();
                    if (pk.toUpperCase().includes('MYK')) pk = 'MYK';
                    else if (pk.toUpperCase().includes('EMPIRE')) pk = 'Empire Gold By ETG';
                    const d = r.dateOfLive || 'Unknown Date';
                    if (!byPage.has(pk)) byPage.set(pk, new Map());
                    const bd = byPage.get(pk)!;
                    if (!bd.has(d)) bd.set(d, []);
                    bd.get(d)!.push(r);
                  }
                  const sortedPages = [...byPage.entries()].sort((a, b) => {
                    if (a[0] === 'MYK') return -1; if (b[0] === 'MYK') return 1;
                    if (a[0] === 'Empire Gold By ETG') return -1; if (b[0] === 'Empire Gold By ETG') return 1;
                    return a[0].localeCompare(b[0]);
                  });

                  return (
                    <div className="px-4 pb-4 border-t border-border pt-3 animate-in fade-in slide-in-from-top-2 duration-200">
                      {statusLiverNames.length > 1 && (
                        <div className="mb-3">
                          <Select value={statusLiver} onValueChange={v => setStatusLiverFilters(prev => ({ ...prev, [status]: v }))}>
                            <SelectTrigger className="h-7 text-xs w-40 bg-background border-border">
                              <SelectValue placeholder="All Livers" />
                            </SelectTrigger>
                            <SelectContent className="bg-popover border-border">
                              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
                              {statusLiverNames.map(name => (
                                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
                              ))}
                            </SelectContent>
                          </Select>
                        </div>
                      )}
                      <div className="space-y-4">
                        {sortedPages.map(([page, dateMap]) => {
                          const sortedDates = [...dateMap.entries()].sort((a, b) => b[0].localeCompare(a[0]));
                          return (
                            <div key={page}>
                              <div className="flex items-center gap-2 mb-2">
                                <span className="text-[10px] font-bold text-primary/70 uppercase tracking-widest">📄 {page}</span>
                                <div className="h-px flex-1 bg-border/50" />
                                <span className="text-[10px] text-muted-foreground">{Array.from(dateMap.values()).reduce((s, v) => s + v.length, 0)}</span>
                              </div>
                              <div className="space-y-2 ml-2">
                                {sortedDates.map(([date, dateItems]) => {
                                  const dateKey = `${status}__${page}__${date}`;
                                  const isDateCollapsed = collapsedDates[dateKey];
                                  const dg = dateItems.reduce((s, r) => {
                                    const c = (r.category || '').toLowerCase();
                                    return c.includes('per pc') || c.includes('screw type') || c.includes('diamond') ? s : s + (Number(r.grams) || 0);
                                  }, 0);
                                  const dp = dateItems.reduce((s, r) => s + calcProfitAED(r), 0); // AED for date header

                                  return (
                                    <div key={date} className="rounded-lg border border-border/50 overflow-hidden">
                                      <button
                                        onClick={() => toggleDate(dateKey)}
                                        className="w-full flex items-center justify-between px-3 py-2 bg-muted/40 hover:bg-muted/60 transition-colors text-left focus:outline-none"
                                      >
                                        <div className="flex items-center gap-2">
                                          <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">📅 {formatDate(date)}</span>
                                          <span className="text-[9px] text-muted-foreground bg-border/50 px-1.5 py-0.5 rounded-full">
                                            {dateItems.length} item{dateItems.length !== 1 ? 's' : ''}{dg > 0 ? ` · ${dg.toFixed(2)}g` : ''}
                                          </span>
                                          {!isDead && (
                                            <span className={`text-[9px] font-semibold ${dp >= 0 ? 'text-green-400' : 'text-destructive'}`}>
                                              AED {dp.toFixed(2)}
                                            </span>
                                          )}
                                        </div>
                                        <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${isDateCollapsed ? '' : 'rotate-180'}`} />
                                      </button>

                                      {!isDateCollapsed && (
                                        <div className="px-3 py-2 space-y-2">
                                          {dateItems.map(record => {
                                            const profit = calcProfitNative(record);
                                            const curr = getEffectiveCurrency(record);
                                            const cat = (record.category || '').toLowerCase();
                                            const isPc = cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond');
                                            const gramsDisplay = isPc ? 'PC' : (record.grams ? `${Number(record.grams).toFixed(2)}g` : '—');
                                            return (
                                              <div key={record.id} className="flex justify-between items-start border-b border-border/40 pb-2 last:border-0 last:pb-0">
                                                <div className="flex-1 pr-2">
                                                  <div className="flex items-center gap-1.5">
                                                    <p className="text-sm font-medium">{record.minerName || 'Unknown'}</p>
                                                    {record.customerId && (
                                                      <button
                                                        onClick={e => { e.stopPropagation(); setHistoryCustomer({ id: record.customerId!, name: record.minerName || '' }); }}
                                                        className="text-muted-foreground hover:text-primary transition-colors"
                                                        title="View Lifetime History"
                                                      >
                                                        <History className="h-3.5 w-3.5" />
                                                      </button>
                                                    )}
                                                  </div>
                                                  <p className="text-xs text-muted-foreground mt-0.5 truncate">{record.itemDescription}</p>
                                                </div>
                                                <div className="text-right shrink-0 space-y-0.5">
                                                  <p className="text-[10px] font-semibold text-muted-foreground">{gramsDisplay}</p>
                                                  {!isDead && (
                                                    <>
                                                      <p className={`text-sm font-medium ${profit >= 0 ? 'text-foreground' : 'text-destructive'}`}>{curr} {profit.toFixed(curr === 'AED' ? 2 : 0)}</p>
                                                      <p className="text-[10px] text-muted-foreground">Profit</p>
                                                    </>
                                                  )}
                                                </div>
                                              </div>
                                            );
                                          })}
                                        </div>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  );
                })()}
              </div>
            );
          })}

          {statusGroups.size === 0 && (
            <div className="text-center py-12 border border-dashed border-border rounded-xl">
              <p className="text-sm text-muted-foreground">No records found for this period.</p>
            </div>
          )}
        </div>
      </div>

      {/* Print Dialog */}
      <Dialog open={showPrintDialog} onOpenChange={setShowPrintDialog}>
        <DialogContent className="bg-card border-border max-w-sm">
          <DialogHeader>
            <DialogTitle className="font-cinzel text-primary text-base">Select Statuses to Print</DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <div className="flex gap-2 mb-2">
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set(statusGroups.keys()))}>Select All</Button>
              <Button size="sm" variant="outline" className="text-xs h-7 border-border" onClick={() => setSelectedPrintStatuses(new Set())}>Clear All</Button>
            </div>
            {sortedStatusEntries.map(([status, items]) => (
              <div key={status} className="flex items-center gap-3">
                <Checkbox id={`print-${status}`} checked={selectedPrintStatuses.has(status)} onCheckedChange={() => togglePrintStatus(status)} />
                <Label htmlFor={`print-${status}`} className="text-sm cursor-pointer flex-1">
                  {status}
                  <span className="text-xs text-muted-foreground ml-2">({items.length} items)</span>
                </Label>
              </div>
            ))}
          </div>
          <DialogFooter>
            <Button variant="outline" size="sm" className="text-xs border-border" onClick={() => setShowPrintDialog(false)}>Cancel</Button>
            <Button size="sm" className="text-xs bg-primary text-primary-foreground" disabled={selectedPrintStatuses.size === 0} onClick={handlePrintReport}>
              <Printer className="h-3.5 w-3.5 mr-1.5" /> Print
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {historyCustomer && (
        <CustomerHistoryModal
          customerId={historyCustomer.id}
          minerName={historyCustomer.name}
          allRecords={records}
          onClose={() => setHistoryCustomer(null)}
        />
      )}
    </div>
  );
}

