    const brandedPhpAnchor = Math.round(brandedTarget * phpRate);
    if (isSilver && rawRate === silverPhpAnchor) return silverTarget;
    if (isSilverBranded && rawRate === brandedPhpAnchor) return brandedTarget;
    // Fallback: standard division for non-menu items
    const rawAED = rawRate / phpRate;
    // Near-anchor Smart Snap (±10 AED) catches manual/rounded entries
    if (isSilverBranded && Math.abs(rawAED - brandedTarget) <= 10) return brandedTarget;
    if (isSilver && Math.abs(rawAED - silverTarget) <= 10) return silverTarget;
    return rawAED;
  }

  if (curr === 'USD') {
    // Dynamically compute today's exact menu prices in USD
    const silverUsdAnchor = Math.round(silverTarget / USD_TO_AED);
    const brandedUsdAnchor = Math.round(brandedTarget / USD_TO_AED);
    if (isSilver && rawRate === silverUsdAnchor) return silverTarget;
    if (isSilverBranded && rawRate === brandedUsdAnchor) return brandedTarget;
    // Fallback: standard USD → AED conversion
    const rawAED = rawRate * USD_TO_AED;
    if (isSilverBranded && Math.abs(rawAED - brandedTarget) <= 10) return brandedTarget;
    if (isSilver && Math.abs(rawAED - silverTarget) <= 10) return silverTarget;
    return rawAED;
  }

  return rawRate; // Unknown currency — pass through
}

// ── MASTER ANCHOR: toAED ─────────────────────────────────────────────────────
// Converts any currency value to AED.
// CRITICAL: Smart Snap NEVER fires for AED inputs — the entered value IS truth.
export function toAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'AED') return value;

  const snap = getRatesForDate(record?.dateOfLive || '');
  let rawAED: number;

  if (curr === 'USD') {
    rawAED = value * USD_TO_AED;
  } else if (curr === 'PHP') {
    rawAED = value / snap.phpRate;
  } else {
    return value;
  }

  // Smart Snap for silver items converting from foreign currency
  if (record?.dateOfLive) {
    const category = (record.category || '').toLowerCase();
    if (category.includes('silver branded')) {
      if (Math.abs(rawAED - snap.silverBrandedSellRate) <= 10) return snap.silverBrandedSellRate;
    } else if (category.includes('silver')) {
      if (Math.abs(rawAED - snap.silverSellRate) <= 10) return snap.silverSellRate;
    }
  }

  return rawAED;
}

// ── fromAED: convert AED → native currency ──────────────────────────────────
export function fromAED(value: number, record?: DatabaseRowType): number {
  if (!value) return 0;
  const curr = record ? getEffectiveCurrency(record) : 'AED';
  if (curr === 'USD') return value / USD_TO_AED;
  if (curr === 'PHP') {
    const snap = getRatesForDate(record?.dateOfLive || '');
    return value * snap.phpRate;
  }
  return value;
}

export function clientRateAED(record: DatabaseRowType): number {
  const curr = getEffectiveCurrency(record);
  if (curr === 'AED') return n(record.clientRate);
  return resolveBaseRateAED(record);
}

export function calcItemPrice(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (clientRate > 0) return roundPrice(n(record.grams) * clientRate);
    return roundPrice(fromAED(n(record.grams) * silverRate, record));
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(clientRate * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(clientRate);
  const price = roundPrice(n(record.grams) * clientRate);
  return price > 0 ? price : (clientRate > 0 ? roundPrice(clientRate) : 0);
}

export function calcItemPriceAED(record: DatabaseRowType): number {
  const rateAED = clientRateAED(record);
  const category = (record.category || '').toLowerCase();
  const silverRate = getSilverRate(category, record);

  if (silverRate !== null) {
    if (n(record.clientRate) > 0) return roundPrice(n(record.grams) * rateAED);
    return roundPrice(n(record.grams) * silverRate);
  }

  if (category.includes('per pc') || category.includes('screw type') || category.includes('diamond')) {
    return roundPrice(rateAED * getQty(record));
  }

  if (isPcItem(record)) return roundPrice(rateAED);
  const price = roundPrice(n(record.grams) * rateAED);
  return price > 0 ? price : (rateAED > 0 ? roundPrice(rateAED) : 0);
}

export function calcItemCostAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const desc = (record.itemDescription || '').toLowerCase();
  const grams = n(record.grams);
  const goldRate = n(record.goldRate);
  const supplierRate = n(record.supplierRate);
  const mc = n(record.mc);

  if (category.includes('diamond')) return roundPrice(supplierRate * getQty(record));

  if (category.includes('per pc') || category.includes('screw type')) {
    let rate = supplierRate > 0 ? supplierRate : goldRate > 0 ? goldRate : 115;
    if (rate === 115 && (desc.includes('buy 1 take 1') || desc.includes('b1t1'))) rate *= 2;
    return roundPrice(rate * getQty(record));
  }

  // Silver cost rates come from the daily snapshot (dynamic, not hardcoded)
  const snap = getRatesForDate(record.dateOfLive || '');
  if (category.includes('silver branded')) return roundPrice(snap.silverBrandedCostRate * grams);
  if (category.includes('silver')) return roundPrice(snap.silverCostRate * grams);

  if (goldRate > 0) {
    const effectiveMc = mc > 0 ? mc : category.includes('special price ef') ? 25 : category.includes('special price') ? 21 : 16;
    if (isPcItem(record)) return roundPrice(goldRate + effectiveMc);
    return roundPrice((goldRate + effectiveMc) * grams);
  }

  if (supplierRate > 0) {
    if (isPcItem(record)) return roundPrice(supplierRate);
    return roundPrice(supplierRate * grams);
  }

  return 0;
}

// ── calcProfitNative ─────────────────────────────────────────────────────────
// Returns profit in the record's NATIVE currency (PHP, AED, or USD).
//
// Native Currency Math Protocol:
//   A. Determine total cost in AED (using dynamic daily cost rates from ratesStore)
//   B. Convert AED cost to native currency (using daily phpRate snapshot)
//   C. Native Profit = native sales - native cost
//
// Why native? AED→PHP→AED roundtrips lose precision, and PHP profit figures
// in PHP are more meaningful to the business owner than AED equivalents.
export function calcProfitNative(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const isSilver = getSilverRate(category, record) !== null;
  const isPerPcType = category.includes('per pc') || category.includes('screw type') || category.includes('diamond');
  const grams = n(record.grams);

  // Guard: skip items with no cost data
  if (!isSilver && !isPerPcType && grams > 0) {
    if (n(record.goldRate) === 0 && n(record.supplierRate) === 0) return 0;
  }

  // A. Total Cost in AED (uses dynamic daily snapshot rates)
  const costAED = calcItemCostAED(record);

  // B. Convert Cost to Native Currency
  const curr = getEffectiveCurrency(record);
  const snap = getRatesForDate(record.dateOfLive || '');

  let nativeCost: number;
  if (curr === 'PHP') nativeCost = costAED * snap.phpRate;
  else if (curr === 'USD') nativeCost = costAED / USD_TO_AED;
  else nativeCost = costAED;

  // C. Native Sales = calcItemPrice (already returns value in native currency)
  const nativeSales = calcItemPrice(record);

  return roundPrice(nativeSales - nativeCost);
}

// calcProfitAED — AED-normalized profit, used for group/status summary headers
export function calcProfitAED(record: DatabaseRowType): number {
  const category = (record.category || '').toLowerCase();
  const grams = n(record.grams);
  const isSilver = getSilverRate(category, record) !== null;
  const isPerPcType = category.includes('per pc') || category.includes('screw type') || category.includes('diamond');

  if (!isSilver && !isPerPcType && grams > 0) {
    if (n(record.goldRate) === 0 && n(record.supplierRate) === 0) return 0;
  }

  return roundPrice(calcItemPriceAED(record) - calcItemCostAED(record));
}

export function calcProfit(record: DatabaseRowType): number {
  return calcProfitAED(record);
}

export function calcShippingFee(record: DatabaseRowType): number {
  const mos = (record.modeOfSale || '').toLowerCase().trim();
  if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return 0;
  if (isFreeSf(record)) return 0;
  if (record.modeOfPayment === 'Pick Up Shop') return 0;
  if (record.modeOfPayment === 'Meet Up') return 10;

  const loc = normCurrency(record.locationOfMiner);
  if (loc === 'LOCAL') {
    const region = (record.regions || '').toLowerCase();
    if (region.includes('dubai')) return 25;
    if (region.includes('western')) return 45;
    if (region.includes('al ain')) return 30;
    return 30;
  }

  if (loc === 'INTERNATIONAL' || loc === 'PINAS') return 299;
  return 0;
}

export function calcCCFee(record: DatabaseRowType): number {
  if (record.modeOfPayment !== 'Credit Card') return 0;
  return roundPrice(calcItemPriceAED(record) * 0.05);
}

export function calcTotalPaid(record: DatabaseRowType): number {
  const dpRaw = n(record.downpayment);
  const dpAED = dpRaw > 0 ? toAED(dpRaw, record) : 0;
  const otherRaw = n(record.la1MonthPayment) + n(record.la2MonthPayment) + n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
  return dpAED + toAED(otherRaw, record);
}

export function calcRemainingBalance(record: DatabaseRowType): number {
  const itemPriceAED = calcItemPriceAED(record);
  const shippingFee = calcShippingFee(record);
  const ccFee = calcCCFee(record);
  const additionalCharges = n(record.additionalCharges);
  const totalPaid = calcTotalPaid(record);
  return roundPrice((itemPriceAED + shippingFee + ccFee + additionalCharges) - totalPaid);
}

export function calcRemainingBalanceAED(record: DatabaseRowType): number {
  return calcRemainingBalance(record);
}

export function calcDueDate(dateOfLive?: string): Date | null {
  const d = parseDateRobust(dateOfLive);
  if (!d) return null;
  const due = new Date(d);
  due.setHours(due.getHours() + 24);
  return due;
}

export function isOverdue(record: DatabaseRowType): boolean {
  if (record.status !== 'Pending' && record.status !== 'Waiting for Details' && record.status !== 'Waiting for Downpayment') return false;
  const due = calcDueDate(record.dateOfLive);
  if (!due) return false;
  return Date.now() > due.getTime();
}

/**
 * calcItemPricePHP — returns the final item price in PHP.
 * Uses dynamic anchor resolution (no static table).
 */
export function calcItemPricePHP(record: DatabaseRowType): number {
  const clientRate = n(record.clientRate);
  if (clientRate === 0) return 0;

  const currency = String(record.currency || 'AED').toUpperCase();
  const snap = getRatesForDate(record.dateOfLive || '');

  // If already PHP — use directly
  if (currency === 'PHP') return clientRate;

  // Resolve to AED first (handles anchors dynamically)
  const aedRate = resolveBaseRateAED(record);

  // AED → PHP
  return aedRate * snap.phpRate;
}

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [;
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
];

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
  }

  return assignedRoles;
}

