import { useRef, useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, Copy, Loader2 } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

// Statuses that mean the item is completed/on-the-way — shown on a SEPARATE invoice
const DISPATCHED_STATUSES = new Set(['Dispatched', 'Delivered', 'Given to Shop']);
// Statuses fully excluded from all invoices
const EXCLUDED_STATUSES = new Set(['Cancelled', 'Returned Item']);

function sortByDate(list: DatabaseRowType[]) {
  return [...list].sort((a, b) => {
    const ta = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
    const tb = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
    return ta - tb;
  });
}

type InvoiceTab = 'active' | 'dispatched';

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);
  const [tab, setTab] = useState<InvoiceTab>('active');

  useEffect(() => {
    if (!document.getElementById('html2canvas-script') && !(window as any).html2canvas) {
      const script = document.createElement('script');
      script.id = 'html2canvas-script';
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  // ACTIVE: pending/waiting/payment — NOT dispatched/delivered/cancelled
  const activeRecords = useMemo(() =>
    sortByDate(records.filter(r => {
      const s = r.status || '';
      return !EXCLUDED_STATUSES.has(s) && !DISPATCHED_STATUSES.has(s);
    })),
    [records]
  );

  // DISPATCHED / COMPLETED: items on-the-way or already delivered
  const dispatchedRecords = useMemo(() =>
    sortByDate(records.filter(r => DISPATCHED_STATUSES.has(r.status || ''))),
    [records]
  );

  const visibleRecords = tab === 'active' ? activeRecords : dispatchedRecords;

  const baseRecord = visibleRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleCopyImage = async () => {
    if (visibleRecords.length === 0 || !printRef.current) return;

    const html2canvas = (window as any).html2canvas;
    if (!html2canvas) {
      toast.error('The image tool is still loading. Please try again in a few seconds.');
      return;
    }

    setIsCopying(true);
    toast.info('Generating image, please wait...');

    try {
      const makeImagePromise = async (): Promise<Blob> => {
        const canvas = await html2canvas(printRef.current!, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          scrollY: 0,
          windowHeight: printRef.current?.scrollHeight || window.innerHeight
        });
        return new Promise<Blob>((resolve, reject) => {
          canvas.toBlob((blob: Blob | null) => {
            if (blob) resolve(blob);
            else reject(new Error('Failed to generate image blob'));
          }, 'image/png');
        });
      };

      await navigator.clipboard.write([
        new ClipboardItem({ 'image/png': makeImagePromise() })
      ]);
      toast.success('Invoice image copied! You can now paste it into Meta Business Suite.');
    } catch (error: any) {
      console.error(error);
      if (error.name === 'NotAllowedError') {
        toast.error('Clipboard permission denied. Please allow clipboard access in your browser settings.');
      } else {
        toast.error('Failed to copy image. Try again.');
      }
    } finally {
      setIsCopying(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0" aria-describedby={undefined}>
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between gap-4">
              <DialogTitle className="text-base font-bold text-foreground">
                Statement of Account
              </DialogTitle>
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                  <Select value={currency} onValueChange={setCurrency}>
                    <SelectTrigger className="h-8 w-24 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CURRENCIES.map(c => (
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button
                  onClick={handleCopyImage}
                  size="sm"
                  variant="outline"
                  className="h-8 border-border text-foreground"
                  disabled={visibleRecords.length === 0 || isCopying}
                >
                  {isCopying ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Copy className="h-3.5 w-3.5 mr-1.5" />}
                  {isCopying ? 'Copying...' : 'Copy Image'}
                </Button>
                <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={visibleRecords.length === 0}>
                  <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
                </Button>
              </div>
            </div>

            {/* Tab switcher — only show if BOTH groups have items */}
            <div className="flex gap-1">
              <button
                onClick={() => setTab('active')}
                className={`px-3 py-1 rounded text-xs font-semibold transition-colors ${
                  tab === 'active'
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground hover:bg-muted/80'
                }`}
              >
                Active Orders
                {activeRecords.length > 0 && (
                  <span className="ml-1.5 bg-primary-foreground/20 text-xs rounded-full px-1.5">
                    {activeRecords.length}
                  </span>
                )}
              </button>
              <button
                onClick={() => setTab('dispatched')}
                className={`px-3 py-1 rounded text-xs font-semibold transition-colors ${
                  tab === 'dispatched'
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted text-muted-foreground hover:bg-muted/80'
                }`}
              >
                Dispatched / Delivered
                {dispatchedRecords.length > 0 && (
                  <span className="ml-1.5 bg-primary-foreground/20 text-xs rounded-full px-1.5">
                    {dispatchedRecords.length}
                  </span>
                )}
              </button>
            </div>
          </div>
        </DialogHeader>

        {visibleRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Items</p>
            <p className="text-xs">
              {tab === 'active'
                ? 'No active/pending items. Check the Dispatched/Delivered tab.'
                : 'No dispatched or delivered items.'}
            </p>
          </div>
        )}

        {visibleRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4 bg-white">
              <InvoicePrintContent records={visibleRecords} currency={currency} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

