  const dpRaw = n(record.downpayment);
  let dpAED = 0;
  if (dpRaw > 0) {
    // Downpayment currency = payment method currency (GCash → PHP, not item currency)
    const paymentCurr = getPaymentCurrency(record);
    const snap = getRatesForDate(record.dateOfLive || '');
    if (paymentCurr === 'PHP') dpAED = dpRaw / snap.phpRate;
    else if (paymentCurr === 'USD') dpAED = dpRaw * USD_TO_AED;
    else dpAED = dpRaw; // AED
  }
  // Layaway payments use item currency
  const otherRaw = n(record.la1MonthPayment) + n(record.la2MonthPayment) + n(record.la3MonthPayment) + n(record.la4MonthPayment) + n(record.amountReceived);
  return dpAED + toAED(otherRaw, record);
}

