import { useMemo, useState } from 'react';
import { ClipboardList, Package, Truck, Users, Layout, Crown, BookOpen, XCircle, PauseCircle, ShieldCheck, CheckCircle2, LayoutGrid, List, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import TabHeader from '@/components/TabHeader';
import DispatchClientCard from './DispatchClientCard';
import PulloutReport from './PulloutReport';
import KanbanView from './KanbanView';
import { ChevronDown } from 'lucide-react';
import { parseDateRobust } from '@/lib/calculations';

function agingHours(dateStr?: string): number {
  if (!dateStr) return 0;
  const d = parseDateRobust(dateStr);
  if (!d) return 0;
  return Math.floor((Date.now() - d.getTime()) / (1000 * 60 * 60));
}

function AgingLabel({ dateStr, warnAfterHours }: { dateStr?: string; warnAfterHours: number }) {
  const hours = agingHours(dateStr);
  const days = Math.floor(hours / 24);
  const isUrgent = hours >= warnAfterHours;
  if (!dateStr) return null;
  return (
    <span className={`inline-flex items-center gap-0.5 text-[9px] font-bold px-1.5 py-0.5 rounded-full border ml-1 ${isUrgent ? 'bg-destructive/20 text-destructive border-destructive/30' : 'bg-secondary text-muted-foreground border-border'}`}>
      {isUrgent && <AlertTriangle className="h-2.5 w-2.5" />}
      {days === 0 ? 'today' : `${days}d`}
    </span>
  );
}

export default function DispatchBoard({ records, searchQuery, onSearchChange, onUpdate, userEmail }: TabProps) {
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [showReport, setShowReport] = useState(false);
  const [showPullout, setShowPullout] = useState(false);
  const [showHold, setShowHold] = useState(false);
  const [showPaymentVerif, setShowPaymentVerif] = useState(false);
  const [showReseller, setShowReseller] = useState(false);
  const [showDispatched, setShowDispatched] = useState(false);
  const [showDelivered, setShowDelivered] = useState(false);
  const [showCancelled, setShowCancelled] = useState(false);

  const { forPullout, onHold, paymentVerif, reseller, dispatched, delivered, cancelled } = useMemo(() => {
    const filtered = records.filter(r => {
      const s = r.status || '';
      if (!['For Pullout', 'Dispatch', 'Dispatched', 'Delivered', 'Given to Shop', 'Paid/DP but Item Hold', 'Payment for Verification', 'Reseller', 'Cancelled'].includes(s)) return false;
      const mos = (r.modeOfSale || '').toLowerCase().trim();
      if (mos === 'in-store' || mos === 'walk-in' || mos === 'walk in') return false;
      return true;
    });
    const searched = applySearch(filtered, searchQuery);
    return {
      forPullout: groupByPageDateMiner(searched.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch')),
      onHold: groupByPageDateMiner(searched.filter(r => r.status === 'Paid/DP but Item Hold')),
      paymentVerif: groupByPageDateMiner(searched.filter(r => r.status === 'Payment for Verification')),
      reseller: groupByPageDateMiner(searched.filter(r => r.status === 'Reseller')),
      dispatched: groupByPageDateMiner(searched.filter(r => r.status === 'Dispatched')),
      delivered: groupByPageDateMiner(searched.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop')),
      cancelled: groupByPageDateMiner(searched.filter(r => r.status === 'Cancelled')),
    };
  }, [records, searchQuery]);

  const pulloutCount = useMemo(() => records.filter(r => r.status === 'For Pullout' || r.status === 'Dispatch').length, [records]);

  const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
    Array.from(g.values()).reduce((s, dm) =>
      s + Array.from(dm.values()).reduce((ss, mm) =>
        ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

  const getPageIcon = (page: string) => {
    if (page === 'MYK') return <Crown className="h-4 w-4 text-yellow-500" />;
    if (page === 'Empire Gold By ETG') return <BookOpen className="h-4 w-4 text-primary" />;
    return <Layout className="h-4 w-4 text-muted-foreground" />;
  };

  const renderGroupedRecords = (groupedData: Map<string, Map<string, Map<string, DatabaseRowType[]>>>, agingWarnHours = 0) => {
    if (groupedData.size === 0) {
      return <p className="text-xs text-muted-foreground px-1">No items found in this category.</p>;
    }
    return Array.from(groupedData.entries()).map(([page, dateMap]) => {
      const totalItems = Array.from(dateMap.values()).reduce((s, m) => s + Array.from(m.values()).reduce((ss, v) => ss + v.length, 0), 0);
      return (
        <div key={page} className="mb-6">
          <div className="flex items-center gap-2 mb-3 py-2 px-3 bg-secondary/40 rounded-lg border border-primary/10">
            {getPageIcon(page)}
            <h3 className="font-cinzel text-sm text-primary tracking-wide uppercase">{page}</h3>
            <div className="h-px flex-1 bg-primary/10" />
            <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
          </div>
          <div className="pl-2 sm:pl-4 space-y-2">
            {Array.from(dateMap.entries()).map(([date, minerMap]) => {
              const allItems = Array.from(minerMap.values()).flat();
              const maxAge = allItems.reduce((m, r) => Math.max(m, agingHours(r.dateOfLive)), 0);
              const isUrgent = agingWarnHours > 0 && maxAge >= agingWarnHours;
              const agingEl = agingWarnHours > 0 ? <AgingLabel dateStr={allItems[0]?.dateOfLive} warnAfterHours={agingWarnHours} /> : null;
              return (
              <CollapsibleGroup key={date} label={formatDate(date)} colorClass={isUrgent ? 'text-destructive' : 'text-muted-foreground'} lineClass={isUrgent ? 'bg-destructive/30' : 'bg-border/40'} indent defaultOpen={false} labelSuffix={agingEl}>
                {Array.from(minerMap.entries()).map(([miner, items]) => (
                  <DispatchClientCard
                    key={miner}
                    minerName={miner}
                    records={items}
                    allRecords={records}
                    onUpdate={onUpdate}
                    userEmail={userEmail}
                  />
                ))}
              </CollapsibleGroup>
              );
            })}
          </div>
        </div>
      );
    });
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Dispatch Board"
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
        rightContent={
          <Button variant="outline" size="sm" className="border-border text-xs h-8" onClick={() => setShowReport(true)}>
            <ClipboardList className="h-3.5 w-3.5 mr-1" />
            Report ({pulloutCount})
          </Button>
        }
      />
      <div className="px-4 pt-4">

        {/* View Toggle */}
        <div className="flex gap-1 mb-4">
          <Button size="sm" variant={viewMode === 'list' ? 'default' : 'outline'} className="h-7 text-xs px-2.5" onClick={() => setViewMode('list')}>
            <List className="h-3.5 w-3.5 mr-1" /> List
          </Button>
          <Button size="sm" variant={viewMode === 'kanban' ? 'default' : 'outline'} className="h-7 text-xs px-2.5" onClick={() => setViewMode('kanban')}>
            <LayoutGrid className="h-3.5 w-3.5 mr-1" /> Kanban
          </Button>
        </div>

        {viewMode === 'kanban' && (
          <KanbanView records={records.filter(r => {
            const s = r.status || '';
            return ['Payment for Verification', 'For Pullout', 'Dispatch', 'Dispatched', 'Delivered', 'Given to Shop'].includes(s);
          })} onUpdate={onUpdate!} />
        )}

        {viewMode === 'list' && <>

        {/* FOR PULLOUT */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPullout(!showPullout)}>
          <Package className="h-4 w-4 text-purple-400" />
          <span className="font-cinzel text-xs text-purple-400 font-bold">FOR PULLOUT</span>
          {countItems(forPullout) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-purple-400/10 text-purple-400">{countItems(forPullout)}</span>}
          <div className="h-px flex-1 bg-purple-400/30" />
          <ChevronDown className={`h-4 w-4 text-purple-400 transition-transform ${showPullout ? 'rotate-180' : ''}`} />
        </button>
        {showPullout && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(forPullout)}</div>}

        {/* RESELLER */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowReseller(!showReseller)}>
          <Users className="h-4 w-4 text-teal-400" />
          <span className="font-cinzel text-xs text-teal-400 font-bold">RESELLER</span>
          {countItems(reseller) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-teal-400/10 text-teal-400">{countItems(reseller)}</span>}
          <div className="h-px flex-1 bg-teal-400/30" />
          <ChevronDown className={`h-4 w-4 text-teal-400 transition-transform ${showReseller ? 'rotate-180' : ''}`} />
        </button>
        {showReseller && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(reseller)}</div>}

        {/* PAID/DP BUT ON HOLD */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowHold(!showHold)}>
          <PauseCircle className="h-4 w-4 text-indigo-400" />
          <span className="font-cinzel text-xs text-indigo-400 font-bold">PAID/DP BUT ON HOLD</span>
          {countItems(onHold) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-indigo-400/10 text-indigo-400">{countItems(onHold)}</span>}
          <div className="h-px flex-1 bg-indigo-400/30" />
          <ChevronDown className={`h-4 w-4 text-indigo-400 transition-transform ${showHold ? 'rotate-180' : ''}`} />
        </button>
        {showHold && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(onHold, 72)}</div>}

        {/* PAYMENT FOR VERIFICATION */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowPaymentVerif(!showPaymentVerif)}>
          <ShieldCheck className="h-4 w-4 text-amber-400" />
          <span className="font-cinzel text-xs text-amber-400 font-bold">PAYMENT FOR VERIFICATION</span>
          {countItems(paymentVerif) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-amber-400/10 text-amber-400">{countItems(paymentVerif)}</span>}
          <div className="h-px flex-1 bg-amber-400/30" />
          <ChevronDown className={`h-4 w-4 text-amber-400 transition-transform ${showPaymentVerif ? 'rotate-180' : ''}`} />
        </button>
        {showPaymentVerif && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(paymentVerif, 24)}</div>}

        {/* DISPATCHED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDispatched(!showDispatched)}>
          <Truck className="h-4 w-4 text-orange-400" />
          <span className="font-cinzel text-xs text-orange-400 font-bold">DISPATCHED</span>
          {countItems(dispatched) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-orange-400/10 text-orange-400">{countItems(dispatched)}</span>}
          <div className="h-px flex-1 bg-orange-400/30" />
          <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform ${showDispatched ? 'rotate-180' : ''}`} />
        </button>
        {showDispatched && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(dispatched)}</div>}

        {/* DELIVERED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowDelivered(!showDelivered)}>
          <CheckCircle2 className="h-4 w-4 text-green-400" />
          <span className="font-cinzel text-xs text-green-400 font-bold">DELIVERED</span>
          {countItems(delivered) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-green-400/10 text-green-400">{countItems(delivered)}</span>}
          <div className="h-px flex-1 bg-green-400/30" />
          <ChevronDown className={`h-4 w-4 text-green-400 transition-transform ${showDelivered ? 'rotate-180' : ''}`} />
        </button>
        {showDelivered && <div className="mb-8 animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(delivered)}</div>}

        {/* CANCELLED */}
        <button className="flex w-full items-center gap-2 mb-5 cursor-pointer text-left focus:outline-none" onClick={() => setShowCancelled(!showCancelled)}>
          <XCircle className="h-4 w-4 text-destructive" />
          <span className="font-cinzel text-xs text-destructive font-bold">CANCELLED</span>
          {countItems(cancelled) > 0 && <span className="text-[10px] font-bold px-1.5 py-0.5 rounded-full bg-destructive/10 text-destructive">{countItems(cancelled)}</span>}
          <div className="h-px flex-1 bg-destructive/30" />
          <ChevronDown className={`h-4 w-4 text-destructive transition-transform ${showCancelled ? 'rotate-180' : ''}`} />
        </button>
        {showCancelled && <div className="animate-in fade-in slide-in-from-top-2 duration-200">{renderGroupedRecords(cancelled)}</div>}

        </>}
      </div>

      {showReport && <PulloutReport records={records} onClose={() => setShowReport(false)} />}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByPageDateMiner, formatDate } from '@/lib/formatters';
import CollapsibleGroup from '@/components/CollapsibleGroup';
import { calcRemainingBalance, parseDateRobust } from '@/lib/calculations';
import { startOfWeek, startOfMonth, subMonths } from 'date-fns';
import TabHeader from '@/components/TabHeader';
import AccountsClientCard from './AccountsClientCard';
import {
  ChevronDown, Plus, Calendar, TrendingDown, Package, Users,
  ShieldCheck, CheckCircle2, Clock, Truck, CreditCard,
} from 'lucide-react';
import AddClientModal from './AddClientModal';

// ─── ACCOUNTS SCOPE ───────────────────────────────────────────────────────────
const ACCOUNTS_STATUSES = [
  'Delivered', 'Given to Shop', 'Paid/DP but Item Hold',
  'Dispatched', 'Payment for Verification',
];

function isAccountsRelevant(r: DatabaseRowType): boolean {
  const status = r.status || '';
  if (status === 'Cancelled' || status === 'Returned Item') return false;
  if (ACCOUNTS_STATUSES.includes(status)) return true;
  const mop = (r.modeOfPayment || '').toLowerCase();
  if (mop === 'layaway') {
    return (
      Number(r.downpayment) > 0 || Number(r.la1MonthPayment) > 0 ||
      Number(r.la2MonthPayment) > 0 || Number(r.la3MonthPayment) > 0 ||
      Number(r.la4MonthPayment) > 0 || Number(r.amountReceived) > 0
    );
  }
  return false;
}

type DateRange = 'all' | 'week' | 'month' | '3months' | 'custom';
const DATE_RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All' }, { key: 'week', label: 'Week' },
  { key: 'month', label: 'Month' }, { key: '3months', label: '3 Mo' },
  { key: 'custom', label: 'Custom' },
];

// ─── Section header component ─────────────────────────────────────────────────
interface SectionHeaderProps {
  icon: React.ReactNode;
  label: string;
  count: number;
  pages: number;
  balance?: number;
  expanded: boolean;
  onToggle: () => void;
  colorClass: string;
  borderClass: string;
  bgClass: string;
}

function SectionHeader({ icon, label, count, pages, balance, expanded, onToggle, colorClass, borderClass, bgClass }: SectionHeaderProps) {
  return (
    <button
      className={`flex w-full items-center gap-2 mb-3 p-3 rounded-lg border ${borderClass} ${bgClass} text-left focus:outline-none hover:opacity-90 transition-opacity`}
      onClick={onToggle}
    >
      <span className={`shrink-0 ${colorClass}`}>{icon}</span>
      <span className={`font-cinzel text-sm font-bold ${colorClass} tracking-wide`}>{label}</span>
      <span className={`text-[10px] px-2 py-0.5 rounded-full font-bold border ${colorClass} bg-white/5 border-current/20`}>
        {pages > 1 ? `${pages} pages · ` : ''}{count} item{count !== 1 ? 's' : ''}
      </span>
      {balance !== undefined && balance > 0 && (
        <span className="text-[10px] font-bold text-destructive bg-destructive/10 px-2 py-0.5 rounded-full border border-destructive/20">
          AED {balance.toFixed(0)}
        </span>
      )}
      <div className={`h-px flex-1 opacity-20 ${bgClass.includes('amber') ? 'bg-amber-400' : bgClass.includes('orange') ? 'bg-orange-400' : bgClass.includes('indigo') ? 'bg-indigo-400' : bgClass.includes('violet') ? 'bg-violet-400' : 'bg-green-500'}`} />
      <ChevronDown className={`h-4 w-4 shrink-0 ${colorClass} transition-transform ${expanded ? 'rotate-180' : ''}`} />
    </button>
  );
}

// ─── Group renderer ───────────────────────────────────────────────────────────
function RenderGroups({ groups, records, onUpdate }: {
  groups: Map<string, Map<string, Map<string, DatabaseRowType[]>>>;
  records: DatabaseRowType[];
  onUpdate: TabProps['onUpdate'];
}) {
  if (groups.size === 0) {
    return (
      <div className="text-center py-6 text-muted-foreground text-sm border border-dashed border-border rounded-lg">
        No records in this section.
      </div>
    );
  }
  return (
    <div>
      {Array.from(groups.entries()).map(([page, dateMap]) => (
        <CollapsibleGroup key={page} label={page} colorClass="text-primary/70" lineClass="bg-primary/10" defaultOpen={false}>
          {Array.from(dateMap.entries()).map(([date, minerMap]) => (
            <CollapsibleGroup key={date} label={formatDate(date)} colorClass="text-muted-foreground" lineClass="bg-border/40" indent defaultOpen={false}>
              <div className="space-y-3">
                {Array.from(minerMap.entries()).map(([minerName, items]) => (
                  <AccountsClientCard key={minerName} minerName={minerName} records={items} allRecords={records} onUpdate={onUpdate} />
                ))}
              </div>
            </CollapsibleGroup>
          ))}
        </CollapsibleGroup>
      ))}
    </div>
  );
}

const countItems = (g: Map<string, Map<string, Map<string, DatabaseRowType[]>>>) =>
  Array.from(g.values()).reduce((s, dm) =>
    s + Array.from(dm.values()).reduce((ss, mm) =>
      ss + Array.from(mm.values()).reduce((sss, v) => sss + v.length, 0), 0), 0);

const sumBalance = (records: DatabaseRowType[]) =>
  records.reduce((s, r) => s + Math.max(0, calcRemainingBalance(r)), 0);

// ─── Main Component ───────────────────────────────────────────────────────────
export default function AccountsTracking({ records, searchQuery, onSearchChange, onUpdate, userFirstName, userEmail, onRefresh }: TabProps) {
  const [showAddModal, setShowAddModal] = useState(false);
  const [verifExpanded, setVerifExpanded] = useState(true);
  const [dispatchedExpanded, setDispatchedExpanded] = useState(true);
  const [onHoldExpanded, setOnHoldExpanded] = useState(true);
  const [layawayExpanded, setLayawayExpanded] = useState(true);
  const [deliveredExpanded, setDeliveredExpanded] = useState(true);
  const [liverFilter, setLiverFilter] = useState('all');
  const [dateRange, setDateRange] = useState<DateRange>('all');
  const [customFrom, setCustomFrom] = useState<Date | undefined>();
  const [customTo, setCustomTo] = useState<Date | undefined>();

  const liverNames = useMemo(() => {
    const names = Array.from(new Set(
      records.filter(isAccountsRelevant).map(r => r.liverName?.trim().toUpperCase()).filter(Boolean)
    )) as string[];
    return names.sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    let base = records.filter(isAccountsRelevant);
    if (liverFilter !== 'all') base = base.filter(r => r.liverName?.trim().toUpperCase() === liverFilter);
    if (dateRange !== 'all') {
      const now = new Date();
      let from: Date;
      if (dateRange === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
      else if (dateRange === 'month') from = startOfMonth(now);
      else if (dateRange === '3months') from = subMonths(now, 3);
      else from = customFrom || new Date(0);
      const to = dateRange === 'custom' ? customTo : undefined;
      base = base.filter(r => {
        if (!r.dateOfLive) return false;
        const d = parseDateRobust(r.dateOfLive);
        if (!d) return false;
        if (d.getTime() < from.getTime()) return false;
        if (to) { const end = new Date(to); end.setHours(23, 59, 59, 999); if (d.getTime() > end.getTime()) return false; }
        return true;
      });
    }
    return base;
  }, [records, liverFilter, dateRange, customFrom, customTo]);

  // ── Split into FIVE clearly separated status sections ──────────────────────
  const sections = useMemo(() => {
    const searched = applySearch(filteredRecords, searchQuery);
    const active: DatabaseRowType[] = [];
    const cleared: DatabaseRowType[] = [];

    searched.forEach(r => {
      const remStatus = (r.remittanceStatus || '').toLowerCase().trim();
      const remittanceConfirmed = remStatus.includes('secured') || remStatus.includes('received');
      const balanceZero = calcRemainingBalance(r) <= 0;
      const isPendingRemittance = remStatus === '' || remStatus === 'pending' || remStatus === 'n/a';
      const isCleared = remittanceConfirmed || (balanceZero && !isPendingRemittance);
      if (isCleared) cleared.push(r);
      else active.push(r);
    });

    // ── Section 1: Payment for Verification ──────────────────────────────
    const verif = active.filter(r => r.status === 'Payment for Verification');

    // ── Section 2: Dispatched (in transit, balance still outstanding) ─────
    const dispatched = active.filter(r => r.status === 'Dispatched');

    // ── Section 3: Paid/DP but Item Hold (layaway installments) ──────────
    const onHold = active.filter(r => r.status === 'Paid/DP but Item Hold');

    // ── Section 4: Layaway MOP (not covered by above statuses) ───────────
    const layaway = active.filter(r => {
      const status = r.status || '';
      // Exclude statuses already shown in their own sections
      if (['Paid/DP but Item Hold', 'Dispatched', 'Delivered', 'Given to Shop', 'Payment for Verification'].includes(status)) return false;
      return (r.modeOfPayment || '').toLowerCase() === 'layaway';
    });

    // ── Section 5: Delivered / Given to Shop ─────────────────────────────
    const delivered = active.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');

    return {
      verifGroups: groupByPageDateMiner(verif),
      dispatchedGroups: groupByPageDateMiner(dispatched),
      onHoldGroups: groupByPageDateMiner(onHold),
      layawayGroups: groupByPageDateMiner(layaway),
      deliveredGroups: groupByPageDateMiner(delivered),
      clearedGroups: groupByPageDateMiner(cleared),
      activeRecords: active,
      verifRecords: verif,
      dispatchedRecords: dispatched,
      onHoldRecords: onHold,
      layawayRecords: layaway,
      deliveredRecords: delivered,
    };
  }, [filteredRecords, searchQuery]);

  const {
    verifGroups, dispatchedGroups, onHoldGroups, layawayGroups, deliveredGroups, clearedGroups,
    activeRecords, verifRecords, dispatchedRecords, onHoldRecords, layawayRecords, deliveredRecords,
  } = sections;

  const totalOutstanding = useMemo(() => sumBalance(activeRecords), [activeRecords]);
  const activeClientCount = useMemo(() => new Set(activeRecords.map(r => r.minerName || '').filter(Boolean)).size, [activeRecords]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader
        title="Accounts Tracking"
        subtitle={`${activeClientCount} clients · AED ${totalOutstanding.toFixed(0)} outstanding`}
        searchQuery={searchQuery}
        onSearchChange={onSearchChange}
      />

      <div className="px-4 pt-4">
        {/* Filters */}
        <div className="flex flex-wrap gap-2 mb-3">
          <Select value={liverFilter} onValueChange={setLiverFilter}>
            <SelectTrigger className="h-8 text-xs w-40 bg-background border-border">
              <SelectValue placeholder="All Livers" />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              <SelectItem value="all" className="text-xs">All Livers</SelectItem>
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-xs">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>

          <div className="flex gap-1 flex-wrap">
            {DATE_RANGES.map(r => (
              <Button
                key={r.key} size="sm"
                variant={dateRange === r.key ? 'default' : 'outline'}
                className={`text-xs h-8 px-2.5 ${dateRange === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                onClick={() => setDateRange(r.key)}
              >
                {r.key === 'custom' && <Calendar className="h-3 w-3 mr-1" />}
                {r.label}
              </Button>
            ))}
          </div>
        </div>

        {dateRange === 'custom' && (
          <div className="flex gap-2 mb-3">
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customFrom ? formatDate(customFrom.toISOString()) : 'From date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customFrom} onSelect={setCustomFrom} />
              </PopoverContent>
            </Popover>
            <Popover>
              <PopoverTrigger asChild>
                <Button variant="outline" size="sm" className="text-xs border-border h-8">
                  {customTo ? formatDate(customTo.toISOString()) : 'To date'}
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-auto p-0 bg-card border-border">
                <CalendarComponent mode="single" selected={customTo} onSelect={setCustomTo} />
              </PopoverContent>
            </Popover>
          </div>
        )}

        <div className="flex justify-end mb-4">
          <Button onClick={() => setShowAddModal(true)} className="bg-primary text-primary-foreground hover:bg-primary/90 text-xs h-9 shadow-sm">
            <Plus className="h-4 w-4 mr-1.5" /> Add Client
          </Button>
        </div>

        <Tabs defaultValue="active">
          <TabsList className="w-full mb-4 bg-secondary">
            <TabsTrigger value="active" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Outstanding ({activeRecords.length})
            </TabsTrigger>
            <TabsTrigger value="cleared" className="flex-1 text-xs data-[state=active]:bg-primary data-[state=active]:text-primary-foreground">
              Cleared ({clearedGroups.size})
            </TabsTrigger>
          </TabsList>

          <TabsContent value="active">
            {/* Summary Strip */}
            <div className="grid grid-cols-3 gap-2 mb-5">
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Users className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Clients</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeClientCount}</span>
              </div>
              <div className="rounded-lg border border-border bg-card px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Package className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Items</span>
                </div>
                <span className="text-base font-bold text-foreground font-cinzel">{activeRecords.length}</span>
              </div>
              <div className="rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 flex flex-col gap-0.5">
                <div className="flex items-center gap-1.5 text-destructive/70">
                  <TrendingDown className="h-3 w-3" />
                  <span className="text-[10px] uppercase tracking-wider font-medium">Due</span>
                </div>
                <span className="text-sm font-bold text-destructive font-cinzel leading-tight">
                  {totalOutstanding > 0 ? `AED ${totalOutstanding.toFixed(0)}` : 'AED 0'}
                </span>
              </div>
            </div>

            {/* ── SECTION 1: PAYMENT FOR VERIFICATION ── */}
            {verifGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<ShieldCheck className="h-4 w-4" />}
                  label="PAYMENT FOR VERIFICATION"
                  count={countItems(verifGroups)}
                  pages={verifGroups.size}
                  balance={sumBalance(verifRecords)}
                  expanded={verifExpanded}
                  onToggle={() => setVerifExpanded(v => !v)}
                  colorClass="text-amber-400"
                  borderClass="border-amber-500/30"
                  bgClass="bg-amber-500/5"
                />
                {verifExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={verifGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 2: DISPATCHED (in transit, balance outstanding) ── */}
            {dispatchedGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<Truck className="h-4 w-4" />}
                  label="DISPATCHED — IN TRANSIT"
                  count={countItems(dispatchedGroups)}
                  pages={dispatchedGroups.size}
                  balance={sumBalance(dispatchedRecords)}
                  expanded={dispatchedExpanded}
                  onToggle={() => setDispatchedExpanded(v => !v)}
                  colorClass="text-orange-400"
                  borderClass="border-orange-400/30"
                  bgClass="bg-orange-400/5"
                />
                {dispatchedExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={dispatchedGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 3: ON HOLD (Paid/DP but Item Hold) ── */}
            {onHoldGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<Clock className="h-4 w-4" />}
                  label="ON HOLD — PAID / DP RECEIVED"
                  count={countItems(onHoldGroups)}
                  pages={onHoldGroups.size}
                  balance={sumBalance(onHoldRecords)}
                  expanded={onHoldExpanded}
                  onToggle={() => setOnHoldExpanded(v => !v)}
                  colorClass="text-indigo-300"
                  borderClass="border-indigo-400/30"
                  bgClass="bg-indigo-400/5"
                />
                {onHoldExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={onHoldGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 4: LAYAWAY PAYMENT PLANS ── */}
            {layawayGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<CreditCard className="h-4 w-4" />}
                  label="LAYAWAY — INSTALLMENT PLANS"
                  count={countItems(layawayGroups)}
                  pages={layawayGroups.size}
                  balance={sumBalance(layawayRecords)}
                  expanded={layawayExpanded}
                  onToggle={() => setLayawayExpanded(v => !v)}
                  colorClass="text-violet-400"
                  borderClass="border-violet-400/30"
                  bgClass="bg-violet-400/5"
                />
                {layawayExpanded && (
                  <div className="animate-in fade-in slide-in-from-top-2 duration-200">
                    <RenderGroups groups={layawayGroups} records={records} onUpdate={onUpdate} />
                  </div>
                )}
              </div>
            )}

            {/* ── SECTION 5: DELIVERED / GIVEN TO SHOP ── */}
            {deliveredGroups.size > 0 && (
              <div className="mb-4">
                <SectionHeader
                  icon={<CheckCircle2 className="h-4 w-4" />}
                  label="DELIVERED / GIVEN TO SHOP"
                  count={countItems(deliveredGroups)}
                  pages={deliveredGroups.size}
                  balance={sumBalance(deliveredRecords)}
                  expanded={deliveredExpanded}
                  onToggle={() => setDeliveredExpanded(v => !v)}
                  colorClass="text-green-400"
                  borderClass="border-green-500/20"
                  bgClass="bg-green-500/5"
                />
