import { useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { AlertTriangle, Clock, CreditCard, X } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import { parseDateRobust } from '@/lib/calculations';
import { Button } from '@/components/ui/button';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

interface LayawayAlert {
  record: DatabaseRowType;
  monthLabel: string;   // e.g. "Month 1 Payment"
  daysUntilDue: number; // negative = overdue
  dueDate: Date;
}

const n = (v: unknown) => parseFloat(String(v ?? '0')) || 0;

function getNextDueAlert(record: DatabaseRowType): LayawayAlert | null {
  const dateOfLive = parseDateRobust(record.dateOfLive);
  if (!dateOfLive) return null;

  const payments = [
    { label: 'Month 1 Payment', value: n(record.la1MonthPayment) },
    { label: 'Month 2 Payment', value: n(record.la2MonthPayment) },
    { label: 'Month 3 Payment', value: n(record.la3MonthPayment) },
    { label: 'Month 4 Payment', value: n(record.la4MonthPayment) },
  ];

  const now = Date.now();

  for (let i = 0; i < payments.length; i++) {
    if (payments[i].value > 0) continue; // already paid

    // Due date: dateOfLive + (i+1) * 30 days
    const dueDate = new Date(dateOfLive.getTime() + (i + 1) * 30 * 24 * 60 * 60 * 1000);
    const msUntilDue = dueDate.getTime() - now;
    const daysUntilDue = Math.ceil(msUntilDue / (1000 * 60 * 60 * 24));

    // Alert if 5 days or fewer away (including overdue up to 3 days)
    if (daysUntilDue <= 5 && daysUntilDue >= -3) {
      return {
        record,
        monthLabel: payments[i].label,
        daysUntilDue,
        dueDate,
      };
    }
    break; // Only check the FIRST unpaid month
  }

  return null;
}

function urgencyConfig(days: number): { color: string; bg: string; border: string; label: string } {
  if (days < 0) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/40', label: 'OVERDUE' };
  if (days === 0) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/40', label: 'DUE TODAY' };
  if (days === 1) return { color: 'text-destructive', bg: 'bg-destructive/10', border: 'border-destructive/30', label: '1 DAY LEFT' };
  if (days === 2) return { color: 'text-orange-400', bg: 'bg-orange-400/10', border: 'border-orange-400/30', label: '2 DAYS LEFT' };
  if (days === 3) return { color: 'text-amber-400', bg: 'bg-amber-400/10', border: 'border-amber-400/30', label: '3 DAYS LEFT' };
  if (days === 4) return { color: 'text-amber-400', bg: 'bg-amber-400/10', border: 'border-amber-400/30', label: '4 DAYS LEFT' };
  return { color: 'text-yellow-400', bg: 'bg-yellow-400/10', border: 'border-yellow-400/30', label: '5 DAYS LEFT' };
}

export default function LayawayPaymentAlert({ records, onClose }: Props) {
  const alerts = useMemo(() => {
    const result: LayawayAlert[] = [];
    for (const r of records) {
      const mop = (r.modeOfPayment || '').toLowerCase();
      if (mop !== 'layaway') continue;
      if (r.status === 'Cancelled' || r.status === 'Delivered' || r.status === 'Given to Shop') continue;
      const alert = getNextDueAlert(r);
      if (alert) result.push(alert);
    }
    // Sort: overdue first, then soonest
    return result.sort((a, b) => a.daysUntilDue - b.daysUntilDue);
  }, [records]);

  if (alerts.length === 0) return null;

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="bg-card border-border max-w-md max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-cinzel text-primary flex items-center gap-2">
            <CreditCard className="h-5 w-5" />
            Layaway Payment Reminders
            <Badge variant="destructive" className="ml-auto text-xs">{alerts.length} alert{alerts.length !== 1 ? 's' : ''}</Badge>
          </DialogTitle>
        </DialogHeader>

        <p className="text-xs text-muted-foreground -mt-2 mb-2">
          The following layaway customers have upcoming or overdue monthly payments.
        </p>

        <div className="space-y-3">
          {alerts.map((alert, idx) => {
            const cfg = urgencyConfig(alert.daysUntilDue);
            return (
              <div
                key={`${alert.record.id}-${idx}`}
                className={`rounded-xl border p-3 ${cfg.bg} ${cfg.border}`}
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <AlertTriangle className={`h-3.5 w-3.5 shrink-0 ${cfg.color}`} />
                      <span className={`text-xs font-bold font-cinzel ${cfg.color}`}>
                        {alert.record.minerName?.toUpperCase() || 'UNKNOWN'}
                      </span>
                    </div>
                    <p className="text-xs text-foreground font-medium truncate mb-0.5">
                      {alert.record.itemDescription}
                    </p>
                    <p className="text-[10px] text-muted-foreground">
                      {alert.record.category} · {alert.record.page}
                      {alert.record.liverName && ` · ${alert.record.liverName}`}
                    </p>
                    <div className="flex items-center gap-1.5 mt-1.5">
                      <Clock className={`h-3 w-3 ${cfg.color}`} />
                      <span className={`text-xs font-semibold ${cfg.color}`}>{alert.monthLabel}</span>
                      <span className="text-[10px] text-muted-foreground">
                        due {alert.dueDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                      </span>
                    </div>
                  </div>
                  <span className={`shrink-0 text-[9px] font-bold px-2 py-1 rounded-full border ${cfg.bg} ${cfg.color} ${cfg.border}`}>
                    {cfg.label}
                  </span>
                </div>
              </div>
            );
          })}
        </div>

        <Button
          className="w-full mt-2 bg-primary text-primary-foreground"
          onClick={onClose}
        >
          <X className="h-4 w-4 mr-1.5" /> Dismiss
        </Button>
      </DialogContent>
    </Dialog>
  );
}

