import { useMemo, useState, useEffect, useCallback } from 'react';
import { ChevronDown, ChevronUp, TrendingUp, Package, Weight, DollarSign, Copy, Check } from 'lucide-react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { TabProps, DatabaseRowType } from '@/types';
import { calcItemPriceAED, parseDateRobust } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import StatusBadge from '@/components/StatusBadge';
import { startOfWeek, startOfMonth } from 'date-fns';

const ACTIVE_STATUSES = [
  'Delivered', 'Given to Shop',
  'Paid/DP but Item Hold', 'Payment for Verification',
  'Dispatched', 'For Pullout', 'Dispatch',
  'Reseller',
  'Pending', 'Waiting for Details', 'Waiting for Downpayment',
];

function calcGrams(records: DatabaseRowType[]): number {
  return records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('per pc') || cat.includes('screw type') || cat.includes('diamond')) return s;
    return s + (Number(r.grams) || 0);
  }, 0);
}

type DateRange = 'all' | 'week' | 'month' | 'custom';

const RANGES: { key: DateRange; label: string }[] = [
  { key: 'all', label: 'All Time' },
  { key: 'week', label: 'This Week' },
  { key: 'month', label: 'This Month' },
  { key: 'custom', label: 'Custom' },
];

const STATUS_ORDER = ['Pending', 'Waiting for Details', 'Waiting for Downpayment', 'Payment for Verification',
  'Paid/DP but Item Hold', 'For Pullout', 'Dispatch', 'Reseller', 'Dispatched', 'Delivered', 'Given to Shop'];

const LIVER_STORAGE_KEY = 'myDeals_selectedLiver';

export default function LiverDashboard({ records, searchQuery, onSearchChange }: TabProps) {
  const [selectedLiver, setSelectedLiver] = useState<string>(() => {
    try { return localStorage.getItem(LIVER_STORAGE_KEY) || ''; } catch { return ''; }
  });
  const [range, setRange] = useState<DateRange>('all');
  const [customStart, setCustomStart] = useState('');
  const [customEnd, setCustomEnd] = useState('');
  const [showBreakdown, setShowBreakdown] = useState(false);
  const [copiedId, setCopiedId] = useState<number | null>(null);

  const copyRow = useCallback((r: DatabaseRowType) => {
    const text = [r.minerName, r.itemDescription, r.grams ? `${r.grams}g` : '', `AED ${calcItemPriceAED(r).toFixed(2)}`].filter(Boolean).join(' · ');
    navigator.clipboard.writeText(text).catch(() => {});
    setCopiedId(r.id);
    setTimeout(() => setCopiedId(null), 1500);
  }, []);

  // Persist selected liver
  useEffect(() => {
    try { localStorage.setItem(LIVER_STORAGE_KEY, selectedLiver); } catch { /* ignore */ }
  }, [selectedLiver]);

  const liverNames = useMemo(() => {
    return Array.from(new Set(
      records.map(r => r.liverName?.toUpperCase().trim()).filter(Boolean) as string[]
    )).sort((a, b) => a.localeCompare(b));
  }, [records]);

  // Auto-deselect if liver no longer exists in data
  useEffect(() => {
    if (selectedLiver && liverNames.length > 0 && !liverNames.includes(selectedLiver)) {
      setSelectedLiver('');
    }
  }, [liverNames, selectedLiver]);

  const byLiver = useMemo(() => {
    if (!selectedLiver) return [];
    return records.filter(r =>
      r.liverName?.toUpperCase().trim() === selectedLiver &&
      ACTIVE_STATUSES.includes(r.status || '')
    );
  }, [records, selectedLiver]);

  const filtered = useMemo(() => {
    if (range === 'all') return byLiver;
    const now = new Date();
    let from: Date;
    let to: Date | undefined;
    if (range === 'week') from = startOfWeek(now, { weekStartsOn: 1 });
    else if (range === 'month') from = startOfMonth(now);
    else {
      from = customStart ? new Date(customStart) : new Date(0);
      to = customEnd ? new Date(customEnd) : undefined;
    }
    return byLiver.filter(r => {
      if (!r.dateOfLive) return false;
      const d = parseDateRobust(r.dateOfLive);
      if (!d) return false;
      if (d < from) return false;
      if (to) {
        const endOfDay = new Date(to);
        endOfDay.setHours(23, 59, 59, 999);
        if (d > endOfDay) return false;
      }
      return true;
    });
  }, [byLiver, range, customStart, customEnd]);

  const totalItems = filtered.length;
  const totalGrams = calcGrams(filtered);
  const totalSalesValue = filtered.reduce((s, r) => s + calcItemPriceAED(r), 0);
  const deliveredCount = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').length;

  // Group by status
  const byStatus = useMemo(() => {
    const map = new Map<string, DatabaseRowType[]>();
    for (const r of filtered) {
      const s = r.status || 'Unknown';
      if (!map.has(s)) map.set(s, []);
      map.get(s)!.push(r);
    }
    // Sort by STATUS_ORDER
    return new Map([...map.entries()].sort((a, b) => {
      const ai = STATUS_ORDER.indexOf(a[0]);
      const bi = STATUS_ORDER.indexOf(b[0]);
      if (ai === -1 && bi === -1) return a[0].localeCompare(b[0]);
      if (ai === -1) return 1;
      if (bi === -1) return -1;
      return ai - bi;
    }));
  }, [filtered]);

  const breakdownByDate = useMemo(() => {
    const deliveredRecords = filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop');
    const map = new Map<string, DatabaseRowType[]>();
    for (const r of deliveredRecords) {
      const key = r.dateOfLive || 'Unknown';
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(r);
    }
    return [...map.entries()].sort((a, b) => b[0].localeCompare(a[0]));
  }, [filtered]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="My Sales" subtitle="Personal sales summary" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4 space-y-4">

        {/* Liver selector */}
        <div>
          <p className="text-xs text-muted-foreground mb-1.5">Select your name</p>
          <Select value={selectedLiver} onValueChange={setSelectedLiver}>
            <SelectTrigger className="h-9 text-sm bg-background border-border w-full max-w-xs">
              <SelectValue placeholder="Select liver name..." />
            </SelectTrigger>
            <SelectContent className="bg-popover border-border">
              {liverNames.map(name => (
                <SelectItem key={name} value={name} className="text-sm">{name}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {selectedLiver && (
          <>
            {/* Date Range */}
            <div>
              <p className="text-xs text-muted-foreground mb-1.5">Date range</p>
              <div className="flex gap-1.5 flex-wrap">
                {RANGES.map(r => (
                  <Button
                    key={r.key}
                    size="sm"
                    variant={range === r.key ? 'default' : 'outline'}
                    className={`text-xs h-7 ${range === r.key ? 'bg-primary text-primary-foreground' : 'border-border'}`}
                    onClick={() => setRange(r.key)}
                  >
                    {r.label}
                  </Button>
                ))}
              </div>
              {range === 'custom' && (
                <div className="flex gap-2 mt-2">
                  <div className="flex flex-col gap-1">
                    <label className="text-[10px] text-muted-foreground">Start Date</label>
                    <Input type="date" value={customStart} onChange={e => setCustomStart(e.target.value)} className="h-8 text-xs w-36 bg-background border-border" />
                  </div>
                  <div className="flex flex-col gap-1">
                    <label className="text-[10px] text-muted-foreground">End Date</label>
                    <Input type="date" value={customEnd} onChange={e => setCustomEnd(e.target.value)} className="h-8 text-xs w-36 bg-background border-border" />
                  </div>
                </div>
              )}
            </div>

            {/* KPI Grid 2x2 */}
            <div className="grid grid-cols-2 gap-3">
              <div className="col-span-2 rounded-xl border border-primary/40 bg-primary/5 p-4 flex flex-col gap-1">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <TrendingUp className="h-3.5 w-3.5 text-primary" />
                  <p className="text-[10px] font-semibold uppercase tracking-widest">Total Sales Value</p>
                </div>
                <p className="text-2xl font-bold font-cinzel leading-none text-primary">AED {totalSalesValue.toFixed(2)}</p>
                <p className="text-[10px] text-muted-foreground">Sum of item prices in AED</p>
              </div>
              <div className="rounded-xl border border-border bg-card p-4 flex flex-col gap-1">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Package className="h-3.5 w-3.5" />
                  <p className="text-[10px] font-semibold uppercase tracking-widest">Total Items</p>
                </div>
                <p className="text-2xl font-bold font-cinzel leading-none text-foreground">{totalItems}</p>
                <p className="text-[10px] text-muted-foreground">{deliveredCount} delivered</p>
              </div>
              <div className="rounded-xl border border-border bg-card p-4 flex flex-col gap-1">
                <div className="flex items-center gap-1.5 text-muted-foreground">
                  <Weight className="h-3.5 w-3.5" />
                  <p className="text-[10px] font-semibold uppercase tracking-widest">Total Grams</p>
                </div>
                <p className="text-2xl font-bold font-cinzel leading-none text-foreground">{totalGrams.toFixed(2)}g</p>
                <p className="text-[10px] text-muted-foreground">Excl. PC / Screw / Diamond</p>
              </div>
            </div>

            {/* Status breakdown mini-pills */}
            {byStatus.size > 0 && (
              <div className="flex flex-wrap gap-1.5">
                {Array.from(byStatus.entries()).map(([status, items]) => (
                  <span key={status} className="text-[10px] font-semibold px-2 py-1 rounded-full bg-secondary border border-border text-muted-foreground">
                    {status} <span className="text-foreground font-bold">{items.length}</span>
                  </span>
                ))}
              </div>
            )}

            {/* Toggle Delivered Breakdown */}
            {breakdownByDate.length > 0 && (
              <Button
                variant="outline"
                size="sm"
                className="w-full h-9 text-xs border-primary/40 text-primary"
                onClick={() => setShowBreakdown(v => !v)}
              >
                {showBreakdown ? <ChevronUp className="h-3.5 w-3.5 mr-1.5" /> : <ChevronDown className="h-3.5 w-3.5 mr-1.5" />}
                {showBreakdown ? 'Hide' : 'Show'} Delivered Breakdown by Date
              </Button>
            )}

            {showBreakdown && breakdownByDate.length > 0 && (
              <div className="rounded-lg border border-border overflow-hidden">
                <table className="w-full text-xs">
                  <thead>
                    <tr className="bg-secondary/40 border-b border-border">
                      <th className="text-left px-3 py-2 text-muted-foreground font-medium">Date</th>
                      <th className="text-right px-3 py-2 text-muted-foreground font-medium">Items</th>
                      <th className="text-right px-3 py-2 text-muted-foreground font-medium">Grams</th>
                      <th className="text-right px-3 py-2 text-muted-foreground font-medium">AED</th>
                    </tr>
                  </thead>
                  <tbody>
                    {breakdownByDate.map(([date, rows], i) => (
                      <tr key={date} className={`border-b border-border/40 ${i % 2 === 0 ? '' : 'bg-secondary/10'}`}>
                        <td className="px-3 py-2 whitespace-nowrap text-muted-foreground">{date ? formatDate(date) : '—'}</td>
                        <td className="px-3 py-2 text-right font-medium">{rows.length}</td>
                        <td className="px-3 py-2 text-right">{calcGrams(rows).toFixed(2)}g</td>
                        <td className="px-3 py-2 text-right font-medium text-primary">
                          {rows.reduce((s, r) => s + calcItemPriceAED(r), 0).toFixed(2)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot>
                    <tr className="bg-secondary/30 border-t border-border font-semibold">
                      <td className="px-3 py-2 text-xs text-muted-foreground">Totals</td>
                      <td className="px-3 py-2 text-right text-xs">{deliveredCount}</td>
                      <td className="px-3 py-2 text-right text-xs">{calcGrams(filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop')).toFixed(2)}g</td>
                      <td className="px-3 py-2 text-right text-xs text-primary">
                        {filtered.filter(r => r.status === 'Delivered' || r.status === 'Given to Shop').reduce((s, r) => s + calcItemPriceAED(r), 0).toFixed(2)}
                      </td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            )}

            {/* All active records */}
            {filtered.length === 0 ? (
              <div className="text-center py-12 border border-dashed border-border rounded-xl">
                <p className="text-sm text-muted-foreground">No active items found for this period.</p>
              </div>
            ) : (
              <div className="space-y-4">
                {Array.from(byStatus.entries()).map(([status, items]) => (
                  <div key={status}>
                    <div className="flex items-center gap-2 mb-2">
                      <StatusBadge status={status} />
                      <span className="text-[10px] text-muted-foreground">{items.length} item{items.length !== 1 ? 's' : ''}</span>
                      <div className="h-px flex-1 bg-border/40" />
                    </div>
                    <div className="rounded-lg border border-border overflow-hidden">
                      <table className="w-full text-xs">
                        <thead>
                          <tr className="bg-secondary/30 border-b border-border">
                            <th className="text-left px-3 py-1.5 text-muted-foreground font-medium">Date</th>
                            <th className="text-left px-3 py-1.5 text-muted-foreground font-medium">Client</th>
                            <th className="text-left px-3 py-1.5 text-muted-foreground font-medium hidden sm:table-cell">Item</th>
                            <th className="text-right px-3 py-1.5 text-muted-foreground font-medium">Grams</th>
                            <th className="text-right px-3 py-1.5 text-muted-foreground font-medium">AED</th>
                          </tr>
                        </thead>
                        <tbody>
                          {items.map((r, i) => (
                            <tr key={r.id} className={`border-b border-border/40 group ${i % 2 === 0 ? '' : 'bg-secondary/10'}`}>
                              <td className="px-3 py-2 text-muted-foreground whitespace-nowrap">{r.dateOfLive ? formatDate(r.dateOfLive) : '—'}</td>
                              <td className="px-3 py-2 font-medium max-w-[90px] truncate">{r.minerName || '—'}</td>
                              <td className="px-3 py-2 text-muted-foreground max-w-[140px] truncate hidden sm:table-cell">{r.itemDescription || '—'}</td>
                              <td className="px-3 py-2 text-right">{r.grams ? `${r.grams}g` : '—'}</td>
                              <td className="px-3 py-2 text-right font-medium text-primary">
                                {calcItemPriceAED(r).toFixed(2)}
                              </td>
                              <td className="px-2 py-2 text-right w-8">
                                <button
                                  onClick={() => copyRow(r)}
                                  title="Copy row"
                                  className="opacity-0 group-hover:opacity-100 transition-opacity p-1 rounded hover:bg-secondary text-muted-foreground hover:text-foreground"
                                >
                                  {copiedId === r.id
                                    ? <Check className="h-3 w-3 text-green-400" />
                                    : <Copy className="h-3 w-3" />}
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                        <tfoot>
                          <tr className="bg-secondary/20 border-t border-border">
                            <td colSpan={3} className="px-3 py-1.5 text-[10px] text-muted-foreground">
                              {items.length} items · {calcGrams(items).toFixed(2)}g
                            </td>
                            <td className="px-3 py-1.5" />
                            <td className="px-3 py-1.5 text-right text-[10px] font-semibold text-primary">
                              {items.reduce((s, r) => s + calcItemPriceAED(r), 0).toFixed(2)}
                            </td>
                          </tr>
                        </tfoot>
                      </table>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </>
        )}

        {!selectedLiver && (
          <div className="text-center py-16 border border-dashed border-border rounded-xl">
            <DollarSign className="h-8 w-8 text-muted-foreground/40 mx-auto mb-2" />
            <p className="text-sm text-muted-foreground">Select your name above to view your sales dashboard.</p>
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { RefreshCw } from 'lucide-react';
import RateCalculatorWidget from '@/components/RateCalculatorWidget';
import { getUserRole, SUPER_ADMIN_EMAILS } from '@/config/roles';
import { getRatesForDate } from '@/lib/ratesStore';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';
import LiverDashboard from '@/pages/LiverDashboard';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[] | null>(null);
  const [rolesError, setRolesError] = useState(false);

  const [dataLoading, setDataLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing' | 'liver'>('admin');

  /**
   * fetchData — two modes:
   *  - silent=false → full load (fetches ALL records, shows skeleton, used on initial load & manual refresh)
   *  - silent=true  → delta sync (fetches only last 500 rows via tailOnly=true, costs 1 API call instead of N)
   *
   * FIX 3 (Quota Bomb): Background syncs now use tailOnly to stay within Google's 60 req/min limit.
   */
  const fetchData = useCallback((silent = false) => {
    if (!user) return;

    if (silent) {
      setIsSyncing(true);
    } else {
      setDataLoading(true);
    }

    Promise.all([
      getRecords({ tailOnly: silent }).catch(() => {
        toast.error('Failed to load records');
        return [];
      }),
      getRoles({}).catch((err) => {
        console.error('getRoles failed — failing closed for security:', err);
        setRolesError(true);
        return null;
      })
    ])
      .then(([recordsData, rolesData]) => {
        const incoming = (recordsData as DatabaseRowType[]) || [];

        if (silent && incoming.length > 0) {
          // Delta merge: replace/add the fetched tail rows, keep the rest untouched
          setRecords(prev => {
            const tailIds = new Set(incoming.map(r => r.id));
            const kept = prev.filter(r => !tailIds.has(r.id));
            return [...kept, ...incoming].sort((a, b) => a.id - b.id);
          });
        } else {
          setRecords(incoming);
        }

        if (rolesData !== null) {
          setDynamicRoles((rolesData as any[]) || []);
        }
      })
      .finally(() => {
        setDataLoading(false);
        setIsSyncing(false);
      });
  }, [user]);

  useEffect(() => { fetchData(false); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    // 1. Optimistic UI update
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));

    try {
      // 2. Look up the record's dateOfLive — prefer from fields, fallback to existing record.
      //    This is critical: updates like status changes don't include dateOfLive in fields.
      const existingRecord = records.find(r => r.id === rowId);
      const dateOfLive = ((fields as any).dateOfLive as string | undefined)
        || existingRecord?.dateOfLive
        || '';
      const rates = getRatesForDate(dateOfLive);

      await updateRecord({
        rowId,
        fields: fields as Record<string, unknown>,
        phpRate: rates.phpRate,
        silverSellRate: rates.silverSellRate,
        silverBrandedSellRate: rates.silverBrandedSellRate,
        silverCostRate: rates.silverCostRate,
        silverBrandedCostRate: rates.silverBrandedCostRate,
      });

      // 3. Delta sync after save — only costs 1 API call
      fetchData(true);
    } catch {
      toast.error('Failed to save changes');
      fetchData(true);
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  if (rolesError) return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <div className="text-center space-y-3 p-8 max-w-sm">
        <p className="text-destructive font-semibold">Failed to load roles</p>
        <p className="text-sm text-muted-foreground">Could not verify your permissions. Please refresh the page to try again.</p>
        <button onClick={() => { setRolesError(false); fetchData(false); }} className="text-xs text-primary underline">Retry</button>
      </div>
    </div>
  );

  // Wait for BOTH data loading AND roles to be resolved before evaluating access.
  // On iOS, React state batching can cause dynamicRoles to still be null when
  // dataLoading flips to false, triggering a false "Access Denied" screen.
  if (dataLoading || dynamicRoles === null) return <LoadingSkeleton />;

  const roles = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = roles.includes('super_admin');
  const isLiverOnly = roles.length === 1 && roles[0] === 'liver';

  if (roles.length === 0) return <AccessDenied email={user.email} />;

  const ALL_TABS = ['admin', 'dispatch', 'accounts', 'bossing', 'liver'] as const;
  const allowedTabs = isSuperAdmin
    ? ALL_TABS
    : ([...ALL_TABS.filter(t => t === 'liver' ? roles.includes('liver') : roles.includes(t as any))] as typeof ALL_TABS[number][]);

  // Liver-only users: force to liver tab, skip all others
  const currentTab = allowedTabs.includes(activeTab)
    ? activeTab
    : allowedTabs[0];

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
    userFirstName: user.firstName,
    onRefresh: () => fetchData(false),
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">

          {/* Small Top Bar Logo */}
          <img
            src="https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png"
            alt="Logo"
            className="h-6 sm:h-8 w-auto object-contain mr-2 sm:mr-4"
          />

          {allowedTabs.length > 1 && (
            <div className="flex h-full items-center border-l border-border pl-2 sm:pl-4">
              {allowedTabs.includes('admin') && (
                <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              )}
              {allowedTabs.includes('dispatch') && (
                <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              )}
              {allowedTabs.includes('accounts') && (
                <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              )}
              {allowedTabs.includes('bossing') && (
                <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
              )}
              {allowedTabs.includes('liver') && (
                <button onClick={() => setActiveTab('liver')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'liver' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>My Sales</button>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 sm:gap-3">
          {/* Manual Refresh Button — always does a FULL sync */}
          <RateCalculatorWidget />

          <button
            onClick={() => fetchData(false)}
            disabled={isSyncing || dataLoading}
            className={`p-1.5 rounded-full hover:bg-secondary transition-colors ${(isSyncing || dataLoading) ? 'animate-spin text-primary' : 'text-muted-foreground'}`}
            title="Full sync — reload all data"
          >
            <RefreshCw className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          </button>

          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[100px] sm:max-w-none">
            {user.email}
          </span>

          {(isSuperAdmin || roles.includes('admin')) && (
            <UploadMasterlistFAB onRefresh={() => fetchData(false)} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {currentTab === 'admin' && <AdminPipeline {...tabProps} />}
          {currentTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {currentTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {currentTab === 'bossing' && <BossingDashboard {...tabProps} />}
          {currentTab === 'liver' && <LiverDashboard {...tabProps} />}
        </div>
      )}
    </div>
  );
}

import { z } from 'zod';
import { createEndpoint, Roles } from 'zite-integrations-backend-sdk'; 

export default createEndpoint({
  description: 'Fetch all Roles from the Google Sheet',
  authenticated: true,
  inputSchema: z.object({}),
  outputSchema: z.array(z.any()),
  execute: async () => {
    // Fail closed: let the error propagate so the app shows an error state
    // rather than falling back to hardcoded roles on a network/API failure.
    const records = await Roles.findAll({});
    if (!records) {
      throw new Error('Roles endpoint returned null — failing closed for security.');
    }
    return records;
  },
});

