import { useEffect, useState, useCallback } from 'react';
import { useAuth } from 'zite-auth-sdk';
import { getRecords, updateRecord, getRoles } from 'zite-endpoints-sdk';
import { Toaster } from '@/components/ui/sonner';
import { toast } from 'sonner';
import { RefreshCw } from 'lucide-react';
import RateCalculatorWidget from '@/components/RateCalculatorWidget';
import { getUserRole, SUPER_ADMIN_EMAILS, EMAIL_TO_LIVER_NAME } from '@/config/roles';
import { getRatesForDate } from '@/lib/ratesStore';
import { DatabaseRowType } from '@/types';
import LoadingSkeleton from '@/components/LoadingSkeleton';
import AccessDenied from '@/components/AccessDenied';
import UploadMasterlistFAB from '@/components/UploadMasterlistFAB';
import AdminPipeline from '@/components/admin/AdminPipeline';
import DispatchBoard from '@/components/dispatch/DispatchBoard';
import AccountsTracking from '@/components/accounts/AccountsTracking';
import BossingDashboard from '@/components/bossing/BossingDashboard';
import WelcomeScreen from '@/components/WelcomeScreen';
import LiverDashboard from '@/pages/LiverDashboard';

export default function App() {
  const { user, isLoading } = useAuth();
  const [records, setRecords] = useState<DatabaseRowType[]>([]);
  const [dynamicRoles, setDynamicRoles] = useState<any[] | null>(null);
  const [rolesError, setRolesError] = useState(false);

  const [dataLoading, setDataLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const [activeTab, setActiveTab] = useState<'admin' | 'dispatch' | 'accounts' | 'bossing' | 'liver'>('admin');

  /**
   * fetchData — two modes:
   *  - silent=false → full load (fetches ALL records, shows skeleton, used on initial load & manual refresh)
   *  - silent=true  → delta sync (fetches only last 500 rows via tailOnly=true, costs 1 API call instead of N)
   *
   * FIX 3 (Quota Bomb): Background syncs now use tailOnly to stay within Google's 60 req/min limit.
   */
  const fetchData = useCallback((silent = false) => {
    if (!user) return;

    if (silent) {
      setIsSyncing(true);
    } else {
      setDataLoading(true);
    }

    Promise.all([
      getRecords({ tailOnly: silent }).catch(() => {
        toast.error('Failed to load records');
        return [];
      }),
      getRoles({}).catch((err) => {
        console.error('getRoles failed — failing closed for security:', err);
        setRolesError(true);
        return null;
      })
    ])
      .then(([recordsData, rolesData]) => {
        const incoming = (recordsData as DatabaseRowType[]) || [];

        if (silent && incoming.length > 0) {
          // Delta merge: replace/add the fetched tail rows, keep the rest untouched
          setRecords(prev => {
            const tailIds = new Set(incoming.map(r => r.id));
            const kept = prev.filter(r => !tailIds.has(r.id));
            return [...kept, ...incoming].sort((a, b) => a.id - b.id);
          });
        } else {
          setRecords(incoming);
        }

        if (rolesData !== null) {
          setDynamicRoles((rolesData as any[]) || []);
        }
      })
      .finally(() => {
        setDataLoading(false);
        setIsSyncing(false);
      });
  }, [user]);

  useEffect(() => { fetchData(false); }, [fetchData]);

  const handleUpdate = async (rowId: number, fields: Partial<DatabaseRowType>) => {
    // 1. Optimistic UI update
    setRecords(prev => prev.map(r => r.id === rowId ? { ...r, ...fields } : r));

    try {
      // 2. Look up the record's dateOfLive — prefer from fields, fallback to existing record.
      //    This is critical: updates like status changes don't include dateOfLive in fields.
      const existingRecord = records.find(r => r.id === rowId);
      const dateOfLive = ((fields as any).dateOfLive as string | undefined)
        || existingRecord?.dateOfLive
        || '';
      const rates = getRatesForDate(dateOfLive);

      await updateRecord({
        rowId,
        fields: fields as Record<string, unknown>,
        phpRate: rates.phpRate,
        silverSellRate: rates.silverSellRate,
        silverBrandedSellRate: rates.silverBrandedSellRate,
        silverCostRate: rates.silverCostRate,
        silverBrandedCostRate: rates.silverBrandedCostRate,
      });

      // 3. Delta sync after save — only costs 1 API call
      fetchData(true);
    } catch {
      toast.error('Failed to save changes');
      fetchData(true);
    }
  };

  if (isLoading) return <LoadingSkeleton />;
  if (!user) return <WelcomeScreen />;

  if (rolesError) return (
    <div className="min-h-screen flex items-center justify-center bg-background">
      <div className="text-center space-y-3 p-8 max-w-sm">
        <p className="text-destructive font-semibold">Failed to load roles</p>
        <p className="text-sm text-muted-foreground">Could not verify your permissions. Please refresh the page to try again.</p>
        <button onClick={() => { setRolesError(false); fetchData(false); }} className="text-xs text-primary underline">Retry</button>
      </div>
    </div>
  );

  // Wait for BOTH data loading AND roles to be resolved before evaluating access.
  // On iOS, React state batching can cause dynamicRoles to still be null when
  // dataLoading flips to false, triggering a false "Access Denied" screen.
  if (dataLoading || dynamicRoles === null) return <LoadingSkeleton />;

  const roles = getUserRole(user.email, dynamicRoles);
  const isSuperAdmin = roles.includes('super_admin');
  const isLiverOnly = roles.length === 1 && roles[0] === 'liver';

  if (roles.length === 0) return <AccessDenied email={user.email} />;

  const ALL_TABS = ['admin', 'dispatch', 'accounts', 'bossing', 'liver'] as const;
  const allowedTabs = isSuperAdmin
    ? ALL_TABS
    : ([...ALL_TABS.filter(t => t === 'liver' ? roles.includes('liver') : roles.includes(t as any))] as typeof ALL_TABS[number][]);

  // Liver-only users: force to liver tab, skip all others
  const currentTab = allowedTabs.includes(activeTab)
    ? activeTab
    : allowedTabs[0];

  // For liver-only users, lock My Sales to their liver name so they can't view others' data.
  // First check the hardcoded mapping, then check dynamicRoles for a name/liverName field.
  const lockedLiverName: string | undefined = (() => {
    if (!isLiverOnly) return undefined;
    const email = user.email.toLowerCase().trim();
    if (EMAIL_TO_LIVER_NAME[email]) return EMAIL_TO_LIVER_NAME[email];
    // Fallback: check dynamicRoles for a name field on their row
    if (dynamicRoles) {
      const row = dynamicRoles.find((r: any) => {
        const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '').toLowerCase().trim();
        return rEmail === email;
      });
      if (row) {
        const name = (row.liverName || row.livername || row.liver_name || row.name || row.Name || '').toString().trim().toUpperCase();
        if (name) return name;
      }
    }
    return undefined;
  })();

  const tabProps = {
    records,
    searchQuery,
    onSearchChange: setSearchQuery,
    onUpdate: handleUpdate,
    userEmail: user.email,
    userFirstName: user.firstName,
    onRefresh: () => fetchData(false),
    lockedLiverName,
  };

  return (
    <div className="min-h-screen bg-background max-w-2xl mx-auto flex flex-col">
      <Toaster richColors position="top-center" />

      <div className="flex items-center justify-between border-b border-border sticky top-0 z-30 bg-background/95 backdrop-blur px-4">
        <div className="flex h-12 items-center">

          {/* Small Top Bar Logo */}
          <img
            src="https://images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png"
            alt="Logo"
            className="h-6 sm:h-8 w-auto object-contain mr-2 sm:mr-4"
          />

          {allowedTabs.length > 1 && (
            <div className="flex h-full items-center border-l border-border pl-2 sm:pl-4">
              {allowedTabs.includes('admin') && (
                <button onClick={() => setActiveTab('admin')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'admin' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Admin</button>
              )}
              {allowedTabs.includes('dispatch') && (
                <button onClick={() => setActiveTab('dispatch')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'dispatch' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Dispatch</button>
              )}
              {allowedTabs.includes('accounts') && (
                <button onClick={() => setActiveTab('accounts')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'accounts' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Accounts</button>
              )}
              {allowedTabs.includes('bossing') && (
                <button onClick={() => setActiveTab('bossing')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'bossing' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>Bossing</button>
              )}
              {allowedTabs.includes('liver') && (
                <button onClick={() => setActiveTab('liver')} className={`h-full px-2 sm:px-3 text-[10px] sm:text-xs font-cinzel ${currentTab === 'liver' ? 'text-primary border-b-2 border-primary' : 'text-muted-foreground'}`}>My Sales</button>
              )}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2 sm:gap-3">
          {/* Manual Refresh Button — always does a FULL sync */}
          <RateCalculatorWidget />

          <button
            onClick={() => fetchData(false)}
            disabled={isSyncing || dataLoading}
            className={`p-1.5 rounded-full hover:bg-secondary transition-colors ${(isSyncing || dataLoading) ? 'animate-spin text-primary' : 'text-muted-foreground'}`}
            title="Full sync — reload all data"
          >
            <RefreshCw className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          </button>

          <span className="text-[10px] sm:text-xs text-muted-foreground truncate max-w-[100px] sm:max-w-none">
            {user.email}
          </span>

          {(isSuperAdmin || roles.includes('admin')) && (
            <UploadMasterlistFAB onRefresh={() => fetchData(false)} />
          )}
        </div>
      </div>

      {dataLoading ? (
        <LoadingSkeleton />
      ) : (
        <div className="p-0 flex-1">
          {currentTab === 'admin' && <AdminPipeline {...tabProps} />}
          {currentTab === 'dispatch' && <DispatchBoard {...tabProps} />}
          {currentTab === 'accounts' && <AccountsTracking {...tabProps} />}
          {currentTab === 'bossing' && <BossingDashboard {...tabProps} />}
          {currentTab === 'liver' && <LiverDashboard {...tabProps} />}
        </div>
      )}
    </div>
  );
}

export type DatabaseRowType = {
  orderId?: string;
  dateOfLive?: string;
  page?: string;
  liverName?: string;
  locationOfMiner?: string;
  minerName?: string;
  itemDescription?: string;
  grams?: number;
  source?: string;
  category?: string;
  mc?: number | string;
  goldRate?: number;
  supplierRate?: number | string;
  clientRate?: number;
  profit?: number | string;
  modeOfSale?: string;
  status?: string;
  modeOfPayment?: string;
  downpayment?: string;
  la1MonthPayment?: string;
  la2MonthPayment?: string;
  la3MonthPayment?: string;
  la4MonthPayment?: string;
  liverAdminRemarks?: string;
  dispatchDate?: string;
  deliveredDate?: string;
  reviewChasing?: string;
  fbProfileName?: string;
  regions?: string;
  remittanceStatus?: string;
  currency?: string;
  additionalCharges?: string;
  amountReceived?: string;
  freeSf?: string; // 'TRUE' | '' — stored as string in Google Sheets
  auditTrail?: string;
  tog?: string;
  pureWeight?: string;
  qty?: number;
  customerId?: string;
  id: number;
};

export type ClientGroup = {
  minerName: string;
  records: DatabaseRowType[];
};

export type TabProps = {
  records: DatabaseRowType[];
  searchQuery: string;
  onSearchChange: (q: string) => void;
  onUpdate: (rowId: number, fields: Partial<DatabaseRowType>) => Promise<void>;
  userEmail?: string;
  userFirstName?: string;
  onRefresh?: () => void;
  lockedLiverName?: string; // Set for liver-role users — they can only see their own name
};

import { useRef, useState, useMemo, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Printer, AlertCircle, Copy, Loader2 } from 'lucide-react';
import { DatabaseRowType } from '@/types';
import InvoicePrintContent from '@/components/InvoicePrintContent';
import { parseDateRobust } from '@/lib/calculations';
import { toast } from 'sonner';

interface Props {
  records: DatabaseRowType[];
  onClose: () => void;
}

const CURRENCIES = ['PHP', 'AED', 'USD'];

// Statuses that mean the item is completed/on-the-way — shown on a SEPARATE invoice
const DISPATCHED_STATUSES = new Set(['Dispatched', 'Delivered', 'Given to Shop']);
// Statuses fully excluded from all invoices
const EXCLUDED_STATUSES = new Set(['Cancelled', 'Returned Item']);

function sortByDate(list: DatabaseRowType[]) {
  return [...list].sort((a, b) => {
    const ta = a.dateOfLive ? (parseDateRobust(a.dateOfLive)?.getTime() || 0) : 0;
    const tb = b.dateOfLive ? (parseDateRobust(b.dateOfLive)?.getTime() || 0) : 0;
    return ta - tb;
  });
}

type InvoiceTab = 'active' | 'layaway' | 'dispatched';

export default function InvoiceModal({ records, onClose }: Props) {
  const printRef = useRef<HTMLDivElement>(null);
  const [isCopying, setIsCopying] = useState(false);
  const [tab, setTab] = useState<InvoiceTab>('active');

  useEffect(() => {
    if (!document.getElementById('html2canvas-script') && !(window as any).html2canvas) {
      const script = document.createElement('script');
      script.id = 'html2canvas-script';
      script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  // LAYAWAY: items with Layaway status
  const layawayRecords = useMemo(() =>
    sortByDate(records.filter(r => r.status === 'Layaway')),
    [records]
  );

  // ACTIVE: pending/waiting/payment — NOT dispatched/delivered/cancelled/layaway
  const activeRecords = useMemo(() =>
    sortByDate(records.filter(r => {
      const s = r.status || '';
      return !EXCLUDED_STATUSES.has(s) && !DISPATCHED_STATUSES.has(s) && s !== 'Layaway';
    })),
    [records]
  );

  // DISPATCHED / COMPLETED: items on-the-way or already delivered
  const dispatchedRecords = useMemo(() =>
    sortByDate(records.filter(r => DISPATCHED_STATUSES.has(r.status || ''))),
    [records]
  );

  const visibleRecords =
    tab === 'active' ? activeRecords :
    tab === 'layaway' ? layawayRecords :
    dispatchedRecords;

  const baseRecord = visibleRecords[0] || records[0];
  const [currency, setCurrency] = useState(baseRecord?.currency || 'PHP');

  const handlePrint = () => {
    const content = printRef.current?.innerHTML || '';
    const win = window.open('', '_blank');
    if (!win) return;
    win.document.write(`<!DOCTYPE html><html><head><title>Invoice - ${baseRecord?.minerName || ''}</title>
      <style>
        @page { size: A4; margin: 12mm; }
        body { margin: 0; padding: 0; background: #fff; font-family: Arial, sans-serif; }
        * { box-sizing: border-box; }
        img { max-width: 100%; }
      </style>
    </head><body>${content}</body></html>`);
    win.document.close();
    setTimeout(() => win.print(), 400);
  };

  const handleCopyImage = async () => {
    if (visibleRecords.length === 0 || !printRef.current) return;

    const html2canvas = (window as any).html2canvas;
    if (!html2canvas) {
      toast.error('The image tool is still loading. Please try again in a few seconds.');
      return;
    }

    setIsCopying(true);
    toast.info('Generating image, please wait...');

    try {
      const makeImagePromise = async (): Promise<Blob> => {
        const canvas = await html2canvas(printRef.current!, {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          scrollY: 0,
          windowHeight: printRef.current?.scrollHeight || window.innerHeight
        });
        return new Promise<Blob>((resolve, reject) => {
          canvas.toBlob((blob: Blob | null) => {
            if (blob) resolve(blob);
            else reject(new Error('Failed to generate image blob'));
          }, 'image/png');
        });
      };

      await navigator.clipboard.write([
        new ClipboardItem({ 'image/png': makeImagePromise() })
      ]);
      toast.success('Invoice image copied! You can now paste it into Meta Business Suite.');
    } catch (error: any) {
      console.error(error);
      if (error.name === 'NotAllowedError') {
        toast.error('Clipboard permission denied. Please allow clipboard access in your browser settings.');
      } else {
        toast.error('Failed to copy image. Try again.');
      }
    } finally {
      setIsCopying(false);
    }
  };

  const tabConfig: { key: InvoiceTab; label: string; count: number; color: string }[] = [
    { key: 'active', label: 'Active Orders', count: activeRecords.length, color: 'bg-primary text-primary-foreground' },
    { key: 'layaway', label: 'Layaway', count: layawayRecords.length, color: 'bg-violet-600 text-white' },
    { key: 'dispatched', label: 'Dispatched / Delivered', count: dispatchedRecords.length, color: 'bg-primary text-primary-foreground' },
  ];

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[92vh] overflow-y-auto bg-white border-border p-0" aria-describedby={undefined}>
        <DialogHeader className="px-4 pt-4 pb-2 border-b border-border">
          <div className="flex flex-col gap-2">
            <div className="flex items-center justify-between gap-4">
              <DialogTitle className="text-base font-bold text-foreground">
                Statement of Account
              </DialogTitle>
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground font-medium">Currency:</span>
                  <Select value={currency} onValueChange={setCurrency}>
                    <SelectTrigger className="h-8 w-24 text-xs">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {CURRENCIES.map(c => (
                        <SelectItem key={c} value={c}>{c}</SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <Button
                  onClick={handleCopyImage}
                  size="sm"
                  variant="outline"
                  className="h-8 border-border text-foreground"
                  disabled={visibleRecords.length === 0 || isCopying}
                >
                  {isCopying ? <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" /> : <Copy className="h-3.5 w-3.5 mr-1.5" />}
                  {isCopying ? 'Copying...' : 'Copy Image'}
                </Button>
                <Button onClick={handlePrint} size="sm" className="h-8 bg-primary text-primary-foreground" disabled={visibleRecords.length === 0}>
                  <Printer className="h-3.5 w-3.5 mr-1.5" /> Print / PDF
                </Button>
              </div>
            </div>

            {/* Tab switcher */}
            <div className="flex gap-1 flex-wrap">
              {tabConfig.map(t => (
                <button
                  key={t.key}
                  onClick={() => setTab(t.key)}
                  className={`px-3 py-1 rounded text-xs font-semibold transition-colors ${
                    tab === t.key
                      ? t.color
                      : 'bg-muted text-muted-foreground hover:bg-muted/80'
                  }`}
                >
                  {t.label}
                  {t.count > 0 && (
                    <span className={`ml-1.5 text-xs rounded-full px-1.5 ${tab === t.key ? 'bg-white/20' : 'bg-muted-foreground/20'}`}>
                      {t.count}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>
        </DialogHeader>

        {visibleRecords.length === 0 && (
          <div className="p-8 text-center text-muted-foreground flex flex-col items-center">
            <AlertCircle className="h-8 w-8 text-amber-500 mb-2" />
            <p className="font-semibold text-amber-600">No Items</p>
            <p className="text-xs">
              {tab === 'active'
                ? 'No active/pending items. Check the other tabs.'
                : tab === 'layaway'
                ? 'No layaway items for this customer.'
                : 'No dispatched or delivered items.'}
            </p>
          </div>
        )}

        {visibleRecords.length > 0 && (
          <div className="overflow-x-auto">
            <div ref={printRef} className="min-w-[640px] p-4 bg-white">
              <InvoicePrintContent records={visibleRecords} currency={currency} />
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useMemo, useState } from 'react';
import { ChevronDown, Layout, Crown, BookOpen, Plus, Calendar, Clock, PauseCircle, ShieldCheck, BarChart2, Merge } from 'lucide-react';
import { TabProps, DatabaseRowType } from '@/types';
import { applySearch, groupByMiner, groupByMinerName, formatDate } from '@/lib/formatters';
import TabHeader from '@/components/TabHeader';
import AdminClientCard from './AdminClientCard';
import ReviewChasingCard from './ReviewChasingCard';
import AddClientModal from '@/components/accounts/AddClientModal';
import DailyRatesEditor from '@/components/admin/DailyRatesEditor';
import MergeClientsModal from '@/components/admin/MergeClientsModal';
import { Button } from '@/components/ui/button';

export default function AdminPipeline({ records, searchQuery, onSearchChange, onUpdate, userEmail, userFirstName, onRefresh }: TabProps) {
  const [expandedPages, setExpandedPages] = useState<Record<string, boolean>>({});
  const [expandedResellers, setExpandedResellers] = useState<Record<string, boolean>>({});
  const [expandedReviewChasing, setExpandedReviewChasing] = useState<Record<string, boolean>>({});
  const [expandedWFDP, setExpandedWFDP] = useState<Record<string, boolean>>({});
  const [expandedDates, setExpandedDates] = useState<Record<string, boolean>>({});
  const [showAddModal, setShowAddModal] = useState(false);
  const [showMergeModal, setShowMergeModal] = useState(false);

  // Pipeline summary counts (global, across all pages)
  const pipelineSummary = useMemo(() => {
    const active = records.filter(r => {
      const s = r.status || '';
      return ['Pending', 'Waiting for Details', 'Waiting for Downpayment', 'Reseller',
        'Payment for Verification', 'Delivered'].includes(s);
    });
    return {
      pending: active.filter(r => r.status === 'Pending' || r.status === 'Waiting for Details').length,
      wfdp: active.filter(r => r.status === 'Waiting for Downpayment').length,
      verif: active.filter(r => r.status === 'Payment for Verification').length,
      reseller: active.filter(r => r.status === 'Reseller').length,
      reviewChasing: active.filter(r => r.status === 'Delivered' && r.reviewChasing !== 'Skipped' && r.reviewChasing !== 'Completed').length,
      total: active.length,
    };
  }, [records]);

  const pageGroups = useMemo(() => {
    const searched = applySearch(records, searchQuery);
    const activeAdminRecords = searched.filter(r => {
      const status = r.status || '';
      if (status === 'Pending' || status === 'Waiting for Details' || status === 'Waiting for Downpayment') return true;
      if (status === 'Reseller') return true;
      if (status === 'Payment for Verification') return true;
      if (status === 'Delivered') {
        if (r.reviewChasing === 'Skipped' || r.reviewChasing === 'Completed') return false;
        return true;
      }
      return false;
    });

    const groups: Record<string, DatabaseRowType[]> = {};
    activeAdminRecords.forEach(r => {
      let pageKey = (r.page || 'Other').trim();
      if (pageKey.toUpperCase().includes('MYK')) pageKey = 'MYK';
      else if (pageKey.toUpperCase().includes('EMPIRE')) pageKey = 'Empire Gold By ETG';
      if (!groups[pageKey]) groups[pageKey] = [];
      groups[pageKey].push(r);
    });

    return Object.keys(groups)
      .sort((a, b) => {
        if (a === 'MYK') return -1; if (b === 'MYK') return 1;
        if (a === 'Empire Gold By ETG') return -1; if (b === 'Empire Gold By ETG') return 1;
        return a.localeCompare(b);
      })
      .reduce((acc, key) => { acc[key] = groups[key]; return acc; }, {} as Record<string, DatabaseRowType[]>);
  }, [records, searchQuery]);

  const togglePage = (page: string) =>
    setExpandedPages(prev => ({ ...prev, [page]: !prev[page] }));

  const toggleDate = (key: string) =>
    setExpandedDates(prev => ({ ...prev, [key]: !prev[key] }));

  const groupMinedByDate = (minedItems: DatabaseRowType[]): Map<string, Map<string, DatabaseRowType[]>> => {
    const byDate = new Map<string, Map<string, DatabaseRowType[]>>();
    for (const r of minedItems) {
      const date = r.dateOfLive || 'Unknown Date';
      const miner = r.minerName?.trim() || 'Unknown Client';
      if (!byDate.has(date)) byDate.set(date, new Map());
      const byMiner = byDate.get(date)!;
      if (!byMiner.has(miner)) byMiner.set(miner, []);
      byMiner.get(miner)!.push(r);
    }
    return new Map([...byDate.entries()].sort((a, b) => b[0].localeCompare(a[0])));
  };

  const renderPageSection = (pageName: string, pageRecords: DatabaseRowType[]) => {
    const isExpanded = expandedPages[pageName] === true;
    const minedItems = pageRecords.filter(r =>
      r.status === 'Pending' || r.status === 'Waiting for Details'
    );
    const wfdpItems = pageRecords.filter(r => r.status === 'Waiting for Downpayment');
    const resellerItems = pageRecords.filter(r => r.status === 'Reseller');
    const paymentVerifItems = pageRecords.filter(r => r.status === 'Payment for Verification');
    const paymentVerifByDate = groupMinedByDate(paymentVerifItems);
    const reviewChasingItems = pageRecords.filter(r => r.status === 'Delivered');
    const minedByDate = groupMinedByDate(minedItems);
    const wfdpByDate = groupMinedByDate(wfdpItems);
    const resellerGrouped = groupByMiner(resellerItems);
    const reviewChasingGroups = groupByMinerName(reviewChasingItems);

    // Mini status chips for page header
    const statusChips = [
      { label: 'Pending', count: minedItems.length, color: 'bg-primary/20 text-primary' },
      { label: 'WFDP', count: wfdpItems.length, color: 'bg-orange-400/20 text-orange-400' },
      { label: 'Verif', count: paymentVerifItems.length, color: 'bg-cyan-400/20 text-cyan-400' },
      { label: 'Reseller', count: resellerItems.length, color: 'bg-teal-400/20 text-teal-400' },
      { label: 'Review', count: reviewChasingItems.length, color: 'bg-yellow-400/20 text-yellow-400' },
    ].filter(c => c.count > 0);

    return (
      <div key={pageName} className="mb-6">
        <div
          className="flex items-center gap-3 py-2.5 px-4 bg-secondary/40 rounded-xl cursor-pointer mb-4 border border-primary/10 hover:bg-secondary/60 transition-colors"
          onClick={() => togglePage(pageName)}
        >
          {pageName === 'MYK' ? <Crown className="h-5 w-5 text-yellow-500" />
            : pageName === 'Empire Gold By ETG' ? <BookOpen className="h-5 w-5 text-primary" />
            : <Layout className="h-5 w-5 text-muted-foreground" />}
          <h2 className="font-cinzel text-base font-bold text-primary tracking-widest uppercase">{pageName}</h2>
          <div className="flex items-center gap-1 flex-wrap">
            {statusChips.map(c => (
              <span key={c.label} className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${c.color}`}>
                {c.label} {c.count}
              </span>
            ))}
          </div>
          <div className="h-px flex-1 bg-primary/10" />
          <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{pageRecords.length}</span>
          <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
        </div>

        {isExpanded && (
          <div className="pl-2 sm:pl-4 space-y-8 animate-in fade-in slide-in-from-top-2 duration-300">
            {minedByDate.size > 0 && (
              <div>
                <div className="flex items-center gap-2 mb-3">
                  <span className="text-[10px] font-black text-muted-foreground uppercase tracking-[0.2em] pl-1">Mined Items</span>
                  <div className="h-px flex-1 bg-border/60" />
                </div>
                {Array.from(minedByDate.entries()).map(([date, minerMap]) => {
                  const dateKey = `${pageName}__${date}`;
                  const isDateExpanded = expandedDates[dateKey] === true;
                  const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                  return (
                    <div key={date} className="mb-3">
                      <div
                        className="flex items-center gap-2 py-2 px-3 bg-primary/10 rounded-lg cursor-pointer mb-2 border border-primary/20 hover:bg-primary/15 transition-colors"
                        onClick={() => toggleDate(dateKey)}
                      >
                        <Calendar className="h-3.5 w-3.5 text-primary" />
                        <span className="text-xs font-bold text-primary uppercase tracking-widest">{formatDate(date)}</span>
                        <div className="h-px flex-1 bg-primary/20" />
                        <span className="text-[10px] font-bold bg-primary/20 text-primary px-2 py-0.5 rounded-md">{totalItems}</span>
                        <ChevronDown className={`h-4 w-4 text-primary transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                      </div>
                      {isDateExpanded && (
                        <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                          {Array.from(minerMap.entries()).map(([name, items]) => (
                            <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {wfdpByDate.size > 0 && (() => {
              const isWFDPExpanded = expandedWFDP[pageName] === true;
              const totalWFDP = wfdpItems.length;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-3 cursor-pointer"
                    onClick={() => setExpandedWFDP(prev => ({ ...prev, [pageName]: !prev[pageName] }))}
                  >
                    <Clock className="h-3.5 w-3.5 text-orange-400" />
                    <span className="text-[10px] font-black text-orange-400 uppercase tracking-[0.2em] pl-1">Waiting for Downpayment</span>
                    <div className="h-px flex-1 bg-orange-400/20" />
                    <span className="text-[10px] font-bold bg-orange-400/20 text-orange-400 px-2 py-0.5 rounded-md">{totalWFDP}</span>
                    <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform duration-200 ${isWFDPExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isWFDPExpanded && (
                    <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                      {Array.from(wfdpByDate.entries()).map(([date, minerMap]) => {
                        const dateKey = `wfdp__${pageName}__${date}`;
                        const isDateExpanded = expandedDates[dateKey] === true;
                        const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                        return (
                          <div key={date} className="mb-3">
                            <div
                              className="flex items-center gap-2 py-2 px-3 bg-orange-400/10 rounded-lg cursor-pointer mb-2 border border-orange-400/20 hover:bg-orange-400/15 transition-colors"
                              onClick={() => toggleDate(dateKey)}
                            >
                              <Calendar className="h-3.5 w-3.5 text-orange-400" />
                              <span className="text-xs font-bold text-orange-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-orange-400/20" />
                              <span className="text-[10px] font-bold bg-orange-400/20 text-orange-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-orange-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {paymentVerifByDate.size > 0 && (() => {
              const isVerifExpanded = expandedDates[`verif__${pageName}`] === true;
              const totalVerif = paymentVerifItems.length;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-3 cursor-pointer"
                    onClick={() => toggleDate(`verif__${pageName}`)}
                  >
                    <ShieldCheck className="h-3.5 w-3.5 text-cyan-400" />
                    <span className="text-[10px] font-black text-cyan-400 uppercase tracking-[0.2em] pl-1">Payment for Verification</span>
                    <div className="h-px flex-1 bg-cyan-400/20" />
                    <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalVerif}</span>
                    <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isVerifExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isVerifExpanded && (
                    <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                      {Array.from(paymentVerifByDate.entries()).map(([date, minerMap]) => {
                        const dateKey = `verif__${pageName}__${date}`;
                        const isDateExpanded = expandedDates[dateKey] === true;
                        const totalItems = Array.from(minerMap.values()).reduce((s, v) => s + v.length, 0);
                        return (
                          <div key={date} className="mb-3">
                            <div
                              className="flex items-center gap-2 py-2 px-3 bg-cyan-400/10 rounded-lg cursor-pointer mb-2 border border-cyan-400/20 hover:bg-cyan-400/15 transition-colors"
                              onClick={() => toggleDate(dateKey)}
                            >
                              <Calendar className="h-3.5 w-3.5 text-cyan-400" />
                              <span className="text-xs font-bold text-cyan-400 uppercase tracking-widest">{formatDate(date)}</span>
                              <div className="h-px flex-1 bg-cyan-400/20" />
                              <span className="text-[10px] font-bold bg-cyan-400/20 text-cyan-400 px-2 py-0.5 rounded-md">{totalItems}</span>
                              <ChevronDown className={`h-4 w-4 text-cyan-400 transition-transform duration-200 ${isDateExpanded ? 'rotate-180' : ''}`} />
                            </div>
                            {isDateExpanded && (
                              <div className="pl-2 animate-in fade-in slide-in-from-top-1 duration-200">
                                {Array.from(minerMap.entries()).map(([name, items]) => (
                                  <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                                ))}
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>
              );
            })()}

            {resellerGrouped.size > 0 && (() => {
              const isResellerExpanded = expandedResellers[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedResellers(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-teal-500 uppercase tracking-[0.2em] pl-1">Resellers</span>
                    <div className="h-px flex-1 bg-teal-500/20" />
                    <span className="text-[10px] font-bold bg-teal-500/20 text-teal-500 px-2 py-0.5 rounded-md">{resellerGrouped.size}</span>
                    <ChevronDown className={`h-4 w-4 text-teal-500 transition-transform duration-200 ${isResellerExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isResellerExpanded && Array.from(resellerGrouped.entries()).map(([name, items]) => (
                    <AdminClientCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} userEmail={userEmail} />
                  ))}
                </div>
              );
            })()}

            {reviewChasingGroups.size > 0 && (() => {
              const isReviewExpanded = expandedReviewChasing[pageName] === true;
              return (
                <div>
                  <div
                    className="flex items-center gap-2 mb-4 cursor-pointer"
                    onClick={() => setExpandedReviewChasing(prev => ({ ...prev, [pageName]: prev[pageName] === undefined ? false : !prev[pageName] }))}
                  >
                    <span className="text-[10px] font-black text-yellow-400 uppercase tracking-[0.2em] pl-1">Review Chasing</span>
                    <div className="h-px flex-1 bg-yellow-400/20" />
                    <span className="text-[10px] font-bold bg-yellow-400/20 text-yellow-400 px-2 py-0.5 rounded-md">{reviewChasingGroups.size}</span>
                    <ChevronDown className={`h-4 w-4 text-yellow-400 transition-transform duration-200 ${isReviewExpanded ? 'rotate-180' : ''}`} />
                  </div>
                  {isReviewExpanded && (
                    <div className="grid grid-cols-1 gap-3">
                      {Array.from(reviewChasingGroups.entries()).map(([name, items]) => (
                        <ReviewChasingCard key={name} minerName={name} records={items} allRecords={records} onUpdate={onUpdate} />
                      ))}
                    </div>
                  )}
                </div>
              );
            })()}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-background pb-24">
      <TabHeader title="Admin Pipeline" subtitle="Active Tasks & Pipeline" searchQuery={searchQuery} onSearchChange={onSearchChange} />
      <div className="px-4 pt-4">
        <DailyRatesEditor date={new Date().toISOString().split('T')[0]} />

        {/* Pipeline Summary Strip */}
        {pipelineSummary.total > 0 && (
          <div className="flex items-center gap-1.5 flex-wrap mb-4 p-3 rounded-xl bg-secondary/30 border border-border">
            <BarChart2 className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
            <span className="text-[10px] text-muted-foreground font-medium uppercase tracking-wide mr-1">Pipeline:</span>
            {pipelineSummary.pending > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-primary/15 text-primary border border-primary/20">
                Pending {pipelineSummary.pending}
              </span>
            )}
            {pipelineSummary.wfdp > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-orange-400/15 text-orange-400 border border-orange-400/20">
                WFDP {pipelineSummary.wfdp}
              </span>
            )}
            {pipelineSummary.verif > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-cyan-400/15 text-cyan-400 border border-cyan-400/20">
                Verif {pipelineSummary.verif}
              </span>
            )}
            {pipelineSummary.reseller > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-teal-400/15 text-teal-400 border border-teal-400/20">
                Reseller {pipelineSummary.reseller}
              </span>
            )}
            {pipelineSummary.reviewChasing > 0 && (
              <span className="text-[10px] font-bold px-2 py-0.5 rounded-full bg-yellow-400/15 text-yellow-400 border border-yellow-400/20">
                Review {pipelineSummary.reviewChasing}
              </span>
            )}
            <div className="h-px flex-1" />
