import { useMemo, useState } from 'react';
import { Search, FileText, ChevronDown, Eye, Edit2, CheckCircle, Info } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { TabProps, DatabaseRowType } from '@/types';
import InvoiceModal from '@/components/InvoiceModal';
import { calcRemainingBalance } from '@/lib/calculations';
import { formatDate } from '@/lib/formatters';
import { toast } from 'sonner';

// Common MOPs with their implied payment currency
const MOP_OPTIONS = [
  { value: 'Bank Transfer AED', label: 'Bank Transfer AED', currency: 'AED' },
  { value: 'Bank Transfer PHP', label: 'Bank Transfer PHP', currency: 'PHP' },
  { value: 'GCash', label: 'GCash', currency: 'PHP' },
  { value: 'COD (Dubai)', label: 'COD (Dubai)', currency: 'AED' },
  { value: 'COD (Abu Dhabi)', label: 'COD (Abu Dhabi)', currency: 'AED' },
  { value: 'COD (Sharjah)', label: 'COD (Sharjah)', currency: 'AED' },
  { value: 'Cash', label: 'Cash', currency: 'AED' },
  { value: 'Credit Card', label: 'Credit Card', currency: 'AED' },
  { value: 'Pick Up Shop', label: 'Pick Up Shop', currency: 'AED' },
  { value: 'Meet Up', label: 'Meet Up', currency: 'AED' },
];

function getMopCurrency(mop: string): string {
  const m = mop.toLowerCase().trim();
  if (m.includes('php') || m === 'gcash') return 'PHP';
  if (m.includes('aed') || m.includes('cod') || m.includes('cash') || m.includes('credit') || m.includes('pick up') || m.includes('meet up')) return 'AED';
  return 'AED';
}

function buildCustomerInvoices(records: DatabaseRowType[]) {
  const customers = new Map<string, Map<string, DatabaseRowType[]>>();
  for (const r of records) {
    const name = (r.minerName || '').trim() || 'Unknown Customer';
    const invoiceNum = String(r.pureWeight ?? '').trim() || '__no_invoice__';
    if (!customers.has(name)) customers.set(name, new Map());
    const byInvoice = customers.get(name)!;
    if (!byInvoice.has(invoiceNum)) byInvoice.set(invoiceNum, []);
    byInvoice.get(invoiceNum)!.push(r);
  }
  return new Map([...customers.entries()].sort((a, b) => a[0].localeCompare(b[0])));
}

interface EditDownpaymentDialogProps {
  records: DatabaseRowType[];
  invoiceNum: string;
  onUpdate: TabProps['onUpdate'];
  onClose: () => void;
}

function EditDownpaymentDialog({ records, invoiceNum, onUpdate, onClose }: EditDownpaymentDialogProps) {
  const [values, setValues] = useState<Record<number, string>>(
    Object.fromEntries(records.map(r => [r.id, String(r.downpayment ?? '')]))
  );
  const [mops, setMops] = useState<Record<number, string>>(
    Object.fromEntries(records.map(r => [r.id, r.modeOfPayment || 'Bank Transfer AED']))
  );
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    setSaving(true);
    try {
      for (const r of records) {
        const newDp = values[r.id];
        const newMop = mops[r.id];
        const dpChanged = newDp !== String(r.downpayment ?? '');
        const mopChanged = newMop !== (r.modeOfPayment || '');
        if (dpChanged || mopChanged) {
          const fields: Partial<DatabaseRowType> = {};
          if (dpChanged) fields.downpayment = newDp;
          if (mopChanged) fields.modeOfPayment = newMop;
          await onUpdate(r.id, fields);
        }
      }
      toast.success('Downpayment updated');
      onClose();
    } catch {
      toast.error('Failed to update downpayment');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open onOpenChange={onClose}>
      <DialogContent className="max-w-lg bg-background border-border" aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle className="text-sm font-bold">
            Edit Downpayment — Invoice {invoiceNum === '__no_invoice__' ? 'N/A' : invoiceNum}
          </DialogTitle>
        </DialogHeader>

        <div className="flex items-start gap-2 text-[10px] text-muted-foreground bg-muted/40 rounded-md px-3 py-2 mb-2">
          <Info className="h-3 w-3 mt-0.5 shrink-0 text-primary" />
          <span>Set the <strong>Mode of Payment</strong> so the system knows the DP currency (AED vs PHP). The badge shows how the amount will be interpreted.</span>
        </div>

        <div className="space-y-4 mt-1 max-h-80 overflow-y-auto pr-1">
          {records.map(r => {
            const currentMop = mops[r.id] || 'Bank Transfer AED';
            const dpCurr = getMopCurrency(currentMop);
            return (
              <div key={r.id} className="rounded-lg border border-border bg-card p-3 space-y-2">
                <p className="text-xs font-semibold text-foreground truncate">{r.itemDescription || '—'}</p>

                {/* MOP selector */}
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground w-24 shrink-0">Mode of Payment</span>
                  <Select
                    value={currentMop}
                    onValueChange={val => setMops(prev => ({ ...prev, [r.id]: val }))}
                  >
                    <SelectTrigger className="h-7 text-xs flex-1">
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {MOP_OPTIONS.map(opt => (
                        <SelectItem key={opt.value} value={opt.value}>
                          <span className="flex items-center gap-2">
                            {opt.label}
                            <span className={`text-[9px] font-bold px-1 rounded ${opt.currency === 'PHP' ? 'bg-green-500/20 text-green-500' : 'bg-blue-500/20 text-blue-400'}`}>
                              {opt.currency}
                            </span>
                          </span>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                {/* Downpayment amount */}
                <div className="flex items-center gap-2">
                  <span className="text-[10px] text-muted-foreground w-24 shrink-0">Downpayment</span>
                  <div className="flex items-center gap-2 flex-1">
                    <Input
                      type="number"
                      value={values[r.id]}
                      onChange={e => setValues(prev => ({ ...prev, [r.id]: e.target.value }))}
                      className="h-7 text-xs flex-1"
                      placeholder="0"
                    />
                    <Badge
                      variant="outline"
                      className={`text-[9px] font-bold shrink-0 ${dpCurr === 'PHP' ? 'border-green-500/40 text-green-500' : 'border-blue-400/40 text-blue-400'}`}
                    >
                      {dpCurr}
                    </Badge>
                  </div>
                </div>

                {/* Current values for reference */}
                <div className="text-[9px] text-muted-foreground">
                  Current: DP={String(r.downpayment || '0')} · MOP={r.modeOfPayment || '—'}
                </div>
              </div>
            );
          })}
        </div>

        <div className="flex gap-2 pt-2 justify-end">
          <Button variant="outline" size="sm" className="h-7 text-xs" onClick={onClose}>Cancel</Button>
          <Button size="sm" className="h-7 text-xs bg-primary text-primary-foreground" onClick={handleSave} disabled={saving}>
            <CheckCircle className="h-3 w-3 mr-1" />
            {saving ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

interface InvoiceRowProps {
  invoiceNum: string;
  records: DatabaseRowType[];
  onUpdate: TabProps['onUpdate'];
}

function InvoiceRow({ invoiceNum, records, onUpdate }: InvoiceRowProps) {
  const [showModal, setShowModal] = useState(false);
  const [showEdit, setShowEdit] = useState(false);

  const displayNum = invoiceNum === '__no_invoice__' ? '—' : invoiceNum;
  const dates = records.map(r => r.dateOfLive).filter(Boolean) as string[];
  const firstDate = dates.length > 0 ? formatDate(dates[0]) : '—';
  const totalBalance = records.reduce((s, r) => s + calcRemainingBalance(r), 0);
  const totalItems = records.length;
  const statuses = [...new Set(records.map(r => r.status || ''))];
  const balanceColor = totalBalance <= 0 ? 'text-green-500' : 'text-destructive';

  return (
    <>
      <div className="flex items-center gap-2 py-2 px-3 rounded-lg border border-border bg-card hover:bg-secondary/20 transition-colors">
        <FileText className="h-3.5 w-3.5 text-primary shrink-0" />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-xs font-bold text-foreground font-mono">{displayNum}</span>
            <span className="text-[10px] text-muted-foreground">{firstDate}</span>
            <span className="text-[10px] bg-muted text-muted-foreground px-1.5 py-0.5 rounded">{totalItems} item{totalItems !== 1 ? 's' : ''}</span>
          </div>
          <div className="flex items-center gap-2 mt-0.5 flex-wrap">
            {statuses.slice(0, 3).map(s => (
              <span key={s} className="text-[9px] text-muted-foreground">{s}</span>
            ))}
            <span className={`text-[10px] font-semibold ml-auto ${balanceColor}`}>
              {totalBalance <= 0 ? 'PAID' : `Balance: ${Math.round(totalBalance).toLocaleString()}`}
            </span>
          </div>
        </div>
        <div className="flex items-center gap-1 shrink-0">
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-primary" onClick={() => setShowEdit(true)} title="Edit downpayment">
            <Edit2 className="h-3.5 w-3.5" />
          </Button>
          <Button variant="ghost" size="sm" className="h-7 w-7 p-0 text-muted-foreground hover:text-primary" onClick={() => setShowModal(true)} title="View invoice">
            <Eye className="h-3.5 w-3.5" />
          </Button>
        </div>
      </div>

      {showModal && <InvoiceModal records={records} onClose={() => setShowModal(false)} />}
      {showEdit && (
        <EditDownpaymentDialog records={records} invoiceNum={invoiceNum} onUpdate={onUpdate} onClose={() => setShowEdit(false)} />
      )}
    </>
  );
}

interface CustomerCardProps {
  minerName: string;
  invoiceGroups: Map<string, DatabaseRowType[]>;
  onUpdate: TabProps['onUpdate'];
}

function CustomerCard({ minerName, invoiceGroups, onUpdate }: CustomerCardProps) {
  const [expanded, setExpanded] = useState(false);
  const totalInvoices = invoiceGroups.size;
  const totalItems = [...invoiceGroups.values()].reduce((s, r) => s + r.length, 0);
  const totalBalance = [...invoiceGroups.values()].flat().reduce((s, r) => s + calcRemainingBalance(r), 0);

  return (
    <div className="mb-3 rounded-xl border border-border bg-card overflow-hidden">
      <button
        onClick={() => setExpanded(e => !e)}
        className="w-full flex items-center gap-3 px-4 py-3 text-left hover:bg-secondary/30 transition-colors"
      >
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-foreground truncate">{minerName}</p>
          <div className="flex items-center gap-2 mt-0.5">
            <span className="text-[10px] text-muted-foreground">{totalInvoices} invoice{totalInvoices !== 1 ? 's' : ''}</span>
            <span className="text-[10px] text-muted-foreground">·</span>
            <span className="text-[10px] text-muted-foreground">{totalItems} items</span>
            {totalBalance > 0 ? (
              <>
                <span className="text-[10px] text-muted-foreground">·</span>
                <span className="text-[10px] font-semibold text-destructive">Balance: {Math.round(totalBalance).toLocaleString()}</span>
              </>
            ) : (
              <>
                <span className="text-[10px] text-muted-foreground">·</span>
                <span className="text-[10px] font-semibold text-green-500">Fully Paid</span>
              </>
            )}
          </div>
        </div>
        <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform duration-200 ${expanded ? 'rotate-180' : ''}`} />
      </button>

      {expanded && (
        <div className="px-3 pb-3 space-y-2 animate-in fade-in slide-in-from-top-1 duration-200">
          {[...invoiceGroups.entries()].map(([invoiceNum, recs]) => (
            <InvoiceRow key={invoiceNum} invoiceNum={invoiceNum} records={recs} onUpdate={onUpdate} />
          ))}
        </div>
      )}
    </div>
  );
}

export default function InvoicingTab({ records, onUpdate }: TabProps) {
  const [search, setSearch] = useState('');

  const customerMap = useMemo(() => {
    const EXCLUDED = new Set(['Cancelled', 'Returned Item']);
    const nonCancelled = records.filter(r => !EXCLUDED.has(r.status || ''));
    const filtered = search.trim()
      ? nonCancelled.filter(r =>
          (r.minerName || '').toLowerCase().includes(search.toLowerCase()) ||
          String(r.pureWeight ?? '').toLowerCase().includes(search.toLowerCase()) ||
          (r.itemDescription || '').toLowerCase().includes(search.toLowerCase())
        )
      : nonCancelled;
    return buildCustomerInvoices(filtered);
  }, [records, search]);

  return (
    <div className="min-h-screen bg-background pb-24">
      <div className="sticky top-12 z-20 bg-background/95 backdrop-blur border-b border-border px-4 py-3">
        <div className="flex items-center gap-2 mb-1">
          <FileText className="h-4 w-4 text-primary" />
          <h1 className="text-sm font-bold text-foreground font-cinzel tracking-wide uppercase">Invoicing</h1>
          <span className="text-[10px] bg-primary/10 text-primary px-2 py-0.5 rounded-full ml-auto">
            {customerMap.size} customers
          </span>
        </div>
        <p className="text-[10px] text-muted-foreground mb-2">View &amp; manage existing invoices. Edit downpayments where needed.</p>
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Search customer, invoice #, or item..."
            className="pl-8 h-8 text-xs bg-background border-border"
          />
        </div>
      </div>

      <div className="px-4 pt-4">
        {customerMap.size === 0 ? (
          <div className="text-center py-24 border-2 border-dashed border-border rounded-2xl">
            <FileText className="h-8 w-8 text-muted-foreground mx-auto mb-2" />
            <p className="text-sm text-muted-foreground font-medium">No customers found.</p>
          </div>
        ) : (
          [...customerMap.entries()].map(([name, invoiceGroups]) => (
            <CustomerCard key={name} minerName={name} invoiceGroups={invoiceGroups} onUpdate={onUpdate} />
          ))
        )}
      </div>
    </div>
  );
}

// ============================================================
// ROLE CONFIGURATION
// ============================================================

export type UserRole = 'super_admin' | 'admin' | 'dispatch' | 'accounts' | 'bossing' | 'liver';

// Super-admins: always have full access and see ALL tabs.
export const SUPER_ADMIN_EMAILS = [;
  "reynanteevillegas@gmail.com",
  "villegasenrique0921@gmail.com",
  "kierbernal66@gmail.com",
];

// Email → Liver display name mapping (UPPERCASE to match liverName field in records).
// Add new livers here when their email is known.
export const EMAIL_TO_LIVER_NAME: Record<string, string> = {
  'adelacr419@gmail.com': 'AIREEN',
  'maybelynloreno016@gmail.com': 'AMBIE',
  'yairakesha@gmail.com': 'KESHA',
};

// Fallback roles if the Database 'Roles' tab hasn't been set up yet
export const fallbackRoleConfig = {
  adminEmails: ["roseannaranez2@gmail.com"],
  dispatchEmails: [] as string[],
  accountsEmails: [] as string[],
  bossingEmails: [] as string[],
  liverEmails: [] as string[],
};

export function getUserRole(
  email: string,
  dynamicRoles: any[] | null = null,
): UserRole[] {
  const e = email.toLowerCase().trim();

  if (SUPER_ADMIN_EMAILS.map(x => x.toLowerCase()).includes(e)) {
    return ['super_admin'];
  }

  const assignedRoles: UserRole[] = [];

  if (dynamicRoles && dynamicRoles.length > 0) {
    const found = dynamicRoles.find(r => {
      const rEmail = (r.email || r.Email || r.EMAIL || r['Email Address'] || '');
      return rEmail.toLowerCase().trim() === e;
    });

    if (found) {
      const role = (found.role || found.Role || found.ROLE || '').toLowerCase().trim();
      if (role === 'super_admin') assignedRoles.push('super_admin');
      if (role === 'admin' || role === 'super_admin') assignedRoles.push('admin');
      if (role === 'dispatch') assignedRoles.push('dispatch');
      if (role === 'accounts') assignedRoles.push('accounts');
      if (role === 'bossing') assignedRoles.push('bossing');
      if (role === 'liver') assignedRoles.push('liver');

      if (assignedRoles.length === 0) {
        const parts = role.split(',').map((s: string) => s.trim());
        for (const p of parts) {
          if (['admin', 'dispatch', 'accounts', 'bossing', 'super_admin', 'liver'].includes(p)) {
            assignedRoles.push(p as UserRole);
          }
        }
      }
    }
  }

  if (assignedRoles.length === 0) {
    if (fallbackRoleConfig.adminEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('admin');
    }
    if (fallbackRoleConfig.dispatchEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('dispatch');
    }
    if (fallbackRoleConfig.accountsEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('accounts');
    }
    if (fallbackRoleConfig.bossingEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('bossing');
    }
    if (fallbackRoleConfig.liverEmails.map(x => x.toLowerCase()).includes(e)) {
      assignedRoles.push('liver');
    }
  }

  return assignedRoles;
}

