/**
 * Historical Rate Locking Store
 *
 * All dates are normalized to YYYY-MM-DD before being used as localStorage keys.
 * This ensures that "02/27/2026", "February 27, 2026", "Feb 27, 2026", and "2026-02-27"
 * all map to the same key: rates_2026-02-27.
 *
 * STICKY RATE:
 * A "current default" rate is stored under STICKY_RATES_KEY.
 * When no date-specific rate exists, getRatesForDate() falls back to the sticky rate.
 * This means you only need to update the rate when it actually changes — it persists
 * automatically for all future dates until you change it again.
 */

export interface RateSnapshot {
  phpRate: number;
  silverSellRate: number;
  silverCostRate: number;
  silverBrandedSellRate: number;
  silverBrandedCostRate: number;
}

export const DEFAULT_RATES: RateSnapshot = {
  phpRate: 16.7,
  silverSellRate: 45,
  silverCostRate: 15,
  silverBrandedSellRate: 60,
  silverBrandedCostRate: 32,
};

// Key for the persistent sticky/default rate (not date-specific)
const STICKY_RATES_KEY = 'rates_current_default';

/** Get the current sticky default rates (falls back to DEFAULT_RATES if never set). */
export function getStickyRates(): RateSnapshot {
  try {
    const raw = localStorage.getItem(STICKY_RATES_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
      return {
        phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
        silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
        silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
        silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
        silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
      };
    }
  } catch { /* fall through */ }
  return { ...DEFAULT_RATES };
}

/** Save a rate snapshot as the persistent sticky default (applies to all future dates with no override). */
export function setStickyRates(rates: RateSnapshot): void {
  try {
    localStorage.setItem(STICKY_RATES_KEY, JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save sticky rates', e);
  }
}

// ── Date Normalization ────────────────────────────────────────────────────────
function normalizeDate(date: string): string {
  if (!date) return '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(date.trim())) return date.trim();
  const mdyMatch = date.trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (mdyMatch) {
    return `${mdyMatch[3]}-${mdyMatch[1].padStart(2, '0')}-${mdyMatch[2].padStart(2, '0')}`;
  }
  try {
    const d = new Date(date);
    if (!isNaN(d.getTime())) {
      const utc = new Date(d.getTime() + d.getTimezoneOffset() * 60000);
      const yyyy = utc.getFullYear();
      const mm = String(utc.getMonth() + 1).padStart(2, '0');
      const dd = String(utc.getDate()).padStart(2, '0');
      return `${yyyy}-${mm}-${dd}`;
    }
  } catch { /* fall through */ }
  return date.trim();
}

const KEY = (date: string) => `rates_${normalizeDate(date)}`;
const LOCK_KEY = (date: string) => `rates_lock_${normalizeDate(date)}`;

/** Save a full rate snapshot for a specific date (any date format accepted). */
export function saveRatesForDate(date: string, rates: RateSnapshot): void {
  if (!date) return;
  try {
    localStorage.setItem(KEY(date), JSON.stringify(rates));
  } catch (e) {
    console.error('ratesStore: failed to save', e);
  }
}

/**
 * Retrieve the rate snapshot for a date (any format).
 * Falls back to STICKY RATES (not hardcoded defaults) when no date-specific rate is found.
 * This means once you set a sticky rate, all future dates automatically use it.
 */
export function getRatesForDate(date: string): RateSnapshot {
  if (date) {
    try {
      const raw = localStorage.getItem(KEY(date));
      if (raw) {
        const parsed = JSON.parse(raw) as Partial<RateSnapshot>;
        return {
          phpRate: parsed.phpRate ?? DEFAULT_RATES.phpRate,
          silverSellRate: parsed.silverSellRate ?? DEFAULT_RATES.silverSellRate,
          silverCostRate: parsed.silverCostRate ?? DEFAULT_RATES.silverCostRate,
          silverBrandedSellRate: parsed.silverBrandedSellRate ?? DEFAULT_RATES.silverBrandedSellRate,
          silverBrandedCostRate: parsed.silverBrandedCostRate ?? DEFAULT_RATES.silverBrandedCostRate,
        };
      }
    } catch (e) {
      console.error('ratesStore: failed to read', e);
    }
  }
  // No date-specific rate — use the sticky default
  return getStickyRates();
}

/** Returns true only if a snapshot was explicitly saved for this date (not just defaults). */
export function hasRatesSnapshotForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(KEY(date)) !== null;
}

// ── Rate Lock / Unlock ────────────────────────────────────────────────────────

export function isRateLockedForDate(date: string): boolean {
  if (!date) return false;
  return localStorage.getItem(LOCK_KEY(date)) === 'true';
}

export function lockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.setItem(LOCK_KEY(date), 'true');
}

export function unlockRatesForDate(date: string): void {
  if (!date) return;
  localStorage.removeItem(LOCK_KEY(date));
}

// ── Convenience getters ───────────────────────────────────────────────────────

export const DEFAULT_PHP_RATE = DEFAULT_RATES.phpRate;
export const DEFAULT_SILVER_SELL_RATE = DEFAULT_RATES.silverSellRate;
export const DEFAULT_SILVER_BRANDED_SELL_RATE = DEFAULT_RATES.silverBrandedSellRate;
export const DEFAULT_SILVER_COST_RATE = DEFAULT_RATES.silverCostRate;
export const DEFAULT_SILVER_BRANDED_COST_RATE = DEFAULT_RATES.silverBrandedCostRate;

export function getPhpRate(date: string): number { return getRatesForDate(date).phpRate; }
export function getSilverSellRate(date: string): number { return getRatesForDate(date).silverSellRate; }
export function getSilverBrandedSellRate(date: string): number { return getRatesForDate(date).silverBrandedSellRate; }
export function getSilverCostRate(date: string): number { return getRatesForDate(date).silverCostRate; }
export function getSilverBrandedCostRate(date: string): number { return getRatesForDate(date).silverBrandedCostRate; }

function patchDate(date: string, patch: Partial<RateSnapshot>) {
  saveRatesForDate(date, { ...getRatesForDate(date), ...patch });
}
export function setPhpRate(date: string, rate: number) { patchDate(date, { phpRate: rate }); }
export function setSilverSellRate(date: string, rate: number) { patchDate(date, { silverSellRate: rate }); }
export function setSilverBrandedSellRate(date: string, rate: number) { patchDate(date, { silverBrandedSellRate: rate }); }
export function setSilverCostRate(date: string, rate: number) { patchDate(date, { silverCostRate: rate }); }
export function setSilverBrandedCostRate(date: string, rate: number) { patchDate(date, { silverBrandedCostRate: rate }); }

// Legacy aliases
/** @deprecated Use getRatesForDate(date).silverSellRate */
export function getSilverRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverSellRate */
export function setSilverRate(date: string, rate: number) { setSilverSellRate(date, rate); }
/** @deprecated Use getRatesForDate(date).silverBrandedSellRate */
export function getSilverBrandedRateForDate(date: string): number | null {
  const raw = localStorage.getItem(KEY(date));
  if (!raw) return null;
  try { return (JSON.parse(raw) as Partial<RateSnapshot>).silverBrandedSellRate ?? null; } catch { return null; }
}
/** @deprecated Use setSilverBrandedSellRate */
export function setSilverBrandedRate(date: string, rate: number) { setSilverBrandedSellRate(date, rate); }
export function hasPhpRate(date: string): boolean { return localStorage.getItem(KEY(date)) !== null; }

import { useState, useEffect } from 'react';
import { ChevronDown, Settings2, Lock, LockOpen, ShieldAlert, Pin, RefreshCw } from 'lucide-react';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { useAuth } from 'zite-auth-sdk';
import {
  getRatesForDate,
  saveRatesForDate,
  getStickyRates,
  setStickyRates,
  DEFAULT_RATES,
  isRateLockedForDate,
  lockRatesForDate,
  unlockRatesForDate,
  hasRatesSnapshotForDate,
} from '@/lib/ratesStore';
import { SUPER_ADMIN_EMAILS } from '@/config/roles';

interface Props {
  date: string;
}

export default function DailyRatesEditor({ date }: Props) {
  const { user } = useAuth();
  const isSuperAdmin = user?.email
    ? SUPER_ADMIN_EMAILS.map(e => e.toLowerCase()).includes(user.email.toLowerCase())
    : false;

  const [open, setOpen] = useState(false);
  const [selectedRateDate, setSelectedRateDate] = useState(date || new Date().toISOString().split('T')[0]);
  const [phpRate, setPhpRateVal] = useState('');
  const [silverSell, setSilverSellVal] = useState('');
  const [silverBrandedSell, setSilverBrandedSellVal] = useState('');
  const [isLocked, setIsLocked] = useState(false);
  const [stickySnap, setStickySnap] = useState(getStickyRates());
  const [editingSticky, setEditingSticky] = useState(false);
  const [stickyPhp, setStickyPhp] = useState('');
  const [stickySilver, setStickySilver] = useState('');
  const [stickySilverBranded, setStickySilverBranded] = useState('');

  useEffect(() => {
    if (date) setSelectedRateDate(date);
  }, [date]);

  useEffect(() => {
    const snap = getRatesForDate(selectedRateDate);
    setPhpRateVal(String(snap.phpRate));
    setSilverSellVal(String(snap.silverSellRate));
    setSilverBrandedSellVal(String(snap.silverBrandedSellRate));
    setIsLocked(isRateLockedForDate(selectedRateDate));
  }, [selectedRateDate, open]);

  useEffect(() => {
    const s = getStickyRates();
    setStickySnap(s);
    setStickyPhp(String(s.phpRate));
    setStickySilver(String(s.silverSellRate));
    setStickySilverBranded(String(s.silverBrandedSellRate));
  }, [open]);

  const saveSticky = () => {
    const php = parseFloat(stickyPhp);
    const ss = parseFloat(stickySilver);
    const sbs = parseFloat(stickySilverBranded);
    if ([php, ss, sbs].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }
    setStickyRates({
      ...getStickyRates(),
      phpRate: php,
      silverSellRate: ss,
      silverBrandedSellRate: sbs,
    });
    setStickySnap(getStickyRates());
    setEditingSticky(false);
    toast.success('Default rate updated and locked in 📌 — all future dates will use this rate');
  };

  const save = () => {
    if (isLocked) {
      toast.error('Rates are locked. Only a Super Admin can unlock them.');
      return;
    }
    const php = parseFloat(phpRate);
    const ss = parseFloat(silverSell);
    const sbs = parseFloat(silverBrandedSell);
    if ([php, ss, sbs].some(v => isNaN(v) || v <= 0)) {
      toast.error('All rates must be positive numbers');
      return;
    }
    const existing = getRatesForDate(selectedRateDate);
    saveRatesForDate(selectedRateDate, { ...existing, phpRate: php, silverSellRate: ss, silverBrandedSellRate: sbs });
    lockRatesForDate(selectedRateDate);
    setIsLocked(true);
    toast.success(`Rates locked for ${selectedRateDate} 🔒`);
    setOpen(false);
  };

  const handleUnlock = () => {
    if (!isSuperAdmin) {
      toast.error('Only Super Admins can unlock rates.');
      return;
    }
    unlockRatesForDate(selectedRateDate);
    setIsLocked(false);
    toast.success(`Rates unlocked for ${selectedRateDate} 🔓`);
  };

  const snap = getRatesForDate(selectedRateDate);
  const isToday = selectedRateDate === new Date().toISOString().split('T')[0];
  const hasDateOverride = hasRatesSnapshotForDate(selectedRateDate);

  return (
    <div className="mb-4">
      {/* Collapsed Summary Bar */}
      <button
        onClick={() => setOpen(o => !o)}
        className="w-full flex items-center gap-2 px-3 py-2 rounded-lg bg-card border border-border hover:bg-secondary/40 transition-colors text-left"
      >
        <Settings2 className="h-3.5 w-3.5 text-primary shrink-0" />
        <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider">Daily Rates</span>
        <span className="text-[10px] text-foreground ml-1">
          PHP <span className="text-primary font-semibold">{snap.phpRate}</span>
          &nbsp;·&nbsp; Ag <span className="text-primary font-semibold">{snap.silverSellRate}</span>
          &nbsp;·&nbsp; Ag★ <span className="text-primary font-semibold">{snap.silverBrandedSellRate}</span>
        </span>
        {!hasDateOverride && (
          <Pin className="h-3 w-3 text-blue-500 ml-1 shrink-0" title="Using sticky default rate" />
        )}
        {isRateLockedForDate(selectedRateDate) && (
          <Lock className="h-3 w-3 text-amber-500 ml-1 shrink-0" />
        )}
        <ChevronDown className={`h-3.5 w-3.5 text-muted-foreground ml-auto transition-transform duration-200 ${open ? 'rotate-180' : ''}`} />
      </button>

      {open && (
        <div className="mt-2 px-3 py-3 rounded-lg bg-card border border-border space-y-3 animate-in fade-in slide-in-from-top-2 duration-200">

          {/* ── STICKY DEFAULT RATE SECTION ── */}
          <div className="rounded-md border border-blue-500/30 bg-blue-500/5 px-3 py-2.5 space-y-2">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Pin className="h-3.5 w-3.5 text-blue-500" />
                <span className="text-xs font-bold text-blue-500">Default Rate (Sticky)</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-muted-foreground">
                  PHP <strong>{stickySnap.phpRate}</strong> · Ag <strong>{stickySnap.silverSellRate}</strong> · Ag★ <strong>{stickySnap.silverBrandedSellRate}</strong>
                </span>
                <Button
                  variant="outline"
                  size="sm"
                  className="text-[10px] h-6 border-blue-500/40 text-blue-500 hover:bg-blue-500/10"
                  onClick={() => setEditingSticky(e => !e)}
                >
                  {editingSticky ? 'Cancel' : <><RefreshCw className="h-2.5 w-2.5 mr-1" /> Change</>}
                </Button>
              </div>
            </div>

            <p className="text-[10px] text-muted-foreground">
              This rate applies to <strong>all dates</strong> that don't have a specific override. Set it once and it stays until you change it.
            </p>

            {editingSticky && (
              <div className="space-y-2 pt-1 border-t border-blue-500/20">
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">PHP Rate (1 AED =)</span>
                  <Input type="number" step="0.01" value={stickyPhp} onChange={e => setStickyPhp(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                  <span className="text-[10px] text-muted-foreground">PHP</span>
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">Silver Rate (AED/g)</span>
                  <Input type="number" step="0.5" value={stickySilver} onChange={e => setStickySilver(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                </div>
                <div className="flex items-center gap-3">
                  <span className="text-xs text-muted-foreground w-36 shrink-0">Silver Branded (AED/g)</span>
                  <Input type="number" step="0.5" value={stickySilverBranded} onChange={e => setStickySilverBranded(e.target.value)}
                    className="h-7 text-xs bg-background border-border w-24" />
                </div>
                <Button size="sm" className="text-xs h-7 bg-blue-500 text-white hover:bg-blue-600" onClick={saveSticky}>
                  <Pin className="h-3 w-3 mr-1" /> Save as Default
                </Button>
              </div>
            )}
          </div>

          <div className="h-px bg-border" />

          {/* ── DATE-SPECIFIC OVERRIDE ── */}
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wider shrink-0">Date Override</span>
            <input
              type="date"
              value={selectedRateDate}
              onChange={e => setSelectedRateDate(e.target.value)}
              className="h-7 text-xs rounded-md border border-border bg-background text-foreground px-2 focus:outline-none focus:ring-1 focus:ring-primary"
            />
            {!isToday && <span className="text-[10px] text-amber-500 font-semibold">Historical</span>}
            {hasDateOverride && <Badge variant="outline" className="text-[10px]">Has Override</Badge>}
          </div>

          {/* Lock Status */}
          {isLocked ? (
            <div className="flex items-center justify-between rounded-md border border-amber-500/30 bg-amber-500/10 px-3 py-2">
              <div className="flex items-center gap-2">
                <Lock className="h-3.5 w-3.5 text-amber-500" />
                <span className="text-xs font-semibold text-amber-500">Rates Locked for {selectedRateDate}</span>
              </div>
              {isSuperAdmin ? (
                <Button variant="outline" size="sm" className="text-[10px] h-6 border-amber-500/50 text-amber-500 hover:bg-amber-500/20" onClick={handleUnlock}>
                  <LockOpen className="h-2.5 w-2.5 mr-1" /> Unlock
                </Button>
              ) : (
                <Badge variant="outline" className="text-[10px] border-amber-500/40 text-amber-500">
                  <ShieldAlert className="h-2.5 w-2.5 mr-1" /> Super Admin Only
                </Badge>
              )}
            </div>
          ) : (
            <div className="flex items-center gap-2">
              <LockOpen className="h-3 w-3 text-muted-foreground" />
              <span className="text-[10px] text-muted-foreground">
                {hasDateOverride ? `Override set for ${selectedRateDate} — unlocked` : `No override for ${selectedRateDate} — using default rate`}
              </span>
            </div>
          )}

          <p className="text-[10px] text-muted-foreground uppercase tracking-wider font-bold">
            Rates for <span className="text-primary">{selectedRateDate}</span>
            {!hasDateOverride && <span className="text-blue-500 ml-2">(from default)</span>}
          </p>

          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">PHP Rate (1 AED =)</span>
            <Input type="number" step="0.01" value={phpRate} onChange={e => setPhpRateVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.phpRate)} disabled={isLocked}
              className="h-7 text-xs bg-background border-border w-24 disabled:opacity-50" />
            <span className="text-[10px] text-muted-foreground">PHP</span>
          </div>

          <div className="h-px bg-border" />
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver (non-branded)</p>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Rate (AED/g)</span>
            <Input type="number" step="0.5" value={silverSell} onChange={e => setSilverSellVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.silverSellRate)} disabled={isLocked}
              className="h-7 text-xs bg-background border-border w-24 disabled:opacity-50" />
          </div>

          <div className="h-px bg-border" />
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wider">Silver Branded</p>
          <div className="flex items-center gap-3">
            <span className="text-xs text-muted-foreground w-36 shrink-0">Rate (AED/g)</span>
            <Input type="number" step="0.5" value={silverBrandedSell} onChange={e => setSilverBrandedSellVal(e.target.value)}
              placeholder={String(DEFAULT_RATES.silverBrandedSellRate)} disabled={isLocked}
              className="h-7 text-xs bg-background border-border w-24 disabled:opacity-50" />
          </div>

          <div className="flex gap-2 pt-1">
            <Button variant="outline" size="sm" className="text-xs h-7 border-border" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button size="sm" className="text-xs h-7 bg-primary text-primary-foreground" onClick={save} disabled={isLocked}>
              <Lock className="h-3 w-3 mr-1" /> Lock for {selectedRateDate}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

