  if (String(fields.freeSf).toUpperCase() === 'TRUE') {
    finalProfit -= COURIER_FEE_AED;
  }
  return Math.round(finalProfit).toFixed(2);
}

export default createEndpoint({
  description: 'Update a Database row securely with historical rate locking',
  authenticated: true,
  inputSchema: z.object({
    rowId: z.number(),
    fields: z.record(z.unknown()),
    // Daily rate snapshot — keyed by the record's dateOfLive on the frontend
    phpRate: z.number().positive().optional().default(16.7),
    silverSellRate: z.number().positive().optional().default(45),
    silverBrandedSellRate: z.number().positive().optional().default(60),
    silverCostRate: z.number().positive().optional().default(15),
    silverBrandedCostRate: z.number().positive().optional().default(32),
  }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    if (!context?.user?.email) throw new Error("Unauthorized request");
    const userEmail = context.user.email.toLowerCase().trim();

    let isAuthorized = SUPER_ADMIN_EMAILS.includes(userEmail);
    if (!isAuthorized) {
      const roles = await Roles.findAll({});
      const found = roles?.find(r => (r.email || '')?.toLowerCase().trim() === userEmail);
      if (found) {
        const roleStr = (found.role || '').toLowerCase();
        if (['super_admin', 'admin', 'dispatch', 'accounts', 'bossing'].some(r => roleStr.includes(r))) {
          isAuthorized = true;
        }
      }
    }
    if (!isAuthorized) throw new Error("Forbidden: Your account does not have permission to modify the database.");

    const sanitized: Partial<DatabaseRowType> = {};
    let needsProfitRecalc = false;

    for (const [key, value] of Object.entries(input.fields)) {
      if (!VALID_FIELDS.has(key as keyof DatabaseRowType)) continue;
      if (key === 'freeSf') {
        sanitized.freeSf = (value === true || value === 'TRUE' || value === 'true') ? true : false;
      } else if (key === 'profit') {
        continue; // Always recalculate server-side
      } else {
        (sanitized as Record<string, unknown>)[key] = value;
        if (PROFIT_FIELDS.has(key)) needsProfitRecalc = true;
      }
    }

    if (needsProfitRecalc) {
      (sanitized as Record<string, unknown>).profit = Number(
        calculateServerProfit(sanitized, {
          phpRate: input.phpRate,
          silverSellRate: input.silverSellRate,
          silverBrandedSellRate: input.silverBrandedSellRate,
          silverCostRate: input.silverCostRate,
          silverBrandedCostRate: input.silverBrandedCostRate,
        })
      );
    }

    await Database.update({ rowId: input.rowId, row: sanitized });
    return { success: true };
  },
});

import { DatabaseRowType } from '@/types';
import { calcShippingFee, calcCCFee, isPcItem, getQty, getEffectiveCurrency, calcItemPriceAED, USD_TO_AED, resolveDownpaymentCurrencyAED } from '@/lib/calculations';
import { getRatesForDate } from '@/lib/ratesStore';
import { numberToWords } from '@/lib/numberToWords';
import { formatDate } from '@/lib/formatters';

interface Props {
  records: DatabaseRowType[];
  currency: string;
}

const MYK_LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/mVy86cbPRgBbVeiVpWrXgn/pasted-image-1772870436282.png';
const EMPIRE_LOGO_URL = 'https://wsrv.nl/?url=images.fillout.com/orgid-614156/flowpublicid-6ydzrkprmt/widgetid-default/gVXEeVabkZMS2jbPUymu31/pasted-image-1773650297935.png';

function isEmpirePage(page?: string): boolean {
  const p = (page || '').toLowerCase();
  return p.includes('empire gold') || p.includes('empire');
}

const NOTES = [
  'We can hold unpaid items for a maximum of 3 days from the invoice date.',
  'Failure to settle within 3 days may result in additional charges.',
  'Unpaid items will be automatically cancelled after the grace period without prior notice.',
  'All items undergo strict quality checking before dispatch.',
  'An unboxing video is strictly required. No video, no refund, no exchange.',
  'No cash refund. Store credit only.',
  'Non Refundable for LA items once the payments is verified and decided not to continue the purchased. Please decide wisely.',
];

const n = (v: unknown) => parseFloat(String(v ?? 0)) || 0;
const rnd = (v: number) => Math.round(v);

export default function InvoicePrintContent({ records, currency }: Props) {
  const first = records[0];

  // Use the most recent record's rate snapshot for invoice-level conversions (e.g. shipping).
  // Mixed-date invoices: shipping should reflect the latest live date's PHP rate.
  const latestRecord = records.reduce((latest, r) => {
    if (!latest?.dateOfLive) return r;
    if (!r.dateOfLive) return latest;
    return r.dateOfLive > latest.dateOfLive ? r : latest;
  }, first);
  const dailyRates = getRatesForDate(latestRecord?.dateOfLive || '');
  const phpRate = dailyRates.phpRate;

  const convertFromAED = (aedValue: number): number => {
    if (currency === 'PHP') return aedValue * phpRate;
    if (currency === 'USD') return aedValue / 3.67;
    return aedValue;
  };

  const fmtAmt = (v: number) =>
    `${currency} ${rnd(v).toLocaleString('en-US')}`;

  const items = records.map(r => {
    const category = (r.category || '').toLowerCase().trim();
    const isScrewType = category.includes('screw type');
    const isPerPc = category.includes('per pc');
    const isSilver = category === 'silver';
    const isSilverBranded = category === 'silver branded';
    const isPc = isPcItem(r);
    const gramsValue = n(r.grams);
    const qtyValue = getQty(r);

    // Use per-record rates so each item reflects its own date's PHP rate
    const recordRates = getRatesForDate(r.dateOfLive || '');
    const convertFromAEDForRecord = (aedValue: number): number => {
      if (currency === 'PHP') return aedValue * recordRates.phpRate;
      if (currency === 'USD') return aedValue / 3.67;
      return aedValue;
    };

    let trueAedRate = 0;
    if (isSilver || isSilverBranded) {
      trueAedRate = n(r.clientRate) > 0 ? clientRateAED(r) : getSilverRate(category, r)!;
    } else {
      trueAedRate = clientRateAED(r);
    }

    const displayRate = rnd(convertFromAEDForRecord(trueAedRate));

    let amount: number;
    if (isScrewType || isPerPc) {
      amount = rnd(displayRate * qtyValue);
    } else if (isPc || gramsValue === 0) {
      amount = displayRate;
    } else {
      amount = rnd(displayRate * gramsValue);
    }



    let gramsDisplay = '';
    if (isScrewType || isPerPc) {
      gramsDisplay = `${qtyValue} PC${qtyValue > 1 ? 'S' : ''}`;
    } else {
      gramsDisplay = (isPc || gramsValue === 0) ? 'PC' : gramsValue.toFixed(2);
    }

    return {
      code: r.orderId || '—',
      desc: r.itemDescription || '—',
      tog: r.tog || r.category || '—',
      gramsDisplay,
      isPc: (isPc || isScrewType || isPerPc),
      rate: displayRate,
      amount,
      liver: r.liverName?.trim() || '',
      date: formatDate(r.dateOfLive),
      mop: (r.modeOfPayment || '').trim().toUpperCase(),
    };
  });

  const subtotal = items.reduce((s, i) => s + i.amount, 0);
  const shippingAED = first ? calcShippingFee(first) : 0;
  // USD shipping: ceil so 299/3.67 = 81.47 → 82 USD (as required). AED/PHP use normal rounding.
  const shipping = currency === 'USD' ? Math.ceil(convertFromAED(shippingAED)) : rnd(convertFromAED(shippingAED));
  const additionalAED = n(first?.additionalCharges);
  const additional = rnd(convertFromAED(additionalAED));
  // CC fee is 5% of each item's display-currency amount (avoids AED rounding loss).
  // e.g. PHP 2,162 × 5% = PHP 108 (correct), vs going through AED which loses precision.
  const ccFee = rnd(items.reduce((s, item, idx) => {
    const r = records[idx];
    if ((r.modeOfPayment || '') !== 'Credit Card') return s;
    return s + item.amount * 0.05;
  }, 0));
  const total = subtotal + shipping + additional + ccFee;

  // Compute total paid with CORRECT currency handling.
  //
  // CRITICAL: Downpayment currency = MOP currency (GCash → PHP), NOT item currency.
  // A customer can buy an AED-priced item but pay via GCash (PHP).
  // If we use the item currency we get: 835 PHP treated as 835 AED → WRONG.
  // We must convert each payment component independently using its own currency.
  const totalPaidConverted = records.reduce((s, r) => {
    const snap = getRatesForDate(r.dateOfLive || '');
    const rPhpRate = snap.phpRate;

    // Helper: convert a value in `fromCurr` to the display currency
    const convertValue = (val: number, fromCurr: string): number => {
      if (fromCurr === currency) return val; // same currency — use directly, no rounding loss
      // Convert to AED first, then to display currency
      let aed = val;
      if (fromCurr === 'PHP') aed = val / rPhpRate;
      else if (fromCurr === 'USD') aed = val * 3.67;
      return convertFromAED(aed);
    };

    // Downpayment: uses PAYMENT currency (based on MOP — GCash = PHP).
    // SMART HEURISTIC: if declared AED but raw DP exceeds AED invoice total,
    // it can't be AED — treat as PHP. BUT only apply when MOP doesn't explicitly
    // name a currency (e.g. "Bank Transfer AED" must always be treated as AED).
    const dpRaw = n(r.downpayment);
    let dpCurr = getPaymentCurrency(r);
    const rMopLower = (r.modeOfPayment || '').toLowerCase().trim();
    const rMopExplicit = rMopLower.includes('aed') || rMopLower.includes('php') ||
      rMopLower === 'gcash' || rMopLower.includes('credit card');
    if (dpCurr === 'AED' && dpRaw > 0 && !rMopExplicit) {
      const invoiceAED = calcItemPriceAED(r) + calcShippingFee(r) + calcCCFee(r) + n(r.additionalCharges);
      if (dpRaw > invoiceAED && invoiceAED > 0) {
        const dpIfPHP = dpRaw / rPhpRate;
        if (dpIfPHP <= invoiceAED) dpCurr = 'PHP';
      }
    }
    const dpConverted = dpRaw > 0 ? convertValue(dpRaw, dpCurr) : 0;

    // Layaway & amountReceived: use item currency
    const otherRaw = n(r.la1MonthPayment) + n(r.la2MonthPayment) + n(r.la3MonthPayment) + n(r.la4MonthPayment) + n(r.amountReceived);
    const itemCurr = getEffectiveCurrency(r);
    const otherConverted = otherRaw > 0 ? convertValue(otherRaw, itemCurr) : 0;

    return s + dpConverted + otherConverted;
  }, 0);
  const totalPaidConverted_rounded = rnd(totalPaidConverted);

  const balanceDue = total - totalPaidConverted_rounded;

  const totalGrams = records.reduce((s, r) => {
    const cat = (r.category || '').toLowerCase();
    if (cat.includes('screw type') || cat.includes('per pc') || cat.includes('diamond')) return s;
    return s + n(r.grams);
  }, 0);

  const amountForWords = Math.max(0, totalPaidConverted_rounded > 0 ? balanceDue : total);
  const amountInWords = numberToWords(amountForWords, currency);

  // Check if items have mixed MOPs — if so, stamp per item instead of once
  const uniqueMops = [...new Set(items.map(i => i.mop).filter(Boolean))];
  const mixedMops = uniqueMops.length > 1;

  const isLayaway = records.every(r => r.status === 'Layaway');

  const mopLabel = (() => {
    if (isLayaway) return null; // layaway gets its own stamp below
    if (mixedMops) return null; // handled per-item
    const mop = (first?.modeOfPayment || '').trim();
    if (!mop) return null;
    return mop.toUpperCase();
  })();

  const invoiceDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
  const invoiceNo = records.map(r => r.pureWeight).find(Boolean);
  const empire = isEmpirePage(first?.page);
  const brandName = empire ? 'EMPIRE GOLD BY ETG' : 'MYKABAYAN JEWELLERY';
  const logoUrl = empire ? EMPIRE_LOGO_URL : MYK_LOGO_URL;
  const watermarkText = empire ? 'EMPIRE GOLD OFFICIAL' : 'MYKABAYAN OFFICIAL';

  const summaryRows: { label: string; value: string; red?: boolean }[] = [
    { label: 'TOTAL GRAMS', value: totalGrams > 0 ? totalGrams.toFixed(2) : '—' },
    { label: 'SHIPPING', value: shipping > 0 ? fmtAmt(shipping) : 'FREE' },
    ...(additional > 0 ? [{ label: 'ADDITIONAL CHARGES', value: fmtAmt(additional) }] : []),
    ...(ccFee > 0 ? [{ label: 'CC SURCHARGE', value: fmtAmt(ccFee) }] : []),
    { label: 'SUBTOTAL', value: fmtAmt(subtotal) },
    { label: 'TOTAL INVOICE AMOUNT', value: fmtAmt(total) },
    ...(totalPaidConverted_rounded > 0 ? [
      { label: 'TOTAL PAID', value: `- ${fmtAmt(totalPaidConverted_rounded)}`, red: true },
      { label: 'BALANCE DUE', value: fmtAmt(balanceDue), red: true },
    ] : []),
  ];

  const emptyRows = Math.max(0, 7 - items.length);

  return (
    <div style={{ position: 'relative', fontFamily: 'Arial, sans-serif', color: '#111', background: '#fff', fontSize: 12 }}>

      <div style={{
        position: 'absolute',
        top: '40%',
        left: '50%',
        transform: 'translate(-50%, -50%) rotate(-35deg)',
        fontSize: '65px',
        color: 'rgba(150, 150, 150, 0.12)',
        fontWeight: 900,
        whiteSpace: 'nowrap',
        pointerEvents: 'none',
        zIndex: 0,
        userSelect: 'none',
        textAlign: 'center'
      }}>
        {watermarkText}<br/>
        {invoiceNo || ''}
      </div>

      <div style={{ position: 'relative', zIndex: 1 }}>
        <div style={{ textAlign: 'center', border: '1px solid #999', padding: '4px', marginBottom: 0, background: '#fff' }}>
          <em style={{ fontSize: 14 }}>Statement of Account</em>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <tbody>
            <tr>
              <td style={{ width: '65%', padding: '12px 16px', verticalAlign: 'top', border: '1px solid #999' }}>
                <div style={{ fontWeight: 900, fontSize: 24, letterSpacing: 1 }}>{brandName}</div>
                <div style={{ marginTop: 8, textAlign: 'left', fontSize: 11 }}>SATWA, DUBAI, UNITED ARAB EMIRATES</div>
                <div style={{ marginTop: 4, fontSize: 11 }}>WhatsApp &amp; Contact no.: +971 52 825 2405</div>
              </td>
              <td style={{ width: '35%', padding: '12px 16px', verticalAlign: 'middle', textAlign: 'center', border: '1px solid #999' }}>
                <img src={logoUrl} crossOrigin="anonymous" alt="Logo" style={{ width: empire ? '150px' : '80px', height: empire ? '100px' : '80px', objectFit: 'contain', display: 'block', margin: '0 auto' }} />
              </td>
            </tr>
            <tr>
              <td style={{ padding: '10px 16px', verticalAlign: 'middle', border: '1px solid #999' }}>
                <div style={{ fontWeight: 700, fontSize: 20, textAlign: 'center', letterSpacing: 1 }}>
                  {(first?.minerName || '').toUpperCase()}
                </div>
              </td>
              <td style={{ padding: '8px', textAlign: 'center', border: '1px solid #999' }}>
                <div style={{ fontWeight: 600, fontSize: 13 }}>{invoiceDate}</div>
                <div style={{ fontSize: 11, marginTop: 4 }}>Date Printed</div>
                {invoiceNo && (
                  <div style={{ marginTop: 8, borderTop: '1px solid #ccc', paddingTop: 6 }}>
                    <div style={{ fontWeight: 700, fontSize: 13, fontFamily: 'monospace', color: '#c00' }}>{invoiceNo}</div>
                    <div style={{ fontSize: 10, color: '#666', marginTop: 2 }}>Account ID / Invoice #</div>
                  </div>
                )}
              </td>
            </tr>
          </tbody>
        </table>

        <table style={{ width: '100%', borderCollapse: 'collapse', background: 'transparent' }}>
          <thead>
            <tr style={{ background: 'rgba(224, 224, 224, 0.9)' }}>
              {['Date', 'Item Description', 'T.O.G', 'Grams/Qty', 'Rate', 'Amount'].map(h => (
                <th key={h} style={{ border: '1px solid #999', padding: '6px 8px', textAlign: 'center', fontSize: 11 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => (
              <tr key={i}>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, color: '#666' }}>{item.date}</td>
                <td style={{ border: '1px solid #999', padding: '5px 8px', textAlign: 'center', fontSize: 11, fontWeight: 600 }}>
